\section{Orthogonal polynomials}

We compile in this appendix some properties about orthogonal polynomials that are used throughout this document.

\subsection{Jacobi polynomials}

Jacobi polynomials $\Jacobi{n}{\alpha}{\beta}$ form a complete orthogonal system in $[-1,1]$ with respect to the weight $w(x)=(1-x)^{\alpha}(1+x)^{\beta}$.

From \cite[Eq. (7.32.5)]{Szego1975} we have the following asymptotic estimates for the Jacobi polynomials (for $\alpha\geq -1/2$):
%
\begin{equation}\label{eq:bounds-Jacobi}
	\Jacobi{n}{\alpha}{\beta}=\begin{cases}
		\theta^{-\alpha-1/2}O(n^{-1/2}) & n^{-1}\leq \theta\leq \pi/2 \\
		O(n^{\alpha}) & 0\leq \theta\leq n^{-1}.
	\end{cases}
\end{equation}

The following formula of Hilb's type can be used to study the asymptotic behavior of the Jacobi polynomials.

\begin{theorem}[{\cite[Theorem 8.21.12]{Szego1975}}]\label{thm:Hilb-Jacobi}
	Let $\alpha>-1$, and let $\beta$ be arbitrary and real. Then, we have
	%
	\begin{equation*}
		\biggl(\sin\frac{\theta}{2}\biggr)^{\alpha}\biggl(\cos\frac{\theta}{2}\biggr)^{\beta}\Jacobi{n}{\alpha}{\beta}(\cos\theta)=A(n)^{-\alpha}\frac{\Gamma(n+\alpha+1)}{n!}\frac{\theta^{1/2}}{\sin^{1/2}\theta}\BesselJ{\alpha}\bigl(A(n)\theta\bigr)+\textup{Error},
	\end{equation*}
	%
	where $A(n)=\bigl(n+(\alpha+\beta+1)/2\bigr)$ and
	%
	\begin{equation*}
		\textup{Error}=\begin{cases}
			\theta^{1/2}O(n^{-3/2}) & n^{-1}\leq \theta\leq \pi-\varepsilon\\
			\theta^{\alpha+2}O(n^{\alpha}) & 0<\theta<n^{-1},
		\end{cases}
	\end{equation*}
	%
	where $\varepsilon$ is a fixed positive constant.
\end{theorem}

We use the following version of Hilb's formula (see \cite[Theorem 8.21.12]{Szego1975}):
%
\begin{equation*}
	\sin\frac{\theta}{2}\Jacobi{L}{1}{0}(\cos\theta)=\frac{\theta^{1/2}}{\sin^{1/2}\theta}\BesselJ{1}((L+1)\theta)+\begin{cases}
		\theta^{1/2}O(L^{-3/2}), & L^{-1}\leq \theta\leq \pi-\varepsilon,\\
		\theta^3 O(L), & 0<\theta\leq L^{-1},
	\end{cases}
\end{equation*}
%
Then,
%
\begin{equation*}
	\Jacobi{L}{1}{0}(\cos\theta)\sin^{1/2}\theta=\frac{\theta^{1/2}}{\sin(\theta/2)}\BesselJ{1}((L+1)\theta)+\textup{Error},
\end{equation*}
%
where
%
\begin{equation*}
	\textup{Error}=\begin{cases}
		(\sin^{1/2}(\theta)\theta^{1/2}/\sin(\theta/2))O(L^{-3/2}), & L^{-1}\leq \theta\leq \pi-\varepsilon,\\
		(\sin^{1/2}(\theta)\theta^3/\sin(\theta/2)) O(L), & 0<\theta\leq L^{-1},
	\end{cases}
\end{equation*}
%
Hence,
%
\begin{equation*}
	\Jacobi{L}{1}{0}(\cos\theta)^2\sin\theta=\frac{\theta}{\sin^2(\theta/2)}\BesselJ{1}((L+1)\theta)^2+\textup{Error}^2+2\textup{Error}\frac{\theta^{1/2}}{\sin(\theta/2)}\BesselJ{1}((L+1)\theta).
\end{equation*}

Near the endpoints, the asymptotic behavior of the Jacobi polynomials is given by the Mehler--Heine formula (see \cite[Theorem 8.1.1]{Szego1975}):
%
\begin{equation}\label{eq:Mehler-Heine}
	\lim_{n\tendsto\infty}n^{-\alpha}\Jacobi{n}{\alpha}{\beta}\biggl(\cos\frac{z}{n}\biggr)=(z/2)^{-\alpha}\BesselJ{\alpha}(z).
\end{equation}
%
In particular, we have
%
\begin{equation}\label{eq:Mehler-Heine-Jacobi-1}
	\lim_{n\tendsto\infty}\frac{1}{n}\Jacobi{n}{1}{0}\biggl(\cos\frac{z}{n}\biggr)=\frac{2}{z}\BesselJ{1}(z).
\end{equation}


From \cite[Eq. (3)]{BeltranMarzoOrtega} we also have
%
\begin{equation}\label{eq:Mehler-Heine-Jacobi-2}
	\lim_{n\tendsto\infty}\Jacobi{n}{1}{0}\biggl(\cos\biggl(\pi-\frac{z}{n}\biggr)\biggr)=\BesselJ{0}(z).
\end{equation}


\subsection{Some integrals involving Jacobi polynomials}\label{integralsjacobi}
Throughout this section we use $f\lesssim g$ to denote that there is a universal constant $C>0$ such that $f\leq Cg$ and we write $f\asymp g$ if there is a universal constant $C>0$ such that $C^{-1}f \leq  g \leq Cf$.






\begin{lemma}\label{lemma:1}
	The following equality holds:
	%
	\begin{equation*}
		\int_{\pi/2}^{\pi}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta=O(L^{-1}).
	\end{equation*}
\end{lemma}

\begin{proof}
	Making the substitution $\theta\mapsto\pi-\theta$ and using that
	%
	\begin{equation*}
		\Jacobi{L}{\alpha}{\beta}(-x)=(-1)^{L}\Jacobi{L}{\beta}{\alpha}(x),
	\end{equation*}
	%
	the integral of the lemma reads as 
	%
	\begin{equation*}
		\int_{0}^{\pi/2}\Jacobi{L}{0}{1}(\cos\theta)^2\log\bigl(1+\cos(\theta/2)\bigr)\sin\theta\dd \theta.
	\end{equation*}
	%
	Using that $\sin\theta=O(\theta)$ and $\log\bigl(1+\cos(\theta/2)\bigr)=O(1)$, together with the bounds \eqref{eq:bounds-Jacobi} for the Jacobi polynomials, we have
	%
	\begin{equation*}
		\int_{0}^{\pi/2}\Jacobi{L}{0}{1}(\cos\theta)^2\log\bigl(1+\cos(\theta/2)\bigr)\sin\theta\dd \theta=O\biggl(L^{-1}\int_{0}^{\pi/2}\theta^{-1}\theta\dd\theta\biggr)=O(L^{-1}).
	\end{equation*}
\end{proof}

\begin{lemma}\label{lemma:2}
	The following equality holds:
	%
	\begin{equation*}
		\int_{0}^{L^{-1/2}}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta=O(L^{-1}\log L).
	\end{equation*}
\end{lemma}

\begin{proof}
	Using that $\sin\theta=O(\theta)$ and $\log\bigl(1+\sin(\theta/2)\bigr)=O(\theta)$ together with the estimates \eqref{eq:bounds-Jacobi}, we have
	%
	\begin{equation*}
		\int_{0}^{L^{-1/2}}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta=O\biggl(L^{-1}\int_{0}^{L^{-1/2}}\theta^{-1}\biggr)=O(L^{-1}\log L).
	\end{equation*}
\end{proof}



\begin{lemma}\label{lemma:3}
	The following identity holds:
	%
	\begin{equation*}
		 \int_{L^{-1/2}}^{\pi/2}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta\asymp\frac{\log L}{L}.
	\end{equation*}
\end{lemma}

\begin{proof}
	We have
	%
	\begin{equation*}
		\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\asymp \theta^2.
	\end{equation*}
	%
	Using this estimate and the bounds \eqref{eq:bounds-Jacobi} for the Jacobi polynomials, we have
	%
	\begin{equation*}
		\int_{L^{-1/2}}^{\pi/2}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta\lesssim L^{-1}\int_{L^{-1/2}}^{\pi/2}\theta^{-1}\dd\theta\lesssim \frac{\log L}{L}.
	\end{equation*}
	%
	For the lower bound, recall that  we have the following asymptotic representation (see \cite[Formula 8.965]{integrales}):
	%
	\begin{equation*}
		\Jacobi{L}{1}{0}(\cos\theta)=\frac{\cos((L+1)\theta-3\pi/4)}{\sqrt{\pi L}\sin^{3/2}(\theta/2)\cos^{1/2}(\theta/2)}+O(L^{-3/2}).
	\end{equation*}
	%
	Then, we have
	%
	\begin{equation*}
		\Jacobi{L}{1}{0}(\cos\theta)^2\gtrsim \frac{\cos^2((L+1)\theta-3\pi/4)}{\pi L\sin^{3}(\theta/2)\cos(\theta/2)}.
	\end{equation*}
	%
	Note that
	%
	\begin{equation*}
		\cos^2((L+1)\theta-3\pi/4)=1\iff \theta=\frac{k\pi+3\pi/4}{L+1},\quad \floor{c\sqrt{L}}\leq k\leq\floor{c'L},
	\end{equation*}
	%
	for certain constants $c,c'>0$. Hence,
	%
	\begin{equation*}
		\frac{k\pi+3\pi/4- \pi/4}{L+1}\leq \theta\leq \frac{k\pi+3\pi/4+ \pi/4}{L+1}\implies \cos^2((L+1)\theta-3\pi/4)\geq 1/2.
	\end{equation*}
	%
	Then,
	%
	\begin{align*}
		\MoveEqLeft\int_{L^{-1/2}}^{\pi/2}\Jacobi{L}{1}{0}(\cos\theta)^2\log\bigl(1+\sin(\theta/2)\bigr)\sin\theta\dd \theta\gtrsim\frac{1}{L} \sum_{k=\floor{c\sqrt{L}}}^{\floor{c'L}}\int_{\frac{k\pi+\pi/2}{L+1}}^{{\frac{k\pi+\pi}{L+1}}}\theta^{-1}\dd\theta\\
		&=\frac{1}{L}\sum_{k=\floor{c\sqrt{L}}}^{\floor{c'L}}\log\biggl(1+\frac{\pi/2}{k\pi+\pi/2}\biggr)\gtrsim\frac{1}{L}\sum_{k=\floor{c\sqrt{L}}}^{\floor{c'L}}\frac{1}{2k+1}\gtrsim \frac{1}{L}\int_{\floor{c\sqrt{L}}}^{\floor{c'L}+1}\frac{1}{2x+1}\dd x\\
		&=\frac{1}{2L}\log\biggl(\frac{2\floor{c'L}+3}{2\floor{c\sqrt{L}}+1}\biggr)\asymp \frac{\log(L)}{L}.
	\end{align*}

\end{proof}
\subsection{Gegenbauer polynomials}

Gegenbauer polynomials belong to the family of Jacobi polynomials. More specifically, we have
%
\begin{equation*}
	\Gegenbauer{n}{\lambda}=\frac{\Gamma(n+2\lambda)\Gamma(\lambda+1/2)}{\Gamma(n+\lambda+1/2)\Gamma(2\lambda)}\Jacobi{n}{\lambda-1/2}{\lambda-1/2}.
\end{equation*}




From \cite[Eq. (7.33.6)]{Szego1975} we have the following asymptotic estimates for the Gegenbauer polynomials:
%
\begin{equation}\label{eq:bounds-Gegenbauer}
	\Gegenbauer{n}{\lambda}=\begin{cases}
		\theta^{-\lambda}O(n^{\lambda-1}) & n^{-1}\leq \theta\leq \pi/2 \\
		O(n^{2\lambda-1}) & 0\leq \theta\leq n^{-1}.
	\end{cases}
\end{equation}



Near the endpoints, the asymptotic behavior of the Gegenbauer polynomials is given by the Mehler--Heine formula \eqref{eq:Mehler-Heine}. To find the exact expression for the polynomials $\Gegenbauer{n}{2}$,  recall that
%
\begin{equation}\label{eq:Gegenabuer-2-Jacobi}
	\Gegenbauer{n}{2}=\frac{\Gamma(n+4)\Gamma(5/2)}{\Gamma(n+5/2)\Gamma(4)}\Jacobi{n}{3/2}{3/2}\sim \frac{\sqrt{\pi}}{8}n^{3/2}\Jacobi{n}{3/2}{3/2}
\end{equation}
%
From \eqref{eq:Mehler-Heine} we have
%
\begin{equation*}
	\lim_{n\tendsto\infty}n^{-3/2}\Jacobi{n}{3/2}{3/2}\biggl(\cos\frac{z}{n}\biggr)=(z/2)^{-3/2}\BesselJ{3/2}(z),
\end{equation*}
%
and so
%
\begin{equation}\label{eq:Mehler-Heine-Gegenbauer-2}
	\lim_{n\tendsto\infty}n^{-3}\Gegenbauer{n}{2}\biggl(\cos\frac{z}{n}\biggr)=\frac{\sqrt{\pi}}{2\sqrt{2}}z^{-3/2}\BesselJ{3/2}(z).
\end{equation}

\subsubsection{Hilb's formula for the Gegenbauer polynomials $\Gegenbauer{n}{2}$}

Using the relation \eqref{eq:Gegenabuer-2-Jacobi}, Hilb's formula from \cref{thm:Hilb-Jacobi} has the following expression:
%
\begin{align*}
	\MoveEqLeft\biggl(\sin\frac{\theta}{2}\biggr)^{3/2}\biggl(\cos\frac{\theta}{2}\biggr)^{3/2}\Jacobi{n}{3/2}{3/2}(\cos\theta)\\
	&=A(n)^{-3/2}\frac{\Gamma(n+3/2+1)}{n!}\frac{\theta^{1/2}}{\sin^{1/2}\theta}\BesselJ{3/2}\bigl(A(n)\theta\bigr)+\textup{Error},
\end{align*}
%
where
%
\begin{equation*}
	\textup{Error}=\begin{cases}
		\theta^{1/2}O(n^{-3/2}) & n^{-1}\leq \theta\leq \pi-\varepsilon\\
		\theta^{7/2}O(n^{3/2}) & 0<\theta<n^{-1}.
	\end{cases}
\end{equation*}
%
Then, simplifying, we obtain
%
\begin{align*}
	\MoveEqLeft\frac{\sin^{3/2}\theta}{2^{3/2}}\frac{\Gamma(n+5/2)\Gamma(4)}{\Gamma(n+4)\Gamma(5/2)}\Gegenbauer{n}{2}(\cos\theta)\\
	&=(n+2)^{-3/2}\frac{\Gamma(n+5/2)}{n!}\frac{\theta^{1/2}}{\sin^{1/2}\theta}\BesselJ{3/2}\bigl((n+2)\theta\bigr)+\textup{Error},
\end{align*}
%
that is,
\begin{align*}
	\sin^{3/2}\theta\Gegenbauer{n}{2}(\cos\theta)=\sqrt{\frac{\pi}{8}}(n+3)(n+2)^{-1/2}(n+1)\frac{\theta^{1/2}}{\sin^{1/2}\theta}\BesselJ{3/2}\bigl((n+2)\theta\bigr)+\textup{Error},
\end{align*}
%
As a consequence, we have
%
\begin{align*}
	\sin\theta\Gegenbauer{n}{2}(\cos\theta)=\sqrt{\frac{\pi}{8}}(n+3)(n+2)^{-1/2}(n+1)\frac{\theta^{1/2}}{\sin\theta}\BesselJ{3/2}\bigl((n+2)\theta\bigr)+\textup{Error},
\end{align*}
%
where the error is now
%
\begin{equation*}
	\textup{Error}=\begin{cases}
		(\theta/\sin\theta)^{1/2}O(n^{-3/2}) & n^{-1}\leq \theta\leq \pi-\varepsilon\\
		(\theta^{7/2}/\sin^{1/2}\theta)O(n^{\alpha}) & 0<\theta<n^{-1}.
	\end{cases}
\end{equation*}
%
Simplifying even more, we can write the previous formula as
%
\begin{equation}\label{eq:Hilb-Gegenbauer-2}
	\sin\theta\Gegenbauer{n}{2}(\cos\theta)=\sqrt{\frac{\pi}{8}}n^{3/2}(1+O(n^{-1}))\frac{\theta^{1/2}}{\sin\theta}\BesselJ{3/2}\bigl((n+2)\theta\bigr)+\textup{Error},
\end{equation}
%
where the error is
%
\begin{equation*}
	\textup{Error}=\begin{cases}
		O(n^{-3/2}) & n^{-1}\leq \theta\leq \pi-\varepsilon\\
		(\theta^{3})O(n^{3/2}) & 0<\theta<n^{-1}.
	\end{cases}
\end{equation*}

\subsection{Bessel functions}

From \cite[Section 3.8.5]{MagnusOberhettingerSoni1966}, we have the following identity:
%
\begin{equation}\label{eq:integral-Bessel}
	\int_{0}^{\infty}t^{-s-1}\BesselJ{\nu}(t)^2\dd t=\frac{1}{2^{s+1}}\frac{\Gamma(s+1)\Gamma(\nu-s/2)}{\Gamma((s+1)/2)^2\Gamma(\nu+1+s/2)}.
\end{equation}
%
As a consequence, we can derive the following identity:
%
\begin{equation}\label{eq:integral-Bessel-log}
	\int_{0}^{\infty}\frac{\log t}{t}\BesselJ{\nu}(t)^2\dd t=\frac{1}{2\nu}\Bigl(\digamma(\nu)+\log 2\Bigr)+\frac{1}{4\nu^2}.
\end{equation}

