\section*{Appendix A: Derived stiffness matrix of a U-shaped spring element}
\label{Appendix_A}

The stiffness matrix of a U-shaped spring element are expressed as follows
\begin{align}
{\bf{\bar F}}_j^{\rm{e}} &= {\left[ {{{\bf{K}}_{\rm{u}}}} \right]^{\rm{e}}}{\bf{\bar U}}_j^{\rm{e}} \tag{12} \\
{\left[ {{{\bf{K}}_\text{u}}} \right]^{\rm{e}}} &= \left[ {\begin{array}{*{20}{c}}
{K_{11}^{\rm{e}}}&0&0&0&0&{K_{16}^{\rm{e}}}\\
0&{K_{22}^{\rm{e}}}&0&0&0&{K_{26}^{\rm{e}}}\\
0&0&{K_{33}^{\rm{e}}}&{K_{34}^{\rm{e}}}&{K_{35}^{\rm{e}}}&0\\
0&0&{K_{43}^{\rm{e}}}&{K_{44}^{\rm{e}}}&{K_{45}^{\rm{e}}}&0\\
0&0&{K_{53}^{\rm{e}}}&{K_{54}^{\rm{e}}}&{K_{55}^{\rm{e}}}&0\\
{K_{61}^{\rm{e}}}&{K_{62}^{\rm{e}}}&0&0&0&{K_{66}^{\rm{e}}}
\end{array}} \right] \tag{15}
\end{align}
where each component is derived and expressed as follows 
\begin{align}
K_{_{11}}^{\rm{e}} &= \frac{{3{i_1}\left( {{i_1} + 2{i_2}} \right)}}{{\left( {2{i_1} + {i_2}} \right)L_1^2}} \tag{A--1} \\
K_{_{16}}^{\rm{e}} &= K_{_{61}}^{\rm{e}} = \frac{{ - 3{i_1}\left( {{i_1} + {i_2}} \right)}}{{\left( {2{i_1} + {i_2}} \right){L_1}}} \tag{A--2}\\
K_{22}^{\rm{e}} &= \frac{{12{i_1}{i_2}}}{{({i_1} + 6{i_2}){L_2}^2}} \tag{A--3}\\
K_{26}^{\rm{e}} &= K_{62}^{\rm{e}} =  - \frac{{6{i_1}{i_2}}}{{\left( {{i_1} + 6{i_2}} \right){\rm{ }}{L_2}}} \tag{A--4}\\
K_{33}^{\rm{e}} &= \frac{{12{j_1}{i_3}{i_4}(2{j_2} + {i_3})}}{{6{i_3}{i_4}{L_2}^2(2{j_2} + {i_3}) + {j_1}\left( {4{j_2}{i_4}{L_1}^2 + 8{i_3}{i_4}{L_1}^2 + 2{j_2}{i_3}{L_2}^2 + {i_3}^2{L_2}^2} \right)}} \tag{A--5}\\
K_{34}^{\rm{e}} &= K_{43}^{\rm{e}} = \frac{{12{j_1}{i_3}{i_4}({j_2} + {i_3}){L_1}}}{{6{i_3}{i_4}{L_2}^2(2{j_2} + {i_3}) + {j_1}\left( {4{j_2}{i_4}{L_1}^2 + 8{i_3}{i_4}{L_1}^2 + 2{j_2}{i_3}{L_2}^2 + {i_3}^2{L_2}^2} \right)}} \tag{A--6}\\
K_{35}^{\rm{e}} &= K_{53}^{\rm{e}} = \frac{{6{j_1}{i_3}{i_4}(2{j_2} + {i_3}){L_2}}}{{6{i_3}{i_4}{L_2}^2(2{j_2} + {i_3}) + {j_1}\left( {4{j_2}{i_4}{L_1}^2 + 8{i_3}{i_4}{L_1}^2 + 2{j_2}{i_3}{L_2}^2 + {i_3}^2{L_2}^2} \right)}} \tag{A--7}\\
K_{44}^{\rm{e}} &= \frac{{{i_3}\left[ {6{j_2}{i_3}{i_4}{L_2}^2 + {j_1}\left( {8{j_2}{i_4}{L_1}^2 + 12{i_3}{i_4}{L_1}^2 + {j_2}{i_3}{L_2}^2} \right)} \right]}}{{6{i_3}{i_4}{L_2}^2(2{j_2} + {i_3}) + {j_1}\left( {4{j_2}{i_4}{L_1}^2 + 8{i_3}{i_4}{L_1}^2 + 2{j_2}{i_3}{L_2}^2 + {i_3}^2{L_2}^2} \right)}} \tag{A--8}\\
