\title{Stability transitions of NLS {action} ground-states on metric graphs}


\author{Francisco Agostinho, Sim\~ao Correia and
	Hugo Tavares}

\date{\today} %leave blank

\begin{document}
\maketitle

\begin{abstract}
We study the orbital stability of action ground-states of the nonlinear Schr\"odinger equation over two particular cases of metric graphs, the $\mathcal{T}$ and the tadpole graphs. We show the existence of \emph{stability transitions} near the $L^2$-critical exponent, a new dynamical feature of the nonlinear Schr\"odinger equation. More precisely, as the frequency $\lambda$ increases, the action ground-state transitions from stable to unstable and then back to stable (or vice-versa).


This result is complemented with the stability analysis of ground-states in the asymptotic cases of low/high frequency and weak/strong nonlinear interaction. Finally, we present a numerical simulation of the stability of action ground-states depending on the nonlinearity and the frequency parameter, which validates the aforementioned theoretical results.


\vskip10pt
	\noindent\textbf{Keywords}: action ground-states, metric graphs, nonlinear Schr\"odinger equation, orbital stability, stability transitions.
	\vskip10pt
	\noindent\textbf{AMS Subject Classification 2020}:  	34C37, {35B35}, 35Q55, 35R02,  {37K45}, 70K05 
\end{abstract}



\section{Introduction}

Let $\mathcal{G}$ be a (finite) metric graph\footnote{Roughly speaking, a set of finitely many edges, identified either with half-lines or finite intervals,  joined through vertices, where the distance between two points is defined as the length of the shortest path joining them. For more details, see \cite{berkolaiko2013introduction}.}. We consider the nonlinear Schr\"odinger equation over\footnote{The equation is to be satisfied over each edge of $\mathcal{G}$, together with a continuity condition on the vertices.} $\mathcal{G}$,
\begin{equation}\label{NLSE_Chapter5}\tag{NLS}
	i\partial_t v+ \partial^2_{xx} v+|v|^{p-2}v=0, \quad v=v(t,x),\quad v:\R\times \mathcal{G}\to \C,\quad p>2. \end{equation}
In physical applications, the metric graphs can represent either an optic network \cite{bolte2014many, burioni2001bose, dalfovo1999theory} (where $v$ is then the signal transmitted along that network) or a ramified trap for a Bose-Einstein condensate \cite{bulgakov2011symmetry, hung2011symmetric} (in which case, $v$ is the wave function of the condensate). 

Among all solutions, we focus on standing waves
\[
v(t,x)=e^{i\lambda t}u(x),
\]
where the real parameter $\lambda$ is usually called \textit{frequency} and $u$ defines the profile of the standing wave. It can be easily checked that $v$ is a standing wave if and only if the profile $u$ is a solution of
\begin{equation}\label{StationaryNLS_Chapter5}
	-u'' + \lambda u = |u|^{p-2}u\ \text{in}\ \G.
\end{equation}
This equation is to be interpreted in the weak-$H^1(\mathcal G)$-sense; its solutions corresponds to critical points of the action functional 
\begin{equation}\label{eq:actionfunctional}
	S_\lambda(u,\mathcal{G})=\frac{1}{2}\int_{\mathcal{G}}|{u'}|^2+\lambda |u|^2dx-\frac{1}{p}\int_{\mathcal{G}}|u|^pdx,\ \text{for}\ u\in H^1(\mathcal{G}),
\end{equation} 
 where $H^1(\mathcal{G})$ is the set of (complex-valued) functions $u$ which are $H^1$ on each edge and continuous at each vertex. A standard computation shows that weak solutions satisfy the equation in the classical sense on each edge, and satisfy Neumann-Kirchoff conditions at each vertex, see \cite{berkolaiko2013introduction} for more details.

 A nontrivial solution of \eqref{StationaryNLS_Chapter5} is called a \textit{bound-state}. As bound-states generate orbits of \eqref{NLSE_Chapter5}, it is natural to analyze their dynamical stability.


\begin{definition}[\textit{Orbital Stability}]%{5.1}
	Let $\G$ be a metric graph. The \textit{orbit} of a solution $u\in H^1(\mathcal{G})$ of \eqref{StationaryNLS_Chapter5} is the set\footnote{if $\mathcal{G}=\R$, we must include the translation invariance in the definition of orbit, $\mathcal{O}(u):=\{e^{i\lambda\theta}u(\cdot+y):\ \theta\in\R,\ y\in\R\}$, see \cite[Section 8.3]{cazenave2003semilinear}.} $\mathcal{O}(u):=\{e^{i\lambda\theta}u:\ \theta\in\R\}$. We say that a bound-state $u$ is \textit{orbitally stable} if, for every $\varepsilon>0$, there exists $\delta>0$ such that
	\[ d\left(\Phi(0),\mathcal{O}(u^\lambda)\right)<\delta\ \ \implies d\left(\Phi(t),\mathcal{O}(u^\lambda)\right)<\varepsilon,\ \forall t>0,
    \]
	where $\Phi(t)$ is the solution of \eqref{NLSE_Chapter5} with initial data $\Phi(0)$, and $d(\cdot,\cdot)$ is the $H^1$-distance.

    If $u$ is not orbitally stable, we say that it is (orbitally) unstable.
\end{definition}

The stability of bound-states  is generally a hard open problem. For this reason, one usually restricts to the class of \emph{action ground-state solutions} of \eqref{StationaryNLS_Chapter5}, i.e., bound-states that attain the 
 least action level
\begin{equation}\label{eq:leastactionlevel} \mathcal{S}_{\mathcal{G}}(\lambda)=\inf\left\{S_\lambda(u,\mathcal{G}),\ u\in H^1(\mathcal{G})\setminus\left\{0\right\}: u \text{ is a bound-state of } \eqref{StationaryNLS_Chapter5}\right\}.
\end{equation}
{The study of such solutions (whose existence and variational characterization might depend on the graph) has been the object of recent work, see \cite{AgostinhoCorreiaTavares,AgostinhoCorreiaTavares2,de2023notion}.}\footnote{{As a parallel comment, we would also like to point out the intense activity on the study of \emph{energy} ground-states, see for e.g. \cite{ Simonegrid2018,adami2015nls, adami2016threshold, 
adami2017negative, 
Borthwick2023,
cacciapuoti2018variational,  chang2023normalized,
deCoster_etal2024,SimoneTree2020,   dovetta2024nonuniquenessnormalizedgroundstates, dovetta2020uniqueness, MR3959930} and references therein. On graphs, in general, these two notions of ground-state are not equivalent, see \cite{AgostinhoCorreiaTavares, dovetta2024nonuniquenessnormalizedgroundstates, dovetta2023action}.}}
For metric graphs with relatively simple topologies, it can be shown that, given $\lambda>0$, there exists a unique action ground-state $u^\lambda$ up to phase multiplication.
In this work, we focus mainly on two such classes (see \cite{AgostinhoCorreiaTavares, AgostinhoCorreiaTavares2} and Theorem \ref{thm:uniqueness} below): \begin{itemize}
    \item the $\mathcal{T}-$graph, consisting of two half-lines, $h_1$ and $h_2$, and a terminal edge of length $\ell>0$, all attached at the same vertex, which we identify with $x=0$, see Figure \ref{fig:T}. To emphasize the dependence on $\ell>0$, throughout this paper we will denote this graph by $\mathcal{T}_\ell$;
    \item the tadpole graph, consisting of one half-line $h_1$ and one loop of length $2\ell>0$, see Figure \ref{fig:tadpole}. We denote such graph by $\mathcal{G}_\ell$.
\end{itemize}
