\section{Grillakis-Shatah-Strauss theory}\label{sec:GSS}




As mentioned in the introduction, the study of orbital stability of action ground-states of \eqref{NLSE_Chapter5} fits within the framework of the Grillakis-Shatah-Strauss stability theory. This theory, albeit sufficiently general to analyze a very large class of equations, stands on three main assumptions which may be, in some situations, hard to verify. In this section, we introduce some notation in order to connect with the results in \cite{grillakis1987stability}, and we conclude with a general criterion that ensures stability transitions.

 For now, we keep the discussion as general as possible, so we work with $\mathcal{G}$ a general metric graph with finitely many edges. We consider $X=H^1(\mathcal{G};\C)$ to be the space of complex valued functions which are $H^1$ in each edge and continuous over the graph $\mathcal{G}$. We identify $X\simeq H^1(\mathcal{G}; \R)\times H^1(\mathcal{G};\R)$ and we endow $X$ with the usual real inner product. Moreover, we denote by $X'$ the dual space of $X$ and use the notation $\langle\cdot,\cdot\rangle$ for the duality pairing between $X'$ and $X$. 


Recall from \eqref{eq:actionfunctional} the $C^2$-action functional $S_\lambda$. It can be decomposed into two functionals of class that are formally preserved under the flow of \eqref{NLSE_Chapter5}:
\begin{equation*}
	S_\lambda(u,\mathcal{G})=E(u,\mathcal{G})+\frac{\lambda}{2} Q(u,\mathcal{G}),
\end{equation*}
where $E,Q:H^1(\mathcal{G};\C)\to\R$ are given by
\begin{equation*}
	E(u,\mathcal{G})=\frac{1}{2}\int_{\mathcal{G}}|u'|^2dx-\frac{1}{p}\int_{\mathcal{G}}|u|^pdx\quad\text{(\textit{Energy})}\quad\text{and}\quad Q(u,\mathcal{G})=\int_{\mathcal{G}}|u|^2dx\quad\text{(\textit{Mass})}.
\end{equation*}

With this notation, equation \eqref{NLSE_Chapter5} can be written as an abstract Hamiltonian system of the form 
$$\partial_t v = JE'(v(t),\mathcal{H}_1),$$
where $J:X'\to X'$ is the closed skew-symmetric linear operator which is represented by
$$ J=\begin{pmatrix}
	0 & 1\\-1 & 0
\end{pmatrix}.$$
For more details, we refer the reader to \cite[Section 6]{grillakis1987stability}. In this abstract setting, there are three assumptions that need to be verified in order to apply the Grillakis-Shatah-Strauss stability theory. In our setting, they can be defined as follows: 

\begin{enumerate}
	\item[$(A_1)$](Well Posedeness) Given $v_0\in X$, there exists a maximal time of existence $T_0>0$ and a unique solution $v\in C([0,T_0),X)$ to \eqref{NLSE_Chapter5} such that $v(0)=v_0$,
	$E\left(v(t),\mathcal{G}\right)=E\left(v_0,\mathcal{G}\right)$ and $Q\left(v(t),\mathcal{G}\right)=Q\left(v_0,\mathcal{G}\right)$, for all $t\in[0,T_0)$.
	\item[$(A_2)$](Existence and regularity of a bound-state curve) There exist $0<\lambda_1<\lambda_2$ and a $C^1$ map $\lambda\mapsto \Phi_\lambda$ from the open interval $(\lambda_1,\lambda_2)$ into $X$ that satisfies:
	\begin{equation}\label{CriticalPointAction}
		\langle S_\lambda'(\Phi_\lambda,\mathcal{G}),v\rangle=\langle E'(\Phi_\lambda,\mathcal{G})+\frac{\lambda}{2} Q'(\Phi_\lambda,\mathcal{G}),v\rangle=0,\ \text{for all}\ v\in H^1(\mathcal{G};\C).
	\end{equation}

	\item[$(A_3)$](Spectral Conditions) Define the linearized Hamiltonian around the bound-state $\Phi_\lambda\in X$ by $H_\lambda: X\to X'$, which satisfies
	\begin{equation}\label{LinearizedOperator}
		\langle H_\lambda v,w\rangle:=\langle S_\lambda''(\Phi_\lambda,\mathcal{G})v,w\rangle.
	\end{equation}
	Assume that $H_\lambda$
	satisfies the following spectral properties: for each $\lambda\in(\lambda_1,\lambda_2)$, $H_\lambda$ has exactly one negative simple eigenvalue, its kernel is spanned by $i\Phi_\lambda$, and the rest of its spectrum is positive and bounded away from zero.
\end{enumerate}

\smallbreak

The Grillakis-Shatah-Strauss stability theory tells us that, under these assumptions, we can discuss the stability of the bound-state $\Phi_\lambda$ for each $\lambda>0$, in terms of the convexity of the function $d:(0,\infty)\to\R$ defined by 
$$ 
d(\lambda)=E(\Phi_\lambda,\mathcal{G})+\frac{\lambda}{2} Q(\Phi_\lambda,\mathcal{G})=S_\lambda(\Phi_\lambda,\mathcal{G}).
$$
This reduces, see \cite[Theorem 3]{grillakis1987stability}, to analyzing the sign of $d''(\lambda)$. Observe that if $\Phi_\lambda$ is a solution of the equation \eqref{StationaryNLS_Chapter5}, we have that
$$ 
d''(\lambda)=\frac{1}{2}\frac{d }{d\lambda}Q(\Phi_\lambda,\mathcal{G}).
$$
Indeed, by definition of $d$, and assumption $(A_2)$, we have
\begin{align*}
	d'(\lambda)&=\left\langle E'(\Phi_\lambda,\mathcal{G}),\frac{d}{d\lambda}\Phi_\lambda \right\rangle+\frac{1}{2}Q(\Phi_\lambda,\mathcal{G})+\frac{\lambda}{2}\left\langle Q'(\Phi_\lambda,\mathcal{G}),\frac{d}{d\lambda}\Phi_\lambda\right\rangle=\frac{1}{2}Q(\Phi_\lambda,\mathcal{G}).
\end{align*}

Then, stability can be determined as follows:
\begin{theorem}[\textit{Vakhitov--Kolokolov Stability Criterion \cite{grillakis1987stability}}]\label{th:5.27}
	Fix $p>2$. Suppose assumptions $(A_1)$, $(A_2)$ and $(A_3)$ hold. Then,
	\begin{enumerate}
		\item If $\frac{d Q}{d \lambda}(\Phi_\lambda,\mathcal{G})>0$, the bound-state $\Phi_\lambda$ is orbitaly \textit{stable};
		\item If $\frac{d Q}{d \lambda}(\Phi_\lambda,\mathcal{G})<0$, the bound-state $\Phi_\lambda$ is orbitaly \textit{unstable}.
	\end{enumerate}
\end{theorem}


\subsection{A general criterion for stability transitions}

In order to present a general criterion for stability transitions close to $p=6$, we need to assume some upper and lower estimates of the size of action ground-states. The validity of this condition is usually ensured by using the variational characterization of action ground-states.
\begin{itemize}
\item[$(H)$] Let $\Phi_\lambda$ be as in $(A_2)$, satisfied for $\lambda\in (0,\infty)$, and consider, for $\lambda=\ell^2>0$, the scaling $$\Phi_\lambda(x)=\ell^\frac{2}{p-2}\Phi_\ell(\ell x)=\lambda^\frac{1}{p-2}\Phi_\ell(\sqrt{\lambda}x),\quad x\in \mathcal{G_\lambda}.$$  Then there exists $C_p>0$ such that
\begin{equation}\label{lower_upper_bounds}
\frac{1}{C_p}\leq \|\Phi_\ell\|_{H^1(\mathcal{G}_\lambda)}\leq C_p\qquad \text{ for all } \ell>0.
\end{equation}
\end{itemize}
\begin{lemma}\label{5.49.Temp}
	Let $\G$ be a non-compact metric graph and assume $(A_2)$ and $(H)$ for some $p>2$. Then there exists $C=C_p>0$ such that 
	\begin{equation}\label{eqn.lema3.14}
		\frac{1}{C}\lambda^{\frac{6-p}{2(p-2)}}\leq Q(\Phi_\lambda,\mathcal{G})\leq C\lambda^{\frac{6-p}{2(p-2)}}.
	\end{equation}
\end{lemma}
\begin{proof}
From the scaling and assumption $(H)$, 
	\begin{equation*}\label{eqn.lema3.14.1}
		Q(\Phi_\lambda,\mathcal{G})\lambda^{\frac{p-6}{2(p-2)}}=\|\Phi_\ell\|^2_{L^2(\G_\lambda)}\leq \|\Phi_\ell\|^2_{H^1(\G_\lambda)} \leq C_p^2
	\end{equation*}
	Recalling the Gagliardo-Nirenberg inequality
	\[
\|\Phi_\ell\|_{H^1(\mathcal{G}_\lambda)}^2=\|\Phi_\ell\|_{L^p(\mathcal{G}_\lambda)}^p\leq C \|\Phi_\ell\|^\frac{p+2}{2}_{L^2(\mathcal{G}_\lambda)}\|\Phi_\ell'\|^\frac{p-2}{2}_{L^2(\mathcal{G}_\lambda)}\leq \kappa C \|\Phi_\ell\|^\frac{p+2}{2}_{L^2(\mathcal{G}_\lambda)},
	\]
	the remaining conclusion follows from the lower bounds in $(H)$. 
\end{proof}



\begin{theorem}\label{thm:transition} 
    	Suppose that $\G$ is a metric graph. For $p\sim 6$, assume conditions $(A_1)$, $(A_2)$ and $(A_3)$ are satisfied for $\lambda\in (0,\infty)$, and that $(H)$ holds. For $\Theta(p,\lambda):=Q(\Phi_\lambda,\mathcal{G})$, suppose that the map $\lambda\in (0,\infty) \mapsto\Theta(6,\Phi_\lambda)$ is not monotone and that $(p,\lambda)\mapsto\frac{\partial\Theta}{\partial\lambda}(p,\lambda)$ is continuous. Then, there exists $\varepsilon>0$ such that
	\begin{enumerate}
		\item for $p\in(6-\varepsilon,6)$, there exists a SUS-stability transition.
		\item  for $p\in(6,6+\varepsilon)$, there exists a USU-stability transition.
	\end{enumerate} 
\end{theorem}

\begin{proof}[Proof of Theorem \ref{thm:transition}] 
    Under the assumptions of the statement, we can apply the Grillakis-Shatah-Strauss stability theory to the curve  $\lambda\in (0,\infty)\mapsto \Phi_\lambda$. The only thing left to do is to study the Vakhitov--Kolokolov criterion, recall Theorem \ref{th:5.27}. 

	Since $\lambda\mapsto\Theta(6,\lambda)$ is not monotone, assume, without loss of generality, there exist $0<\lambda_1<\lambda_2$ for which
	\[
    \frac{\partial\Theta}{\partial\lambda}(6,\lambda_1)<0\quad\text{and}\quad\frac{\partial\Theta}{\partial\lambda}(6,\lambda_2)>0
    \]
	(the situation where $\lambda_2<\lambda_1$ is analogous). Since, $(p,\lambda)\mapsto\frac{\partial\Theta}{\partial\lambda}(p,\lambda)$ is continuous, for $\varepsilon>0$ sufficiently small, 
	\begin{align*}
		&\frac{\partial\Theta}{\partial\lambda}(p,\lambda)<0\quad \text{for}\ p\in [6-\varepsilon,6+\varepsilon],\ \lambda\in [\lambda_1-\varepsilon,\lambda_1+\varepsilon],\\
        &\frac{\partial\Theta}{\partial\lambda}(p,\lambda)>0\quad \text{for}\ p\in [6-\varepsilon,6+\varepsilon],\ \lambda\in [\lambda_2-\varepsilon,\lambda_2+\varepsilon].
	\end{align*}
	Now, in the supercritical case $p\in (6,6+\varepsilon]$, since  $\Theta(p,\lambda)\to0^+$ as $\lambda\to+\infty$ (by Lemma \ref{5.49.Temp}),  there exist $\lambda_3,\lambda_4$ with $\lambda_2+\varepsilon<\lambda_3<\lambda_4$ such that 
	\begin{equation}\label{GSSAux.2}
		\frac{\partial\Theta}{\partial\lambda}(p,\lambda)<0\quad \text{for}\ \lambda\in(\lambda_3,\lambda_4),
	\end{equation}
	which concludes the proof of Item 2. In the subcritical case $p\in [6-\varepsilon,6)$,  we use once again Lemma \ref{5.49.Temp} to ensure the existence of $\lambda_5,\lambda_6$ with  $\lambda_5<\lambda_6<\lambda_1-\varepsilon$ for which
	\begin{equation}\label{GSSAux.2_Sub}
		\frac{\partial\Theta}{\partial\lambda}(p,\lambda)>0\quad \text{for}\ \lambda\in(\lambda_5,\lambda_6)
	\end{equation}
    and the proof is finished.
\end{proof}

\begin{remark}\label{rem:lambda_estrela}
    In the case of the $\mathcal{T}$ and tadpole graphs, the spectral condition $(A_3)$ will be verified for all $\lambda$ except for a problematic frequency $\lambda^*=\lambda^*(\mathcal{G})$ (see Section \ref{AssumptionA_3}). This poses no particular obstacle for the validity of the above result, as one can choose the various frequency intervals so that they do not include $\lambda^*$.
\end{remark}


\section{Review of known results for the $\mathcal{T}$ and tadpole graphs}\label{sec:Preliminaries}

In this section, we review known results on the qualitative and quantitative properties of action ground-states on the $\mathcal{T}$ and tadpole graphs. 
Unless we want to stress that a result or a proof holds only for a specific graph, we shall denote the graphs $\mathcal{T}_\ell$ and $\G_\ell$ by $\mathcal{H}_\ell$. 

From now on, $u^\lambda$ will denote the positive action ground-state solution on $\mathcal{H}_1$ (we omit here the dependence on $p$ of simplicity). Since we will study the mass of $u^\lambda$ as a function of $p$, we denote
\[
(p,\lambda)\mapsto \Theta(p,\lambda)=\|u^\lambda\|_{L^2(\mathcal{H}_1)}^2.
\]
A key element in our analysis is the function $f:\R^+_0\to \R$ defined by $f(t)=\frac{t^2}{2}-\frac{t^p}{p}$ (see Figure \ref{fig:f}). We write $f_1=f|_{[0,1]}$ and $f_2=f|_{[1,\infty)}$ and observe that both functions are invertible over the respective domains.

\begin{figure}[h]\label{fig:f}
\begin{center}
\includegraphics[height=3cm]{Plot_f.png}
\end{center}
\caption{Plot of the function $f(t)$ for $p=3$.}
\end{figure}

Moreover, we denote by $\varphi$ the soliton (for $\lambda=1$) centered at zero in the real line, i.e., the unique positive solution of 
\[
-\varphi''+\varphi=\varphi^{p} \text{ in } \R,
\] 
symmetric (and decreasing) with respect to the origin. A direct integration of the equation shows that
\[
\varphi(x)=\left(\frac{p}{2}\right)^\frac{1}{p-2}\sech^{\frac{2}{p-2}}\left(\frac{p-2}{2}x\right),\quad x\in\R,
\]
from which we observe that $\varphi(0)=(p/2)^\frac{1}{p-2}$.




\bigskip

We recall the following uniqueness result.

\begin{theorem}[{\cite[Theorem 1.3]{AgostinhoCorreiaTavares} $\&$ \cite[Proposition 1.17-1]{AgostinhoCorreiaTavares2}}]\label{thm:uniqueness}
For every $\lambda>0$, there exists a unique positive action ground-state solution $u^\lambda$ of \eqref{StationaryNLS_Chapter5}. Moreover:
\begin{enumerate}
\item In the $\mathcal{T}$-graph, $u^\lambda$ is symmetric and stricly decreasing in the half-lines, being increasing in the pendant, with a global maximum at the tip.
\item In the tadpole graph, $u^\lambda$ is strictly decreasing in the half-line; it is  symmetric in the loop with respect to the middle point $x=1$, being strictly increasing in $[0,1]$.
\end{enumerate}
\end{theorem}


To state further properties, we work with the rescaled ground-state $u_\ell(x)=\ell^\frac{2}{p-2}u^{\lambda}(\ell x)=\lambda^\frac{1}{p-2}u^{\lambda}(\sqrt{\lambda}x)$, where $\ell=\sqrt{\lambda}$, which solves
\[
-u_\ell''+u_\ell=|u_\ell|^{p-1}u_\ell \text{ in } \mathcal{H}_\ell.
\]
For both graphs, we denote by $u_h=u_{h,\ell}$ the solution on the half-lines, which are identified with $[0,\infty)$, and $u_\kappa=u_{\kappa,\ell}$ the solution on the pendant (on $\mathcal{T}_\ell$) and on the half-loop (on $\mathcal{G}_\ell$), identified with the interval $[0,\ell]$).  We have the following result, whose proof can be found in \cite{AgostinhoCorreiaTavares,AgostinhoCorreiaTavares2} (more precisely, by combining the uniqueness statements written above with Lemma 2.1 of the second paper).
\begin{theorem}\label{thm:description_edge_by_edge}
Under the previous notation, there exists a \emph{unique} $y=y(p,\ell)>0$ such that
\begin{enumerate}
\item for each half-line $h$, $u_h(x)=\varphi(x+y)$;
\item defining $z=z(p,\ell):=\varphi(y)=\varphi(-y) \in\left(0,(p / 2)^{1 /(p-2)}\right)$, on the compact edge identified with $[0,\ell]$, $u_\kappa$ solves the overdetermined problem
\begin{equation}\label{eq:sol_finite_edge}
-u_\kappa''+u_\kappa=u_\kappa^{p-1} \text { in }[0, \ell], \quad u_\kappa(0)=z, \quad u_\kappa^{\prime}(0)=\theta \sqrt{2 f(z)}, \quad u_\kappa^{\prime}(\ell)=0,
\end{equation}
where $\theta=2$ in the $\mathcal{T}$-graph $\mathcal{T}_\ell$, and $\theta=1/2$ in the tadpole graph $\mathcal{G}_\ell$. In particular,
\begin{equation}\label{eq:hamilt}
    -\frac{1}{2}(u_\kappa')^2+f(u_\kappa)=(1-\theta^2)f(z)
\end{equation}
\end{enumerate}
Moreover,  $z(p,\ell)$ is uniquely determined by the identity
\[
 L(p,z(p,\ell))=\ell,
\]
where, for each $\theta>0$ and $p\in(2,\infty)$, $L(p,\cdot):\left(0,\left(\frac{p}{2}\right)^{\frac{1}{p-2}}\right) \rightarrow \mathbb{R}^{+}$ is the length function 
\begin{equation}\label{eq:Length}
L(p,z)=\frac{1}{\sqrt{2}} \int_z^{f_{2}^{-1}\left(\left(1-\theta^2\right) f(z)\right)} \frac{d t}{\sqrt{f(t)-\left(1-\theta^2\right) f(z)}}.
\end{equation}
% where $f_{2}=f|_{[1,\infty)}$. 
Finally, assumption (H) holds, that is, there exists a constant $C_p>0$ for which
$$
\frac{1}{C_p}\leq \|u_\ell\|_{H^1(\mathcal{G})}\leq C_p.
$$
\end{theorem}
The length function was introduced in \cite[Definition 2.7]{AgostinhoCorreiaTavares2} (see also \cite[Definition 2.2]{AgostinhoCorreiaTavares} for the $\mathcal{T}$-graph case), corresponding to an explicit expression of  the length of the interval for increasing solutions of \eqref{eq:sol_finite_edge} written only in terms of the initial data. From \cite[Proposition 2.8]{AgostinhoCorreiaTavares2}, we have that
\begin{equation}\label{eq:asymptotic_L}
\lim_{z\to 0^+} L(p,z)=+\infty\quad \text{ and } \quad \lim_{z\to (p/2)^\frac{1}{p-2}} L(p,z)=0
\end{equation}
whenever $\theta>0$, being strictly decreasing for $\theta\in (0,2]$ (which includes the case of the $\mathcal{T}$ and tadpole graphs). 
{
\begin{remark} \label{rem:theta} Even though, for the purpose of this paper, only the cases $\theta=2,\frac{1}{2}$ matter, having in mind future extensions to other graphs, we keep in many statements an arbitrary $\theta>0$, whenever the result is true in such general setting. In the class of regular single-knot graphs introduced in \cite{AgostinhoCorreiaTavares2},  consisting of graphs with $H$ half-lines, $P$ pendants and $L$ loops, all attached to the same vertex, the solutions on the compact edges satisfy \eqref{eq:sol_finite_edge}, for an \emph{incidence index related to} $H$, $L$, $P$ and the monotonicity of the solution on the half-lines. For more details, we refer to \cite{AgostinhoCorreiaTavares2}, in particular to equation (1.8) therein.
\end{remark}
}

For the purpose of studying orbital stability (in particular in applying the {Vakhitov--Kolokolov stability criterion}, see the introduction or Theorem \ref{th:5.27} above), we also need to recall the following. 

\begin{lemma}  \label{lemma:L'}
	For $\theta>0$ and $z\in \left(0,(p/2)^{1/(p-2)}\right)$,
	\begin{align}
		\sqrt{2}L(p,z)\left((1-\theta^2)\right.&f(z)-\left.f(1)\right)=-2\theta\frac{(f(z)-f(1))\sqrt{f(z)}}{f'(z)} \nonumber \\
		&-\int_z^{f_2^{-1}\left((1-\theta^2)f(z)\right)}\left(3-2\frac{(f(t)-f(1))}{f'(t)^2}f''(t)\right)\sqrt{f(t)-(1-\theta^2)f(z)}dt\label{eqn.LDiffForm1}
	\end{align}
	and, taking derivatives in $z$,
	\begin{align}
&\sqrt{2}\frac{\partial L}{\partial z}(p,z)\left((1-\theta^2)f(z)-f(1)\right)=\theta\frac{f(1)}{\sqrt{f(z)}}+(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{A(t)dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}\label{H_p(z,theta)NotSingular}\\
		&=\frac{\theta\left(f(1)-2(1-\theta^2)A(z)f(z)\right)}{\sqrt{f(z)}}-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{\rho(t)}{f'(t)^4}\sqrt{f(t)-(1-\theta^2)f(z)}dt,\noindent
	\end{align}
	where:
	\begin{itemize}
	\item $A:\R^+\to \R$ is defined by
	\begin{equation*}
A(t)=\frac{1}{2}-\frac{(f(t)-f(1))f''(t)}{{f'}^2(t)},
	\end{equation*}
	having a continuous extension to $\mathbb{R}^{+}$ (still denoted by $A$), with the following properties: 
    \[
    A(t)>0 \text{ for } t \in(0,1),\ A(t)<0 \text{ for } t \in(1,+\infty),\text{ and } A(1)=0. 
    \]
    Moreover, $\lim_{t\to 0^+} t^2A(t)=f(1)$ and $\lim _{t \rightarrow \infty} A_p(t)=-\frac{p-2}{2 p}<0$.
	\item $\rho:\R^+\setminus\{1\}\to\R$ is defined by 
    \[
    \rho(t)=-3f''(t)f'(t)^2+6(f(t)-f(1))f''(t)^2-2(f(t)-f(1))f'''(t)f'(t),
    \]
    and satisfies $\rho(t)<0$ for $t\neq 1$, and $\lim_{t\to 0^+}\rho(t)=-6f(1)$.
	\end{itemize}

    \smallbreak
	 In particular, the maps $(p,z)\mapsto L(p,z),\ \frac{\partial L}{\partial z}(p,z)$ are continuous. Finally, for $\theta\in (0,2]$, $\frac{\partial L}{\partial z}(p,z)<0$.
\end{lemma}
\begin{proof}
The identities involving $L$ and its derivative correspond to Lemma 2.10, Lemma 2.11 and Proposition 2.12 in \cite{AgostinhoCorreiaTavares2}. Regarding the continuity of $L(p,z)$ in $p$ and $z$, as we are away from $t=0$ and the integrand is uniformly bounded, the right hand side of \eqref{eqn.LDiffForm1} is continuous in both variables. Since $(1-\theta^2)f(z)-f(1)$ does not vanish (it is negative), it follows that $(p,z)\mapsto L(p,z)$ is continuous. 

As for the continuity of $\frac{\partial L}{\partial z}(p,z)$, again from the fact that $(1-\theta^2)f(z)-f(1)<0$, we just need to check that the right-hand-side of \eqref{H_p(z,theta)NotSingular} is continuous;	for that,  it is enough to show that $\lim\limits_{t\to1}\frac{\rho(t)}{f'(t)^4}$ exists and is finite. But
	$$\lim_{t\to1}\frac{\rho(t)}{f'(t)^4}=\lim_{t\to1}-\frac{(p-2)^3(p^2+p-2)(t-1)^4+o((t-1)^5)}{(p-2)^4(t-1)^4+o((t-1)^5)}=-\frac{p^2+p-2}{p-2}, $$
	which concludes the proof. Finally, the fact that $\frac{\partial L}{\partial z}(p, z)<0$, although not explicitly stated in  \cite[Proposition 2.8]{AgostinhoCorreiaTavares2} (which only mentions strict monotonicity of $L$), is included in its proof. 
\end{proof}






With the aid of this result, we are able to study the variation of $y(p,\ell)$ and $z(p,\ell)$ with respect to $\ell$.

\begin{lemma}\label{cor:4.2.Temp}
	 The map $(p,\ell)\mapsto (y(p,\ell),z(p,\ell))$ is continuous, $C^1$ in $\ell$, with\footnote{$L^{-1}(p,\ell)$ denotes the inverse of $L$ in the $z$ variable, for each fixed $p$.} \begin{equation}\label{derz(p,ell)}
		\frac{\partial z}{\partial \ell}(p,\ell)=\frac{1}{\frac{\partial L}{\partial z}(L^{-1}(p,\ell))}<0,
	\end{equation}
	\begin{equation}\label{dery(p,ell)}
		\frac{\partial y}{\partial \ell}(p,\ell)=\frac{1}{\varphi'(y(p,\ell))}\frac{1}{\frac{\partial L}{\partial z}(L^{-1}(p,\ell))}>0.
	\end{equation}
\end{lemma}
\begin{proof}
	Since $\frac{\partial L}{\partial z}(p,z)<0$ and $\varphi'(x)<0$ for $x>0$, by the implicit function theorem, the maps $L^{-1}$ and $\varphi^{-1}$ are continuous in $p$ and $C^1$ in $\ell$. Therefore, the claimed smoothness of $y$ and $z$ follows from the identities
    $$z(p,\ell)=L^{-1}(p,\ell),\qquad y(p,\ell)=\varphi^{-1}(z(p,\ell)).$$ 
    The identities in \eqref{derz(p,ell)} and \eqref{dery(p,ell)} are obtained by direct differentiation with respect to $\ell$. The inequality in \eqref{derz(p,ell)} follows from Lemma \ref{lemma:L'}, and the inequality in  \eqref{dery(p,ell)} follows from Lemma \ref{lemma:L'} and the fact that $y(p,\ell)>0$.
\end{proof}


\subsection{Explicit expressions for the mass of action ground-states}\label{sec:explicit_mass}

In the previous paragraphs, we recalled an explicit expression for the length $\ell$ to the solutions of the overdetermined problem \eqref{eq:sol_finite_edge}. Here, for future purposes, we do the same for the mass of action ground-states, which we always denote (in both graphs) by
\[
(p,\lambda)\mapsto \Theta(p,\lambda):=\|u^\lambda\|_{L^2(\mathcal{H}_1)}^2.
\]
By scaling,  we have
\begin{equation}\label{ThetaScaled}
	\Theta(p,\lambda)=\lambda^\frac{6-p}{2(p-2)}\|u_\ell\|^2_{\mathcal{H}_\ell},
\end{equation} 
where $\lambda=\ell^2$. From now on, we denote by $\Theta_1:(2,\infty)\times(0,\infty)\mapsto\R^+$ the function defined by 
\begin{equation}\label{eq:Theta_1}
\Theta_1(p,\ell):=\norm{u_\ell}{2}{\mathcal{H}_\ell}^2.
\end{equation}

\begin{lemma} \label{lemma:Theta_1_expressions}
For each $p>2$, $z\in\left(0,\left(\frac{p}{2}\right)^\frac{1}{p-2}\right)$, and $\theta>0$, define $\mu_1(p,z,\theta)$ and $\mu_2(p,z)$ by
\begin{equation}\label{mu_functions}
    \mu_1(p,z,\theta)=\frac{1}{\sqrt{2}}\int_{z}^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{t^2dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}\quad\text{and}\quad\mu_2(p,z)=\frac{1}{\sqrt{2}}\int_0^z\frac{t^2dt}{\sqrt{f(t)}}.
\end{equation}
Then:
\begin{enumerate}
\item In the $\mathcal{T}$-graph $\mathcal{T}_\ell$, 
\begin{equation}\label{Theta_1_T'}
	\Theta_1(p,\ell)=\Theta_1(p,z(p,\ell))=\mu_1\left(p,z(p,\ell),2\right)+2\mu_2(p,z(p,\ell)).
    %\Theta_1(p,\ell)=\nu_2(p,z(p,\ell)):=\mu_1\left(p,z(p,\ell),2\right)+2\mu_2(p,z(p,\ell)).
\end{equation}
\item In the tadpole graph $\mathcal{G}_1$,
\begin{equation}\label{Theta_1_TADPOLE'}
	%\Theta_1(p,\ell)=\nu_1(p,z(p,\ell)):=2\mu_1\left(p,z(p,\ell),\frac{1}{2}\right)+\mu_2(p,z(p,\ell)).
    \Theta_1(p,\ell)=\Theta_1(p,z(p,\ell))=2\mu_1\left(p,z(p,\ell),\frac{1}{2}\right)+\mu_2(p,z(p,\ell)).
\end{equation}
\end{enumerate}
\end{lemma}
\begin{proof}
By Theorem \ref{thm:description_edge_by_edge}, using, in each edge, the change of variable $t=u(x)$ (which is possible, by the monotonicity of the solutions), we can rewrite the function $\Theta_1$ in $\mathcal{T}_\ell$ as
\begin{align}\label{Theta_1_T}
	\Theta_1(p,\ell)&=\int_0^\ell u^2_{\ell,h}(x)dx+2\int_0^\infty u^2_{\ell,\kappa}(x)dx\nonumber\\
	&=\frac{1}{\sqrt{2}}\int_{z(p,\ell)}^{f_{2}^{-1}\left(-3f(z(p,\ell))\right)}\frac{t^2dt}{\sqrt{f(t)+3f(z(p,\ell))}}+\frac{2}{\sqrt{2}}\int_0^{z(p,\ell)}\frac{t^2}{\sqrt{f(t)}}dt
\end{align}
Similarly, in the tadpole $\G_\ell$,
\begin{align}\label{Theta_1_TADPOLE}
	\Theta_1(p,\ell)&=2\int_0^\ell u^2_{\ell,\kappa}(x)dx+\int_0^\infty u^2_{\ell,h}(x)dx\nonumber\\
	&=\frac{2}{\sqrt{2}}\int_{z(p,\ell)}^{f_{2}^{-1}\left(\frac{3}{4}f(z(p,\ell))\right)}\frac{t^2dt}{\sqrt{f(t)-\frac{3}{4}f(z(p,\ell))}}+\frac{1}{\sqrt{2}}\int_0^{z(p,\ell)}\frac{t^2}{\sqrt{f(t)}}dt.
\end{align}\qedhere
\end{proof}

\begin{lemma}[Regularity and expressions of $\frac{\partial \mu_1}{\partial z}$ and $\frac{\partial \mu_2}{\partial z}$]\label{lemma:mu_1reg}
	Fix $\theta\in(0,\infty)$ and $0< z<\left(\frac{p}{2}\right)^\frac{1}{p-2}$. We have
    \begin{equation}\label{mu2DerAux}
		\sqrt{2}\frac{\partial \mu_2}{\partial z}(p,z)=\frac{z^2}{\sqrt{f(z)}}.
	\end{equation}
    Moreover,
    \begin{align}
		&\sqrt{2}\mu_1(p,z,\theta) \left((1-\theta^2)f(z)-f(1)\right)=-2\theta z^2\frac{(f(z)-f(1))}{f'(z)}\sqrt{f(z)}\nonumber\\
		-&\int_z^{f_{2}^{-1} \left((1-\theta^2)f(z)\right)}g(t)\sqrt{f(t)-(1-\theta^2)f(z)}dt,\label{eqn.4.21}
	\end{align}
    and
    \begin{align}
		\sqrt{2}\frac{\partial\mu_1}{\partial z}(p,z,\theta)&((1-\theta^2)f(z)-f(1))=\theta z^2\frac{f(1)}{\sqrt{f(z)}}\nonumber\\
        &-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}},\label{mu1DerAux}
	\end{align}
	where, for every $p>2$, the function $g:\R\to\R$ is given by
	$$g(t)=3t^2-2t^2\frac{(f(t)-f(1))}{f'(t)^2}f''(t)+4t\frac{(f(t)-f(1))}{f'(t)}.
    $$
    In particular, the map 
    $$(p,z)\mapsto \left(\mu_1(p,z,\theta),\ \frac{\partial \mu_1}{\partial z} (p,z,\theta), \mu_2(p,z,\theta),\ \frac{\partial \mu_2}{\partial z}(p,z,\theta)\right)$$ is continuous. 
\end{lemma}
\begin{proof}
	Fix $\theta\in(0,\infty)$. The continuity of $\mu_2$ follows easily from the Dominated Convergence Theorem. Since the integrand is integrable at the origin, we have $\frac{\partial\mu_2}{\partial z}(p,z)=\frac{z^2}{\sqrt{2f(z)}},$
	which is continuous in both variables. 

	As for $\mu_1$, we argue similarly to the proof of Lemma \ref{lemma:L'} (whose detailed computations, as recalled, are included in \cite{AgostinhoCorreiaTavares2}). We write
	\begin{align}\label{eqn.4.22_AUX}
		\sqrt{2}&\mu_1(p,z,\theta) \left((1-\theta^2)f(z)-f(1)\right)=-\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}t^2\sqrt{f(t)-(1-\theta^2)f(z)}dt\nonumber\\
		+&\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{(f(t)-f(1))t^2dt}{\sqrt{f(t)-(1-\theta^2)f(z)}},
	\end{align}
	and define $W:\R\setminus\{1\}\times\R\to\R$ by $W(x,y)=\frac{f(x)-f(1)}{f'(x)}x^2y$, which is of class $C^1$ in its domain and can be extended by continuity to $\R^2$. Consider now the curve $\gamma:\left[z,f^{-1}\left((1-\theta^2)f(z)\right)\right]\to \R^2$ defined by
	$\gamma(t)=(x(t),y(t))=\left(t,\sqrt{2}\sqrt{f(t)-(1-\theta^2)f(z)}\right),$
	which parametrizes the level curve $\Gamma$, $-y^2+f(x)=(1-\theta^2)f(z)$, for $y\geq0$.

	Then
	\begin{align*}
		-W(z,\theta\sqrt{2}\sqrt{f(z)})&=W\left(f^{-1}\left((1-\theta^2)f(z)\right),0\right)-W\left(z,\theta\sqrt{2}\sqrt{f(z)}\right)=\int_\Gamma 
		dW(x,y)\nonumber\\
		&=\int_\Gamma\frac{\partial}{\partial x}W(x,y)dx+\frac{\partial}{\partial y}W(x,y)dy\\
		&=\int_\Gamma y\left(2x\frac{f(x)-f(1)}{f'(x)}+x^2\left(1-\frac{f(x)-f(1)}{f'(x)^2}f''_p(x)\right)\right)dx+x^2\frac{f(x)-f(1)}{f'(x)}dy,
	\end{align*}
	and, taking $(x,y)=(x(t),y(t))=\gamma(t)$, we obtain
	\begin{align*}
		&\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}t^2\frac{f(t)-f(1)}{\sqrt{f(t)-(1-\theta^2)f(z)}}dt=-\sqrt{2}W(z,\theta\sqrt{2}\sqrt{f(z)})\\-&2\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\sqrt{f(t)-(1-\theta^2)f(z)}\left(2t\frac{f(t)-f(1)}{f'(t)}+t^2\left(1-\frac{f(t)-f(1)}{f'(t)^2}f''_p(t)\right)\right)dt.
	\end{align*}
Equation \eqref{eqn.4.21} follows from plugging  the previous expression into \eqref{eqn.4.22_AUX}. 

For each fixed $\theta>0$, the continuity of the map $(p,z)\mapsto \mu_1(p,z,\theta)$ will follow by the same kind of arguments as in Lemma \ref{lemma:L'}. Let us compute its derivative.  Differentiating both sides of \eqref{eqn.4.21} with respect to $z$, we obtain
	\begin{align*}
		\sqrt{2}\frac{\partial\mu_1}{\partial z}&(p,z,\theta)((1-\theta^2)f(z)-f(1))=-\sqrt{2}(1-\theta^2)f'(z)\mu_1(p,z,\theta)+\frac{d}{dz}\left(-2\theta z^2\sqrt{f(z)}\frac{f(z)-f(1)}{f'(z)}\right)\nonumber\\
		-&\frac{d}{dz}\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}g(t)\sqrt{f(t)-(1-\theta^2)f(z)}dt\nonumber\\
		&=-\sqrt{2}(1-\theta^2)f'(z)\mu_1(p,z,\theta)+\frac{d}{dz}\left(-2\theta z^2\sqrt{f(z)}\frac{f(z)-f(1)}{f'(z)}\right)+\theta g(z)\sqrt{f(z)}\nonumber\\
		+&(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\frac{g(t)}{2}\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}.
	\end{align*}


	Computing the derivative of the non-integral term in the previous expression and simplifying, we get
	\begin{align}\label{mu1DerAux}
		\sqrt{2}\frac{\partial\mu_1}{\partial z}&(p,z,\theta)((1-\theta^2)f(z)-f(1))=
		-\frac{\theta z^2(f(z)-f(1))}{\sqrt{f(z)}}+2\theta z^2\frac{(f(z)-f(1))\sqrt{f(z)}f''(z)}{{f'}(z)^2}\nonumber\\
		-&4\theta z\frac{(f(z)-f(1))\sqrt{f(z)}}{f'(z)}
		-2\theta z^2\sqrt{f(z)}+3\theta z^2\sqrt{f(z)}-2\theta z^2\frac{(f(z)-f(1))\sqrt{f(z)}f''(z)}{{f'}(z)^2}\nonumber\\
		+&4\theta z\frac{(f(z)-f(1))\sqrt{f(z)}}{f'(z)}-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}\nonumber\\
		&=\theta z^2\frac{f(1)}{\sqrt{f(z)}}-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}.
	\end{align}


	Now, we prove the continuity of the map $(p,z)\mapsto\frac{\partial\mu_1}{\partial z}(p,z,\theta)$. This is trivial in the case $\theta=1$; therefore, we assume $\theta\neq 1$ in what follows. 

	We consider the integral term in \eqref{mu1DerAux}. Integrating this term by parts with respect to $t$, we get
	\begin{equation}\label{New_Int_EXPRESSION}
		-\frac{\theta(2z^2-g(z))\sqrt{f(z)}}{f'(z)}-\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\frac{d}{dt}\left(\frac{2t^2-g(t)}{f'(t)}\right)\sqrt{f(t)-(1-\theta^2)f(z)}.
	\end{equation}
	The non-integral term is continuous in both variables. Now, we observe that integrand function in this new integral expression contains no singularities, since
	$$\lim\limits_{t\to1}\frac{d}{dt}\left(\frac{2t^2-g(t)}{f'(t)}\right)  =\lim\limits_{t\to1}\frac{(4t-g'(t))f'(t)-(2t^2-g(t))f''(t)}{f'(t)^2}=\frac{22-11p+p^2}{6(p-2)}. $$ 
    Consequently, the continuity of the integral term in \eqref{New_Int_EXPRESSION} follows from the Dominated Convergence Theorem, since the integrand is uniformly bounded in compact sets that are far away from zero. This finishes the proof.
\end{proof}



\begin{lemma}[Explicit expression of $\frac{\partial \Theta_1}{\partial z}$ in the $\mathcal{T}$ and tadpole graphs.]\label{lemma:4.7.Temp}
	Let $p>2$ and $ 0<z<\left(\frac{p}{2}\right)^\frac{1}{p-2}$, and let $\Theta_1$ be as in \eqref{eq:Theta_1}. Then
	\begin{enumerate}
    \item For the $\mathcal{T}$-graph ($\theta=2$):
    \begin{align*}
		\sqrt{2}\frac{\partial\Theta_1}{\partial z}(p,z)&\left(-3f(z)-f(1)\right)=-6z^2\sqrt{f(z)}\\
		+&3f'(z)\int_z^{f_{2}^{-1}\left(-3f(z)\right)}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)+3f(z)}}.
	\end{align*}
	\item For the tadpole graph ($\theta=1/2$):
    \begin{align*}
		\sqrt{2}\frac{\partial\Theta_1}{\partial z}\left(p,z\right)&\left(\frac{3}{4}f(z)-f(1)\right)=\frac{3}{4}z^2\sqrt{f(z)}\\
		-&\frac{3}{4}f'(z)\int_z^{f_{2}^{-1}\left(3f(z)/4\right)}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-\frac{3}{4}f(z)}}.
	\end{align*}
\end{enumerate}
    In particular, the map $(p,z)\mapsto \frac{\partial \Theta_1}{\partial z}(p,z)$ is continuous.
\end{lemma}
\begin{proof}
	Recalling the expression of $\Theta_1$ from Lemma \ref{lemma:Theta_1_expressions} in each graph, this is a direct consequence of Lemma \ref{lemma:mu_1reg}.
\end{proof}






\section{Grillakis-Shatah-Strauss theory in the $\mathcal{T}$ and tadpole graphs}\label{sec:GSS_particular}

In this section, we check that conditions $(A1)$, $(A2)$ and $(A3)$ from Section \ref{sec:GSS} are valid in the $\mathcal{T}$ graph $\mathcal{T}_1$ (terminal edge of length 1) and in the tadpole graph $\mathcal{G}_1$ (terminal loop of length 2). Recall that we can assume that $\ell=1$, up to a scaling.

\begin{lemma}\label{lemma:A1}
Let $\mathcal{H}_1$ be either the $\mathcal{T}$-graph $\mathcal{T}_1$ or the tadpole graph $\mathcal{G}_1$. Then, condition $(A_1)$ is satisfied.
\end{lemma}
\begin{proof}
The tadpole and $\mathcal{T}-$graphs are a part of a more general family of graphs, called starlike graphs. This family of graphs was introduced in \cite{cacciapuoti2017ground} and it consists of metric graphs with \textit{any} compact core and at least one half-line. In \cite[Proposition 2.2]{cacciapuoti2017ground} the authors prove, via fixed point arguments, that the IVP associated to the equation \eqref{NLSE_Chapter5} is locally well-posed in $H^1$ for any $p>2$. Moreover, due to energy and mass conservation, see \cite[Proposition 2.3]{cacciapuoti2017ground}, a global well-posedness result in $H^1$ is obtained for any $L^2$-subcritical power, see \cite[Theorem 2.3]{cacciapuoti2017ground}.
\end{proof}






Assumption $(A_2)$ concerns the existence of a regular curve of bound-states. Recall from Theorem \ref{thm:uniqueness} that in $\mathcal{H}_1$, for each $\lambda>0$, there exists exactly one positive action ground-state, which we denote by $u^\lambda$. 

\begin{lemma}\label{lemma:5.32}
	The curve $\lambda\in (0,\infty)\mapsto u^\lambda\in H^1(\mathcal{H}_1)$ is of class $C^1$. In particular, condition $(A_2)$ is satisfied.
\end{lemma}
\begin{proof}
	Recall from Theorem \ref{thm:description_edge_by_edge} the definition of $y(p,\ell)$ and $z(p,\ell)=\varphi(y(p,\ell))$. By Lemma \ref{cor:4.2.Temp}, these maps are $C^1$ in the variable $\ell$. Since $u_{h,\ell}$ is explicitly given as
    \[
    u_{h,\ell}(x)=\varphi(x+y(p,\ell)),
    \]
    the action ground-state depends on $\ell$ as a $C^1$ map. In the compact edge, $u_{\kappa,\ell}$ satisfies \eqref{eq:sol_finite_edge}, for which one has $C^1$ dependence on the parameters (see, for instance, \cite[Proposition 9.4]{amann1990ordinary}).  Finally, since $\ell=\sqrt{\lambda}$, the conclusion follows.
\end{proof}




The verification of $(A_3)$ is, as usual, much more delicate, and we dedicate the following section to it. 

\subsection{Spectral Analysis of $H_\lambda$: condition $(A_3)$}\label{AssumptionA_3}

The goal of this section is to prove that assumption $(A_3)$ holds true for both the tadpole and $\mathcal{T}$-graphs. Recalling that the length function $L$ is defined in \eqref{eq:Length}, we show the following. 


\begin{proposition}\label{prop:5.26}
Consider the metric graph $\mathcal{H}_1$. For $p>2$ fixed, set\footnote{{Observe that $\lambda^*$  depends on the considered graph through the parameter $\theta$ (recall formula \eqref{eq:Length}).}} $\lambda^*:=(L(p,1))^2$. For any interval $J\subset\R^+\setminus\{\lambda^*\}$, the operator $H_\lambda:X\to X'$ satisfies assumption $(A_3)$.
\end{proposition}



Here, we benefit from the fact that the curve $\lambda\mapsto u^\lambda$ consists of action ground-states. This makes the negative eigenvalue property particularly simple to analyze, see Lemma \ref{prop:5.43.Temp}. However, analyzing the kernel of $H_\lambda$ is the biggest challenge as it depends on the topology of the graph we are considering. Nonetheless, inspired by the work done in \cite{noja2020standing}, which treats the case $p=6$ in the tadpole graph, we are able to determine the kernel of $H_\lambda$ (for all but one frequency $\lambda^*$). 


The argument of the proof of Proposition \ref{prop:5.26} is almost exactly the same for both graphs, except for the analysis of the zero eigenvalue of $H_\lambda$, see the proof of Lemma \ref{prop:5.43.Temp} below. We start with the results that are common to both graphs.

\smallbreak

We begin by writing explicitly the operator $H_\lambda$. Take $X=H^1(\mathcal{H}_1;\C)\simeq H^1(\mathcal{H}_1)\times H^1(\mathcal{H}_1)$ with the usual (real) inner product and, for any, $u\in X$,  write $u\simeq\left(\Re(u),\Im(u)\right)$, where $\Re$ and $\Im$ denote the real and imaginary parts of $u$, respectively. For each $\lambda>0$, let $u^\lambda\simeq(u^\lambda,0)$ be the positive action ground-state in $\mathcal{H}_1$. Then, for any $v,w\in H^1(\mathcal{H}_1;\C)$, $H_\lambda$ is given by:
\begin{align}\label{LinearizedOperatorExplicit}
	\langle H_\lambda v,w\rangle=\langle S_\lambda''(u_\lambda,\mathcal{H}_1)v,w\rangle&=\langle \mathcal{L}^{-}_\lambda v,w\rangle+\langle \mathcal{L}^{+}_\lambda v,w\rangle,
\end{align}
where the operators $\mathcal{L}^{-}_\lambda, \mathcal{L}^{+}_\lambda:X\to X'$ are defined by:
\begin{equation}\label{L-Operator}
	\langle \mathcal{L}^{-}_\lambda v,w\rangle=\int_{\mathcal{H}_1}\Re(v')\Re(w')+(\lambda-(p-1)|{u^\lambda}|^{p-2})\Re(v)\Re(w)dx,\ \text{for all}\ w\in X,
\end{equation}
and
\begin{equation}\label{L+Operator}
	\langle \mathcal{L}^{+}_\lambda v,w\rangle=\int_{\mathcal{H}_1}\Im(v')\Im(w')+(\lambda-|{u^\lambda}|^{p-2})\Im(v)\Im(w)dx,\ \text{for all}\ w\in X.
\end{equation}
It is classical to show that $H_\lambda:X\to X'$ is self-adjoint (i.e., by taking the canonical identification $I:X\to X'$ via Riesz' representation theorem, $I^{-1}H_\lambda$ is a bounded self-adjoint operator in the standard sense).

Under the previous identification, we define the \textit{spectrum} of the operator $H_\lambda$ by
\begin{equation}\label{Spectrum}
	\sigma(H_\lambda):=\left\{\lambda\in\C: I^{-1}H_\lambda-\lambda\ \text{is not invertible}\right\}.
\end{equation}
Since $H_\lambda$ is self-adjoint, $\sigma(H_\lambda)\subset\R$, and we split the spectrum into the disjoint union $\sigma(H_\lambda)=\sigma_{disc}(H_\lambda)\cup\sigma_{ess}(H_\lambda)$, where
\begin{equation}\label{DiscreteSpec}
	\sigma_{disc}(H_\lambda)=\left\{\nu\in\R: \nu\ \text{is an eigenvalue of}\ H_\lambda\ \text{with finite multiplicity}\right\}
\end{equation}
is the \textit{discrete spectrum} and 
\begin{equation}\label{EssentialSpec}
	\sigma_{ess}(H_\lambda)=\sigma(H_\lambda)\setminus\sigma_{disc}(H_\lambda)
\end{equation}
is the \textit{essential spectrum}. We analyze the spectrum of $H_\lambda$ by examining the spectra of $\mathcal{L}^{-}_\lambda$ and $\mathcal{L}^{+}_\lambda$ separately. We start with the essential spectrum. 

\begin{lemma}\label{prop:5.40.Temp}
	For any $\lambda>0$,  $\sigma_{\text{ess}}\left(\mathcal{L}^{-}_\lambda\right)=\sigma_{\text{ess}}\left(\mathcal{L}^{+}_\lambda\right)=\sigma_{\text{ess}}\left(-\frac{d^2}{dx^2}+\lambda\right)=[\lambda,\infty).$ In particular, $\sigma_{\text{ess}}\left(H_\lambda\right)=[\lambda,\infty)$.
\end{lemma}
\begin{proof}
	We claim that $\mathcal{L}^{-}_\lambda$ and $\mathcal{L}^{+}_\lambda$ are compact perturbations of the operator $-\frac{d^2}{dx^2}+\lambda$, in which case the first two equalities will follow from Weyl's Theorem, see \cite[Section XIII.4-Example 3]{reed1978iv}. Finally, we note that the last equality holds as an adaptation of \cite[Theorem 2.3.5]{hofmann2021}. To prove the claim, it is enough to show that the operator $K:H^1(\mathcal{H}_1)\to H^1(\mathcal{H}_1)'$ defined by
	$$\langle K(u),v\rangle=\int_{\mathcal{H}_1}|u^\lambda|^{p-2}uvdx,\ \text{for all}\ v\in H^1(\mathcal{H}_1),$$
	is compact. We note that through the identification of $L^2(\mathcal{H}_1)$ with its dual and the exponential decay of the real line soliton $\varphi$, the operator $K$ can be understood, on each edge, as $K:H^1(\mathcal{H}_1)\to L^2(\mathcal{H}_1)$ and defined as $K(u)=|u^\lambda|^{p-2}u$.

	 On the compact core of the graph, by Rellich-Kondrachov embedding theorem,  the operator $K$ is compact. We show that it is compact on the half-lines. Take  $(u_n)_{n\in\N}$ to be a bounded sequence in $H^1(\R^+)$ such that $u_n \rightharpoonup u^*$ weakly in $H^1(\R^+)$, and let $M>0$ be such that $\|u_n\|_{H^1(\R^+)},\|u\|_{H^1(\R^+)}\leq C$. Denote $g:=|u^\lambda|^{p-2}\in W^{1,\infty}(\R^+)$, and recall that $u^\lambda$ is a decreasing portion of the real line soliton (see Theorem \ref{thm:description_edge_by_edge}), which is known to have exponential decay as $|x|\to \infty$. Then
	 \begin{align*}
	 	&\int_0^\infty\left|{g u_n-g u^*}\right|^2dx\leq g (0)\int_0^r\left|{u_n-u^*}\right|^2dx+\int_r^\infty\left|{g(u_n-u^*)}\right|^2dx\leq g (0)\int_0^r\left|{u_n-u^*}\right|^2dx+g (r)2M.
	 \end{align*}
By taking the limit as $n\to \infty$, and then as $r\to \infty$, we deduce that $gu_n\to gu^*$ in $L^2(\R^+)$ as $n\to \infty$.
\end{proof}

We now analyze the discrete spectrum of $\mathcal{L}^{-}_\lambda$ and $\mathcal{L}^{+}_\lambda$. Observe that, due to the exponential decay of the action ground-state on half-lines (Theorem \ref{thm:description_edge_by_edge}), the discrete spectrum of the operators $\mathcal{L}^{-}_\lambda$ and $\mathcal{L}^{+}_\lambda$ consists of a finite number of isolated eigenvalues. This was shown in \cite{kairzhan2018nonlinear}, in the context of star graphs, and referred often throughout the literature for other classes of graphs. For instance, \cite{noja2020standing}, for tadpole graphs, and, more generally, in \cite{cacciapuoti2017ground}, for starlike graphs. To analyze the discrete spectrum in more detail, we focus on understanding the eigenvalue problem $H_\lambda\chi=\nu\chi$, where  $\chi=(\chi_1,\chi_2)\in X$. This problem is expressed as follows:
\begin{equation}\label{eigenvalueProbs}
	\begin{cases}
		\int_{\mathcal{H}_1}\chi_1'\Re(w')+\lambda\chi_1\Re(w)-(p-1)|{u^\lambda}|^{p-2}\chi_1\Re(w)dx=\nu\int_\G\chi_1\Re(w)dx,\\
		\int_{\mathcal{H}_1}\chi_2'\Im(w')+\lambda\chi_2\Im(w)-|{u^\lambda}|^{p-2}\chi_2\Im(w)dx=\nu\int_\G\chi_2\Im(w)dx,
	\end{cases}\ \text{for any}\ w\in X.
\end{equation}

Let us first focus on (real) solutions $\chi_2\in H^1(\mathcal{H}_1)$ of the second equation in \eqref{eigenvalueProbs}. 
\begin{lemma}\label{lemma:5.41.Temp}
	For any $\lambda>0$, $\sigma_{disc}\left(\mathcal{L}^{+}_\lambda\right)\subseteq[0,\infty)$ and $\text{Ker}\left(\mathcal{L}^{+}_\lambda\right)=\text{span}\left\{u^\lambda\right\}$.
\end{lemma}
\begin{proof}
	We start by observing that $0$ is indeed an eigenvalue of $H_\lambda$ (and also $\mathcal{L}^{+}_\lambda$), since $w=(0,u^\lambda)\simeq iu^\lambda$ solves \eqref{eigenvalueProbs} with $\nu=0$.

	Next, we show that the first eigenvalue $\nu_1$ has to be zero. By the variational characterization of the first eigenvalue we have that
	\begin{equation}\label{MinimizationAux}
		\nu_1=\inf_{\chi_2\in H^1(\mathcal{H}_1)}\left\{\int_{\mathcal{H}_1}{\chi_2'}^2+\left(\lambda-{|u^\lambda|}^{p-2}\right)\chi_2^2dx: \int_{\mathcal{H}_1}\chi_2^2dx=1\right\}.
	\end{equation}
and any associated eigenfunction $\chi_2$ is therefore non-negative. Testing \eqref{eigenvalueProbs} with $w=(0,u^\lambda)$ and integrating by parts, we find that, since $u^\lambda>0$ is a bound-state,
	\begin{equation*}
		0=\int_{\mathcal{H}_1}\left(-({u^\lambda})''+\lambda u^\lambda-{(u^\lambda)}^{p-1}\right)\chi_2dx=\nu_1\int_{\mathcal{H}_1} u^\lambda\chi_2dx.
	\end{equation*}
which implies that $\nu_1=0$.

	To finish the proof, observe that $\nu_1=0$, being the first eigenvalue of $\mathcal{L}^{+}_\lambda$, is a simple eigenvalue, and thus $\text{Ker}(\mathcal{L}^{+}_\lambda)=\text{span}\left\{u^\lambda\right\}$.
\end{proof}

To finish the spectral analysis of $H_\lambda$, we need to look carefully into the spectrum of  $\mathcal{L}^{-}_\lambda$. We will need the following concepts.

\begin{definition}[\textit{Morse and Nullity Index}]%\label{Indices}
	Suppose that $A:X\to X'$ is a linear operator. We define \setlist{nolistsep}
	\begin{itemize}[noitemsep]
		\item the \textit{Morse Index} of $A$, as
		$ n(A):=\#\left\{\nu\in\R: \nu\ \text{is a negative eigenvalue of}\ A\right\}.$
		\item the \textit{Nullity Index} of $A$, as the multiplicity of the zero eigenvalue of $A$, and denote it by $z(A)$. 
	\end{itemize}
\end{definition}

With the above definition,
\begin{lemma}\label{lemma:5.44.Temp}
	For each $\lambda>0$, $n(H_\lambda)=n(\mathcal{L}^{-}_\lambda)=1$.
\end{lemma}
\begin{proof}
	Firstly, recall that $u_\lambda\simeq (u^\lambda,0)\in X$ is a (real) bound-state, so
	\begin{equation*}
		\langle H_\lambda u_\lambda,u_\lambda\rangle=\langle\mathcal{L}^{-}_\lambda u_\lambda,u_\lambda\rangle=\int_{\mathcal{H}_1}(-{u^\lambda}''+\lambda u^\lambda-(p-1){|u^\lambda|}^{p-1})u^\lambda dx=-(p-2)\|u^\lambda\|^p_{L^p(\mathcal{H}_1)}<0.
	\end{equation*}
	Consequently, $n(H_\lambda)\geq1$.

	To show the reverse inequality, observe that $u^\lambda$ is the (unique) solution of the minimization problem:
	\begin{equation*}
		\min\left\{I_\lambda(u,\mathcal{H}_1):=\frac{1}{2}\int_{\mathcal{H}_1}|u'|^2+\lambda |u|^2dx:\ R(u,\mathcal{H}_1):=\frac{1}{p}\int_{\mathcal{H}_1}|u|^pdx=\mu\right\}
	\end{equation*}
	for some suitable $\mu>0$ (for the $\mathcal{T}$-graph see \cite[Section 3.1]{AgostinhoCorreiaTavares}, for the tadpole see \cite[proof of Proposition 1.17]{AgostinhoCorreiaTavares}). Additionally, note that the action functional $S_\lambda$ can be written as $S_\lambda=I_\lambda-R$. Take the manifold of codimension one $R_\mu:=R^{-1}(\cdot,\mathcal{H}_1)\{\mu\}\subset X$, associated to the constraint $R(\cdot,\mathcal{H}_1)=\mu$.

Consider $v\in T_{u_\lambda}R_\mu$, the tangent space of $R_\mu$ at $u_\lambda$. Define a smooth curve $\gamma:[-1,1]\to R_\mu$ such that $\gamma(0)=u_\lambda$ and $\gamma'(0)=v$. Since $I_\lambda$ is of class $C^2$ in $X$ and $R$ is constant along $\gamma$, then $S_\lambda\circ \gamma=(I_\lambda-R)\circ \gamma$ is (twice) differentiable at $t=0$ and
	$$\frac{d^2}{dt^2}\left(S_\lambda\circ\gamma\right)\big|_{t=0}=\langle S_\lambda''(\Phi_\lambda)v,v\rangle=\langle I_\lambda''(\Phi_\lambda)v,v\rangle=\frac{d^2}{dt^2}\left(I_\lambda\circ\gamma\right)\big|_{t=0}=\langle I_\lambda''(\Phi_\lambda)v,v\rangle\geq0,$$
by minimality of $u^\lambda=(u^\lambda,0)$. Since $R_\mu$ has codimension $1$, we deduce that $n(H_\lambda)\leq 1$. Finally, from Lemma \ref{lemma:5.41.Temp}, we have that $n(H_\lambda)=n(\mathcal{L}^{-}_\lambda)$.
\end{proof}



\begin{lemma}\label{prop:5.43.Temp}
	Let $L$ be the length function defined in \eqref{eq:Length} (with  $\theta=2$ in the $\mathcal{T}$-graph $\mathcal{T}_\ell$, and $\theta=1/2$ in the tadpole graph $\mathcal{G}_\ell$). For each $\lambda>0$ with  $\lambda\neq\lambda^*:=(L_1(p,1))^2$, we have $z\left(\mathcal{L}^{-}_\lambda\right)=0$.
\end{lemma}

Assuming Lemma \ref{prop:5.43.Temp} is true, we show that assumption $(A_3)$ holds.
\begin{proof}[Proof of Proposition \ref{prop:5.26}]
	By Lemmas \ref{lemma:5.41.Temp}, \ref{lemma:5.44.Temp} and \ref{prop:5.43.Temp}, we have that $H_\lambda$ has exactly one negative eigenvalue, and its kernel is generated by $iu^\lambda$. Recalling that eigenvalues are in finite number, it follows from Lemma \ref{prop:5.40.Temp} that the remaining part of the spectrum is bounded away from zero.
\end{proof}

We now focus on proving Lemma \ref{prop:5.43.Temp}, following the arguments developed in \cite{noja2020standing} for the tadpole graph and $p=6$. We analyze the zero eigenvalue of $\mathcal{L}^{-}_\lambda$. 

\begin{remark}\label{rem:NK} Observe that, whenever $u\in H^1(\G)$ is a zero-eigenvector for $\mathcal{L}^-_\lambda$, then $u\in H^2_{\text{NK}}(\G)$, i.e., the restriction of $u$ to each edge, $u_e$, belongs to $H^2$ in each edge, and $u$ satisfies the Neumann-Kirchoff conditions at each vertex:
$$
\sum_{e \prec v} \frac{d u_e}{d x_e}(v)=0
$$
where $e \prec \mathbf{v}$ means that the edge $e$ is incident to the vertex $\mathbf{v}$, and the derivatives are taken in the inward direction of each edge.  
\end{remark}


Since the topology of the $\mathcal{T}$ and the tadpole graphs are different, we will need to split the proof of Lemma \ref{prop:5.43.Temp} in two parts, one for each graph.
Before that, we present an auxiliary result concerning the half-line.

\begin{lemma}\label{lemma:Half-lineKernel}
Take $y\geq 0$, and let $\varphi$ be the even real line soliton. Any non-trivial solution in $H^1$ to the equation
	\begin{equation}\label{eqn.LinearizedHalf-line}
		-v''+v-(p-1)\varphi(x+y)^{p-2}v=0,\ \text{in}\ \R^+,
	\end{equation}
	is of the form $v(x)=\alpha\varphi'(x+y)$, for some  $\alpha\in\R$. 
\end{lemma}
\begin{proof}
	We follow \cite[Proposition 2.8b)]{weinstein1985modulational}. Without loss of generality, we assume $y=0$, being the proof in the general case completely analogous. 

	First of all, differentiating the equation $-\varphi''+\varphi=\varphi^p$, we get that $\varphi'$ is a solution of \eqref{eqn.LinearizedHalf-line}. Let $v$ be a solution to the ODE \eqref{eqn.LinearizedHalf-line}, with $v(0)=1$ and $v'(0)=0$;. 
    In particular, any solution to \eqref{eqn.LinearizedHalf-line} is of the form
	\[
	\alpha\varphi'+\beta v,\qquad \text{ for some } \alpha,\beta\in \R.
	\]
	We show that $v\notin H^1$, which concludes our proof. Consider the Wronskian of the two solutions, 
	$$ 
W(\varphi',v)(x)=\text{det}\begin{pmatrix}
		\varphi'(x) & v(x) \\ \varphi''(x) & v'(x)
	\end{pmatrix}=\varphi'(x)v'(x)-v(x)\varphi''(x). $$
	Since both $v$ and $\varphi'$ are solutions of \eqref{eqn.LinearizedHalf-line}, we get
	$$ \frac{d}{dx} W(\varphi',v)(x)=\frac{d}{dx}\left(\varphi'(x)v'(x)-v(x)\varphi''(x)\right)=\varphi'(x)v''(x)-v(x)\varphi'''(x)=0,$$
so $W(\varphi',v)(x)\equiv-\varphi''(0)$.

	Observe now that, for $x>0$, we have
	$$ \left(\frac{v}{\varphi'}\right)'(x)=\frac{W(\varphi',v)(x)}{{\varphi'}^2(x)}=\frac{-\varphi''(0)}{{\varphi'}^2(x)}.$$
Fixing $x_0$ such that $\varphi(x_0)=1$, we have $\varphi''>0$ for $x\geq x_0$. Then
	\begin{equation*}
		\frac{v(x)}{\varphi'(x)}-\frac{v(x_0)}{\varphi'(x_0)}=-\varphi''(0)\int_{x_0}^x\frac{dt}{{\varphi'}^2(t)} \quad \mbox{that is, }\quad v(x)=v(x_0)\frac{\varphi'(x)}{\varphi'(x_0)}-\varphi''(0)\varphi'(x)\int_{x_0}^x\frac{dt}{{\varphi'}^2(t)},
	\end{equation*}
As $x\to\infty$, since $\varphi(x)=\left(\frac{p}{2}\right)^\frac{1}{p-2}\sech^{\frac{2}{p-2}}\left(\frac{p-2}{2}x\right),$ we find that $v(x)\to \infty$ and thus $v\not\in H^1$.
\end{proof}


Next, we study the Nullity Index in $\mathcal{T}_1$.

\begin{proof}[Proof of Lemma \ref{prop:5.43.Temp} for the $\mathcal{T}$-graph $\mathcal{T}_1$.]
	We consider a solution $\Gamma\in H^1(\mathcal{T}_1)$ to the eigenvalue problem $\mathcal{L}^{-}_\lambda\Gamma=0$, and show that $\Gamma=0$.  Denote by $\Gamma_1,\Gamma_2$ the restriction of $\Gamma$ to each half-line, and $\Gamma_3$ the restriction of $\Gamma$ to the pendant. Observe that, by Remark \ref{rem:NK}, $\Gamma\in H^2_{\text{NK}}(\mathcal{T}_1)$.	

    \medskip
	     \noindent\textit{Step 1. Discussion of the kernel of $\mathcal{L}^{-}_\lambda$ in terms of the parameter $\ell$.}

	Recall the scaling
	$u^\lambda(x)=\lambda^{\frac{1}{p-2}}u_\ell(\lambda^{1/2}x)$ and define, for $\ell=\lambda^\frac{1}{2}$, $\gamma=(\gamma_1,\gamma_2,\gamma_3)\in H^2_{\text{NK}}(\mathcal{T}_\ell)$ such that
	\begin{equation*}
		\begin{cases}
			\Gamma_i(x)=\gamma_i(\lambda^\frac{1}{2} x),\ x\in[0,\infty),\ i=1,2,\\
			\Gamma_3(x)=\gamma_3(\lambda^\frac{1}{2} x),\ x\in[0,\ell].
		\end{cases}
	\end{equation*}
	Then, the  problem $\mathcal{L}^{-}_\lambda\Gamma=0$ can be written equivalently in terms of $\gamma$ as
	\begin{equation}\label{eqn.4.eigenvalueprobTGRAPH}
		\begin{cases}
			-\gamma_i''+\gamma_i-(p-1)u_{\ell,i}^{p-2}\gamma_i=0,\ \text{in}\ [0,\infty),\ i=1,2;\\
			-\gamma_3''+\gamma_3-(p-1)u_{\ell,3}^{p-2}\gamma_3=0,\ \text{in}\ [0,\ell],
		\end{cases}\text{with}\ \ \begin{cases}
			\gamma_1(0)=\gamma_2(0)=\gamma_3(0),\\
			\gamma_1'(0)+\gamma_2'(0)+\gamma_3'(0)=0,\\
			\gamma_3'(\ell)=0.
		\end{cases}
	\end{equation}


    \medskip
	\noindent\textit{Step 2. Analysis of the boundary value problem \eqref{eqn.4.eigenvalueprobTGRAPH}.}


	We start by analyzing the half-lines. Recall from Theorem \ref{thm:description_edge_by_edge} that, for each $i=1,2$, we have $u_{\ell,i}(x)=\varphi(x+y(p,\ell))$, for some $y(p,\ell)>0$ uniquely defined in terms of $\ell$ by the equation
	$\varphi(y(p,\ell))=L^{-1}(p,\ell)$, where $L$ is the length function with $\theta=2$, and $\varphi$ is the real line soliton. 


	Let $i=1,2$. By Lemma \ref{lemma:Half-lineKernel}, the function  $\gamma_i(x)=\alpha_i\varphi'(x+y(p,\ell))$ is the only non-trivial $H^1$ solution to the first equation in \eqref{eqn.4.eigenvalueprobTGRAPH} for some $\alpha_i\in\R$. The continuity condition $\gamma_1(0)=\gamma_2(0)$ then yields, for some $\alpha \in \mathbb{R}$,
	\begin{equation}\label{eqn.gamma1TGRAPH}
		\gamma_i(x)=\alpha\varphi'(x+y(p,\ell)),\ \text{for}\  i=1,2.
	\end{equation}

	We focus now on the terminal edge. Similarly, since $u_\ell$ is a bound-state, $\gamma_3=u'_{\ell,3}$ solves the second equation in \eqref{eqn.4.eigenvalueprobTGRAPH}. Since we have a linear second-order ODE, any solution to the second equation in \eqref{eqn.4.eigenvalueprobTGRAPH} takes the form
	\begin{equation}\label{eqn.gamma2TGRAPH}
		\gamma_3(x)=\beta u'_{\ell,3}(x)+\delta W(x),
	\end{equation}
	where $\beta,\delta\in \mathbb{R}$ are arbitrary and $W$ is a linear independent solution from $u'_{\ell,3}$ to be chosen later.

	Since $u_\ell$ satisfies the Neumann-Kirchoff conditions, by equations \eqref{eqn.gamma1TGRAPH} and \eqref{eqn.gamma2TGRAPH}, the boundary conditions in \eqref{eqn.4.eigenvalueprobTGRAPH} become
	\begin{equation*}
		\begin{cases}
			\beta u''_{3,\ell}(\ell)+\delta W'(\ell)=0,\\
			\alpha\varphi'(y(p,\ell))=-2\beta\varphi'(y(p,\ell))+\delta W(0),\\
			2\alpha\varphi''(y(p,\ell))+\beta u''_{\ell,3}(0)+\delta W'(0)=0.
		\end{cases}
	\end{equation*}
	Recalling that, for $f:\R^+\to\R$ given by $f(x)=\frac{1}{2}x^2-\frac{1}{p}x^p$, we have $u''_{\ell,3}=f'(u_{\ell,3})$ and $\varphi''=f'(\varphi)$. The previous system can be reduced to
	\begin{equation}\label{NewBoundaryConds}
		\begin{cases}
			\beta f'(u_{\ell,3}(\ell))+\delta W'(\ell)=0,\\
			(\alpha+2\beta)\varphi'(y(p,\ell))=\delta W(0),\\
			(2\alpha+\beta)f'(\varphi(y(p,\ell)))+\delta W'(0)=0.
		\end{cases}
	\end{equation}

    \medskip
	\noindent\textit{Step 3. Study of $C(\ell)$.}

	Recall that, by \eqref{eq:hamilt} with $\theta=2$, $u_{\ell,3}$ satisfies, for every $x\in[0,\ell]$,
	\begin{equation}\label{eqn.ODEDependCTGRAPH}
		-\frac{1}{2}{u_{\ell,3}}'(x)^2+f({u_{\ell,3}}(x))=C(\ell):=-3f\left(\varphi(y(p,\ell))\right).
	\end{equation}
By Lemma \ref{cor:4.2.Temp}, the map $C:\R^+\to (-3f(1),0)$ is of class $C^1$, and $C'(\ell)=0$ if and only if $f'(\varphi(y(p,\ell)))=0$, i.e., if $\varphi(y(p,\ell))=1$. Taking then the unique $\ell^*>0$ such that $\varphi(y(p,\ell^*))=L^{-1}(p,\ell^*)=1$, the function $C$ is invertible in the intervals $(0,\ell^*)$ and $(\ell^*,\infty)$. 

Observe that, by Lemma \ref{cor:4.2.Temp}, $\frac{\partial y}{\partial\ell}(p,\ell)>0$. Since $\varphi$ is decreasing, we have, for every $\ell<\ell^*$, $\varphi(y(p,\ell))>1$. Conversely, if $\ell>\ell^*$, $\varphi(y(p,\ell))<1$. Thus, the inverses of $C$ are the functions $\ell_1:(-3f(1),0)\to(\ell^*,\infty)$ and $\ell_2:(-3f(1),0)\to(0,\ell^*)$ defined by
	$$ \ell_1(C)=y^{-1}\left(p,\varphi^{-1}\left(f_{1}^{-1}\left(-\frac{1}{3}C\right)\right)\right)\ \text{and}\ \ell_2(C)=y^{-1}\left(p,\varphi^{-1}\left(f_{2}^{-1}\left(-\frac{1}{3}C\right)\right)\right).$$
Since, for $i=1,2$, $$\lim_{C\to-3f(1)^+}\ell_i(C)=y^{-1}(p,x_0)=\ell^*,$$ the functions $\ell_i$ can be both continuously extended to the interval $[-3f(1),0)$.\footnote{However, since $C'(\ell^*)=0$, 
	$$\lim_{C\to-3f(1)^+}\left|\frac{\partial \ell_i}{\partial C}(C)\right|=+\infty,\quad i=1,2.$$
	Consequently, the derivative cannot be continuously extended to the interval $[-3f(1),0)$.}

\noindent	\textit{Step 4. Choice of $W$.}

	Fix now $i=1$ or $i=2$  and consider $\ell=\ell_i(C)$. To ease notation, we shall drop the subscript $i$.
Define $w(\cdot;C)$ as the unique (positive and monotone) solution to
	\begin{equation}\label{eqn.boundary_conditionsTGRAPH}
		\begin{cases}
			-{w''}+{w}={w}^{p-1},\ \text{in}\ [0,\ell],\\
			{w}(0;C)=\varphi(y(p,\ell)),\\
			{w}'(0;C)=-2\varphi'(y(p,\ell))=2 \sqrt{2 f(z(p,\ell))},\\
			{w}'(\ell,C)=0.
		\end{cases}
	\end{equation}
	By the previous step, this IVP has $C^1$ dependence on initial conditions for $C\neq-3f(1)=:C^*$ and continuous dependence on initial conditions in the case $C=C^*$. Observe also that $w(x;C)$  is related with $u_{\ell,3}$ by
	$$w(\cdot;C)=u_{\ell_i(C),3},\ i=1,2,$$
	where $i=1$ if $\ell>\ell^*$ and $i=2$ if $\ell<\ell^
	*$.

	For any $C\neq C^*$ (equivalently, $\ell\neq\ell^*$), define, for $x\in[0,\ell]$, $$W(x):=\frac{\partial w}{\partial C}(x;C).$$
By differentiation with respect to $C$ of the equation in \eqref{eqn.boundary_conditionsTGRAPH}, we obtain that $W$ is a solution of the second ODE in \eqref{eqn.4.eigenvalueprobTGRAPH}. We also observe that $w$ solves 
	\begin{equation}\label{ODEinC}
		-\frac{1}{2}w'(x;C)^2+f(w(x;C))=C,\ \text{for}\ x\in[0,\ell].
	\end{equation}
	Consequently, differentiation with respect to $C$ yields the following relation between $w$ and $W$:
	\begin{equation}\label{eqn.ConservAux}
		1=-w'(x;C)W'(x)+f'(w(x;C))W(x).
	\end{equation}

	We now check that $W$ is linearly independent from $u'_{\ell_i(C),3}$. Assume, by contradiction that there exists $k\neq0$ such that $W(x)=ku'_{\ell_i(C),3}(x)$ for any $x\in[0,\ell]$. 
	If $x=\ell$, we know that $w'(\ell;C)=u'_{\ell_i(C),3}(\ell)=0$, and thus, $W(\ell)=0$. Now, plugging $x=\ell$ into \eqref{eqn.ConservAux} gives us a contradiction.



    \medskip
\noindent	\textit{Step 5. $W(0)\neq0$.}

Differentiating with respect to $C$ the second equality in \eqref{eqn.boundary_conditionsTGRAPH}, we obtain, by Lemma \ref{cor:4.2.Temp} and the fact that $\ell\neq \ell^*$,
	\begin{equation}\label{eqn.W(0)AUXTGRAPH}
		W(0)=\varphi'(y(p,\ell(C)))\frac{\partial}{\partial\ell}y(p,\ell(C))\ell'(C)\neq0.
	\end{equation}

    \medskip
	\noindent\textit{Step 6.} $W'(0)\neq0$.

	Reasoning as in the previous step, we have, differentiating with respect to $C$ the third equality in \eqref{eqn.boundary_conditionsTGRAPH}, and since $\ell\neq \ell^*$,
	\begin{equation}\label{eqnStep4Aux2}
		W'(0)=-2f'(\varphi(y(p,\ell(C))))\frac{\partial}{\partial\ell}y(p,\ell(C))\ell'(C)\neq0.
	\end{equation}

    \medskip
	\noindent\textit{Step 7.} $W'(\ell)\neq0$. 

    Differentiating with respect to $C$ the last equation in \eqref{eqn.boundary_conditionsTGRAPH} yields
	$$0=w''(\ell(C);C)\ell'(C)+W'(\ell)=f'(w(\ell(C);C))\ell'(C)+W'(\ell).$$
	If $W'(\ell)=0$, we would obtain $f'(w(\ell(C);C))=0$, so (since $w$ is positive) $w(\ell(C);C)=1$. Moreover, given that $w'(\ell(C);C)=0$, by existence and uniqueness theory for ODE's, we have $w(x;C)=u_{\ell,3}(x)\equiv1$ in $[0,\ell]$, which is a contradiction, since the action ground-state $u_\ell$ is not constant on the terminal edge.


    \medskip
	\noindent\textit{Step 8. Conclusion.}

	On the one hand, from the second and third equations in \eqref{NewBoundaryConds}, we obtain
	$$\frac{W(0)}{W'(0)}=\frac{(\alpha+2\beta)\varphi'(y(p,\ell))}{-(2\alpha+\beta)f'(\varphi(y(p,\ell)))}.$$
	On the other hand, from equations \eqref{eqn.W(0)AUXTGRAPH} and \eqref{eqnStep4Aux2}, given that $\ell'(C)\neq0$ and $\frac{\partial y}{\partial\ell}(p,\ell)\neq0$, we have
	$$\frac{W(0)}{W'(0)}=\frac{\varphi'(y(p,\ell))}{-2f'(\varphi(y(p,\ell)))}.$$
	Equating both expressions for $\frac{W(0)}{W'(0)}$, we get
	$$\frac{\varphi'(y(p,\ell))}{-2f'(\varphi(y(p,\ell)))}=\frac{(\alpha+2\beta)\varphi'(y(p,\ell))}{-(2\alpha+\beta)f'(\varphi(y(p,\ell)))},$$
	which simplifies to $$\alpha+2\beta=\alpha+\frac{1}{2}\beta\Longleftrightarrow \beta=0.$$
	Thus, the system \eqref{NewBoundaryConds} becomes
	\begin{equation*}
		\begin{cases}
			\delta W'(\ell)=0,\\
			\alpha\varphi(y(p,\ell))=\delta W(0),\\
			2\alpha f'(\varphi(y(p,\ell)))=-\delta W'(0).
		\end{cases}\Longleftrightarrow
		\begin{cases}
			\delta =0,\\
			\alpha\varphi(y(p,\ell))=0,\\
			2\alpha f'(\varphi(y(p,\ell)))=0.
		\end{cases}\Longleftrightarrow\begin{cases}\delta=0,\\ \alpha=0.			\end{cases}
	\end{equation*}
	In conclusion, $\gamma=0=\Gamma$, and no nontrivial solution to the equation $\mathcal{L}^{-}_\lambda\Gamma=0$ exists in $H^2_{\text{NK}}(\mathcal{T}_1)$.
\end{proof}


Finally, we study the Nullity Index in $\mathcal{G}_1$. We follow the same structure as before, highlighting mostly the differences.

\begin{proof}[Proof of Lemma \ref{prop:5.43.Temp} for the tadpole graph $\mathcal{G}_1$.]
	Let $\G_1$ be the tadpole graph. We consider a solution $\Gamma\in H^1$ to the eigenvalue problem $\mathcal{L}^{-}_\lambda\Gamma=0$ and show that $\Gamma=0$. We denote by $\Gamma_1$ and $\Gamma_2$, respectively, the restrictions of $\Gamma$ to the half-line and to the loop. Observe that, by Remark \ref{rem:NK}, $\Gamma\in H^2_{\text{NK}}(\G_1)$.	

    \medskip
	\noindent\textit{Step 1. Discussion of the kernel of $\mathcal{L}^{-}_\lambda$ in terms of the parameter $\ell$.}

	Recall the scaling
	$u^\lambda(x)=\lambda^{\frac{1}{p-2}}u_\ell(\lambda^{1/2}x)$ and define, for $\ell=\ell(\lambda)=\lambda^\frac{1}{2}$, $\gamma=(\gamma_1,\gamma_2)\in H^2_{\text{NK}}(\G_\ell)$
	\begin{equation*}
		\begin{cases}
			\Gamma_1(x)=\gamma_1(\lambda^\frac{1}{2} x),\ x\in[0,\infty),\\
			\Gamma_2(x)=\gamma_1(\lambda^\frac{1}{2} x),\ x\in[0,2\ell].
		\end{cases}
	\end{equation*}
	Then, problem $\mathcal{L}\Gamma=0$ can be written equivalently in $(\gamma_1,\gamma_2)$ as
	\begin{equation}\label{eqn.4.eigenvalueprob}
		\begin{cases}
			-\gamma_1''+\gamma_1-(p-1)u_{\ell,1}^{p-2}\gamma_1=0,\ \text{in}\ [0,\infty),\\
			-\gamma_2''+\gamma_2-(p-1)u_{\ell,2}^{p-2}\gamma_2=0,\ \text{in}\ [0,2\ell],
		\end{cases}\text{with}\ \begin{cases}
			\gamma_1(0)=\gamma_2(0)=\gamma_2(2\ell),\\
			\gamma_1'(0)+\gamma_2'(0)-\gamma_2'(2\ell)=0.
		\end{cases}
	\end{equation}

    \medskip
\noindent	\textit{Step 2. Analysis of the boundary value problem \eqref{eqn.4.eigenvalueprob}.}

We have $u_{\ell,1}(x)=\varphi(x+y(p,\ell))$, with $y(p,\ell)>0$ uniquely defined in terms of $\ell$ by the equation
	$\varphi(y(p,\ell))=L^{-1}(p,\ell)$, where $L$ is the length function, this time with $\theta=\frac{1}{2}$. By Lemma \ref{lemma:Half-lineKernel}, for some $\alpha\in\R$,
	\begin{equation}\label{eqn.gamma1}
		\gamma_1(x)=\alpha\varphi'(x+y(p,\ell)).
	\end{equation}
Any general solution to the second equation in \eqref{eqn.4.eigenvalueprob} takes the form
	\begin{equation}\label{eqn.gamma2}
		\gamma_2(x)=\beta u'_{\ell,2}(x)+\delta W(x),
	\end{equation}
	where $\beta,\delta\in \R$ are arbitrary and $W$ is a linear independent solution from $u'_{\ell,2}$ to be chosen later.

    \medskip
	\noindent\textit{Step 3. Analysis of $C(\ell)$.}

	This is a simple adaptation of Step 3 of the proof in the $\mathcal{T}$-graph. Note that in $\G_\ell$, by \eqref{eq:hamilt} with $\theta=\frac{1}{2}$, $u_{\ell,2}$ satisfies, for every $x\in[0,2\ell]$,
	\begin{equation}\label{eqn.ODEDependC}
		-\frac{1}{2}{u_{\ell,2}}'(x)^2+f({u_{\ell,2}}(x))=C(\ell)=\frac{3}{4}f\left(\varphi(y(p,\ell))\right).
	\end{equation}
	Moreover, there exists a unique $\ell^*>0$ such that $C'(\ell^*)=0$, characterized by $\varphi(y(p,\ell^*))=L^{-1}(\ell^*)=1$. The function $C:\R^+\to\left(0,\frac{3}{4}f(1)\right)$ can be inverted for $\ell\neq\ell^*$. The inverses of $C$ are the functions $\ell_1:(0,\frac{3}{4}f(1))\to(\ell^*,\infty)$ and $\ell_2:(0,\frac{3}{4}f(1))\to(0,\ell^*)$ defined by
	$$ \ell_1(C)=y^{-1}\left(p,\varphi^{-1}\left(f_{1}^{-1}\left(\frac{4}{3}C\right)\right)\right)\ \text{and}\ \ell_2(C)=y^{-1}\left(p,\varphi^{-1}\left(f_{2}^{-1}\left(\frac{4}{3}C\right)\right)\right).$$


    \medskip
	\noindent\textit{Step 4. Choice of $W$.}

	Fix now $i=1$ or $i=2$ and consider $\ell=\ell_i(C)$ as given in the previous step. To ease notation we shall drop the subscript $i$. Let $w(\ \cdot\ ;C)$ be the (unique) positive and symmetric (with respect to $x=\ell$) solution to
	\begin{equation}\label{eqn.boundary_conditions}
		\begin{cases}
			-w''+w=w^{p-1},\ \text{in}\ [0,2\ell],\\
			w(0;C)=w(2\ell;C)=\varphi(y(p,\ell)),\\
			w'(0;C)=-\frac{1}{2}\varphi'(y(p,\ell))=\frac{1}{2}\sqrt{2f(z(p,\ell))},\\
		\end{cases}
	\end{equation}
	By the previous step, this IVP has $C^1$ dependence on initial conditions for $C\neq\frac{3}{4}f(1)=:C^*$ and continuous dependence on initial conditions in the case $C=C^*$. Observe also that the function $w(x;C)$ is related with $u_{\ell,2}$ by
	$$w(\cdot;C)=u_{\ell_i(C),2},\ i=1,2,$$
	where $i=1$ if $\ell>\ell^*$ and $i=2$ if $\ell<\ell^
	*$.
We define, for $x\in[0,\ell]$, $$W(x):=\frac{\partial w}{\partial C}(x;C).$$ Differentiating with respect to $C$, we obtain that $W$ is a solution to the second ODE in \eqref{eqn.4.eigenvalueprob} that is linearly independent from $u'_{\ell,2}$.


    \medskip
\noindent	\textit{Step 5. Reduction to the unique solvability of a linear $2\times 2$ system.}

	Observe that, by symmetry of $u_{\ell,2}$ (recall Theorem \ref{thm:uniqueness}),  $u_{\ell,2}(x)=u_{\ell,2}(2\ell-x)$, for any $x\in [0,2\ell]$. Thus, in the same interval, we have $u'_{\ell,2}(x)=-u'_{\ell,2}(2\ell-x)$.

	From the continuity condition in \eqref{eqn.4.eigenvalueprob}, equations \eqref{eqn.gamma1} and \eqref{eqn.gamma2}, and the symmetry properties of $u'_{\ell,2}$ and $W$, 
	\begin{equation}\label{Cont-EigenProb}
		\begin{cases}
			\gamma_2(2\ell)=\gamma_1(0),\\
			\gamma_2(0)=\gamma_1(0),\\
			\gamma_1'(0)+\gamma_2'(0)-\gamma_2'(2\ell)=0,
		\end{cases}
		\Longleftrightarrow\ \ 
		\begin{cases}
			\beta u'_{\ell,2}(2\ell)+\delta W(2\ell)=\alpha\varphi'(y(p,\ell)),\\
			-\beta u'_{\ell,2}(0)+\delta W(0)=\alpha\varphi'(y(p,\ell)),\\
			\alpha\varphi''(y(p,\ell))+\delta (W'(0)-W'(2\ell))=0.
		\end{cases}
	\end{equation}	
	Since  $u'_{\ell,2}(0)=-u'_{\ell,2}(2\ell)$ we have, by adding the first two equations in \eqref{Cont-EigenProb},
	\begin{equation}\label{seconlineareq}
		2\alpha\varphi'(y(p,\ell))=\delta\left(W(0)+W(2\ell)\right).
	\end{equation}
	We claim that the linear system 
	\begin{equation}\label{ClaimSystem}
		\begin{cases}
			\alpha\varphi''(y(p,\ell))+\delta (W'(0)-W'(2\ell))=0,\\
			2\alpha\varphi'(y(p,\ell))-\delta\left(W(0)+W(2\ell)\right)=0.
		\end{cases}
	\end{equation}
	has only the trivial solution $(\alpha,\delta)=(0,0)$. Observe that, if this is the case, then by the first equation in \eqref{Cont-EigenProb}, we find $\beta=0$ and therefore no nontrivial solution to the equation $\mathcal{L}^{-}_\lambda\Gamma=0$ exists in  $H^2_{\text{NK}}(\G_1)$.

    \medskip
	\noindent\textit{Step 6. Unique solvability of \eqref{ClaimSystem}.}

	The idea is to write the system \eqref{ClaimSystem} in terms of the soliton $\varphi$. Differentiating the second and third equations in \eqref{eqn.boundary_conditions} with respect to $C$, 
	\begin{equation}\label{W(0)-W(2ell)_relation}
		W(0)=2w'(2\ell;C)\ell'(C)+W(2\ell)=\varphi'(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)
	\end{equation}
	and
	\begin{equation}\label{W'(0)_Explicit}
		W'(0)=-\frac{1}{2}\varphi''(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)
	\end{equation}
	From \eqref{W(0)-W(2ell)_relation},
	\begin{equation}\label{W(2ell)_eq}
		W(2\ell)=\varphi'(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)-\varphi'(y(p,\ell))\ell'(C).
	\end{equation}

	Recalling that $w(\cdot;C)=u_{\ell(C),2}$, we have, by the symmetry properties of $u_{\ell,2}$, that $w'(2\ell;C)=-w'(0;C)$. Differentiating this expression with respect to $C$ and using $u_{\ell,2}(0)=u_{\ell,2}(2\ell)=\varphi(y(p,\ell))$, we get
	\begin{align}\label{W'(0)-W'(2ell)_relation}
		-W'(0)&=2w''(2\ell;C)\ell'(C)+W'(2\ell)=-2f'(w(2\ell;C))\ell'(C)+W'(2\ell)\nonumber\\
		&=-2f'(u_{\ell,2}(0))\ell'(C)+W'(2\ell)=2\varphi''(y(p,\ell))\ell'(C)+W'(2\ell).
	\end{align}
	Now, \eqref{W'(0)_Explicit} and \eqref{W'(0)-W'(2ell)_relation} yield
	\begin{equation}\label{W'(2ell)_eq}
		W'(2\ell)=\frac{1}{2}\varphi''(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)-2\varphi''(y(p,\ell))\ell'(C).
	\end{equation}



	Therefore, the proof of unique solvability of \eqref{ClaimSystem} reduces to checking that the matrix
	\begin{align*}
		A&=\begin{pmatrix}
			\varphi''(y(p,\ell)) & W'(0)-W'(2\ell) \\
			2\varphi'(y(p,\ell)) & -(W(0)+W(2\ell))
		\end{pmatrix}\\
		&=\begin{pmatrix}
			\varphi''(y(p,\ell)) & -\varphi''(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)+2\varphi''(y(p,\ell))\ell'(C) \\
			2\varphi'(y(p,\ell)) & -2\varphi'(y(p,\ell))\frac{\partial y}{\partial\ell}(p,\ell(C))\ell'(C)+\varphi'(y(p,\ell))\ell'(C)
		\end{pmatrix},
	\end{align*}
 has nonzero determinant. By direct computation,
	 \begin{align*}
	 	\text{det}
	 	(A)=-3\varphi'(y(p,\ell))\varphi''(y(p,\ell))\ell'(C).
	 	\end{align*}
	 By construction of $\ell$ as a function of $C$, independently of taking $i=1$ or $i=2$, we know that $\varphi''(y(p,\ell(C))\neq0$. Since also $y(p,\ell)>0$, we have $\varphi'(y(p,\ell))\neq0$. Moreover, one can easily check by straightforward differentiation that, as a consequence of Lemma \ref{cor:4.2.Temp}, $\ell'(C)\neq0$ for any $C\neq C^*=\frac{3}{4}f(1)$ independently of choosing $i=1$ or $i=2$. In particular, it follows that $\text{det}(A)\neq0$ and the proof is finished.
\end{proof}	 
