\section{Stability transitions near $p=6$}\label{sec:NonMonotoneTheta}

In view of having a stability transition, it is crucial to prove that the map $\lambda\mapsto\Theta(6,\lambda)$ is not monotone. For the tadpole graph, this was shown in \cite{noja2020standing}.

\begin{theorem}[{{\cite[Theorem 3]{noja2020standing}}}]\label{th:5.28}
	Let $\lambda>0$ and $u^\lambda$ be the action ground-state on the tadpole graph $\mathcal{G}_1$. Then, there exist $\lambda_1>0$ for which
\[
		\frac{\partial\Theta}{\partial\lambda}(6,\lambda)>0\quad\text{for}\quad \lambda\in(0,\lambda_1) \quad \text{and}\quad \frac{\partial\Theta}{\partial\lambda}(6,\lambda)<0\quad\text{for $\quad\lambda\in(\lambda_1,\infty),$}.
\]
\end{theorem}

Inspired by the arguments in \cite{noja2020standing}, we present the first complete characterization of the $L^2$-norm of action ground-states in the critical case $p=6$ on the $\mathcal{T}-$graph. This complements what was known in \cite{AgostinhoCorreiaTavares,pierotti2021local}. Namely, we prove

\begin{theorem}\label{th:5.29}
	Let $\lambda>0$ and $u^\lambda$ be the action ground-state on the $\mathcal{T}-$graph $\mathcal{T}_1$. Then,  there exist $\lambda_0>0$ for which
	\[
	\frac{\partial\Theta}{\partial\lambda}(6,\lambda)<0\quad\text{for}\quad \lambda\in(0,\lambda_0)\quad\text{for $\quad\lambda\in(\lambda_0,\infty)$}\quad\text{and}\quad 	\frac{\partial\Theta}{\partial\lambda}(6,\lambda)>0.
\]
\end{theorem}
We prove this result in a series of lemmas below. For now, having these results at hand, we conclude the proof of the first result of this paper. 


\begin{proof}[Proof of Theorem \ref{thm:transition_particular}]
We apply Theorem \ref{thm:transition} (see also Remark \ref{rem:lambda_estrela}) to the curve of positive action ground-states $\lambda\in (0,\infty)\mapsto u^\lambda$. Indeed, condition $(A_1)$ is satisfied by Lemma \ref{lemma:A1}, $(A_2)$ by Lemma \ref{lemma:5.32} and $(A_3)$ (for $\lambda\neq \lambda^*$) is satisfied by Proposition \ref{prop:5.26}. Condition $(H)$, on the other hand, is satisfied by Theorem \ref{thm:description_edge_by_edge}. Recalling from Section \ref{sec:explicit_mass} that $\ell=\sqrt{\lambda}$ and
\[
\Theta(p,\lambda)=\lambda^\frac{6-p}{2(p-2)}\Theta_1(p,z(p,\ell)),
\]
the map $(p,\lambda)\mapsto \frac{\partial\Theta}{\partial \lambda}(p,\lambda)$ is continuous by Lemmas \ref{cor:4.2.Temp} and \ref{lemma:4.7.Temp}. Finally, the map $p\mapsto \Theta(6,\lambda)$ is not monotone by Theorems \ref{th:5.28} (for the tadpole) and \ref{th:5.29} (for the $\mathcal{T}$-graph).
\end{proof}


In the next section, we proof Theorem \ref{th:5.29}.
\subsection{Exact behavior of $\lambda\mapsto \Theta(6,\lambda)$ in the $\mathcal{T}$-graph}


From now on, we work in the $\mathcal{T}$-graph. Recall from \eqref{ThetaScaled} and \eqref{eq:Theta_1} that $\Theta(6,\lambda)=\Theta_1(6,\ell)$. From Lemma \ref{lemma:Theta_1_expressions} we write, with some abuse of notation,
\[
\Theta_1(6,\ell)=\Theta_1(6,z(p,\ell)).
\]
The derivative of $\Theta_1$ in $z$ is given in Lemma \ref{lemma:4.7.Temp} for a general $p$. By taking $p=6$, we deduce the following.

\begin{lemma}\label{lemma:5.34}
In the $\mathcal{T}$-graph, for $z\in \left(0,\sqrt[4]{3}\right)$ we have
	\begin{align}\label{MapMuDerivative}
		\sqrt{2}\frac{\partial \Theta_1}{\partial z}(6,z)(-3f(z)-f(1))&=-6z^2\sqrt{f(z)}+f'(z)\int_z^{f_2^{-1}(-3f(z))}\frac{1-t^2}{(1+t^2)^2}\frac{dt}{\sqrt{f(t)+3f(z)}}.
	\end{align}
\end{lemma}
\begin{proof}
	By taking $p=6$ in Lemma \ref{lemma:4.7.Temp}-1, we have
	\begin{align*}
		\sqrt{2}\frac{\partial \Theta_1}{\partial z}(6,z)&\left(-3f(z)-f(1)\right)=-6z^2\sqrt{f(z)}\\
		+&3f'(z)\int_z^{f_2^{-1}(-3f(z))}\left(-\frac{t^2}{2}-2t\frac{f(t)-f(1)}{f'(t)}+t^2f''(t)\frac{f(t)-f(1)}{f'(t)^2}\right)\frac{dt}{\sqrt{f(t)+3f(z)}}.
	\end{align*}
	Finally, by recalling that $f(t)=\frac{1}{2} t^2-\frac{1}{6}t^6$, we have 
\[
		-\frac{t^2}{2}-2t\frac{f(t)-f(1)}{f'(t)}+t^2f''(t)\frac{f(t)-f(1)}{f'(t)^2}=\frac{(1-t^2)}{3(1+t^2)^2}.\qedhere
\]
\end{proof}

In the following lemmas, we analyze the sign of $\frac{\partial\Theta_1}{\partial z}(6,z)$. We split this analysis in the cases $z\geq 1$ and $z\in(0,1)$, starting with the former.
\begin{lemma}\label{lemma:5.35}
Under the previous notations, in the $\mathcal{T}$-graph we have
	$\frac{\partial \Theta_1}{\partial z}(6,z)>0$ for any $z\in [1,\sqrt[4]{3})$.
\end{lemma}
\begin{proof}
	Suppose that $z\geq1$. Using the explict expression $f'(z)=z(1-z^4)$, integration by parts yields
	\begin{align*}
		\int_z^{f_2^{-1}(-3f(z))}\frac{1-t^2}{(1+t^2)^2}\frac{dt}{\sqrt{f(t)+3f(z)}}&=\int_z^{f_2^{-1}(-3f(z))}\frac{2}{t(1+t^2)^3}\frac{d}{dt}\sqrt{f(t)+3f(z)}dt\\
		&=-\frac{4\sqrt{f(z)}}{z(1+z^2)^3}+2\int_z^{f_2^{-1}(-3f(z))}\frac{1+7t^2}{t^2(1+t^2)^4}\sqrt{f(t)+3f(z)}dt.
	\end{align*}
	Thus,\vspace{-0.2cm}
	\begin{align*}
		\sqrt{2}\frac{\partial \Theta_1}{\partial z}(6,z)(-3f(z)-f(1))=&-6z^2\sqrt{f(z)}-\frac{4(1-z^2)\sqrt{f(z)}}{(1+z^2)^2}\\
		&+2f'(z)\int_z^{f_2^{-1}(-3f(z))}\frac{1+7t^2}{t^2(1+t^2)^4}\sqrt{f(t)+3f(z)}dt.
	\end{align*}
	Since $f'(z)\leq0$ for $z\geq1$, $(-3f(z)-f(1))<0$, and
	\[
	-6z^2\sqrt{f(z)}-\frac{4(1-z^2)\sqrt{f(z)}}{(1+z^2)^2}=-\frac{\sqrt{f(z)}}{(1+z^2)^2}\left(6z^2(1+z^2)^2+4(1-z^2)\right)<0,
	\]
	 we have $\frac{\partial \Theta_1}{\partial z}(6,z)>0$.
\end{proof}

In order to study $\frac{\partial \Theta_1}{\partial z}(6,z)$ for $z\in (0,1)$, recalling \eqref{MapMuDerivative}, we write
\[
\sqrt{2}\frac{\partial \Theta_1}{\partial z}(6,z)\frac{-3f(z)-f(1)}{f'(z)}=F(z)-G(z),
\]
where  $F,G:(0,1)\to\R$ are defined by the following expressions:
\begin{equation}\label{FunctionsFG}
	F(z)=\int_{z}^{f_2^{-1}(-3f(z))}\frac{1-t^2}{(1+t^2)^2}\frac{dt}{\sqrt{f(t)+3f(z)}}\quad\text{and}\quad G(z)=\frac{6z^2\sqrt{f(z)}}{f'(z)}.
\end{equation}



\begin{lemma}\label{lemma:5.36}
	Let $F,G:(0,1)\to\R$ be defined as in \eqref{FunctionsFG}. Then,\setlist{nolistsep}
	\begin{enumerate}[noitemsep]
		\item $F$ is decreasing in the interval $(0,1)$,
		\item $\lim\limits_{z\to0^+}F(z)=+\infty$ and $F(1):=\lim\limits_{z\to1^-}F(z)<0$,
		\item $G(z)$ is increasing in $z\in(0,1)$,
		\item $\lim\limits_{z\to0^+}G(z)=0$ and $\lim\limits_{z\to1^-}G(z)=+\infty$.
	\end{enumerate}
\end{lemma}

\begin{remark}The proof of Lemma \ref{lemma:5.36} is inspired by the proof of \cite[Lemma 10]{noja2020standing}, where the authors analyzed the same behaviour for the tadpole graph. In that work, to understand the sign of $F'$, the authors integrate by parts the expression of $F$ and then directly compute the derivative with respect to $z$. This argument can be seen in \cite[Lemma 10]{noja2020standing} after equation (4.33). In our case, however, if we integrate by parts the expression $F$ and then differentiate with respect to $z$, we encounter the problem that $3f'(z)>0$ (as opposed to $-\frac{3}{8}A'(z)<0$ in \cite[Lemma 10]{noja2020standing}) causes the integral term in the expression of $F'$ to have positive sign, instead of the desired negative sign. Thus, we take a different approach. We rewrite the integrand in $F$ in a suitable way and prove that it is decreasing in $z$.
\end{remark}




\begin{proof}[Proof of Lemma \ref{lemma:5.36}]
	Item 3. is a consequence of 
	\begin{align*}
		G'(z)&=\frac{6}{f'(z)^2}\left(\left(2z\sqrt{f(z)}+\frac{z^2f'(z)}{2\sqrt{f(z)}}\right)f'(z)-z^2\sqrt{f(z)}f''(z)\right)\\
		&=\frac{3}{f'(z)^2\sqrt{f(z)}}\left(4zf(z)f'(z)+z^2(f'(z))^2-2z^2f(z)f''(z)\right)\\
		&=\frac{3z^2}{f'(z)^2\sqrt{f(z)}}\left(2f(z)z^2\left(1+3z^4\right)+f'(z)^2\right)>0,
	\end{align*}	
	while Item 4 is straightforward. 


		As for Item 2, from dominated convergence,
	\begin{align*}
		\lim_{z\to1^-}F(z)=\int_1^{f_2^{-1}(-3f(1))}\frac{1-t^2}{(1+t^2)^2}\frac{dt}{\sqrt{f(t)+3f(1)}}\leq 0
	\end{align*}	
	while the limit as $z\to 0^+$ is a consequence of the fact that  $\frac{1}{\sqrt{f(t)t}}\sim \frac{\sqrt{2}}{t}$ for $t$ close to 0 (not integrable) and $\frac{1}{\sqrt{f(t)}}\sim \frac{c}{\sqrt{t-\sqrt[4]{3}}}$ for $t$ close to $f_2^{-1}(0)=\sqrt[4]{3}$ (integrable).






	 Finally, we prove Item 1. We rewrite $F$ as
\[
		F(z)=\left(\int_z^1+\int_1^{f_2^{-1}(-3f(z))}\right)\frac{1-t^2}{(1+t^2)^2}\frac{dt}{\sqrt{f(t)+3f(z_0)}}=:F_1(z)+F_2(z).
\]
	Differentiating under the integral we have, for all $z\in(0,1)$,
	\begin{equation*}
		F'_1(z)=-\frac{1-z^2}{2(1+z^2)^2\sqrt{f(z)}}-\frac{3}{2}f'(z)\int_z^1\frac{1-t^2}{(1+t^2)^2}(f(t)+3f(z))^{-\frac{3}{2}}dt<0.
	\end{equation*}
For $F_2$, taking the variable change $t=1+sI_z$, where $I_z=f_2^{-1}(-3f(z))-1>0$, we obtain
	\begin{equation}\label{F2DecreasingForm}
		F_2(z)=\int_0^1\frac{(1-(1+sI_z)^2)I_zds}{(1+(1+sI_z)^2)^2\sqrt{f(1+sI_z)+3f(z)}}=:\int_0^1K(z,s)ds.
	\end{equation}
To conclude the proof, we claim that
the map $z\mapsto K(z,s)$ is strictly decreasing for every $s\in(0,1)$.
To simplify notation, we let $B(z,s)=f(1+sI_z)+3f(z)>0$ and $X(z,s)=1+sI_z>1$. Differentiating $K$ with respect to $z$ yields
	\begin{align}
		\frac{\partial K}{\partial z}(z,s)=&\frac{1}{(1+X(z,s)^2)^4B(z,s)}\left[(1+X(z,s)^2)^2\sqrt{B(z,s)}\left(-2X(z,s)sI'_zI_z+(1-X(z,s)^2)I'_z\right)\right.\nonumber\\
		&-\left.(1-X(z,s)^2)I_z\left(4sX(z,s)(1+X(z,s)^2)I'_z\sqrt{B(z,s)}+(1+X(z,s)^2)^2\frac{\partial_z B(z,s)}{2\sqrt{B(z,s)}}\right)\right]\nonumber\\
		=&\frac{1}{2(1+X(z,s)^2)^4B(z,s)^\frac{3}{2}}\left[2(1+X(z,s)^2)^2B(z,s)I'_z\left(-2X(z,s)sI_z+(1-X(z,s)^2)\right)\right.\nonumber\\
		&-\left.(1-X(z,s)^2)I_z\left(8sX(z,s)(1+X(z,s)^2)I'_zB(z,s)+(1+X(z,s)^2)^2 \partial_z B(z,s)\right)\right]. \nonumber \\
		=&\frac{1}{2(1+X(z,s)^2)^4B(z,s)^\frac{3}{2}}\left[Q(z,s) + 2(1+X(z,s)^2)^2B(z,s)I'_z(1-X(z,s)^2)\right. \nonumber \\
		&\left.-(1-X(z,s)^2)(1+X(z,s)^2)^2I_z\partial_zB(z,s) \right], \label{DerK}
	\end{align}
	for 
\[
Q(z,s):=-(1-X(z,s)^2)I_z8sX(z,s)(1+X(z,s)^2)I'_zB(z,s)-4(1+X(z,s)^2)^2B(z,s)I'_zX(z,s)sI_z.
\]
	Recall now the following simple facts: for $z\in(0,1)$, we have  $X(z,s)>1$, $f'(z)>0$, $I_z=f_2^{-1}(-3f(z))-1>0$ and 
	\[
	I'_z=\frac{-3f'(z)}{f'(f_2^{-1}(-3f(z)))}>0,\ \text{for all}\ z\in(0,1),\quad \text{ with }\quad	I'_0=0.
	\]
Observe now that the term outside the brackets in \eqref{DerK} is positive. We show that the term inside are negative:
	\begin{itemize}
	\item $2(1+X(z,s)^2)^2B(z,s)I'_z(1-X(z,s)^2)<0$, by the observations made in the previous paragraph.
	\item Observe that $-(1-X(z,s)^2)(1+X(z,s)^2)^2I_z>0$ and 	\begin{equation*}
\frac{\partial^2 B}{\partial s\partial z}(z,s)=\frac{\partial}{\partial s}\left(f'(1+sI_z)sI'_z+3f'(z)\right)=f''(1+sI_z)s^2{I'_z}^2+f'(1+sI_z)I'_z<0.
	\end{equation*}
	Thus, the map $s\mapsto \partial_z B(z,s)$ is strictly decreasing for every $z\in(0,1)$. Moreover, since $\partial_zB(0,s)=f'(1)sI'_0+3f'(0)=0$, we have that $\partial_z B(z,s)<0$ for all $(z,s)\in(0,1)^2$. This implies that the term $(1+X(z,s)^2)^2\partial_z B(z,s)$ in \eqref{DerK} is negative.
\item Finally, we show that $Q(z,s)$ has negative sign.

 We note that $Q$ can be simplified to
	$$Q(z,s)=-4sI_zI'_zB(z,s)X(z,s)(1+X(z,s)^2)(3-X(z,s)^2).$$
	The term $-4sI_zI'_zB(z,s)X(z,s)(1+X(z,s)^2)$ is negative. We show that $h(z,s):=3-X(z,s)^2>0$. Differentiating $h$ with respect to $s$, we get
	$\frac{\partial h}{\partial s}(z,s)=-2X(z,s)I_z<0$; that is, $s\mapsto h(z,s)$ is strictly decreasing for every $z\in(0,1)$. To conclude, we  show that $h(z,1)>0$. Note that
	$$h(z,1)=3-X(z,1)^2=3-(1+I_z)^2=3-(f_2^{-1}(-3f(z)))^2,$$
	and that (recalling that $f(1)=1/3$, since $p=6$), 
	$$\frac{\partial h}{\partial z}(z,1)=\frac{6f'(z)(f_2^{-1}(-3f(z))}{f'(f_2^{-1}(-3f(z)))}<0\quad \text{ and }\quad h(1,1)=3-(f_2^{-1}(-3f(1)))^2=3-(f_2^{-1}(-1))^2>0$$
	\end{itemize}
	This finishes the proof of Item 1.
\end{proof}


We now conclude this section with the following.

\begin{proof}[Proof of Theorem \ref{th:5.29}]
	By Lemmas \ref{lemma:5.35} and \ref{lemma:5.36},  there exists a unique $z_0\in(0,1)$ such that 
	\begin{equation}\label{existence_of_z0}
	\frac{\partial \Theta_1}{\partial z}(6,z)<0\quad \text{ for any } z\in(0,z_0),\qquad  \frac{\partial \Theta_1}{\partial z}(6,z)>0\quad \text{for any $z\in (z_0,\sqrt[4]{3})$. }
	\end{equation}
	The conclusion now follows from
	\[
	\frac{\partial \Theta}{\partial \lambda}(6,\lambda)=	\frac{\partial }{\partial \lambda}(\Theta_1(6,\ell(\lambda)))=\frac{\partial \Theta_1}{\partial z}(6,z(6,\ell(\lambda)))\frac{\partial z}{\partial\ell}(6,\ell(\lambda))\frac{d \ell}{d\lambda}(\lambda). 
	\]
	The conclusion now follows from \eqref{existence_of_z0}, Lemma \ref{cor:4.2.Temp} and the explicit expression $\ell(\lambda)=\lambda^{\frac{1}{2}}$.
\end{proof}




\section{Asymptotic stability analysis in $\lambda$ and $p$}\label{sec:asymptotics}


Recall from \eqref{ThetaScaled} that
\begin{equation}\label{eq:alpha}
    \Theta(p,\lambda)=\lambda^\alpha\Theta_1(p,\ell(\lambda)),\quad \text{where $\alpha=\frac{6-p}{2(p-2)}$ and $\ell(\lambda)=\sqrt{\lambda}$},
\end{equation}
and $\Theta_1$ is as in \eqref{Theta_1_T'} and \eqref{Theta_1_TADPOLE'}, for the $\mathcal{T}$-graph and tadpole graph, respectively. Setting
\begin{equation}\label{z_func_ell}
z(p,\ell)=L^{-1}(p,\ell)
\end{equation}
(cf. Theorem \ref{thm:description_edge_by_edge}), Lemma \ref{cor:4.2.Temp} implies
\begin{align}
     \frac{\partial\Theta}{\partial\lambda}(p,\lambda)&=\lambda^{\alpha-1}\left(\alpha\Theta_1(p,z(p,\ell(\lambda))+\frac{\sqrt{\lambda}}{2}\frac{\partial\Theta_1}{\partial z}(p,z(p,\ell(\lambda))\frac{\partial z}{\partial \ell}(p,\ell(\lambda))\right)\nonumber \\
     &=\lambda^{\alpha-1}\left(\alpha\Theta_1(p,z(p,\ell(\lambda))+\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z(p,\ell(\lambda))\frac{1}{\frac{\partial L}{\partial z}(p,z(p,\ell(\lambda)))}\right)\label{der_Theta_z}.
\end{align}
Since $L(p,z(p,\ell))=\ell=\sqrt{\lambda}$, we study the asymptotic behavior of $\frac{\partial\Theta}{\partial\lambda}(p,\lambda)$ in $\lambda$ and $p$ in terms of the variable $z$ by analyzing the behavior of 
\begin{equation}\label{der_Theta_z2}
   z\mapsto \alpha\Theta_1(p,z)+\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z)\frac{1}{\frac{\partial L}{\partial z}(p,z)}.
\end{equation}
\subsection{Asymptotics in $\lambda$}\label{sec:asymptotics_lambda}
Observe that, by \eqref{eq:asymptotic_L}, \eqref{z_func_ell} and the behavior of $\varphi$,
\begin{equation}\label{eq:limitzlambda}
    \lambda\to 0^+ \iff z\to \varphi(0)^- \quad \text{ and } \quad \lambda\to +\infty \iff z\to 0^+.
\end{equation}

\begin{lemma}\label{prop6.1}
    We have 
    \[
    \lim_{z\to 0^+} \Theta_1(p,z)=\begin{cases} \frac{1}{2}\|\varphi\|^2_{L^2(\R)} & \text{ in the } \mathcal{T}\text{-graph},\\
    \|\varphi\|^2_{L^2(\R)} & \text{ in the tadpole graph,}
    \end{cases}
    \]
    and
    \[
    \lim_{z\to \varphi(0)^-} \Theta_1(p,z)=\begin{cases} \|\varphi\|^2_{L^2(\R)} & \text{ in the } \mathcal{T}\text{-graph},\\
    \frac{1}{2}\|\varphi\|^2_{L^2(\R)} & \text{ in the tadpole graph.}
    \end{cases}
    \]   
\end{lemma}
\begin{proof}
Recalling the decompositions \eqref{Theta_1_T'} and \eqref{Theta_1_TADPOLE'}, the result is a direct consequence of the fact that
\begin{equation}\label{mu_functions}
  \lim_{z\to 0^+}  \mu_1(p,z,\theta)=\frac{1}{\sqrt{2}}\int_{0}^{(p/2)^\frac{1}{p-2}}\frac{t^2dt}{\sqrt{f(t)}}=\frac{1}{2}\|\varphi\|_{L^2(\R)^2},\qquad  \lim_{z\to \varphi(0)^-}  \mu_1(p,z,\theta)=0,
\end{equation}    
and, recalling that $\varphi(0)=(p/2)^\frac{1}{p-2}$,
\[
\lim_{z\to 0^+}\mu_2(p,z)=0,\qquad \lim_{z\to \varphi(0)^-}\mu_2(p,z)=\frac{1}{\sqrt{2}}\int_0^{\varphi(0)}\frac{t^2dt}{\sqrt{f(t)}}=\frac{1}{2}\|\varphi\|_{L^2(\R)^2}.\qedhere
\]
\end{proof}


\begin{lemma}\label{assymptotic_L1}
    Fix $p>2$ with $p\neq 6$ and $\theta>0$. Then there exist constants $C_1=C_1(p,\theta)>1$ and $C_2=C_2(p,\theta)<1$ such that
    \[
\frac{1}{C_1}|\ln (z)|\leq L(p,z) \leq C_2|\ln (z)|\quad \text{ and } \quad  -\frac{1}{C_2z}\leq \frac{\partial L}{\partial z}(p,z)\leq -\frac{C_2}{z}\qquad \text{ for } z\sim 0^+,
    \]
while
     \[
 L(p,z) \sim \frac{2\theta}{\sqrt{|f'(\varphi(0))|}}\sqrt{\varphi(0)-z}\quad \text{ and }\quad  \frac{\partial L}{\partial z}(p,z) \sim -\frac{\theta}{2|f'(\varphi(0))|\sqrt{\varphi(0)-z}}\qquad \text{ for } z\sim \varphi(0)^-.
    \]
\end{lemma}

\begin{proof}
\emph{Step 1.} Behavior of $L(p,z)$ as $z\to 0^+$.\newline

From \eqref{eq:Length}, 
\[
L(p,z)=\frac{1}{\sqrt{2}} \int_z^{f_{2}^{-1}\left(\left(1-\theta^2\right) f(z)\right)} \frac{d t}{\sqrt{f(t)-\left(1-\theta^2\right) f(z)}}= \frac{1}{\sqrt{2}}\left(\int_z^1 +\int_1^{f_{2}^{-1}\left(\left(1-\theta^2\right) f(z)\right)}\right)\frac{d t}{\sqrt{f(t)-\left(1-\theta^2\right) f(z)}}.
\]
Since $\varphi(0)$ is a simple root of $f$, $\frac{1}{\sqrt{f(z)}}$ is integrable close to $t=\varphi(0)$, and
\[
\int_1^{f_{2}^{-1}\left(\left(1-\theta^2\right) f(z)\right)}\frac{d t}{\sqrt{f(t)-\left(1-\theta^2\right) f(z)}}\to \int_1^{\varphi(0)}\frac{1}{\sqrt{f(t)}}\, dt<\infty\qquad \text{ as } t\to \varphi(0)^-.
\]
On the other hand, since $f$ is increasing in $(0,1)$, for $1>t>z$ we have
\begin{equation}\label{eq:bounded_above_below}
\begin{cases}
\theta\sqrt{f(t)}\leq \sqrt{f(t)-(1-\theta^2)f(z)}\leq \sqrt{f(t)}& \text{ if } \theta^2\leq 1,\\ \max\{{\theta\sqrt{f(z)}},\sqrt{f(t)}\}\leq \sqrt{f(t)-(1-\theta^2)f(z)}\leq \theta\sqrt{f(t)}& \text{ if } \theta^2\geq 1.
\end{cases}
\end{equation}
Therefore, as $z\to 0^+$, $\int_z^{1} \frac{d t}{\sqrt{f(t)-\left(1-\theta^2\right) f(z)}}$ is bounded from above and below by a multiple of
\[
\int_z^1 \frac{1}{\sqrt{f(t)}}\, dt\sim \sqrt{2}\int_z^1 \frac{1}{t}\, dt\sim -\sqrt{2}\ln z.
\]
From this, we deduce the existence of $C>0$ such that
\[
\frac{1}{C}|\ln z|\leq L(p,z)\leq C|\ln z| \qquad \text{ as } z\to 0^+.
\]

\smallbreak

\noindent \emph{Step 2.} Behavior of $L(p,z)$  as $z\to \varphi(0)^-$.\newline

As $z\to \varphi(0)^-$, since $\varphi(0)$ is a simple zero of $f$, $\frac{1}{\sqrt{f(t)}}$ is integrable near $t=\varphi(0)$, and 
\[
f(t)\sim f'(\varphi(0))(t-\varphi(0)),\qquad f_2^{-1}((1-\theta^2)f(t))\sim \varphi(0)+(1-\theta^2)(t-\varphi(0)),
\]we have\footnote{To properly justify the asymptotic estimate, perform a change of variable $t=z+s(f_2^{-1}((1-\theta^2)f(z))-z)$, and use the dominated convergence theorem.}

\begin{align*}
L(p,z)&\sim \frac{1}{\sqrt{2}}\int_z^{ \varphi(0)+(1-\theta^2)(z-\varphi(0))} \frac{dt}{\sqrt{f'(\varphi(0))(t-\varphi(0))-(1-\theta^2)f'(\varphi(0))(z-\varphi(0))}}\, dt\\
 &=\frac{1}{\sqrt{2|f'(\varphi(0))|}}\int_z^{ \varphi(0)+(1-\theta^2)(z-\varphi(0))} \frac{dt}{\sqrt{\varphi(0)+(1-\theta^2)(z-\varphi(0))-t}}\, dt\\
 &=\frac{2}{\sqrt{2|f'(\varphi(0))|}}\left[ \sqrt{\varphi(0)+(1-\theta^2)(z-\varphi(0))-t}\,dt\right]_z^{ \varphi(0)+(1-\theta^2)(z-\varphi(0))}=\frac{\sqrt{2}\theta}{\sqrt{|f'(\varphi(0))|}}\sqrt{\varphi(0)-z}.
\end{align*}



\bigbreak 

\noindent \emph{Step 3.} Behavior of $\frac{\partial L}{\partial z}(p,z)$ as $z\to 0^+$.\newline

Recall now from Lemma \ref{lemma:L'} that
\begin{equation}\label{eq:aux_asym1}
\sqrt{2}\frac{\partial L}{\partial z}(p,z)\left((1-\theta^2)f(z)-f(1)\right)=\theta\frac{f(1)}{\sqrt{f(z)}}+(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{A(t)dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}
\end{equation}
    As $z\to 0^+$, we have
    \begin{equation*}\label{eq:aux_asym2}
   \sqrt{2}\left((1-\theta^2)f(z)-f(1)\right)\to -\sqrt{2}f(1) \quad \text{ and } \quad \theta\frac{f(1)}{\sqrt{f(z)}}\sim \frac{\theta\sqrt{2}f(1)}{z}.
    \end{equation*}
As for the integral term, since $\varphi(0)$ is a simple root of $f$ and $A(t)\sim f(1)/t^2$,
\[
(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{A(t)dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}\sim (1-\theta^2)z\int_z^1 \frac{f(1)}{t^2\sqrt{f(t)-(1-\theta^2)f(z)}}\, dt.
\]
Recalling \eqref{eq:bounded_above_below}, and using
\[
z\int_z^1 \frac{f(1)}{t^2\sqrt{f(t)}}\, dt,\ \frac{zf(1)}{\sqrt{f(z)}}\int_z^1 \frac{dt}{t^2}\sim \frac{\sqrt{2}f(1)}{z},
\]
in \eqref{eq:aux_asym1}, we deduce that
\begin{equation*} 
\frac{\sqrt{2}f(1)}{z}(\theta+1-\theta^2)\lesssim -\sqrt{2}f(1)\frac{\partial L}{\partial z}\leq \frac{\sqrt{2}f(1)}{\theta z} \qquad \text{ if } \theta<1,
\end{equation*}
and
\begin{equation*} 
\frac{\sqrt{2}f(1)}{\theta z}\lesssim -\sqrt{2}f(1)\frac{\partial L}{\partial z}\lesssim \frac{\sqrt{2}f(1)}{\theta z} \qquad \text{ if } \theta\geq 1.
\end{equation*}


\noindent{ \textit{Step 4}.} Behavior of $\frac{\partial L}{\partial z}$ as $z\sim \varphi(0)^-$.\newline

This time,
since
\[
A(t)\sim \frac{1}{2}+\frac{f(1)f''(\varphi(0))}{f'(\varphi(0))^2}=:A_0
\]
we have from \eqref{eq:aux_asym1} that
\begin{align*}
-f(1)\sqrt{2}\frac{\partial L}{\partial z}(p,z) &\sim\frac{\theta f(1)}{\sqrt{f(\varphi(0))(z-\varphi(0))}}+\int_z^{\varphi(0)+(1-\theta^2)(z-\varphi(0))}\frac{A_0 (1-\theta^2)\sqrt{|f'(\varphi(0))|}(\varphi(0)-z)}{\sqrt{\varphi(0)+(1-\theta^2)(z-\varphi(0))-t}}\, dt\\
&\sim \frac{\theta f(1)}{\sqrt{f(\varphi(0))(z-\varphi(0))}},
\end{align*}
as wanted. 
\end{proof}


\begin{lemma}\label{assymptotic_mu_der}
    Fix $p>2$ with $p\neq 6$ and $\theta\in\R$. Then, there exists a constant $C=C(p,\theta)$ such that
    \begin{equation}\label{eq:d_mu_1}
  \frac{1}{C}z|\ln z|  \leq \frac{\partial\mu_1}{\partial z}(p,z,\theta)\leq C z|\ln z| \qquad \text{ for } z\sim 0^+,
    \end{equation}
    \[
        \frac{\partial\mu_1}{\partial z}(p,z,\theta)\sim -\frac{\theta \varphi(0)^2}{\sqrt{2|f'(\varphi(0))|}}\frac{1}{\sqrt{\varphi(0)-z}} \qquad \text{ for } z\sim \varphi(0)^-,
    \]
        and
     \begin{equation}\label{eq:asym_derivative_mu_2}
        \frac{\partial\mu_2}{\partial z}(p,z)\sim\begin{cases}
            z,\ & \text{for}\ z\sim0^+,\\
           \frac{\varphi(0)^2}{\sqrt{2|f'(\varphi(0))|}}\frac{1}{\sqrt{(\varphi(0)-z)}},& \text{for}\ z\sim\varphi(0)^-.
        \end{cases}
    \end{equation}
\end{lemma}


\begin{proof} \emph{Step 1.} Estimates for $\frac{\partial\mu_2}{\partial z}(p,z)$.\newline

    The estimates \eqref{eq:asym_derivative_mu_2} follow directly from the formula (see Lemma \ref{lemma:mu_1reg})
    $$ 
    \frac{\partial\mu_2}{\partial z}(p,z)= \frac{z^2}{\sqrt{2}\sqrt{f(z)}}.
    $$

\smallbreak

\noindent \emph{Step 2.} Estimates for $\frac{\partial\mu_1}{\partial z}(p,z,\theta)$ as $z\to 0^+$.\newline

Recall also from Lemma \ref{lemma:mu_1reg} that
\begin{align}
		\sqrt{2}\frac{\partial\mu_1}{\partial z}(p,z,\theta)&((1-\theta^2)f(z)-f(1))=\theta z^2\frac{f(1)}{\sqrt{f(z)}}\nonumber\\
        &-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}},\label{mu1DerAux}
	\end{align}
where for every $p>2$, the function $g:\R\to\R$ is given by
	$$
    g(t)=3t^2-2t^2\frac{(f(t)-f(1))}{f'(t)^2}f''(t)+4t\frac{(f(t)-f(1))}{f'(t)}.
    $$
Since $t^2-g(t)/2\sim f(1)$, we have
\begin{equation}\label{eq:auxiliary_asymptotic_mu_2}
-\sqrt{2}f(1)\frac{\partial \mu_1}{\partial \theta}(p,z,\theta)\sim \sqrt{2}\theta f(1)z-(1-\theta^2)z\int_z^1 \frac{f(1)}{\sqrt{f(t)+(1-\theta^2)f(z)}}\, dt
\end{equation}
As
\begin{equation}\label{eq:bounded_above_below2}
\begin{cases}
    \theta\sqrt{f(t)}\leq \sqrt{f(t)-(1-\theta^2)f(z)}\leq \sqrt{f(t)}\ \text{ if } \theta^2\leq 1,\\ {\sqrt{f(t)}}\leq \sqrt{f(t)-(1-\theta^2)f(z)}\leq \theta\sqrt{f(t)}\ \text{ if } \theta^2\geq 1
\end{cases}
\end{equation}
for $0<z<t$, the integral term in \eqref{eq:auxiliary_asymptotic_mu_2} is bounded from above and below by a multiple of
\[
z\int_z^1\frac{1}{\sqrt{t}}\, dt\sim z\int_z^1 \frac{\sqrt{2}}{t}\sim -\sqrt{2}z\ln z,
\]
from which \eqref{eq:d_mu_1} follows.

\smallbreak

\noindent \emph{Step 3.} Estimates for $\frac{\partial\mu_1}{\partial z}(p,z,\theta)$ as $z\to \varphi(0)^-$.

This time,
\[
t^2-\frac{g(t)}{2}\sim \varphi(0)^2\to -\frac{\varphi(0)^2}{2}-2\varphi(0)^2f''(\varphi(0))\frac{f(1)}{f'(\varphi(0))^2}+4\varphi(0)\frac{f(1)}{f'(\varphi(t))}=:g_0,
\]
so
\begin{align*}
-\sqrt{2}f(1)\frac{\partial\mu_1}{\partial z}(p,z,\theta)&\sim\theta \varphi(0)^2\frac{f(1)}{\sqrt{f'(\varphi(0))(z-\varphi(0))}}
        -\int_z^{\varphi(0)+(1-\theta^2)(z-\varphi(0))}\frac{(1-\theta^2)g_0f'(\varphi(0))(z-\varphi(0)) dt}{\sqrt{\varphi(0)+(1-\theta^2)(z-\varphi(0))-t}},\\
\end{align*}
as wanted.
\end{proof}

\begin{remark}
    Through a simple (but slightly cumbersome) analysis of the above proofs, one can check that the asymtotic estimates of Lemmas \ref{prop6.1}-\ref{assymptotic_mu_der} are uniform for $p\in [2+\delta,6-\delta]$ and $p\in[6+\delta,1/\delta]$, for any $\delta>0$.
\end{remark}

\begin{proof}[Proof of Theorem \ref{thm:asymptotics}-1.,2]
   For $z\sim0^+$, Lemma \ref{assymptotic_mu_der}, together with \eqref{Theta_1_T'} and \eqref{Theta_1_TADPOLE'}, implies that
    % In conclusion, 
\[
\left| \frac{\partial \Theta_1}{\partial z}(p,z)\right|\leq Cz|\ln z| \quad \text{ for } z\sim 0^+,\qquad 
\left| \frac{\partial \Theta_1}{\partial z}(p,z)\right|\leq C\frac{1}{\sqrt{\varphi(0)-z}} \quad \text{ for } z\sim \varphi(0)^-.
\]
By Lemma \ref{assymptotic_L1},
    \[
    \left|\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z)\frac{1}{\frac{\partial L}{\partial z}(p,z)}\right|\leq 
    \begin{cases}
    Cz^2|\ln z|^2& \text{ for } z\sim 0^+,\\ 
    C\sqrt{\varphi(0)-z}& \text{ for } z\sim \phi(0)^-
    \end{cases}.
    \]
    Since $\Theta_1$ converges to a positive constant (Lemma \ref{prop6.1}), by \eqref{der_Theta_z}, the sign of $\frac{\partial \Theta}{\partial \lambda}$ is determined by $\alpha=\frac{6-p}{2(p-2)}$. In particular, it follows from \eqref{eq:limitzlambda} that, for $p>6$,
    \[
    \frac{\partial \Theta}{\partial \lambda}(p,z)<0  \text{ for }\lambda\sim 0^+,\infty.
    \]
    and, for $p<6$,
     \[
    \frac{\partial \Theta}{\partial \lambda}(p,z)>0  \text{ for }\lambda\sim 0^+,\infty.
    \]
    The conclusion now follows from Theorem \ref{th:5.27}, since conditions $(A_1)$, $(A_2)$ and $(A_3)$ were already verified for the $\mathcal{T}$ and tadpole graphs in Section \ref{sec:GSS_particular}.
\end{proof}


\subsection{Asymptotics in $p$}\label{sec:asymptotics_p}
As the arguments are different, we split this section into two parts, dealing first with the case $p\sim 2^+$ and then with the case $p\sim \infty$.

\subsubsection{Asymptotics for $p\sim 2^+$}


Throughout this section, it is important to observe that, for $\alpha$ given by \eqref{eq:alpha},
\[
\lim_{p\to 2^+}\left(\frac{p}{2}\right)^\frac{1}{p-2}= \sqrt{e}\qquad \text{ and} \qquad \lim_{p\to 2^+} \alpha=\lim_{p\to 2^+}\frac{p-6}{2(p-2)}=\infty.
\]
\begin{lemma}\label{lemma:asympt_p_aux1}
    Take $\delta>0$. Define
    \[
    f_\infty(z):=\frac{z^2}{4}(1-2\ln z),
    \]
    and let $f_{2,\infty}^{-1}$ denote the inverse of $f_\infty|_{[1,\infty)}$.
    Then, as $p\sim 2^+$,
    \begin{equation}\label{eq:asympt_p=2}
        f(z)\sim f_\infty(z)(p-2),\quad f'(z) \sim f'_\infty(z) (p-2),\quad f''(z)\sim f''_\infty(z)(p-2)\quad f'''(z)\sim f'''_\infty(z)(p-2)
    \end{equation}
    and
    \[
    f_2^{-1}((1-\theta^2) f(z))\sim f_{2,\infty}^{-1}((1-\theta^2)f_\infty(z))
    \]
    uniformly for $z\in [\delta,1/\delta]$.
\end{lemma}


\begin{proof}[Proof of Lemma \ref{lemma:asympt_p_aux1}]
    The first three asymptotics follow directly by a Taylor expansion of $f(z)=\frac{z^2}{2}-\frac{z^p}{p}$ with Lagrange remainder. As for the last one, we claim that
 \begin{equation}\label{claimp2}
         f_{2}^{-1}((p-2)\cdot )\to f_{\infty}^{-1}(\cdot) \text{ uniformly in compact sets of } (0,\infty).
 \end{equation}
    Take $z_p:=f_{2}^{-1}((p-2) y)$. First, we observe that $z_p$ is bounded: otherwise, for each $L>0$, we would have (up to a subsequence) $z_p\geq z_0$ and, since $f|_{(1,\infty)}$ is decreasing,
    \[
    y=\frac{f(z_p)}{p-2}\leq \frac{f(L)}{p-2}\to f_\infty(z_0) \qquad \text{ as } p\to 2^+.
    \]
    Since $z_0$ is arbitrary, $y$ varies in a compact set, and $f_\infty(z_0)\to -\infty$ as $L\to \infty$, we obtain a contradiction. 

    Having shown that $z_p\ge 1$ is bounded, by the first estimate in \eqref{eq:asympt_p=2},
    \[
    y=\frac{f(z_p)}{p-2}=\frac{f(z_p)}{p-2}-f_\infty(z_p)+f_\infty(z_p)=f_\infty(z_p)+o(1),
    \]
    from which the claim \eqref{claimp2} follows.

    Finally, by \eqref{eq:asympt_p=2} and \eqref{claimp2},
\[
    f_2^{-1}((1-\theta^2) f(z))\sim f_2^{-1}((1-\theta^2)f_\infty(z)(p-2)+o(p-2))\sim f_{2,\infty}^{-1}((1-\theta^2)f_\infty(z)).\qedhere
\]
\end{proof}

\begin{lemma}\label{lem:lim_z_p2}
    Take $\delta>0$ small. Then, as $p\to 2^+$, uniformly in $z\in (\delta,\sqrt{e}-\delta)$ we have
\begin{equation}\label{eq:asympt_L_p2}
    \sqrt{p-2}\ L(p,z)\sim\frac{1}{\sqrt{2}} \int_z^{f_{2,\infty}^{-1}\left(\left(1-\theta^2\right) f_\infty(z)\right)} \frac{d t}{\sqrt{f_\infty(t)-\left(1-\theta^2\right) f_\infty(z)}}.
\end{equation}
In particular, given $\delta>0$, if $z(p,\lambda)$ is the unique solution to $L(p,z)=\lambda$, then
\begin{equation}\label{eq:lim_z}
    \lim_{p\to2^+}z(p,\lambda)=\sqrt{e},\quad \text{uniformly in }\lambda\in [\delta,1/\delta].
\end{equation}
\end{lemma}
\begin{proof}
    The asymptotic estimate of $L(p,z)$ is a direct consequence of the definition of $L$, formula \eqref{eq:Length}, and Lemma \ref{lemma:asympt_p_aux1}.

    By contradiction, suppose that \eqref{eq:lim_z} does not hold. Since $z(p,\lambda)<(p/2)^{1/(p-2)}\to\sqrt{e}$, there would exist a sequence $(p_n,\lambda_n)$, with $p_n\to 2^+$ and $\lambda_n\in [\delta,1/\delta]$, such that $z(p_n,\lambda_n)<\sqrt{e}-\delta'$, for some $\delta'>0$. In particular, by \eqref{eq:asympt_L_p2} and since the map $z\mapsto L(p,z)$ is strictly  decreasing for each $p>2$,
\begin{align*}
        \sqrt{\lambda_n}=L(p_n,z(p_n,\lambda_n)) &> L(p_n, \sqrt{e}-\delta') \\&\sim \frac{1}{\sqrt{2(p_n-2)}} \int_{\sqrt{e}-\delta'}^{f_{2,\infty}^{-1}\left(\left(1-\theta^2\right) f_\infty(\sqrt{e}-\delta')\right)} \frac{d t}{\sqrt{f_\infty(t)-\left(1-\theta^2\right) f_\infty(\sqrt{e}-\delta')}} \to \infty,
\end{align*}
     which is a contradiction.
\end{proof}

\begin{lemma} \label{lem:lim_p2}
Fix $\delta>0$. Given $\lambda\in [\delta,1/\delta]$, let $z(p,\lambda)$ be the unique solution to $L(p,z)=\sqrt{\lambda}$. Then, as $p\sim 2^+$, uniformly in $\lambda\in[\delta,1/\delta],$
\begin{equation*}
    \sqrt{p-2}\ \mu_1(p,z(p,\lambda),\theta)\sim 0, \quad \sqrt{p-2}\frac{\partial \mu_1}{\partial z}(p,z(p,\lambda),\theta) \sim -\frac{\theta z^2}{\sqrt{2f_\infty(z)}},
\end{equation*}
\begin{equation*}
    \sqrt{p-2}\ \mu_2(p,z(p, \lambda))\sim\frac{1}{\sqrt{2}}\int_0^{\sqrt{e}}\frac{t^2dt}{\sqrt{f_\infty(t)}},\quad \sqrt{p-2}\ \frac{\partial \mu_2}{\partial z}(p,z(p, \lambda))\sim \frac{z^2}{\sqrt{2f_\infty(z)}},
\end{equation*}
and
\begin{equation*}
    \sqrt{p-2}\frac{\partial L}{\partial z}(p, z(p,\lambda)) \sim -\frac{\theta}{\sqrt{2f_\infty(z)}}.
\end{equation*}
\end{lemma}
\begin{proof}
    By Lemmas \ref{lemma:asympt_p_aux1} and \ref{lem:lim_z_p2}, we have
    \[
z(p,\lambda)\sim \sqrt{e},\quad f_2^{-1}((1-\theta^2)f(z(p,\lambda)))\sim \sqrt{e}.
    \]
    On the other hand, the mapping
    \[
    t\mapsto f(t)-(1-\theta^2)f(z(p,\lambda)),\qquad t\in [z(p,\lambda), f_2^{-1}((1-\theta^2)f(z(p,\lambda)))],
    \]
    has a simple root at $t=f_2^{-1}((1-\theta^2)f(z(p,\lambda)))$. In particular, the map $t\mapsto s=f(t)-(1-\theta^2)f(z(p,\lambda))$ is invertible near $t=f_2^{-1}((1-\theta^2)f(z(p,\lambda)))$ and
 \begin{align*}
     &\int_z^{f_2^{-1}((1-\theta^2)f(z(p,\lambda)))}\frac{\text{bounded in }t}{\sqrt{f(t)-(1-\theta^2)f(z(p,\lambda))}}dt \\= &\int_0^{f(z(p,\lambda))-(1-\theta^2)f(z(p,\lambda))}\frac{\text{bounded in }s}{\sqrt{s}}\frac{ds}{f'(t(s))} \to 0\quad \text{ as }p\to 2^+.
 \end{align*}
    Taking into account this consideration, it now suffices to pass to the limit in the expressions of Lemmas \ref{lemma:Theta_1_expressions}, \ref{lemma:mu_1reg} and \eqref{H_p(z,theta)NotSingular}.
\end{proof}

\begin{proposition}
    Under the notations of Lemma \ref{lem:lim_p2}, as $p\sim 2^+$,
    \begin{equation}\label{eq:sinalp2}
         \frac{\partial \Theta}{\partial \lambda}(p,\lambda)=\alpha\Theta_1(p,z(p,\lambda))+\frac{L(p,z(p,\lambda))}{2}\frac{\partial\Theta_1}{\partial z}(p,z(p,\lambda))\frac{1}{\frac{\partial L}{\partial z}(p,z(p,\lambda))}>0
    \end{equation}
     uniformly in $\lambda\in[\delta,1/\delta]$.
\end{proposition}
\begin{proof}
    By Lemma \ref{lem:lim_p2}, and recalling from Lemma \ref{lemma:Theta_1_expressions} the relation between $\Theta_1$, $\mu_1$ and $\mu_2$ in the $\mathcal{T}$ and tadpole graphs, up to positive factors we have
    \[\alpha\Theta_1(p,z(p,\lambda)) \sim \frac{1}{\sqrt{2}(p-2)^{3/2}}\int_0^{\sqrt{e}} \frac{t^2dt}{\sqrt{f_\infty(t)}},\]
    \[
    \sqrt{p-2}\sqrt{f_\infty(z(p,\lambda))}\frac{\partial\Theta_1}{\partial z}(p,z(p,\lambda))\sim 0
    \]
    and
    \[
    \sqrt{p-2}\sqrt{f_\infty(z(p,\lambda))}\frac{\partial L}{\partial z}(p,z(p,\lambda))\sim -1.
    \]
    Since $L(p,z(p,\lambda))=\sqrt{\lambda}$, we find
    \begin{align*}
        \frac{\partial \Theta}{\partial \lambda}(p,\lambda)&=\alpha\Theta_1(p,z(p,\lambda))+\frac{L(p,z(p,\lambda))}{2}\frac{\partial\Theta_1}{\partial z}(p,z(p,\lambda))\frac{1}{\frac{\partial L}{\partial z}(p,z(p,\lambda))}\\&\sim \frac{1}{(p-2)^{3/2}} \to \infty,
    \end{align*}
    and the conclusion follows.
\end{proof}
\begin{proof}[Proof of Theorem \ref{thm:asymptotics}-(a).] Let $\lambda^*=\lambda^*(p)=(L(p,1))^2$. Then, by Lemma \ref{lem:lim_z_p2}, $\lambda^*=(L(p,1))^2\sim \infty$ as $p\sim 2^+$. In particular, for $p$ close to $2$, $\lambda \neq \lambda^*(p)$. The result now follows from \eqref{eq:sinalp2}, Section \ref{sec:GSS_particular} and Theorem \ref{th:5.27}.
\end{proof}





\subsubsection{Asymptotics for $p\to \infty$}
{Observe that, for $\alpha$ given by \eqref{eq:alpha},
\[
\lim_{p\to \infty} \alpha=\lim_{p\to \infty} \frac{p-6}{2(p-2)}=\frac{1}{2}.
\]
In particular, contrary to the case $p\sim 2^+$, where the first term in \eqref{der_Theta_z2} dominated, both terms in \eqref{der_Theta_z2} will be of equal size as $p\sim \infty$. This fact will force us to perform a more precise asymptotic analysis.}
\begin{lemma}\label{lemma1:pinfty}
    Take $\delta>0$. Then, as $p\sim\infty$,
    \begin{equation}
        f(z)\sim \frac{z^2}{2},\quad f'(z) \sim z,\quad f''(z)\sim 1, \quad f_2^{-1}((1-\theta^2)f(z))\sim 1. 
    \end{equation}
    uniformly for $z\in [\delta,1-\delta]$,
\end{lemma}
\begin{proof}
    The first three asymptotics follow directly from the expression for $f(z)=\frac{z^2}{2}-\frac{z^p}{p}$. For the latter, observe that, by the definition of $f_2$, $f_2^{-1}((1-\theta^2)f(z))>1$. If 
    $$\liminf_{p\to \infty} f_2^{-1}((1-\theta^2)f(z))\ge 1+\epsilon,\quad \mbox{ for some } \epsilon>0,$$
    then we would have
    $$
    -\theta^2f(1)<\liminf_{p\to \infty} (1-\theta^2)f(z)\le \liminf_{p\to \infty}f(1+\epsilon) = -\infty,
    $$
    which is a contradiction.
\end{proof}
\begin{lemma}\label{lem:pinfty}
     Take $\delta>0$. Given $z\in[0,1-\delta]$, set $\sigma=-(1-\theta^2)z^2$. Then, as $p\sim\infty$,
     \begin{equation}\label{eq:Lpinfty}
         L(p,z)\sim \int_z^1 \frac{dt}{\sqrt{t^2+\sigma}}=\frac{1}{2}\ln\left(\frac{(\sqrt{1+\sigma}+1)(\theta-1)}{(\sqrt{1+\sigma}-1)(\theta+1)}\right)=:G(\sigma),\quad  \frac{\partial L}{\partial z}(p,z)\sim -\frac{1}{z\sqrt{1+\sigma}},
     \end{equation}
     \begin{equation}\label{eq:mu1pinfty} \mu_1(p,z,\theta)\sim \frac{\sqrt{1+\sigma}}{2} - \frac{\theta z^2}{2} - \frac{\sigma G(\sigma)}{2},\quad \frac{\partial \mu_1}{\partial z}(p,z,\theta)\sim -\theta z - \frac{G(\sigma)\sigma}{z}+ \frac{\sigma}{z\sqrt{\sigma+1}},
     \end{equation}
     \begin{equation}\label{eq:mu2pinfty}
          \mu_2(p,z)\sim \frac{z^2}{2},\quad \frac{\partial \mu_2}{\partial z}(p,z) \sim z,
     \end{equation}
     uniformly in $z\in[\delta,1-\delta]$. In particular, if $K=1/2$ for the $\mathcal{T}$ graph and $K=1$ for the tadpole graph,
     \begin{equation}\label{eq:thetapinfty}
         \Theta_1(p,z)\sim K\left(\sqrt{1+\sigma}-\sigma G(\sigma)\right), \quad \frac{\partial \Theta_1}{\partial z}(p,z) \sim 2K\left( - \frac{G(\sigma)\sigma}{z}+ \frac{\sigma}{z\sqrt{\sigma+1}} \right)
     \end{equation}
     and, for $\alpha=\frac{6-p}{p-2}$,
     \begin{equation}\label{eq:massapinfty}
          \alpha\Theta_1(p,z)\frac{\partial L}{\partial z}(p,z)+\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z)\sim  \frac{K\sigma}{z}G(\sigma)^2\frac{d}{d\sigma}\left(\frac{\sqrt{1+\sigma}}{G(\sigma)}-\sigma\right).
     \end{equation}
\end{lemma}
\begin{proof}
    The proof follows from arguments similar to those used to prove Lemma \ref{assymptotic_mu_der}. 

    We start with the asymptotics for $L$. Since $z$ is bounded away from $0$ and $\varphi(0)$ is a simple zero of $f$, by dominated convergence, the asymptotics derived in Lemma \ref{lemma1:pinfty} yield
    $$
    L(p,z)=\frac{1}{\sqrt{2}}\int_z^{f_2^{-1}((1-\theta^2)f(z))}\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}} \sim \int_z^{1}\frac{dt}{\sqrt{t^2-(1-\theta^2)z^2}} = \int_z^{1}\frac{dt}{\sqrt{t^2+\sigma}}.  
    $$
    Computing explicitly this integral, we arrive at the first equality in \eqref{eq:Lpinfty}. For the second, recall from Lemma \ref{lemma:Theta_1_expressions} that
    \begin{equation}\label{eq:aux_asym11}
\sqrt{2}\frac{\partial L}{\partial z}(p,z)\left((1-\theta^2)f(z)-f(1)\right)=\theta\frac{f(1)}{\sqrt{f(z)}}+(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}\left((1-\theta^2)f(z)\right)}\frac{A(t)dt}{\sqrt{f(t)-(1-\theta^2)f(z)}},
\end{equation}
where $A(t)=\frac{1}{2}-\frac{f(t)-f(1)}{(f'(t))^2}f''(t)$. Observing that $A(t)\sim \frac{1}{2t^2}$,
    \begin{align*}
        -\frac{1}{\sqrt{2}}\frac{\partial L}{\partial z}(p,z)(\sigma +1) = \frac{\theta}{\sqrt{2}z}-\frac{\sqrt{2}\sigma}{z}\int_z^1 \frac{dt}{2t^2\sqrt{t^2+\sigma}} = \frac{\theta}{\sqrt{2}z} + \frac{\sigma}{\sqrt{2}z}\left[\frac{\sqrt{t^2+\sigma}}{t\sigma}\right]_z^1 = \frac{\sqrt{1+\sigma}}{\sqrt{2}z}
    \end{align*}
    which concludes the proof of \eqref{eq:Lpinfty}. Next, we have
\begin{align*}
        \mu_1(p,z,\theta)&=\frac{1}{\sqrt{2}}\int_z^{f_2^{-1}((1-\theta^2f(z)))}\frac{t^2 dt}{\sqrt{f(t)-(1-\theta^2)f(z)}}\\&\sim \int_z^{1}\frac{t^2dt}{\sqrt{t^2-(1-\theta^2)z^2}} \\&= \left[\frac{t\sqrt{t^2+\sigma}}{2}\right]_{z}^1 - \frac{\sigma}{2}\int_z^1 \frac{dt}{\sqrt{t^2-(1-\theta^2)z^2}} = \frac{\sqrt{1+\sigma}}{2}-\frac{\theta z^2}{2} - \frac{\sigma G(\sigma)}{2}.
\end{align*}
From \eqref{mu1DerAux},
\begin{align*}
    		\sqrt{2}\frac{\partial\mu_1}{\partial z}(p,z,\theta)&((1-\theta^2)f(z)-f(1))=\theta z^2\frac{f(1)}{\sqrt{f(z)}}\nonumber\\
        &-(1-\theta^2)f'(z)\int_z^{f_{2}^{-1}((1-\theta^2)f(z))}\left(t^2-\frac{g(t)}{2}\right)\frac{dt}{\sqrt{f(t)-(1-\theta^2)f(z)}},\label{mu1DerAux}
\end{align*}
and thus
\begin{align*}
    -\frac{1+\sigma}{\sqrt{2}}\frac{\partial \mu_1}{\partial z}(p,z,\theta)&\sim \frac{\theta z}{\sqrt{2}} - \frac{(1-\theta^2)z}{\sqrt{2}}\int_z^1 \left(\frac{1}{2}-t^2\right)\frac{dt}{\sqrt{t^2+\sigma}}\\&= \frac{\theta z}{\sqrt{2}} + \frac{\sigma}{\sqrt{2}z} \left((\sigma+1)G(\sigma)-\sqrt{\sigma+1}+\theta z^2\right)\\&=-\frac{1+\sigma}{\sqrt{2}}\left(-\theta z - \frac{G(\sigma)\sigma}{z}+ \frac{\sigma}{z\sqrt{\sigma+1}}\right),
\end{align*}
which proves \eqref{eq:mu1pinfty}. Finally, \eqref{eq:mu2pinfty} follows from 
$$
\mu_2(p,z)=\frac{1}{\sqrt{2}}\int_0^z \frac{t^2dt}{\sqrt{f(t)}} \sim \int_0^t t dt = \frac{z^2}{2}\quad, \frac{\partial \mu_2}{\partial z}=\frac{z^2}{\sqrt{2f(z)}}\sim z.
$$
The proof of \eqref{eq:thetapinfty}  follows from using \eqref{Theta_1_T'} (for the $\mathcal{T}$ graph) and \eqref{Theta_1_TADPOLE'} (for the tadpole graph). Finally, since $\alpha \to -1/2$, \eqref{eq:massapinfty} is a consequence of
\begin{equation}
    \alpha\Theta_1(p,z)\frac{\partial L}{\partial z}(p,z)+\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z) \sim \frac{L^2(p,z)}{2} \frac{\partial}{\partial z}\left(\frac{\Theta_1(p,z)}{L(p,z)}\right)\sim  \frac{K\sigma}{z}G(\sigma)^2\frac{d}{d\sigma}\left(\frac{\sqrt{1+\sigma}}{G(\sigma)}-\sigma\right).
\end{equation}
\end{proof}
\begin{proposition}
  For $z\in[\delta,1-\delta]$, as $p\sim \infty$,
    \begin{equation}\label{eq:sinalpinfty}
        \alpha\Theta_1(p,z)\frac{\partial L}{\partial z}(p,z)+\frac{L(p,z)}{2}\frac{\partial\Theta_1}{\partial z}(p,z)>0.
    \end{equation}
    In particular, as $p\sim \infty$,
\begin{equation}\label{eq:sinalpinfty2}
        \frac{\partial \Theta}{\partial \lambda}(p,\lambda) < 0, \quad  \mbox{ uniformly in }\lambda\in[\delta,1/\delta].
\end{equation}
\end{proposition}
\begin{proof}
\textit{Step 1. Proof of \eqref{eq:sinalpinfty}.} By Lemma \ref{lem:pinfty}, the claim is equivalent to
$$
\sigma \frac{d}{d\sigma}\left(\frac{\sqrt{1+\sigma}}{G(\sigma)}-\sigma\right)>0.
$$
Fix first the case of the $\mathcal{T}$ graph, where $\theta=2$. Then $\sigma=-(1-\theta^2)z^2>0$. For $\xi=\sqrt{1+\sigma}=\sqrt{1+3z^2}\in (1,2)$, we want to check that
\begin{align*}
    0<\frac{d}{d\xi}\left(\frac{\xi}{\ln\left(\frac{\xi+1}{3(\xi-1)}\right)}-\frac{\xi^2-1}{2}\right)&= \frac{1}{\ln^2\left(\frac{\xi+1}{3(\xi-1)}\right)}\left(\ln\left(\frac{\xi+1}{3(\xi-1)}\right)+\frac{2\xi}{\xi^2-1}-\xi\ln^2\left(\frac{\xi+1}{3(\xi-1)}\right)\right)\\&=:\frac{1}{\ln^2\left(\frac{\xi+1}{3(\xi-1)}\right)}h(\xi).
\end{align*}
A direct computation shows that
$$
h'(\xi)=-\left(\ln\left(\frac{\xi+1}{3(\xi-1)}\right)-\frac{2\xi}{\xi^2-1}\right)^2<0,\quad h(2)=\frac{4}{3}.
$$
Therefore $h>0$ over $(1,2)$, which concludes the proof of \eqref{eq:sinalpinfty} for the $\mathcal{T}$ graph. For the tadpole graph, $\theta=1/2$ and $\sigma=-(1-\theta^2)z^2<0.$ Writing once again $\xi=\sqrt{1+\sigma}=\sqrt{1-\frac{3}{4}z^2}\in (0,1)$, we need to verify that
\begin{align*}
    0>\frac{d}{d\xi}\left(\frac{\xi}{\ln\left(\frac{\xi+1}{3(1-\xi)}\right)}-\frac{\xi^2-1}{2}\right)&= \frac{1}{\ln^2\left(\frac{\xi+1}{3(1-\xi)}\right)}\left(\ln\left(\frac{\xi+1}{3(1-\xi)}\right)+\frac{2\xi}{\xi^2-1}-\xi\ln^2\left(\frac{\xi+1}{3(1-\xi)}\right)\right)\\&=:\frac{1}{\ln^2\left(\frac{\xi+1}{3(1-\xi)}\right)}j(\xi).
\end{align*}
Again, by direct computation,
$$
j'(\xi)=-\left(\ln\left(\frac{\xi+1}{3(1-\xi)}\right)-\frac{2\xi}{\xi^2-1}\right)^2<0,\quad j(0)=\ln\frac{1}{3}<0
$$
and thus $j<0$ over $(0,1)$. This concludes the proof of \eqref{eq:sinalpinfty}.

\textit{Step 2.} We claim that, letting $z(p,\lambda)$ be the (unique) solution to $\sqrt{\lambda}=L(p,z)$, there exists $\delta>0$ such that $z(p,\lambda)\in [\delta,1-\delta]$, uniformly in $\lambda\ge \lambda_0$. 

By contradiction, suppose that there exists a sequence $(p_n,\lambda_n)$, with $p_n\to \infty$ and $\lambda_0<\lambda_n$, such that  $z(p_n,\lambda_n)\ge 1$. As $z\mapsto G(-(1-\theta^2)z)$ is strictly decreasing, with $G(0^+)=+\infty$ and $G(1)=0$, we may let $z_0\in (0,1)$ be the unique solution to $G(-(1-\theta^2)z)=\sqrt{\lambda_0}$. Then, for $n$ large, $z(p_n,\lambda_n)>\frac{z_0+1}{2}>z_0$. Since, for each fixed $p\in (2,\infty)$, $z\mapsto L(p,z)$ is strictly decreasing,
$$
\sqrt{\lambda_n}=L(p_n,z(p_n,\lambda_n)) < L\left(p_n,\frac{z_0+1}{2}\right)
$$
and, passing to the limit,
$$
\sqrt{\lambda_0} \le \lim L\left(p_n,\frac{z_0+1}{2}\right) =  G\left(-(1-\theta^2)\frac{z_0+1}{2}\right) <  G\left(-(1-\theta^2)z_0\right) =\sqrt{\lambda_0},
$$
which is absurd. This proves that $z(p,\lambda)<1-\delta$, for some $\delta>0$. A similar argument can be used to show that $z(p,\lambda)>\delta$ and the claim follows.

\textit{Step 3.} For $\lambda>0$ fixed, we need to prove that, as $p\sim \infty$, the expression in \eqref{der_Theta_z}, with $z=z(p,\lambda)$, is strictly negative. Since $\frac{\partial L}{\partial z}<0$, it is enough to check that 
\begin{equation}
    \alpha\Theta_1(p,z(p,\lambda))\frac{\partial L}{\partial z}(p,z(p,\lambda))+\frac{L(p,z(p,\lambda))}{2}\frac{\partial\Theta_1}{\partial z}(p,z(p,\lambda))>0,
\end{equation}
which follows directly from Steps 1 and 2.
\end{proof}

\begin{proof}{Proof of Theorem \ref{thm:asymptotics}-(b).} Let $\lambda^*=\lambda^*(p)=(L(p,1))^2$. Then, arguing as in the proof of Lemma \ref{lem:pinfty}, $\lambda^*\sim 0$ as $p\sim \infty$. In particular, for $p$ large, $\lambda \neq \lambda^*(p)$. The result now follows from \eqref{eq:sinalpinfty2} and the Grillakis-Shatah-Strauss theory developed in Section \ref{sec:GSS_particular}.
\end{proof}


