In this section we give  more details on the proof of Theorem \ref{thm4}. More precisely we derive in Theorem \ref{thm3} below the weak convergence in \eqref{det100}, which is the essential ingredient in the proof of Theorem \ref{thm4}.
Our first result provides a uniform Bahadur expansion for the estimators of the semiparametric distribution regression model.

\begin{theorem}\label{thm1}
Under Assumption \ref{ass:1}, it holds for $\ell=1,2$
\begin{equation}\label{theoremA1}
\sqrt{n_\ell}\big(\hat \beta ^{\ell}(t,y)- \beta ^{\ell}(y)\big)= -\tfrac{1}{\sqrt{n_\ell}} {C_\ell^{-1}  \over t}S^\ell_{\lfloor n_\ell t \rfloor}(\beta^\ell(y))+D_n(t,y)
\end{equation}
 where
$$S_k^\ell(\beta(y))=\sum_{i=1}^k R_i^\ell(\beta^\ell(y)),$$
\begin{equation*}
    R_i^\ell(\beta^\ell(y)) = X^\ell_i I_{\{Y_i^\ell\leq y\}}\frac{\lambda\big(X_i^{\ell^\top }\beta^\ell(y)\big)}{\Lambda\big(X_i^{\ell^\top }\beta^\ell(y)\big)} - X^\ell_i (1-I_{\{Y_i^\ell> y\}})\frac{\lambda\big(X_i^{\ell^\top }\beta^\ell(y)\big)}{\Lambda\big(X_i^{\ell^\top }\beta^\ell(y)\big)}, 
\end{equation*}
\begin{equation*}
C_\ell=\mathbb{E}\Big[\frac{\partial}{\partial \beta^\ell(y)} R_i^\ell\big(\beta^\ell(y)\big) \Big] \in \mathbb{R}^{p\times p}.
\end{equation*}
and the remainder satisfies 
$\sup_{(t,y)\in[\epsilon,1]\times I} |D_n(t,y)| \rightarrow 0$ for $n_\ell \rightarrow \infty$.
\end{theorem}
\begin{proof}
Using a Taylor approximation as in the proof of Theorem 5.2 in \citet{chernozhukov:2013}, we obtain
\begin{equation*}
\sqrt{n_\ell}\big(\hat \beta ^{\ell}(t,y)- \beta ^{\ell}(y)\big)= -\tfrac{1}{\sqrt{n_\ell}} \left(\frac{1}{n_\ell}\sum_{i=1}^{[n_\ell t]} \frac{\partial}{\partial \beta^\ell(y)} R_i^\ell\big(\beta^\ell(y)\big)\right)^{-1}S^\ell_{\lfloor n_\ell t \rfloor}(\beta^\ell(y))+D_n(t,y)
\end{equation*}
with
\begin{equation*}
D_n(t,y) = - \frac{1}{2} \left(\frac{1}{n_\ell}\sum_{i=1}^{[n_\ell t]} \frac{\partial}{\partial \beta^\ell(y)} R_i^\ell\big(\beta^\ell(y)\big)\right)^{-1} E_n(t,y)\left(\sqrt{n_\ell}\big(\hat \beta ^{\ell}(t,y)- \beta ^{\ell}(y)\big),\hat \beta ^{\ell}(t,y)- \beta ^{\ell}(y)\big)\right),
\end{equation*}
where $E_n(t,y)$ is a bilinear form, which contains the appropriate entries of the matrix 
\begin{equation*}
\frac{1}{n_\ell}\sum_{i=1}^{[n_\ell t]} \frac{\partial}{\partial \beta^\ell(y) \partial \beta^\ell(y)^\top } R_i^\ell\big(\tilde \beta^\ell(y)\big).
\end{equation*}
Here, $\tilde \beta^\ell(t,y)$ is some intermediate point  between $\hat \beta^\ell(t,y)$ and $\beta^\ell(y)$. By similar arguments as given in the proof of Theorem 5.2 in \citet{chernozhukov:2013}, it follows that
$\sup_{(t,y) \in [\epsilon,1] \times I} |\hat \beta^\ell(t,y) - \beta^\ell(y)| \rightarrow_p 0$ for $n \rightarrow \infty$. Therefore, the statement of Theorem \ref{thm1} follows from the boundedness conditions in Assumption 1.
    \end{proof}
We continue noting  that 
\begin{align}
\label{det101}
\left\{\tfrac{1}{\sqrt{n_\ell}}S^\ell_{\lfloor n_\ell t \rfloor}(\beta^\ell(y))\right\}_{(t,y)\in Q}
\end{align} 
is a $p$-dimensional process on $Q=[\epsilon,1]\times I$, and  define 
\begin{equation*}
    \ell^\infty(Q,\mathbb{R}^p):=\Big \{f:Q\rightarrow \mathbb{R}^p \vert\ ||f||_\infty=||(f_1,\ldots,f_p)^\top ||_\infty :=\max_{i=1}^p||f_i||_\infty <\infty\Big \}
\end{equation*}
 as the set of all $p$-dimensional functions defined on $Q$ with bounded components.
 Our next result establishes the weak convergence of the process defined by  \eqref{det101} in $ \ell^\infty(Q,\mathbb{R}^p)$.



\begin{theorem}\label{thm2}
Under Assumption \ref{ass:1}, it holds  for $\ell=1,2$
\begin{equation*}
\left\{\tfrac{1}{\sqrt{n_\ell}}S^\ell_{\lfloor n_\ell t \rfloor}(\beta^\ell(y))\right\}_{(t,y)\in Q} \leadsto \left\{\mathbb{G}^\ell(t,y)\right\}_{(t,y)\in Q}
\end{equation*}
in $\ell^\infty(Q,\mathbb{R}^p)$, where $\mathbb{G}^\ell$ is a centered Gaussian process with covariance structure
\begin{equation*}
Cov\big(\mathbb{G}^\ell(t_1,y_1),\mathbb{G}^\ell(t_2,y_2)\big)=(t_1 \land t_2)\ C^\ell(y_1,y_2)
\end{equation*}
with
\begin{eqnarray*}
C^\ell(y_1,y_2) = \mathbb{E}\bigg[X_i^\ell X_i^{\ell^\top }  \frac{\lambda\big(X_i^{\ell^\top }\beta^\ell(y_1)\big)\lambda\big(X_i^{\ell^\top }\beta^\ell(y_2)\big)\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_1)\big)\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_2)\big)}{\big(1-\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_1)\big)\big)\big(1-\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_2)\big)\big)}\cdot \\
\Big\{\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_1 \land y_2)\big)-\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_1)\big)\Lambda\big(X_i^{\ell^\top }\beta^\ell(y_2)\big)\Big\}
\bigg].
\end{eqnarray*}
\end{theorem}
\begin{proof} 
By Theorem 5.2 in \citet{chernozhukov:2013}, for $\ell =1,2$, the process 
$$
\left\{\tfrac{1}{\sqrt{n_\ell}}S^\ell_{\lfloor n_\ell \rfloor}(\beta^\ell(y))\right\}_{y\in I}
$$
fulfills a functional central limit theorem, where the covariance kernel of the limiting (centered) Gaussian process in $\ell^\infty (I) $ is given by $C^\ell(y_1,y_2)$. The statement of Theorem \ref{thm2} then follows with the equivalence of the conditions (A) and (F) in Theorem 1.1 in \citet{sheehy:1992}.
\end{proof}

A direct consequence of Theorem \ref{thm1} and \ref{thm2} is the following corollary.

\begin{kor}
Under Assumption \ref{ass:1}, it holds for $\ell=1,2$
\begin{eqnarray*}
\left\{\sqrt{n_\ell}\big(\hat \beta ^{\ell}(t,y)- \beta ^{\ell}(y)\big)\right\}_{(t,y)\in Q} \leadsto \left\{{1 \over t} \mathbb{G}^\ell(t,y)\right\}_{(t,y)\in Q}
\end{eqnarray*}
in $\ell^\infty(Q,\mathbb{R}^p)$, where the $p$-dimensional Gaussian process $\mathbb{G}^\ell$ is defined in Theorem \ref{thm2}.
\end{kor}
We now consider the mapping 
\begin{eqnarray}
\label{det1}
    \Phi: \begin{cases}
      \ell^\infty(Q,\mathbb{R}^p)\times\ell^\infty(Q,\mathbb{R}^p) &\rightarrow\ \ell^\infty(Q) \\
      \big(\gamma^1,\gamma^2\big) &\rightarrow\ \Phi\big(\gamma^1,\gamma^2\big)
    \end{cases}~,
\end{eqnarray}
where the function $\Phi\big(\gamma^1,\gamma^2\big): Q \to \mathbb{R}$ is defined by 
\begin{equation}
\label{det2?}
    \Phi\big(\gamma^1,\gamma^2\big)(t,y)=\Lambda\big(x^\top \gamma^1(t,y)\big) - \Lambda\big(x^\top \gamma^2(t,y)\big).
\end{equation}
In the following we interpret the function $\beta^\ell: y\mapsto\beta^\ell(y)$ as a function $(y,t)\mapsto \beta^\ell(y)$ defined on the domain $Q$, which is constant with respect to the second argument $t$. This  gives the representation 
\begin{eqnarray*}
\Phi\big(\beta^1,\beta^2\big)(t,y) &=& \Lambda\big(x^\top \beta^1(y)\big) - \Lambda\big(x^\top \beta^2(y)\big) \\
&=& F^1_{Y|X}(y|x) - F^2_{Y|X}(y|x) \\
&=:& \Delta(y|x).
\end{eqnarray*}
Interpreting the estimators $\hat \beta^\ell$ in the same way, we have 
\begin{eqnarray*}
\Phi\big(\hat\beta^1,\hat\beta^2\big)(t,y) &=& \Lambda\big(x^\top \hat\beta^1(y)\big) - \Lambda\big(x^\top \hat\beta^2(y)\big) \\
&=& \hat F^1_{Y|X}(t,y|x) - \hat F^2_{Y|X}(t,y|x) \\
&=:& \hat\Delta(t,y|x),
\end{eqnarray*}
and by the functional Delta method (\citealp{VaartWellner2023}) we obtain the following result.


\begin{theorem}\label{thm3}
    Under Assumption \ref{ass:1} and $n=n_1+n_2$, $\tfrac{n_1}{n_1+n_2}\rightarrow c$, it holds
    \begin{equation*}
   \left\{\sqrt{n}\big(\hat\Delta(t,y|x)- \Delta(y|x)\big)\right\}_{(t,y)\in Q} \leadsto \left\{\mathbb{H}(t,y)\right\}_{(t,y)\in Q} ~, 
\end{equation*}
where $\mathbb{H}$ is a centered real valued Gaussian process with covariance structure
\begin{equation} \label{det3}
    Cov\big(\mathbb{H}(t_1,y_1),\mathbb{H}(t_2,y_2)\big)= {t_1 \land t_2  \over t_1t_2} \cdot H(y_1,y_2)
\end{equation}
and
\begin{equation}\label{eq:H}
  H(y_1,y_2) = {1 \over c} \lambda\big(x^\top \beta^1(y_1)\big )^2 x^\top C^1(y_1,y_2) x + {1 \over 1-c} \lambda\big(x^\top \beta^2(y_2)\big )^2 x^\top C^2(y_1,y_2) x.
\end{equation}
\end{theorem}
\begin{proof}
Note that  the mapping $\Phi$ defined 
 in \eqref{det1} is Hadamard differentiable at the point $(\beta^1,\beta^2) \in  \ell^\infty(Q,\mathbb{R}^p)\times\ell^\infty(Q,\mathbb{R}^p) $ with derivative
    \begin{eqnarray}
    \Phi^\prime _{(\beta^1,\beta^2) }: 
    \begin{cases}
      \ell^\infty(Q,\mathbb{R}^p)\times\ell^\infty(Q,\mathbb{R}^p) &\rightarrow\ \ell^\infty(Q) \\
      \big(\gamma^1,\gamma^2\big) &\rightarrow\ \Phi 
      ^\prime _{(\beta^1,\beta^2)}
      \big(\gamma^1,\gamma^2\big)
    \end{cases}
\end{eqnarray}
where the function $\Phi 
      ^\prime _{(\beta^1,\beta^2)}
      \big(\gamma^1,\gamma^2\big): Q \to \mathbb{R} $ is defined by 
\begin{equation}
\label{det2}
    \Phi ^\prime _{(\beta^1,\beta^2)}\big(\gamma^1,\gamma^2\big)(t,y)=\Lambda^\prime \big(x^\top \beta^1(y)\big )x^\top\gamma^1(t,y) - \Lambda^\prime \big(x^\top \beta^2(y) \big )x^\top\gamma^2(t,y).
\end{equation}
Then, by the functional delta method it follows that  
\begin{align*} &\left\{\sqrt{n}\big(\hat\Delta(t,y|x)- \Delta(y|x)\big)\right\}_{(t,y)\in Q} \\ & =   \sqrt{n} \left\{
     \Phi\big(\hat\beta^1,\hat\beta^2\big)(t,y) - 
    \Phi\big(\beta^1,\beta^2\big)(t,y) 
     \right\}_{(t,y)\in Q} \\
    &=   \Phi ^\prime _{(\beta^1,\beta^2)}\Big( \sqrt{n}\big \{ \hat \beta ^{1}(t,y)- \beta ^{1}(y),
   \hat \beta ^{2}(t,y)- \beta ^{2}(y) \big \} _{(t,y)\in Q}
       \Big )  + o_{\mathbb{P}}(1) \\
    &  \leadsto \left\{\mathbb{H}(t,y)\right\}_{(t,y)\in Q}:= 
     \Phi ^\prime _{(\beta^1,\beta^2)}\Big( \Big \{ {1 \over\sqrt{c} } {1 \over\  t} \mathbb{G}^1(t,y) , {1 \over\sqrt{1-c} }{1 \over  t} \mathbb{G}^2(t,y)
      \Big \} _{(t,y)\in Q}
       \Big )~,
\end{align*}
where the $p$-dimensional Gaussian processes $\mathbb{G}^1$  and  $\mathbb{G}^2$ are defined in Theorem \ref{thm2}. Observing the definition of the derivative in \eqref{det2}, we see that
\begin{equation*}
\mathbb{H}(t,y) = \Lambda^\prime \big(x^\top \beta^1(y)\big )x^\top {1 \over\sqrt{c} } {1 \over\  t} \mathbb{G}^1(t,y) - \Lambda^\prime \big(x^\top \beta^2(y) \big )x^\top{1 \over\sqrt{1-c} } {1 \over\  t} \mathbb{G}^2(t,y).
\end{equation*}
It is now straightforward to show that the covariance structure of the limiting process factorizes as stated in \eqref{det3}. 
\end{proof}

