Let $K_4^-$ denote the graph with vertex set $V(K_4)$ and edge set $E(K_4) \setminus \{\{3,4\}\}$.

\begin{construction}\label{ConsB} \emph{Consider any $k \in \mathbb{N}$. Let $F_1, \dots, F_k$ be pairwise vertex-disjoint graphs, where $F_k \simeq K_3$ and $F_i \simeq K_4^-$ for each $i \in [k-1]$. For each $i \in [k-1]$, let $v_i, v_i', w_i, w_i'$ be the vertices of $F_i$ corresponding to the vertices $1, 2, 3, 4$ of $K_4^-$, respectively. Let $v_k, v_k', w_k$ be the vertices of $F_k$ corresponding to the vertices $1, 2, 3$ of $K_3$, respectively. Let $B_k^*$ be the connected $(4k-1)$-vertex graph with vertex set $\bigcup_{i=1}^{k} V(F_i)$ and edge set $\left( \bigcup_{i=1}^{k} E(F_i) \right) \cup \bigcup_{i=1}^{k-1} \{w_iv_{i+1}, w_i'v_{i+1}'\}$.}
\end{construction}

Note that $B_1^* \simeq K_3$ and $B_2^*$ is the graph $G_{7,6}$ in~\cite{BBS}. The following is one of the results proved in the next section. 

\begin{proposition}\label{PropB} For any $k \geq 1$, $B_k^*$ has no induced $6$-cycles and
%
\[\iota(B_k^*,P_3) = k = \frac{|V(B_k^*)|+1}{4}.\]
%
\end{proposition}
%
\noindent
Using Construction~\ref{ConsB}, for any $n \geq 1$, we now construct a connected $n$-vertex graph $B_n$ with no induced $6$-cycles and with $\iota(B_n,P_3) = \lfloor (n+1)/4 \rfloor$ (see Corollary~\ref{PropBcor}).

\begin{construction}\label{ConsB2} \emph{Consider any $n \in \mathbb{N}$. Let $k = \lfloor (n+1)/4 \rfloor$. Thus, $n+1 = 4k + r$ for some $r \in \{0, 1, 2, 3\}$. If $k = 0$, then let $B_n = P_n$. If $r = 0$, then let $B_n = B_k^*$. If $k \geq 1$ and $r \geq 1$, then let $F^* \simeq P_{r+1}$ such that $V(B_k^*) \cap V(F^*) = \{v_1\}$, and let $B_n$ be the connected $n$-vertex graph with vertex set $V(B_k^*) \cup V(F^*)$ and edge set $E(B_k^*) \cup E(F^*)$.}
\end{construction}
%
\noindent
Note that $\Delta(B_n) = 4$. Thus, there are infinitely many graphs $G$ with $\Delta(G) = 4$ and $\iota(G,P_3) > n/4$, and as mentioned above, there are 12 graphs $G$ with $\Delta(G) \leq 3$ and $\iota(G,P_3) > n/4$. We show that $\iota(G,P_3) \leq n/4$ if $\Delta(G) \geq 5$. In light of this fact, for any $h \geq 5$ and $n \geq 4(h-2)$, we construct a connected $n$-vertex graph $B_{n,K_3,h}$ with no induced $6$-cycles and with $\iota(B_{n,K_3,h}, P_3) = \lfloor n/4 \rfloor$ and $\Delta(B_{n,K_3,h}) = h$ (see Figure~\ref{FigB3} and Proposition~\ref{PropB3}). We modify the construction of the graph $B_{n,F}$ with $F = K_3$ in \cite{Borg1}.


