\begin{construction}\label{ConsB3} \emph{Consider any $n, h \in \mathbb{N}$ with $h \geq 5$ and $n \geq 4(h-2)$. Let $a_n = \lfloor n/4 \rfloor$, let $b_{n} = n - 3a_{n}$ (so $a_{n} \leq b_{n} \leq a_{n} + 3$), let $F_1, \dots, F_{a_{n}}$ be copies of $K_3$ such that $P_{b_{n}}, F_1, \dots, F_{a_{n}}$ are pairwise vertex-disjoint, and let $B_{n,K_3,h}$ be the connected $n$-vertex graph with vertex set $[b_{n}] \cup \bigcup_{i=1}^{a_{n}} V(F_i)$ and edge set $(E(P_{b_{n}}) \setminus E(P_{h-2})) \cup \{\{1,i+1\} \colon i \in [h-3]\} \cup \bigcup_{i=1}^{a_{n}} (E(F_i) \cup \{\{i,v\} \colon v \in V(F_i)\})$.}
