We now state our main result, proved in Section~\ref{Sectionpf}.

\begin{theorem}\label{ThmP3beyond} Let $G$ be a connected $n$-vertex graph that has no induced $6$-cycles. Then, 
%
\begin{equation} \iota(G,P_3) \leq \left \lfloor \frac{n+1}{4} \right \rfloor, \label{thmfact1} 
\end{equation}
%
and equality holds if $G = B_n$. Moreover, the following statements hold:\medskip 
\\
(a) If $\iota(G,P_3) = \frac{n+1}{4}$, then for each $v \in V(G)$,
%
\[\iota(G-v,P_3) \leq \iota(G,P_3) - 1.\]
%
(b) If $h = \Delta(G) \geq 5$ or $\iota(G,P_3) \neq \frac{n+1}{4}$, then 
%
\begin{equation} \iota(G,P_3) \leq \left \lfloor \frac{n}{4} \right \rfloor, \label{thmfact2} 
\end{equation}
%
and equality holds if $n \geq 4(h-2)$ and $G = B_{n,K_3,h}$.
\end{theorem}
%
\noindent
Theorem~\ref{ThmP3beyond} has the following immediate consequence.
%
\begin{corollary} For any $n \geq 1$,
%
\[f(n) = \left \lfloor \frac{n+1}{4} \right \rfloor.\]
%
\end{corollary}
%

It is worth pointing out that the bound in (\ref{thmfact1}) appears to be the first of its kind because, as indicated above, sharp upper bounds on $\iota(G,\mathcal{F})$ in terms of $n$ are typically of the form $\alpha n$ for some positive constant $\alpha < 1$. Despite this intriguing fact, we provide an affirmative answer to the above-mentioned question of Huang, Zhang and~Jin.

\begin{corollary}[Solution to {\cite[Problem 5.1]{HZJ}}]\label{CorLimsup} %$f(n)$ be $\max\{\iota(G, P_3) \colon G \mbox{ is a connected $n$-vertex graph with no induced $6$-cycles}\}$ 
\[\limsup_{n \to\infty} \frac{f(n)}{n} = \frac{1}{4}.\] 
\end{corollary}
\proof{By Theorem~\ref{ThmP3beyond}, for any $n \in \mathbb{N}$, we have $\frac{f(n)}{n} \leq \frac{1}{4}$ if $4$ does not divide $n+1$, and $\frac{f(n)}{n} = \frac{1}{4} + \frac{1}{4n}$ if $4$ divides $n+1$. Let $n^+$ be the smallest integer in $\{k \in \mathbb{N} \colon k \geq n, \, 4 \mbox{ divides } k+1\}$. Thus, $\lim_{n \rightarrow \infty} \sup \left\{\frac{f(k)}{k} \colon k \geq n \right\}  = \lim_{n \rightarrow \infty} \left( \frac{1}{4} + \frac{1}{4n^+} \right)  = \frac{1}{4}$. \qed}




\section{Proof of Theorem~\ref{ThmP3beyond}}\label{Sectionpf}

We now prove Theorem~\ref{ThmP3beyond}. We often use the following two lemmas from~\cite{Borg1}.

\begin{lemma}[\cite{Borg1}]\label{LemIsol1} If $G$ is a graph, $\mathcal{F}$ is a set of graphs, $X\subseteq V(G)$, and $Y\subseteq N[X]$, then \[\iota(G,\mathcal{F}) \leq |X| + \iota(G-Y,\mathcal{F}).\]
\end{lemma}
%
\noindent
\textbf{Proof.} Let $D$ be an $\mathcal{F}$-isolating set of $G-Y$ of size $\iota(G-Y, \mathcal{F})$. Clearly, $V(F) \cap Y \neq \emptyset$ for each $\mathcal{F}$-graph $F$ that is a subgraph of $G$ and not a subgraph of $G-Y$. Since $Y \subseteq N[X]$, $X \cup D$ is an $\mathcal{F}$-isolating set of $G$. The result follows.~\hfill{$\Box$}
\\
\\
%\parskip=0pt
\indent A \emph{component} of a graph $G$ is a maximal connected subgraph of $G$. Clearly, the components of $G$ are pairwise vertex-disjoint (that is, no two have a common vertex), and their union is $G$. The set of components of $G$ is denoted by $\mathrm{C}(G)$.  
%\parskip=4pt

\begin{lemma}[\cite{Borg1}]\label{LemIsol2} If $G$ is a graph and $\mathcal{F}$ is a set of connected graphs, then \[\iota(G,\mathcal{F}) = \sum_{H \in \mathrm{C}(G)}\iota(H,\mathcal{F}).\]
\end{lemma}
%
\noindent
\textbf{Proof.} Let $G_1, \dots, G_r$ be the distinct components of $G$. For each $i \in [r]$, let $D_i$ be a smallest $\mathcal{F}$-isolating set of $G_i$. Consider any $\mathcal{F}$-graph $F$ contained by $G$. Since $F$ is connected, $G_j$ contains $F$ for some $j \in [r]$, so $N[D_j] \cap V(F) \neq \emptyset$. Thus, $\bigcup_{i = 1}^r D_i$ is an $\mathcal{F}$-isolating set of $G$, and hence $\iota(G, \mathcal{F}) \leq \sum_{i = 1}^r |D_i| = \sum_{i = 1}^r \iota(G_i, \mathcal{F})$. Let $D$ be a smallest $\mathcal{F}$-isolating set of $G$. For each $i \in [r]$, $D \cap V(G_i)$ is an $\mathcal{F}$-isolating set of $G_i$. We have $\sum_{i = 1}^r \iota(G_i, \mathcal{F}) \leq \sum_{i = 1}^r |D \cap V(G_i)| = |D| = \iota(G, \mathcal{F})$. The result follows.~\hfill{$\Box$}
\\
\\
\textbf{Proof of Proposition~\ref{PropB}.} We use induction on $k$. The result is trivial if $k = 1$. Suppose $k \geq 2$. Let $G = B_k^*$ and $n = |V(G)|$. We have $k = (n+1)/4$. 

Let $G' = G - N[v_1]$. Then, $G' = G - \{v_1, v_1', w_1, w_1'\} \simeq B_{k-1}^*$. By the induction hypothesis, $G'$ has no induced $6$-cycles. Suppose $G[X] \simeq C_6$ for some $X \subseteq V(G)$. Then, $X \cap N[v_1] \neq \emptyset$ and $X \cap V(G') \neq \emptyset$. It clearly follows that $w_1v_2, w_1'v_2' \in E(G[X])$, so $X = \{w_1, v_2, w_1', v_2', x_1, x_2\}$ for some $x_1 \in \{v_1, v_1'\}$ and $x_2 \in \{v_1, v_1', w_2, w_2'\} \setminus \{x_1\}$. By symmetry, we may assume that $x_1 = v_1$. Since $G[v_1, v_1', w_1, w_1', v_2, v_2'] \not\simeq C_6$, we have $x_2 \neq v_1'$, so $x_2 \in \{w_2, w_2'\}$. We have $|E(G[X])| = 7$, contradicting $G[X] \simeq C_6$. Therefore, $G$ has no induced $6$-cycles.

Clearly, $\{v_i \colon i \in [k]\}$ is a $P_3$-isolating set of $B_k^*$, so $\iota(B_k^*, P_3) \leq k$. Let $D$ be a $P_3$-isolating set of $G$. The result follows if we show that $|D| \geq k$. %Since $G[\{v_k, v_k', w_k\}]$ contains a $3$-path, $D \cap N[\{v_k, v_k', w_k\}] \neq \emptyset$.
Let $G' = G - N[v_k']$. We have $N(v_k') = \{w_{k-1}', v_k, w_k\}$ and $G' = B_{k-1}^*$.

\noindent\textbf{Case 1:} $v_k \in D$ or $v_k' \in D$. By symmetry, we may assume that $v_k' \in D$. Let $D^* =  D \cap N[v_k']$. Then, $v_k' \in D^*$. If $D^* = \{v_k'\}$, then $N[D^*] \cap V(G') = \emptyset$, and let $D' = D \setminus D^*$. If $D^* \neq \{v_k'\}$, then $|D^*| \geq 2$ and $N[D^*] \cap V(G') \subseteq N[v_{k-1}]$, and let $D' = (D \setminus D^*) \cup \{v_{k-1}\}$. Thus, $D'$ is a $P_3$-isolating set of $G'$, and $|D| \geq |D'| + 1$. By the induction hypothesis, $|D'| \geq k-1$, so $|D| \geq k$. 

\noindent\textbf{Case 2:} $v_k, v_{k-1}' \notin D$.

\noindent\textbf{Case 2.1:} $w_k \in D$. Let $D' = (D \setminus \{w_k\}) \cup \{v_k'\}$. Since $N[w_k] \subseteq N[v_k']$, $D'$ is a $P_3$-isolating set of $G$. We have $|D| = |D'| \geq k$ by Case~1.

\noindent\textbf{Case 2.2:} $w_k \notin D$. Since $D$ is a $P_3$-isolating set of $G$ and $v_k, v_k', w_k \notin D$, we have $w_{k-1} \in D$ or $w_{k-1}' \in D$. We may assume that $w_{k-1}' \in D$.  Since $G[\{w_{k-1}, v_k, w_k\}]$ is a copy of $P_3$ and has no vertex in $N[w_{k-1}']$, $D$ has some vertex $x$ in $\{v_{k-1}, v_{k-1}', w_{k-1}\}$. Let $D' = D \setminus \{w_{k-1}'\}$. Since $N[w_{k-1}'] \cap V(G') \subseteq N[x]$, $D'$ is a $P_3$-isolating set of $G'$. By the induction hypothesis, $|D'| \geq k-1$. We have $|D| = |D'| + 1 \geq k$. \qed{}

\begin{corollary}\label{PropBcor} For any $n \geq 1$, $B_n$ has no induced $6$-cycles and
%
\[\iota(B_n, P_3) = \left\lfloor \frac{n+1}{4} \right\rfloor.\]
%
\end{corollary}
%
\noindent
\textbf{Proof.} The result is trivial if $k = 0$. The result is Proposition~\ref{PropB} if $r = 0$. Suppose $k \geq 1$ and $r \geq 1$. It is immediate from Proposition~\ref{PropB} that $B_n$ has no induced $6$-cycles. Let $D$ be a smallest $P_3$-isolating set of $B_n$. Clearly, $\{v_i \colon i \in [k]\}$ is a $P_3$-isolating set of $B_n$, so $|D| \leq k$. Let $X = V(B_n) \setminus V(B_k^*)$. Thus, $X = V(F^*) \setminus \{v_1\}$. If $D \cap X = \emptyset$, then let $D' = D$. If $D \cap X \neq \emptyset$, then let $D' = (D \setminus X) \cup \{v_1\}$. Thus, $D'$ is a $P_3$-isolating set of $B_k^*$, and we have $k \geq |D| \geq |D'| \geq k$ by Proposition~\ref{PropB}. Therefore, $|D| = k$. \qed{}

\begin{proposition}\label{PropB3} For any $h \geq 5$ and $n \geq 4(h-2)$, $B_{n,K_3,h}$ is a connected $n$-vertex graph that has no induced $6$-cycles, $\Delta(B_{n,K_3,h}) = h$ and
%
\[\iota(B_{n,K_3,h}, P_3) = \left\lfloor \frac{n}{4} \right\rfloor.\]
%
\end{proposition}
%
\noindent
\textbf{Proof.} Let $G = B_{n,K_3,h}$. It is immediate from Construction~\ref{ConsB3} that $G$ is a connected $n$-vertex graph that has no induced $6$-cycles. We have $d(1) = |V(F_1)| + h-3 = h$ and $d(v) \leq |V(K_3)| + 2 = 5$ for each $v \in V(G) \setminus \{1\}$, so $\Delta(G) = h$ as $h \geq 5$. Note that $[a_n]$ is a $P_3$-isolating set of $G$, so $\iota(G, P_3) \leq a_n$. For each $i \in [a_n]$, $N(V(F_i)) = \{i\}$. Thus, if $D$ is a $P_3$-isolating set of $G$, then $D \cap (V(F_i) \cup \{i\}) \neq \emptyset$ for each $i \in [a_n]$. Therefore, $\iota(G, P_3) = a_n$. \qed{}
\\
\\
\textbf{Proof of Theorem~\ref{ThmP3beyond}.}
By Corollary~\ref{PropBcor}, equality in (\ref{thmfact1}) holds if $G = B_n$. By Proposition~\ref{PropB3}, equality in (\ref{thmfact2}) holds if $h = \Delta(G) \geq 5$, $n \geq 4(h-2)$ and $G = B_{n,K_3,h}$. 

We now prove (\ref{thmfact1}), (\ref{thmfact2}) and (a), using induction on $n$. Note that since $G$ has no induced $6$-cycles, for any $X \subseteq V(G)$, $G-X$ has no induced $6$-cycles. Also note that (\ref{thmfact1}) implies that if $\iota(G, P_3) \neq (n+1)/4$, then $4 \iota(G, P_3) < n+1$, so $\iota(G, P_3) \leq n/4$.

The result is trivial if $\Delta(G) \leq 1$. Suppose $\Delta(G) \geq 2$. Then, $n \geq 3$. If $n=3$, then $\iota(G,P_3) = 1 = (n+1)/4$ and $\iota(G-v,P_3) = 0$ for any $v \in V(G)$. Suppose $n \geq 4$. 

We first prove (a). Thus, suppose $\iota(G,P_3) = (n+1)/4$. 
%Since $\iota(G,P_3)$ is an integer, $n = 4k + 3$ for some $k \in \{0\} \cup \mathbb{N}$, so $\iota(G,P_3) = k+1$. 
Let $\mathcal{I} = \mathrm{C}(G-v)$, $\mathcal{I}' = \{I \in \mathcal{I} \colon \iota(I, P_3) = (|V(I)|+1)/4\}$ and $\mathcal{I}^*=\mathcal{I} \setminus \mathcal{I}'$. By the induction hypothesis, $\iota(I, P_3) \leq (|V(I)|+1)/4$ for each $I \in \mathcal{I}$. For each $I \in \mathcal{I}^*$, we have $\iota(I, P_3) < (|V(I)|+1)/4$, so $4\iota(I, P_3) < |V(I)|+1$, and hence $\iota(I, P_3) \leq |V(I)|/4$. Since $G$ is connected, for each $I \in \mathcal{I}$, $vx_I \in E(G)$ for some $x_I \in V(I)$. Suppose $\mathcal{I}' \neq \emptyset$. By the induction hypothesis, for each $I \in \mathcal{I}'$, $\iota(I - x_I, P_3) \leq \iota(I, P_3) - 1$, so $\iota(I - x_I, P_3) \leq (|V(I)|-3)/4$. Let $Y = \{v\} \cup \{x_I \colon I \in \mathcal{I}'\}$. Then, $Y \subseteq N[v]$ and $\mathrm{C}(G-Y) = \mathcal{I}^* \cup \bigcup_{I \in \mathcal{I}'} \mathrm{C}(I - x_I)$. By Lemma~\ref{LemIsol1} (with $X = \{v\}$) and Lemma~\ref{LemIsol2}, we have
%
\begin{align*} \iota(G, P_3) &\leq 1 + \iota(G-Y,P_3) = 1 + \sum_{I \in \mathcal{I}^*} \iota(I, P_3) + \sum_{I \in \mathcal{I}'} \sum_{H \in \mathrm{C}(I - x_I)} \iota(H, P_3) \\
&= 1 + \sum_{I \in \mathcal{I}^*} \iota(I, P_3) + \sum_{I \in \mathcal{I}'} \iota(I - x_I, P_3) \leq \frac{4}{4} + \sum_{I \in \mathcal{I}^*} \frac{|V(I)|}{4} + \sum_{I \in \mathcal{I}'} \frac{|V(I)|-3}{4} \\
&=\frac{4-3|\mathcal{I}'|+n-1}{4}=\frac{n-3(|\mathcal{I}'|-1)}{4}<\frac{n+1}{4},
\end{align*}
%
which contradicts $\iota(G,P_3) = (n+1)/4$. Thus, $\mathcal{I}' = \emptyset$, and hence $\mathcal{I} = \mathcal{I}^*$. By Lemma~\ref{LemIsol2},
%
\[\iota(G-v, P_3) \leq \sum_{I \in \mathcal{I}} \frac{|V(I)|}{4} = \frac{n-1}{4} < \frac{n+1}{4}= \iota(G,P_3).\]
%
Since $\iota(G-v, P_3)$ and $\iota(G, P_3)$ are integers, $\iota(G-v, P_3) \leq \iota(G, P_3) - 1$.

We now prove (\ref{thmfact1}) and (\ref{thmfact2}). Since $\iota(G,P_3)$ is an integer, it suffices to show that $\iota(G,P_3) \leq (n+1)/4$ if $\Delta(G) \leq 4$, and that $\iota(G,P_3) \leq n/4$ if $\Delta(G) \geq 5$. 

Suppose $\Delta(G) = 2$. Since $G$ is connected, we have $G \simeq P_n$ or $G \simeq C_n$. Recall that $n \geq 4$. If $G = P_n$, then $\{4k \colon k\in [\floor{n/4}]\}$ is a $P_3$-isolating set of $G$. If $G = C_n$, then $n\neq 6$ (as $G$ has no induced $6$-cycles) and $\{5k-4 \colon k \in \mathbb{N}, \, 5k-4 \leq n\}$ is a $P_3$-isolating set of size $\floor{(n+4)/5}$. Clearly, $\floor{(n+4)/5} \leq (n+1)/4$ if $n \in \{4,5,7,8,9,10\}$, and $(n+4)/5 \leq (n+1)/4$ if $n\geq 11$. Therefore, $\iota(G,P_3) \leq (n+1)/4$. Suppose that equality holds. Then, $G \simeq C_r$ for some $r \in \{7, 11\}$. Thus, for any $v \in V(G)$, we have $G-v \simeq P_{r-1}$, and hence trivially $\iota(G-v, P_3) = \iota(G, P_3) - 1$.  

Now suppose $\Delta(G) \geq 3$. Let $v\in V(G)$ with $d(v) = \Delta(G)$. If $N[v]=V(G)$, then $\iota(G,P_3)=1 \leq n/4$. Suppose $N[v] \neq V(G)$. Let $G'=G-N[v]$. Since $\Delta(G) \geq 3$ and $V(G') \neq \emptyset$, $n\geq 5$. 

Let $\mathcal{H} = \mathrm{C}(G')$, $\mathcal{H}' = \{H \in \mathcal{H} \colon \iota(H,P_3) = (|V(H)|+1)/4\}$ and $\mathcal{H}^*=\mathcal{H}\setminus\mathcal{H}'$. Thus, for each $H \in \mathcal{H}'$, $|V(H)| = 4k+3$ for some $k \in \{0\} \cup \mathbb{N}$. By the induction hypothesis, $\iota(H,P_3) \leq (|V(H)|+1)/4$ for each $H \in \mathcal{H}$. By the argument above for $\mathcal{I}^*$, $\iota(H,P_3)\leq |V(H)|/4$ for each $H \in \mathcal{H}^*$.

If $\mathcal{H}' = \emptyset$, then by Lemmas~\ref{LemIsol1} and~\ref{LemIsol2},
%    
\begin{align*}
\iota(G,P_3) &\leq 1 + \iota(G',P_3)\leq \frac{|N[v]|}{4} + \sum_{H\in\mathcal{H}} {\frac{|V(H)|}{4}} = \frac{n}{4}.% < \frac{n+1}{4}.
\end{align*}
%
Suppose $\mathcal{H}' \neq \emptyset$. For every $x \in N(v)$ and $H \in \mathcal{H}$ such that $xy_{x,H} \in E(G)$ for some $y_{x,H} \in V(H)$, we say that \emph{$x$ is linked to $H$} and that \emph{$H$ is linked to $x$}. Since $G$ is connected, each member of $\mathcal{H}$ is linked to at least one member of $N(v)$. For each $x \in N(v)$, let $\mathcal{H}_{x} = \{H \in \mathcal{H} \colon H$ is linked to $ x\}$, $\mathcal{H}'_{x} = \{H \in \mathcal{H}' \colon H $ is linked to $x\}$ and $\mathcal{H}_{x}^* = \{H \in \mathcal{H}^* \colon H$ is linked to $x$ only$\}$. 

For each $H \in \mathcal{H}^*$, let $D_H$ be a smallest $P_3$-isolating set of $H$. For each $x \in N(v)$ and each $H \in \mathcal{H}_x'$, let $H_x' = H - y_{x,H}$, and let $D_{x,H}$ be a smallest $P_3$-isolating set of $H_x'$. By the induction hypothesis, $|D_{x,H}| \leq (|V(H)|-3)/4$.\medskip
\\
\textbf{Case 1:} $|\mathcal{H}'_x| \geq 2$ for some $x \in N(v)$. For each $H \in \mathcal{H}' \setminus \mathcal{H}'_x$, let $x_H \in N(v)$ such that $H$ is linked to $x_H$. Let $X = \{x_H \colon H \in \mathcal{H}' \setminus \mathcal{H}'_x\}$. Note that $x \notin X$. Let 
%
\[D = \{v, x\} \cup X \cup \left( \bigcup_{H \in \mathcal{H}_x'} D_{x,H} \right) \cup \left( \bigcup_{H \in \mathcal{H}' \setminus \mathcal{H}_x'} D_{x_H,H} \right) \cup \left( \bigcup_{H \in \mathcal{H}^*} D_{H} \right).\]
%
We have $V(G) = N[v] \cup \bigcup_{H \in \mathcal{H}} V(H)$, $y_{x,H} \in N[x]$ for each $H \in \mathcal{H}'_x$, and $y_{x_H,H} \in N[x_H]$ for each $H \in \mathcal{H}' \setminus \mathcal{H}'_x$, so $D$ is a $P_3$-isolating set of $G$. We have
%
\begin{align*} \iota(G, P_3) &\leq |D| = 2 + |X| + \sum_{H \in \mathcal{H}_x'} |D_{x,H}| + \sum_{H \in \mathcal{H}' \setminus \mathcal{H}_x'} |D_{x_H,H}| + \sum_{H \in \mathcal{H}^*} |D_{H}| \nonumber \\
&\leq \frac{8 + 4|X|}{4} + \sum_{H \in \mathcal{H}_x'} \frac{|V(H)| - 3}{4} + \sum_{H \in \mathcal{H}' \setminus \mathcal{H}_{x}'} \frac{|V(H)| - 3}{4} + \sum_{H \in \mathcal{H}^*} \frac{|V(H)|}{4} \nonumber \\ 
&= \frac{2+|X| - 3(|\mathcal{H}_{x}'| - 2) - 3(|\mathcal{H}'\setminus\mathcal{H}_{x}'| - |X|)}{4} + \sum_{H \in \mathcal{H}} \frac{|V(H)|}{4}.
\end{align*}
%
Thus, since $|\mathcal{H}_{x}'| \geq 2$, $|\mathcal{H}'\setminus\mathcal{H}_{x}'| \geq |X|$ and $2 + |X| = |\{v, x\} \cup X| \leq |N[v]|$, we have 
%
\[\iota(G,P_3) \leq \frac{2+|X|}{4} + \sum_{H\in\mathcal{H}} \frac{|V(H)|}{4} \leq \frac{|N[v]|}{4} + \sum_{H\in\mathcal{H}} \frac{|V(H)|}{4} = \frac{n}{4}.\]

\noindent\textbf{Case 2:} 
%
\begin{equation}|\mathcal{H}'_x| \leq 1 \mbox{ for each } x \in N(v). \label{beyondcase2} 
\end{equation}
%
For each $H \in \mathcal{H}'$, let $x_H \in N(v)$ such that $H$ is linked to $x_H$. Let $X = \{x_H \colon H \in \mathcal{H}'\}$. By (\ref{beyondcase2}), $|X| = |\mathcal{H}'|$. Let $W = N(v) \setminus X$ and
%
\[D = \{v\} \cup X \cup \left( \bigcup_{H \in \mathcal{H}'}D_{x_H,H} \right) \cup \left( \bigcup_{H \in \mathcal{H}^*} D_{H} \right).\] 
%
Then, $D$ is a $P_3$-isolating set of $G$.\medskip
\\
\textbf{Case 2.1:} $|W|\geq3$. Similarly to Case~1, we have
%
\begin{align*} \iota(G,P_3) &\leq |D| = 1 + |X| + \sum_{H \in \mathcal{H}'} |D_{x_H,H}| + \sum_{H \in \mathcal{H}^*} |D_{H}|  \\
&\leq \frac{|\{v\} \cup W| + 4|X|}{4} + \sum_{H \in \mathcal{H}'} \frac{|V(H)| - 3}{4} + \sum_{H \in \mathcal{H}^*} \frac{|V(H)|}{4} \\
&= \frac{|N[v]\setminus X| + |X|}{4} + \sum_{H \in \mathcal{H}} \frac{|V(H)|}{4}=\frac{n}{4}.
\end{align*} 

\noindent\textbf{Case 2.2:} $|W| \leq 2$.\medskip
\\
\textbf{Case 2.2.1:} Some member $H$ of $\mathcal{H}'$ is linked to $x_H$ only. Let $G^* = G - (\{x_H\} \cup V(H))$. Then, $G^*$ has a component $G_v^*$ such that $N[v] \setminus \{x_H\} \subseteq V(G_v^*)$, and any other component of $G^*$ is a member of $\mathcal{H}_{x_H}^*$. Let $D^*$ be a smallest $P_3$-isolating set of $G_v^*$. Then, $D^* \cup \{x_H\} \cup D_{x_H,H} \cup \bigcup_{I \in \mathcal{H}_{x_H}^*} D_I$ is a $P_3$-isolating set of $G$, so
%
\begin{align*} \iota(G, P_3) 
&\leq |D^*| + 1 + |D_{x_H,H}| + \sum_{I \in \mathcal{H}_{x_H}^*} |D_I| \\ 
&\leq \iota(G_v^*, P_3) + \frac{4}{4}+\frac{|V(H)|-3}{4} + \sum_{I \in \mathcal{H}_{x_H}^*}\frac{|V(I)|}{4} \\
&\leq \iota(G_v^*,P_3) + \frac{|\{x_H\}\cup V(H)|}{4} + \sum_{I \in \mathcal{H}_{x_H}^*} \frac{|V(I)|}{4}.
\end{align*}
%
This gives $\iota(G,P_3) \leq n/4$ if $\iota(G_v^*,P_3) \leq |V(G_v^*)|/4$. Suppose $\iota(G_v^*,P_3) > |V(G_v^*)|/4$. Then, $4 \iota(G_v^*,P_3) \geq |V(G_v^*)| + 1$, so $\iota(G_v^*,P_3) \geq (|V(G_v^*)| + 1)/4$. By the induction hypothesis, $\iota(G_v^*,P_3) = (|V(G_v^*)|+1)/4$. Let $G_v^- = G_v^* - v$. By the induction hypothesis, $\iota(G_v^-,P_3) \leq (|V(G_v^*)| - 3)/4$. Let $D^-$ be a smallest $P_3$-isolating set of $G_v^-$. Since $v \in N[x_H]$, $D^- \cup \{x_H\} \cup D_{x_H,H} \cup \bigcup_{I \in \mathcal{H}_{x_H}^*} D_I$ is a $P_3$-isolating set of $G$, so
%
\begin{align*} \iota(G, P_3) 
    &\leq |D^-| + 1 + |D_{x_H,H}| + \sum_{I \in \mathcal{H}_{x_H}^*} |D_I| \\ 
    &\leq \iota(G_v^-, P_3) + \frac{4}{4}+\frac{|V(H)|-3}{4} + \sum_{I \in \mathcal{H}_{x_H}^*}\frac{|V(I)|}{4} \\
    &\leq \frac{|V(G_v^*)|-3}{4} + \frac{|\{x_H\}\cup V(H)|}{4} + \sum_{I \in \mathcal{H}_{x_H}^*} \frac{|V(I)|}{4} < \frac{n}{4}.
\end{align*}
%
\noindent\textbf{Case 2.2.2:} For each $H \in \mathcal{H}'$, $H$ is linked to some $x_H' \in N(v) \setminus \{x_H\}$. Let $X' = \{x_H': H\in \mathcal{H}'\}$. By (\ref{beyondcase2}), for every $H, I \in \mathcal{H}'$ with $H \neq I$, we have $x_H' \neq x_I'$ and $x_H \neq x_I'$. Thus, $|X'| = |\mathcal{H}'|$ and $X' \subseteq W$. This yields $|\mathcal{H}'| \leq 2$ as $|W| \leq 2$.

Suppose $|\mathcal{H}'| = 2$. Then, $|W| = 2$ and $X' = W$. Let $H_1$ and $H_2$ be the two members of $\mathcal{H}'$. We have $N(v) = \{x_{H_1},x'_{H_1},x_{H_2},x'_{H_2}\}$. Thus, $\Delta(G) = 4$. Therefore, by Lemma~\ref{LemIsol1}, Lemma~\ref{LemIsol2} and the induction hypothesis,
%
\begin{align*}
    \iota(G,P_3) &\leq 1 + \iota(H_1,P_3) + \iota(H_2,P_3) + \sum_{H\in\mathcal{H}^*}\iota(H,P_3) \\
    &\leq \frac{|N[v]|-1}{4} + \frac{|V(H_1)| + 1}{4} + \frac{|V(H_2)| + 1}{4} + \sum_{H\in\mathcal{H}^*}\frac{|V(H)|}{4} = \frac{n+1}{4}.
\end{align*}

Now suppose $|\mathcal{H}'| = 1$. Let $H_1$ be the member of $\mathcal{H}'$. Since $3 \leq \Delta(G) = d(v) = |X| + |W| = 1 + |W| \leq 3$, $\Delta(G) = 3$. Therefore, by Lemma~\ref{LemIsol1}, Lemma~\ref{LemIsol2} and the induction hypothesis,
\begin{align*}\pushQED{\qed}
    \iota(G,P_3) &\leq 1 + \iota(H_1,P_3) + \sum_{H\in\mathcal{H}^*}\iota(H,P_3) \\
    &\leq \frac{|N[v]|}{4} + \frac{|V(H_1)| + 1}{4} + \sum_{H\in\mathcal{H}^*}\frac{|V(H)|}{4} = \frac{n+1}{4}. \qedhere
    \popQED
\end{align*}



