\section{Quantities of Interest in Differential Algebraic Equations}\label{sec:background}
%\subsection{Standard form ODE}

This sections gives a brief background on  Differential-Algebraic Equations (DAEs), their numerical approximation, and introduces two quantities of interest (QoIs) that are the focus of error estimation.

\subsection{Differential-Algebraic Equations}\label{subsec:dae}
%\justifying
The general form of an  implicit DAE is
%implicit Ordinary Differential Equation (ODE) as well as an
\begin{align}\label{eq:implicit_ode}
    F(\dot{x}(t),x(t),t) = 0.
\end{align}
Here $x(t)\in \mathbb{R}^{n+m}$ for some positive integers $n$, $m$, and $\dot{x}(t)=\frac{dx(t)}{dt}$.
If the Jacobian matrix $\frac{\partial F}{\partial \dot{x}}$ is invertible for all values of the arguments within a suitable domain \cite{computermethodpetzold} then we can solve \cref{eq:implicit_ode} for $\dot{x}$ to get an \emph{explicit} ODE of the form
\begin{align}\label{eq:explicit_ode}
    \dot{x} = f(x,t),
\end{align}
 and \cref{eq:implicit_ode} represents an implicit ODE (or a so-called index-0 DAE). If the Jacobian matrix $\frac{\partial F}{\partial \dot{x}}$ is singular then \cref{eq:implicit_ode} is a DAE with a particular index greater than zero. 
 %(see \cref{subsec:index}). 
 In this case, $x(t)=[y(t),z(t)]^T$, for  $y(t) \in \mathbb{R}^n$ and $z(t) \in \mathbb{R}^m$, and we have an ODE with constraints, resulting in a semi-explicit DAE,
\begin{subequations}\label{eq:dae_equation}
\begin{align}
    \dot{y} &= f(y, z, t), \label{eq:dae_diff}\\
    0 &= g(y, z, t) \label{eq:dae_alg}.
\end{align}
\end{subequations}
Here, $y(t)$ and $ z(t)$ are called the differential and algebraic variables respectively.
% \cite{nsivpdaepetzol}







\subsection{Index and Semi-explicit DAEs}\label{subsec:index}
%\justifying
The index of a DAE is an important property of the problem that plays a role in classification and has many consequences for the behavior of solutions \cite{nsivpdaepetzol}. 
There are, in fact, several distinct, but related, definitions of the index of a DAE. 
Here we restrict ourselves to the discussion of the ``differential index.''
For a DAE of the form given by \cref{eq:implicit_ode}, the differential index $k$ is the minimum number of differentiations required such that the $k$-th total derivative
$$\frac{d^kF}{dt^k}=0,$$
uniquely determines the variable $\dot{x}$ as a continuous function of $x(t)$ and $t$ \cite{nsivpdaepetzol}.



\subsubsection{Semi-explicit index-1 DAE}\label{subsec:index_1_subsec}
%\justifying
Consider a semi-explicit DAE of the form \cref{eq:dae_equation}. Differentiating the constraint \cref{eq:dae_alg} with respect to $t$ and formally solving for $\dot{z}$ gives
\begin{align}\label{eq:index_1_zdot}
    \dot{z} &= -[g_{z}]^{-1}\left [g_{y}f + g_{t}\right],
\end{align}
where $g_y\in \mathbb{R}^{m\times n}$ is the Jacobian matrix of the function $g$ with respect to $y$ and the $ij$-th component of $g_y$ is: $(g_y)_{ij}=\frac{\partial g_i}{\partial y_j}$ for $i=1,2,\dots,m$, and $j=1,2,\dots,n$. Similarly, $g_z\in \mathbb{R}^{m\times m}$ is the Jacobian of $g$ with respect to $z$ and $g_t=\frac{\partial g}{\partial t}$.
It follows from \cref{eq:index_1_zdot}   that the invertibility of the Jacobian matrix $g_{z}$ in a neighborhood of the solution of \cref{eq:dae_equation} is required to yield explicit differential equations corresponding to the algebraic variables $z(t)$ \cite{solvingodestiffanddae}. 
Indeed, the DAE \cref{eq:dae_equation} is index-1 if and only if $g_{z}$ is invertible \cite{nsivpdaepetzol}.





\subsubsection{Hessenberg (Pure) index-2 DAE}\label{subsec:hessenberg_subsec}
%\justifying
We now consider a common class of DAEs for which the index is greater than one. 
Consider the semi-explicit DAE in case that the algebraic constraint \cref{eq:dae_alg} does not explicitly depend on the algebraic variable $z$. In this case, the DAE may be written,
\begin{subequations}\label{eq:index_2_dae_eq}
\begin{align}
    \dot{y} &= f(y, z, t), \label{eq:index_2_dae_diff}\\
    0 &= g(y, t). \label{eq:index_2_dae_alg}
\end{align}
\end{subequations}
Taking the  derivative of \cref{eq:index_2_dae_alg} with respect to $t$ yields the  so-called hidden constraint,
    \begin{align}\label{eq:hidden_constraint}
        0 = g_yf + g_t.
    \end{align}
Now, in the event that $g_yf_z\in \mathbb{R}^{m\times m}$ is invertible, the ODE \cref{eq:index_2_dae_diff} together with the hidden constraint \cref{eq:hidden_constraint} form a index-1 DAE \cite{solvingodestiffanddae}.
    % satisfying the invertibility of $g_y(y,t)f_z(y,z,t)$ in a neighborhood of the solution \cite{solvingodestiffanddae}. 
To see this, we differentiate  the hidden constraint \cref{eq:hidden_constraint} with respect to time and formally solve for $\dot z$ to yield the differential equations corresponding to the algebraic variables,

    \begin{align}\label{eq:zdot_for_index_2}
        \dot{z} = -\left(g_yf_z\right)^{-1}\displaystyle\left(f^Tg_{yy}f +  g_yf_yf + 2g_{yt}f + g_yf_t + g_{tt}\right),
    \end{align}
here, $g_{yy}$ is the derivative of the Jacobian matrix $g_y$ with respect to $y$, a third order tensor of dimension $m\times n\times n$ with components given by
    \begin{align*}
     \left(g_{yy} \right) _{ijk} = \frac{\partial^2g_i}{\partial y_j\partial y_k}, \quad \text{ for } i=1,2,\dots,m, \, j=1,2,\dots,n, \text{ and } k=1,2,\dots,n.
    \end{align*}
     For a fixed $i$, each slice of this tensor represents a Hessian matrix. 
    For $f\in \mathbb{R}^n$, $f^Tg_{yy}f$ has components
\[
\left( f^T g_{yy} f \right)_i = \sum_{j=1}^{n} \sum_{k=1}^{n} \frac{\partial^2 g_i}{\partial y_j \partial y_k} f_j f_k,\quad \text{ for }  i=1,2,\dots, m.
\]
% so $f^Tg_{yy}f\in \mathbb{R}^m$. As the Jacobian $f_y\in \mathbb{R}^{n\times n}$ so, $g_yf_yf\in \mathbb{R}^m$. The $ij$-th component of $g_{yt}\in \mathbb{R}^{m\times n}$ is represented by $(g_{yt})_{ij}=\frac{\partial^2 g_i}{\partial y_j \partial t}$ and $g_{yt}f\in \mathbb{R}^m$, similarly $g_yf_t=\frac{\partial g}{\partial y}\frac{\partial f}{\partial t}\in \mathbb{R}^m$, and $g_{tt}=\frac{\partial^2 g}{\partial t^2}\in \mathbb{R}^m$.
The DAE \cref{eq:index_2_dae_eq} with $g_yf_z$ nonsingular in a neighborhood of the solution is called Hessenberg (Pure) index-2 DAE \cite{nsivpdaepetzol}. 
This is called a pure index-2 because all the algebraic variables (components of $z$) are of index-2. The initial conditions (IC): $(y_0,z_0,t_0)$ must satisfy
\begin{equation*} 
0 = g(y_0), \quad \text{ and } \quad 0 = g_y(y_0,t_0)f(y_0,z_0)+g_t(y_0,t_0),
\end{equation*}
for the consistency of IC \cite{solvingodestiffanddae}.





\subsection{Numerical Solution of DAEs}\label{subsec:ns}
There are two main ways to solve DAEs numerically. 
The first is to directly discretize the DAE as written. 
The second is to reformulate the DAE as an ODE through a process knowns as index reduction.
Direct discretization is often preferred due to the cost of index reduction and to preserve the constraint \cref{eq:dae_alg} exactly for the numerical solution.
The well studied class of numerical methods for ODEs called backward differentiation formula (BDF) methods were applied first in 1971 by Gear \cite{Gear:1970pw} to solve DAEs numerically. 
These methods serve as the basis for the DASSL code \cite{nsivpdaepetzol, DASSL}. 
It is known that the $p$-step BDF method is accurate to order $p$ for $p\leq6$ and effective for solving index-1 as well as Hessenberg index-2 DAEs numerically \cite{Atkinson,nsivpdaepetzol}.

We denote the approximate solution to \cref{eq:dae_equation} or \cref{eq:index_2_dae_eq} as 
\begin{equation}
\label{eq:num_soln}
X(t)=[Y(t),Z(t)]^T,
\end{equation}
where $X(t) \in \mathbb{R}^{n+m}, Y(t) \in \mathbb{R}^{n}$ and $Z(t) \in \mathbb{R}^{m}$.
In this work, we use the simplest first order BDF method, also known as the Implicit Euler Method, for the numerical solution of index-1 \cref{eq:dae_equation} as well as Hessenberg index-2 DAEs \cref{eq:index_2_dae_eq}. This method is first order accurate, stable and convergent for semi-explicit index-1 and Hessenberg index-2 DAEs \cite{Atkinson}. 
The approximate solution is calculated at a discrete set of nodes,
\begin{align}
    0=t_0<t_1<t_2<\dots <t_N= T.
\end{align}
We take these nodes to be evenly spaced, $t_n=t_0+n\Delta t$, $n=0,1,2,\dots ,N$, where $\Delta t = T/N$. 
Applying the BDF-1 method  to the DAE \cref{eq:dae_equation} yields,
\begin{equation}\label{eq:bdf1}
 \left.
    \begin{aligned}
       Y_{n+1} &= Y_n + \Delta t f(Y_{n+1},Z_{n+1},t_{n+1}),\\
    0 &= g(Y_{n+1},Z_{n+1},t_{n+1}),
    \end{aligned}\right\}
\end{equation}
for $n=0,1,\dots,N-1$.
In the case of Hessenberg (Pure) index-2 DAE \cref{eq:index_2_dae_eq}, the constraint equation does not explicitly depend on the algebraic variable and the first order BDF method becomes
\begin{equation}\label{eq:bdf1_for_index2}
    \left.
    \begin{aligned}
        Y_{n+1} &= Y_n + \Delta t f(Y_{n+1},Z_{n+1},t_{n+1}),\\
    0 &= g(Y_{n+1},t_{n+1}),
    \end{aligned} \right \}
\end{equation}
for $n=0,1,\dots,N-1$, where $Y(t_n)=Y_n$, and $Z(t_n)=Z_n$ for $n=0,1,\dots,N$. 
This discretization is implicit in time and yields a system of $n+m$ equations in $n+m$ unknowns. 
Given values for $Y_{n}$, and $Z_{n}$, one must solve this nonlinear system for $Y_{n+1}$, and $Z_{n+1}$.
The numerically computed solution to the index-1 DAEs \cref{eq:dae_equation} and index-2 DAEs \cref{eq:index_2_dae_eq} are naturally calculated at the discrete time points $t_n$. 
Whenever we must evaluate the numerical solution any \emph{other} time point $ t\in (0,T]$, we do so using  linear interpolation between the two closet time points such that $t \in (t_n,t_{n+1})$.



\subsection{Quantity of Interest (QoI)}\label{subsec:qoi}
In this section we formalize the notion of a Quantity of Interest or QoI. 
In many applications, the approximate solution of an  DAE is used to calculate some measurable quantity, called the QoI, and thus predict behavior of the underlying system.
%For instance, a QoI could be average concentration levels in chemical reactions, indicating the overall effectiveness of a reaction process. 
%In fluid dynamics, QoIs such as the average flow rate, are crucial to understanding how efficiently fluids move through a given medium.
%In this work we will restrict ourselves to \emph{linear} QoIs. 
%That is, 
In this work we model QoIs as measurable quantities that can be expressed as a linear functional acting on the solution of the DAE. To describe the QoI considered, we first introduce some notation. For any two time-dependent functions $a,b:  [0,T] \rightarrow \mathbb{R}^n$, we define
\begin{align}\label{eq:definition_integration}
    \langle a,b\rangle=\int_{0}^{T}\left(a(t),b(t)\right)\,\,dt,
\end{align}
where $(\cdot,\cdot)$ is the usual Euclidean inner-product. 
%\justifying

We consider two types of QoI in this work, one is cumulative over the interval $\left[0,T\right]$ and defined as,
\begin{align}\label{eq:qoi_def_inverval}
    \mathcal{Q}_{\left[0,T\right]}(x) = \langle x, \psi \rangle, \quad\quad \psi\in [\mathcal{L}^2(0,T]]^{n+m}.
\end{align}
The other type of QoI depends only on the solution at the terminal time $T$, and is defined as,
\begin{align}\label{eq:qoi_def_at_terminal_time}
    \mathcal{Q}_{\left[T\right]}\left(x\right) = \left(x(T), \zeta\right), \quad\quad \zeta\in \mathbb{R}^{n+m}.
\end{align}






\subsection{Error in QoI}\label{subsec:error_in_qoi}
Now, given an approximate solution to a DAE (or ODE), our main goal is to calculate
the error in the computed value of the QoIs: $\mathcal{Q}_{\left[0,T\right]}(X)$, and $\mathcal{Q}_{\left[T\right]}\left(X\right)$  (see   \cref{eq:qoi_def_inverval,eq:qoi_def_at_terminal_time} for the definitions of the QoIs).
Recalling that  $x$ is the \emph{true} solution of \cref{eq:dae_equation} and $X$ the numerically computed solution, we denote the error in the solution by \(e^{(x)} = x - X\). The error in the two QoIs is given below.
\begin{itemize}
    \item The error in the QoI $\mathcal{Q}_{\left[0,T\right]}(X)$ is
    \begin{align}\label{eq:qoi_over_time}
        \mathcal{Q}_{\left[0,T\right]}(x) - \mathcal{Q}_{\left[0,T\right]}(X) &= \langle x, \psi\rangle - \langle X, \psi \rangle= \langle e^{(x)}, \psi \rangle=\mathcal{Q}_{\left[ 0,T\right]}\left(e^{(x)}\right).
    \end{align}

   % So, we define $\mathcal{Q}_{\left[ 0,T\right]}\left(e^{(x)}\right)$ as follows
   % \begin{align}\label{eq:qoi_over_time}
   %     \mathcal{Q}_{\left[ 0,T\right]}\left(e^{(x)}\right)=\langle e^{(x)}, \psi \rangle.
   % \end{align}

    \item Similarly, the error in the QoI $\mathcal{Q}_{\left[T\right]}\left(X\right)$ is
    \begin{align}\label{eq:qoi_terminal_time_error}
       \mathcal{Q}_{[T]}\left( x \right) - \mathcal{Q}_{[T]}\left( X \right) = \left( e^{(x)}(T), \zeta\right)=\mathcal{Q}_{[T]}\left(e^{(x)}\right).
    \end{align}
\end{itemize}
%Note that for linear QoIs, the error in QoI is the QoI of the error.
For notational clarity, it is often convenient to break vector quantities into their components corresponding to the differential and algebraic variables of the given DAE. 
Thus, we write $x=[y,z]^T$, $\psi=[\psi^y,\psi^z]^T$,  $\zeta = [\zeta^y,\zeta^z]^T$, and $e^{(x)} = [e^{(y)}, e^{(z)}]^T$ where $y(t),\psi^y(t), \zeta^y, e^{(y)}(t) \in\mathbb{R}^n$ and $z(t),\psi^z(t),\zeta^z, e^{(z)}(t) \in\mathbb{R}^m$. Note that
$e^{(y)} = (y-Y)$ and $e^{(z)} = (z-Z)$.
%, and all functions of time are  $\mathcal{L}^2$-integrable. 
Based on this notation \cref{eq:qoi_over_time} and \cref{eq:qoi_terminal_time_error} become,
\begin{equation}\label{eq:qoi_over_time_components}
        \mathcal{Q}_{\left[ 0,T\right]}\left(e^{(x)}\right)= \langle e^{(y)}, \psi^y \rangle + \langle e^{(z)}, \psi^z \rangle,
\end{equation}
and
\begin{equation}\label{eq:qoi_terminal_time_error_components}
       \mathcal{Q}_{[T]}\left(e^{(x)}\right) = \left( e^{(y)}(T), \zeta^y\right) + \left( e^{(z)}(T), \zeta^z\right).
\end{equation}

Quantifying this error is the focus of the next two sections. In \cref{sec:adj_error_analysis_sec_adj_dae}, the analysis is carried out by defining an adjoint problem to the DAE system~\cref{eq:dae_equation}. Later, in \cref{sec:adj_error_analysis_sec_adj_ode}, index reduction is used to convert the DAE to an ODE, and then classical analysis is employed to derive error estimates.


\section{Error Analysis of DAEs by Adjoint to the DAE system}\label{sec:adj_error_analysis_sec_adj_dae}
% In this section we develop two different analyses, Adjoint DAE and Adjoint ODE, to quantify the error in QoIs. 
The error analysis in this section, called Adjoint DAE analysis, is carried out by defining an adjoint problem to the DAE system~\cref{eq:dae_equation}, and by a careful choice of the initial conditions for the adjoint problem.

\subsection{Adjoint System}\label{subsec:adjoint_dae_general}
% The Adjoint DAE analysis is motivated by defining an adjoint problem to the DAE system~\cref{eq:dae_equation} motivated by the definition of adjoint equations for ODE analysis~\cite{estep}.
We introduce adjoint differential variables $\phi^{(y)}(t)\in\mathbb{R}^n$ and adjoint algebraic variables $\phi^{(z)}(t)\in\mathbb{R}^m$, and define the corresponding adjoint problem for a system of semi-explicit DAE \cref{eq:dae_equation} as follows,
\begin{subequations}\label{eq:adj_all_time}
    \begin{align}
    -\dot{\phi}^{(y)} &= \bar{f}_y^T \phi^{(y)} + \bar{g}_y^T \phi^{(z)} + \psi^y,\quad t\in [0,T), \label{eq:diff}\\
0 &= \bar{f}_z^T \phi^{(y)} + \bar{g}_z^T \phi^{(z)} + \psi^z,\quad t\in [0,T),\label{eq:alg}
    \end{align}
\end{subequations}
where the linearized operators are
$$\displaystyle \bar{f}_y = \int_0^1 \frac{\partial f(\tilde{y},\tilde{z})}{ \partial y}ds,\quad\quad \displaystyle \bar{f}_z = \int_0^1 \frac{\partial f(\tilde{y},\tilde{z})}{ \partial z}ds,$$
$$\displaystyle \bar{g}_y = \int_0^1 \frac{\partial g(\tilde{y},\tilde{z})}{ \partial y}ds,\quad\quad \displaystyle \bar{g}_z = \int_0^1 \frac{\partial g(\tilde{y},\tilde{z})}{ \partial z}ds,$$
for $\tilde{y}=sy + (1-s)Y$, and $\tilde{z}=sz + (1-s)Z$.
Here, we leave the initial conditions $\phi^{(y)}(T)$ and $\phi^{(z)}(T)$ unspecified for the moment. Defining the correct initial conditions is a key component of analysis. Our choice of the initial conditions will be motivated from the work on adjoint based sensitivity analysis in \cite{adjointsensitivitypetzoldae}. For the adjoint DAE \cref{eq:adj_all_time}, the initial conditions must be set in a manner determined by the index of the original DAE as well as the dependency of QoIs over the interval $[0,T]$, and at the terminal time $T$ as we show in later sections. For now, we note some properties of the linearized operators. By the fundamental theorem of calculus,
    \begin{align*}
    f(y,z)-f(Y,Z)&=\int_{0}^{1}\frac{d}{d s}\left[f(sy+(1-s)Y,sz+(1-s)Z)\right]\,ds,\\
    &=\int_{0}^{1}\frac{\partial f}{\partial y}ds\,(y-Y) + \int_{0}^{1}\frac{\partial f}{\partial z}ds\,(z-Z),\\
    &=\bar{f}_y(y-Y)+\bar{f}_z(z-Z),
    \end{align*}
so, we have
\begin{align}\label{eq:property_adj_1_property_1}
    \bar{f}_y(y-Y)+\bar{f}_z(z-Z)=f(y,z)-f(Y,Z),
\end{align}
similarly,
\begin{align}\label{eq:property_adj_1_property_2}
    \bar{g}_y(y-Y)+\bar{g}_z(z-Z)&=g(y,z)-g(Y,Z).
\end{align}


\begin{lemma}\label{lem:adj_error}
%Let $X = [Y,Z]^T$ be the approximate solution to \cref{eq:dae_equation} and $\phi^{(x)}=[\phi^{(y)}, \phi^{(z)}]^T$ be the solution to the adjoint problem \cref{eq:adj_all_time}. Then,
We have 
%%%%with the initial condition $\phi^{(y)}(T)$ then
\begin{align}\label{eq:error_dae1_differential}
    \langle e^{(y)}, \psi^y \rangle + \langle e^{(z)}, \psi^z \rangle 
    &= \left( \phi^{(y)}(0),e^{(y)}(0) \right) - \left(\phi^{(y)}(T),y(T)-Y(T)\right)\notag\\
    &\quad\quad +\langle \phi^{(y)}, f(Y,Z) - \dot{Y}  \rangle + \langle \phi^{(z)}, g(Y,Z)  \rangle.
\end{align}
% where $\psi^y$ and $\psi^z\in \mathcal{L}^2(0, T]$.
\end{lemma}
The proof is quite similar to standard proofs for error analysis of ODEs, however, for completeness we include it in the appendix, see \cref{sec:app_proofs}.
%This lemma will be useful for our error representations using Adjoint DAE approach.
\subsection{Error Analysis for Semi-explicit Index-1 DAE}\label{subsec:error_analysis_index_1_sec}
% \subsubsection{Adjoint DAE Technique for Semi-explicit Index-1 DAE}
% To analyze the error in the QoI which is cumulative in time, for the semi-explicit index-1 DAE \cref{eq:dae_equation},  we employ the  adjoint system in \cref{eq:adj_all_time} with the  initial condition given by $\phi^{(y)}(T) = 0$. 
Now we derive error representations for numerically computed QoIs for index-1 DAEs.
The error in semi-explicit index 1 DAE for the QoI $\mathcal{Q}_{\left[0,T\right]}(X)$ in analyzed in \cref{thm:adj_1_qoi_diff_vari_all_time}, while the error in QoI $\mathcal{Q}_{\left[T\right]}\left(X\right)$ in analyzed in \cref{thm:adj1_qoi_terminal_time_diff_algeb_vari}. Finally, a special case is investigated in \cref{cor:adj1_qoi_terminal_time_diff_vari}.

\begin{theorem}\label{thm:adj_1_qoi_diff_vari_all_time}
%Let $X = [Y,Z]^T$ be the approximate solution to the semi-explicit index-1 DAE \cref{eq:dae_equation} and $\phi^{(x)}=[\phi^{(y)}, \phi^{(z)}]^T$ be the solution to the associated adjoint problem \cref{eq:adj_all_time} with initial condition 
Let $\phi^{(y)}(T)=0$ in the adjoint problem \cref{eq:adj_all_time}.
Then the error in the QoI $\mathcal{Q}_{\left[0,T\right]}(X)$ is,
\begin{align}\label{eq:error_dae1_both_diff_alg}
