\begin{theorem}\label{thm:error_dae_index2_updated}
%Let $X = [Y,Z]^T$ be the approximate solution to the Hessenberg index-2 DAE \cref{eq:index_2_dae_eq} and $\phi^{(x)}=[\phi^{(y)}, \phi^{(z)}]^T$ be the solution to the associated adjoint problem \cref{eq:adj_all_time} and the initial condition for
Consider \cref{eq:adj_all_time} and let $\phi^{(y)}(T)$ be given by %\cref{eq:phi_1(T)_final}. 
\begin{align}\label{eq:phi_1(T)_final}
    \phi^{(y)}(T)=-\bar{g}_y^T\left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z\Bigr|_{t=T}.
\end{align}
Then the error in the QoI $\mathcal{Q}_{[0,T]}(X)$, is given by
\begin{align}\label{eq:error_dae_index2_differential_updated}
    \mathcal{Q}_{[0,T]}(e^{(x)}) &= \left( \phi^{(y)}(0),e^{(y)}(0) \right) + \langle \phi^{(y)}, f(Y,Z) - \dot{Y}  \rangle+ \langle \phi^{(z)}, g(Y)  \rangle\notag\\
    &\quad\quad\quad - \left( g(Y), \left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z\right)\Bigr|_{t=T}.
\end{align}
\end{theorem}
\begin{proof}
    Since $g$ is independent of $z$, we have  $\bar{g}_z=0$. Using this in \cref{lem:adj_error} leads to,
    \begin{align}\label{eq:proof_of_error_in_index_2_cumulative}
     \langle e^{(y)}, \psi^y \rangle + \langle e^{(z)}, \psi^z \rangle &= \left( \phi^{(y)}(0),e^{(y)}(0) \right) - \left(\phi^{(y)}(T),y(T)-Y(T)\right)\notag\\ 
     &\quad\quad + \langle \phi^{(y)}, f(Y,Z) - \dot{Y} \rangle+ \langle \phi^{(z)}, g(Y)  \rangle.
    \end{align}
Clearly, the term $
    \left(\phi^{(y)}(T),y(T)-Y(T)\right)$ in \cref{eq:proof_of_error_in_index_2_cumulative} is not computable because of the presence of unknown $y(T)$. Using \cref{eq:phi_1(T)_final} in this  term, followed by \cref{eq:property_adj_1_property_2} leads to,
\begin{align}\label{eq:expression}
     \left(\phi^{(y)}(T),y(T)-Y(T)\right) &= \left( -\bar{g}_y^T\left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z, e^{(y)}\right)\Bigr|_{t=T} ,\notag\\
    &= - \left( \left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z, \bar{g}_y(y-Y)\right)\Bigr|_{t=T} ,\notag\\
    &= - \left(\left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z,  g(y)-g(Y)\right)\Bigr|_{t=T} ,\notag\\
    &= \left( g(Y), \left(\bar{f}_z^T\bar{g}_y^T\right)^{-1}\psi^z\right)\Bigr|_{t=T},
\end{align}
where we used $g(y) = 0$ in the last step. Combining \cref{eq:expression} and \cref{eq:proof_of_error_in_index_2_cumulative} proves the result.
