\section{Staggered Grid}
\label{macscheme}
We use relatively standard central difference approximations for the spatial derivative of $c_x,c,a_x,$ and $a$. 
The nonlinear terms $ cw$, and $aw$, require multiplication of quantities which ``live'' at cell centers and those that live at cell edges. 
In this case, we average the two cell centered quantities ($c$ or $a$) to the cell edge between. 
We explicitly show the details of the spatial discretization for $c$ below. 
The discretization of $a$ is completely analogous.

The partial derivative of $c$ with respect to $x$ at $\tilde{x}_j$ is approximated as follows:
\[
c_x(x_j) \approx \frac{c(\tilde{x}_j+\Delta x/2) - c(\tilde{x}_j-\Delta x/2)}{\Delta x} = \frac{c(x_{j+1}) - c(x_j)}{\Delta x}. 
\]
That is to say that first derivatives (which naturally live at cell edges) are calculated by applying centered differences to quantities defined at cell centers. 
For the nonlinear terms, we average concentrations to the cell edges to yield 
\begin{equation}
    c(\tilde{x}_j) w(\tilde{x_j}) \approx \frac{c(\tilde{x}_j+\Delta x/2) + c(\tilde{x}_j-\Delta x/2)}{2}w(\tilde{x}_j) = \frac{c(x_{j+1}) + c(x_j)}{2}w(\tilde{x}_j)
\end{equation}  
We can now apply centered differences to the above expressions to yield the following expressions for $j=2,3,\dots,N_s-1$,
\begin{align*}
    &\left. \frac{\partial}{\partial x}\left(c_{x}+  cw\right) \right|_{x_j}\\
    &\approx \frac{1}{\Delta x}\left(c_x(x_j+\Delta x/2)+c(x_j+\Delta x/2)w(x_j+\Delta x/2)\right)\\
    &\quad\quad - \frac{1}{\Delta x}\left(c_x(x_j-\Delta x/2)+c(x_j-\Delta x/2)w(x_j-\Delta x/2)\right),\\
    &= \frac{1}{\Delta x}\left(c_x(\tilde{x}_j)+c(\tilde{x})w(\tilde{x}_j)\right)\\
    &\quad\quad - \frac{1}{\Delta x}\left(c_x(\tilde{x}_{j-1})+c(\tilde{x}_{j-1})w(\tilde{x}_{j-1})\right),\\
    &= \frac{1}{\Delta x}\left(\frac{c(x_{j+1}) - c(x_j)}{\Delta x}+\frac{c(x_{j+1}) + c(x_j)}{2}w(\tilde{x}_j)\right)\\
    &\quad \quad - \frac{1}{\Delta x}\left(\frac{c(x_{j}) - c(x_{j-1})}{\Delta x}+\frac{c(x_{j}) + c(x_{j-1})}{2}w(\tilde{x}_{j-1})\right)\\
    % &= \frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j+\Delta x/2+\Delta x/2)-c(\tilde{x}_j+\Delta x/2-\Delta x/2)}{\Delta x}\right)\\
    % &\quad\quad+ \frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j+\Delta x/2-\Delta x/2) + c(\tilde{x}_j+\Delta x/2+\Delta x/2)}{2}\right)w(\tilde{x}_j+\Delta x/2)\\
    % &\quad\quad-\frac{1}{\Delta x} \left(\frac{c(\tilde{x}_j-\Delta x/2+\Delta x/2)-c(\tilde{x}_j-\Delta x/2-\Delta x/2)}{\Delta x}\right)\\
    % &\quad\quad -\frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j-\Delta x/2-\Delta x/2)+c(\tilde{x}_j-\Delta x/2+\Delta x/2)}{2}\right)w(\tilde{x}_j-\Delta x/2),\\
    % &\approx \frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j+\Delta x)-c(\tilde{x}_j)}{\Delta x}\right)
    % + \frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j) + c(\tilde{x}_j+\Delta x)}{2}\right)w(\tilde{x}_j+\Delta x/2)\\
    % &\quad\quad-\frac{1}{\Delta x} \left(\frac{c(\tilde{x}_j)-c(\tilde{x}_j-\Delta x)}{\Delta x}\right) -\frac{1}{\Delta x}\left(\frac{c(\tilde{x}_j-\Delta x)+c(\tilde{x}_j)}{2}\right)w(\tilde{x}_j-\Delta x/2),\\
    &= \frac{1}{\Delta x^2}\left(c(x_{j+1})-2c(x_j)+c(x_{j-1})\right)\\
    &\quad\quad+\frac{1}{2\Delta x}\Big(\left(c(x_j)+c(x_{j+1})\right)w(\tilde{x}_j)-\left(c(x_j)+c(x_{j-1})\right)w(\tilde{x}_{j-1})\Big).
\end{align*}

For $j = 1$ and $j = N_s$, we need to utilize the  no flux (homogeneous Robin) boundary conditions \cref{eq:robin_bcs}.
These can be expressed as 
\[ \left. c_{x}+  cw \right|_{x=0} = \left. c_{x}+  cw \right|_{\tilde{x}_0} = 0, \]
and 
\[ \left. c_{x}+  cw \right|_{x=1} = \left. c_{x}+  cw \right|_{\tilde{x}_{N_s}} = 0. \]
Now, for $j=1$, i.e., the scheme at the left boundary of the modified domain is
\begin{align*}
    &\left. \frac{\partial}{\partial x}\left(c_{x}+  cw\right) \right|_{x_1}\\
    % &\approx \frac{1}{\Delta x}\left(c_x(x_j+\Delta x/2)+c(x_j+\Delta x/2)w(x_j+\Delta x/2)\right)\\
    % &\quad\quad - \frac{1}{\Delta x}\left(c_x(x_j-\Delta x/2)+c(x_j-\Delta x/2)w(x_j-\Delta x/2)\right),\\
    &\approx \frac{1}{\Delta x}\left(c_x(\tilde{x}_1)+c(\tilde{x})w(\tilde{x}_1)\right)-  0 ,\\
    &= \frac{1}{\Delta x}\left(\frac{c(x_{2}) - c(x_1)}{\Delta x}+\frac{c(x_{2}) + c(x_1)}{2}w(\tilde{x}_1)\right)\\
    &= \frac{1}{\Delta x^2}\left(c(x_{2})-c(x_1))\right) +\frac{1}{2\Delta x}\Big(\left(c(x_1)+c(x_{2})\right)w(\tilde{x}_1)\Big).
\end{align*}
Similarly, for $j=N_s$, i.e., the scheme at the right boundary of the modified domain is 
\begin{align*}
    &\left. \frac{\partial}{\partial x}\left(c_{x}+  cw\right) \right|_{x_{N_s}}\\
    &\approx 0 - \frac{1}{\Delta x}\left(c_x(\tilde{x}_{N_s-1})+c(\tilde{x}_{N_s-1})w(\tilde{x}_{N_s-1})\right),\\
    &= - \frac{1}{\Delta x}\left(\frac{c(x_{N_s}) - c(x_{N_s-1})}{\Delta x}+\frac{c(x_{N_s}) + c(x_{N_s-1})}{2}w(\tilde{x}_{N_s-1})\right)\\
    &= \frac{1}{\Delta x^2}\left( -c(x_{N_s})+c(x_{N_s-1})\right)+\frac{1}{2\Delta x}\Big(-\left(c(x_{N_s})+c(x_{N_s-1})\right)w(\tilde{x}_{N_s-1})\Big).
\end{align*}
A completely analogous discretization is used for the the anion $a$. 
These finite difference discretizations are used to construct the right hand side of the differential equation for the differential variables in \cref{eq:hc_index_2_equation}. 

In order to construct the algebraic constraint for \cref{eq:hc_index_2_equation} we notice that the above finite difference equations are conservative. 
This implies that 
\[ \sum_{j= 1}^{N_s} c(x_j,t) \text{ and } \sum_{j = 1}^{N_s} a(x_j,t),\]
are both constants independent of time. 
This, in turn, means that if $c(x_j,0) - a(x_j,0) = 0$ at the initial time, and $c(x_j) - a(x_j) = 0$ for $j = 1, 2, \ldots N_s -1$, then it must be true that $c(x_{N_s}) - a(x_{N_s}) = 0$. 
Put another way, if we use a conservative discretization and use initial conditions which satisfy the constraint at all spatial locations, then we do not need to explicitly enforce the constraint at all locations. 
We need only enforce it in the first $N_s -1$ grid cells, and we are guranteed that it will be satisfied in the final grid cell ``for free''. 
Thus, we do not explicitly require that $C - A = 0$ in \cref{eq:hc_index_2_equation}. 
Rather, we require that $\Pi(C - A) = 0$, where $\Pi$ is the linear operator which simply evaluates a variable at all but the final cell center. 






