    \section{Nullstellens\"atze for punctured and structured grids}
    \label{sec:punct}
    In this Section, we prove Theorem~\ref{thm:ballcn2} and
    Corollary~\ref{cor:ballcn2cor}. We start with the description
    of the vanishing ideal of a punctured grid. We note that
    a similar result that includes multiplicities has been
    given in~\cite[Theorem~4.1]{BS:PCN}, but our proof is
    different. For a subset $J$ of $\kxn$ and $f \in \kxn$, we write
    $\V(J)$ for the set $\{\vb{a} \in \kn \mid f (\vb{a}) = 0
    \text{ for all } f \in J \}$ of common zeros of $J$.
\begin{thm}[cf. {\cite[Theorem~4.1]{BS:PCN}}]  \label{thm:ballcn1}
  Let $X \setminus Y = (\bigtimes_{i=1}^n X_i) \setminus
  (\bigtimes_{i=1}^n Y_i)$ be a punctured grid with
  $Y_i \subseteq X_i$ for all $i \in \N$,
  let $g_i := \prod_{a \in X_i} (x_i - a)$, let
  $l_i := \prod_{a \in Y_i} (x_i - a)$, and let
  $f \in \kxn$. Then $f$ vanishes on $X \setminus Y$
  if and only if
  $f \in \submod{g_1, \ldots, g_n, \prod_{i=1}^n \frac{g_i}{l_i}}$.
  Furthermore, for every admissible monomial ordering $\lea$,
  $\{g_1, \ldots, g_n, \prod_{i=1}^n \frac{g_i}{l_i} \}$
  is a Gr\"obner basis  with respect to $\lea$.
\end{thm}    
\begin{proof}
  We first compute generators of the vanishing ideal
  $\I (X \ohne Y)$.
  We have $X \setminus Y
  =
  X \setminus \bigcap_{i \in \ul{n}} X_1 \times \cdots \times X_{i-1}
  \times Y_i \times X_{i+1}  \times  \cdots \times X_n
  =
  X \cap \, \bigcup_{i \in \ul{n}} X_1 \times \cdots \times X_{i-1}
  \times (X_i \setminus Y_i) \times X_{i+1}  \times  \cdots \times X_n
  =
  X \cap \, \bigcup_{i \in \ul{n}}  \ob{K} \times \cdots \times \ob{K}
  \times (X_i \setminus Y_i) \times \ob{K} \times  \cdots \times \ob{K}
  =
  X \cap \, \bigcup_{i \in \ul{n}} \V (\frac{g_i}{l_i})
  =
  X \cap \, \V (\prod_{i \in \ul{n}} \frac{g_i}{l_i})$.
  Now for finite $X$, Clark's Finitesatz \cite[Theorem~7]{Cl:TCNR}
  tells that for any ideal
  $J$ of $\kxn$, we have $\I (X \cap \V(J)) = \I(X) + J$, and therefore
  \[
  \I (X \setminus Y) 
  = \I (X \cap \, \V (\prod_{i \in \ul{n}} \frac{g_i}{l_i}))
  =
  \I(X) + \langle
                          \prod_{i \in \ul{n}} \frac{g_i}{l_i}
                          \rangle =
                  \langle g_1, \ldots, g_n, \prod_{i \in \ul{n}} \frac{g_i}{l_i}
                  \rangle.
  \]
  In order to show that $G := \{ g_1, \ldots, g_n, \prod_{i \in \ul{n}} \frac{g_i}{l_i} \}$ is a Gr\"obner basis, we again use
  Buchberger's Characterization Theorem for Gr\"obner bases \cite[Theorem~5.64]{BW:GB},
  and we therefore look at the $S$-polynomials of $G$.
  First, we note that for $i, j \in \ul{n}$ with
  $i \neq j$, the leading monomials of $g_i$ and $g_j$ are coprime,
  and therefore the $S$-polynomial of $g_i$ and $g_j$ has a standard
  expression by $\{g_i, g_j\}$  with remainder $0$ (\cite[Lemma~5.66]{BW:GB});
  such an expression can
  also be obtained by setting $t := 1$ in the proof of Theorem~\ref{thm:gt}.
  For checking the other $S$-polynomials,
  let $j \in \ul{n}$, and let $p := \prod_{i \in \ul{n}} \frac{g_i}{l_i}$.
  We compute $S (g_j, p)$. Let $a_i := |X_i|$ and $b_i := |Y_i|$.
  Then
  \[
       \LM (g_j) = x_j^{a_j} \text{ and }
       \LM (p) = \prod_{i \in \ul{n}} x_i^{a_i - b_i}.
  \]
  Now let $q := \prod_{i \in \ul{n} \setminus \{j\}} \frac{g_i}{l_i}$; then
  $q \frac{g_j}{l_j} = p$. Then we have
   \begin{equation*}
   S (g_j, p) = (\prod_{i \in \ul{n} \setminus \{j\}} x_i^{a_i - b_i}) g_j
                -
                x_j^{b_j} p 
                =
                \LM (q) \, g_j
                - \LM (l_j) \, p.
   \end{equation*}                                
   Since $l_j p = q  g_j$,
   we have 
   \[
           \LM (q) \, g_j
           - \LM (l_j) \, p =
           (l_j - \LM (l_j)) \, p -
           (q - \LM(q)) \, g_j.           
    \]
    We show that $S(g_j , p) = (l_j - \LM (l_j)) \, p - (q - \LM(q)) \, g_j$
    is a standard expression of $S(g_j, p)$ by $\{g_j, p\}$.
  If at least one of the summands is $0$, we are done.
  Otherwise, we show 
    that the two summands have different multidegree.
     Suppose that both summands are nonzero and that they have the same multidegree. Then
    $\LM (g_j)$ divides $\LM ((l_j - \LM (l_j)) \, p)$.
    We have $\deg_{x_j} (\LM(g_j)) = a_j$ and
    $\deg_{x_j} (\LM ( (l_j - \LM (l_j))\, p))
    = \deg_{x_j} (\LM (l_j - \LM (l_j)) \, \LM (p))
    = \deg_{x_j} (\LM (l_j - \LM (l_j))) + \deg_{x_j} (\LM (p))
    \le \deg_{x_j} (\LM (l_j - \LM (l_j))) + \deg_{x_j} (p)
    \le (b_j - 1) + (a_j - b_j) =
    a _j - 1$.
    But then $\LM (g_j) \nmid \LM ((l_j - \LM (l_j))\, p)$.

    Since all $S$-polynomials have a standard expression by $G$ with
    remainder $0$, Buchberger's Characterization Theorem yields
    that $G$ is a Gr\"obner basis.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:ballcn2}]
  Let $p := \prod_{i=1}^n \frac{g_i}{l_i}$, and  let
  $G' := \{g_1, \ldots, g_n, p \}$.
  We first show that $\mono{\alpha}$ is a $(G',\lambda)$-stable monomial
  in $f$.
  Let us first show that there is no $g \in G'$ with
  $\LM(g) \mid \mono{\alpha}$. If there is $i \in \ul{n}$ with
  $\LM (g_i) \mid \mono{\alpha}$, then $|X_i| \le \alpha_i$,
  contradicting Assumption~\eqref{it:al1}.
  If $\LM(p) \mid \mono{\alpha}$, then
  we have $|X_i| - |Y_i| \le \alpha_i$  for all $i \in \ul{n}$,
  contradicting Assumption~\eqref{it:al2}.
%
  %
  It remains to show that $f$ contains no $(G, \lambda, \alpha)$-shading
  monomial. Let $\mono{\gamma} \in \Mon (f)$. By the assumptions,
  there is $i \in \ul{n}$ such that one of the Conditions~\eqref{it:al3a},
  \eqref{it:al3b}, \eqref{it:al3c} holds.
  We fist consider the case that $\gamma_i \in [0, \alpha_i - 1]$.
  Then Condition~\eqref{it:sha1} of Definition~\ref{de:shading2} fails,
  and thus $\mono{\gamma}$ is not $(G', \lambda, \alpha)$-shading.
  In the case $\gamma_i \in [\alpha_i + 1, \alpha_i + \lambda_i]$,
  Condition~\eqref{it:sha3} of Definition~\ref{de:shading2} fails,
  and thus $\mono{\gamma}$ is not $(G', \lambda, \alpha)$-shading.
  In the case that $\gamma_i \in [\alpha_i + 1, |X_i| - 1]$ and $|X_i| = |Y_i|$,
  we show that Condition~\eqref{it:sha2} of Definition~\ref{de:shading2} fails.
  Seeking a contradiction, we suppose that Condition~\eqref{it:sha2}
  holds. Then there is $g \in G'$ with $\deg_{x_i} (g) > 0$ and
  $\LM(g) \mid \mono{\gamma}$. Since $|X_i| = |Y_i|$, $\deg_{x_i} (p) = 0$
  and thus $g = g_i$. Hence $|X_i| \le \gamma_i$, contradicting the assumptions.
  Thus Condition~\eqref{it:sha2} of Definition~\ref{de:shading2} fails,
  and $\gamma$ is not $(G', \lambda, \alpha)$-shading.
  Now we consider the case that $\gamma_i \in [\alpha_i + 1, |X_i| - 1]$ and that there is $j \in \ul{n}$ with $\gamma_j < |X_j| - |Y_j|$.
  Supposing again that $\gamma$ is $(G',\lambda, \alpha)$-shading,
  we obtain that $\LM(g_i) \mid \mono{\gamma}$ or $\LM(p) \mid \mono{\gamma}$.
  If $\LM (g_i) \mid \mono{\gamma}$, then $|X_i| \le \gamma_i$, contradicting
  the assumptions. If $\LM (p) \mid \mono{\gamma}$, then
  for all $j \in \ul{n}$, we have $|X_j| - |Y_j| \le \gamma_j$. This is
  also excluded by the case assumption.

  Therefore $\mono{\alpha}$ is a $(G',\lambda)$-stable
  monomial in $f$. Let $g_{n+1} := p$ and 
     let
   \(
      f = \sum_{j=1}^t c_j \, \mono{\delta_j} g_{i_j} + r
  \)
  be a natural standard expression of $f$ by $G'$.
  We note that $g_1, \ldots, g_n$ are $\lambda$-lacunary by
  assumption. Furthermore, for each $i \in \ul{n}$,
  $g_i$ and $l_i$ are 
  $\lambda$-lacunary and hence by Lemma~\ref{lem:proquolac},
  $p = \prod_{i=1}^n \frac{g_i}{l_i}$ is $\lambda$-lacunary.
    Since $\mono{\alpha}$ is a $(G', \lambda)$-stable monomial in $f$
  and all $g' \in G'$ are $\lambda$-lacunary,
   Corollary~\ref{cor:rem} yields that 
    $\mono{\alpha} \in \Mon(r)$. 
   By Theorem~\ref{thm:ballcn1}, 
   the set $G'$ is a Gr\"obner basis of $\I (X \setminus Y)$.
     Since then all
  elements of $\I (X \setminus Y)$ have zero remainder in every standard expression
  by $G'$,
  we obtain $f \not\in \I (X \setminus Y)$, and therefore,
  there is $\vb{s} \in X \setminus Y$ with $f (\vb{s}) \neq 0$.
\end{proof}  

\begin{proof}[Proof of Corollary~\ref{cor:ballcn2cor}]
  We show that for $\lambda_1 = \cdots = \lambda_n
  = \lambda$, the assumptions of
  Theorem~\ref{thm:ballcn2} are satisfied.
  Assume that Assumption~\eqref{it:al3} of Theorem~\ref{thm:ballcn2} fails.
  Then there is a monomial $\mono{\gamma} \in \Mon (f) \ohne \{\alpha\}$
  such that for all $i \in \ul{n}$,
  $\gamma_i \not\in [0, \alpha_i - 1] \union [\alpha_i + 1, \alpha_i + \lambda_i]$, which means that for all $i \in \ul{n}$, $\gamma_i = \alpha_i$ or
  $\gamma_i > \alpha_i + \lambda_i$.  Then
  $\deg (f) \ge \deg (\mono{\gamma}) > (\sum_{i=1}^n \alpha_i) + \lambda$,
  contradicting Assumption~\eqref{it:al3new} of
  Corollary~\ref{cor:ballcn2cor}.
  Now Theorem~\ref{thm:ballcn2} yields the result.
 \end{proof}

\section{A punctured version of the Alon-F\"uredi Theorem} \label{sec:AF}
In \cite{Cl:ATCW}, Clark gives a proof of the Alon-F\"uredi Theorem for
counting nonzeros of polynomials on grids that is based
on the fact that for a finite set $X \subseteq \kn$,
the vector space dimension of $\kxn/\I(X)$ is equal to
$|X|$, and this dimension
can be determined as the number of monomials $\mono{\alpha}$
that are not leading monomials of any polynomial in $\I(X)$.
We proceed by adapting some methods from~\cite{Cl:ATCW} to punctured grids. 
For a subset $G$ of $\kxn$ and an admissible monomial ordering
$\le_a$, we define two subsets of
$\{\mono{\alpha} \mid \alpha \in \NON \}$.
\[
   \begin{array}{rcl}
    \filter{G} & := & \{ \mono{\alpha} \mid \alpha \in \NON \text{ and } \exists g \in G : \LM (g) \text{ divides }
    \mono{\alpha} \}, \\
    \cofilter{G} & := & \{\mono{\alpha} \mid \alpha \in \NON\} \ohne (\filter{G}) = \\ &  &
    \{ \mono{\alpha} \mid \alpha \in \NON \text{ and }\text{there is no } g \in G \text{
        such that } \LM (g) \text{ divides } \mono{\alpha} \}.
   \end{array}
\]
\begin{thm}[Clark's formula, \cite{Cl:ATCW}] \label{thm:cf}
  Let $\ob{K}$ be a field, and
  let $X$ be a finite subset of $\kn$, and let $f \in \kxn$.
  Then
  \[
     |X \ohne \V (f)| =
     | \cofilter{\I (X)} \, \ohne \, \cofilter{\I(X) + \submod{f}}|.
  \]
\end{thm}
\begin{proof}
  For every finite subset $Y$ of $\kn$, we have
  \begin{equation} \label{eq:sizeY}
    |Y|= |\cofilter{\I (Y)}|.
  \end{equation}
  To prove this, let $\epsi : \kxn \to \kk^Y$, $\epsi (p) := \hat{p}|_Y$,
  where $\hat{p}$ is the function from $\kn$ to $\kk$ induced
  by $p$, and $\hat{p}|_Y$ denotes its restriction to $Y$.
  Then $\ker \epsi = \I (Y)$, and $\epsi$ is surjective because
  every mapping from $Y$ to $\kk$ can be interpolated by a polynomial.
  Since $\epsi$ is a homomorphism of $\kk$-vector spaces, we 
  get $\dim_{\kk} (\kxn / \I(Y)) = \dim_{\kk} (\kk^Y) = |Y|$.
  The vector space dimension of the residue class ring
  $\dim_{\kk} \kxn / \I(Y)$ is equal to $|\cofilter{\I(Y)}|$
  because $\{ \mono{\alpha} + \I(Y) \mid \mono{\alpha} \in \cofilter{\I(Y)} \}$ is
  a basis of this vector space.
  This proves~\eqref{eq:sizeY}.
  Hence
  $|X \cap \V (f)| = |\cofilter{\I (X \cap \V(f))}|$.
  By Clark's Finitesatz \cite[Theorem~7]{Cl:TCNR},
  the last expression is
  equal to $|\cofilter{\I(X) + \submod{f}}|$.
  Thus $|X \ohne \V(f)| =
  |X| - |X \cap \V(f)| =
  |\cofilter{\I(X)}| - |\cofilter{\I(X) + \submod{f}}|$.
  Since $\I(X) \subseteq \I(X) + \submod{f}$, we have
  $\cofilter{\I(X) + \submod{f}} \subseteq \cofilter{\I(X)}$,
  and therefore
  $|\cofilter{\I(X)}| - |\cofilter{\I(X) + \submod{f}}|
   = |\cofilter{\I(X)} \, \ohne \, \cofilter{\I(X) + \submod{f}}|$.
\end{proof}
For $a, b \in \N_0$, we will denote the
interval $\{x \in \N_0 \mid a \le x < b\}$ by $[a, b)$.
  \begin{lem} \label{lem:punctured}
      Let $X = \bigtimes_{i=1}^n X_i, Y = \bigtimes_{i=1}^n Y_i$ be grids over the
      field $\kk$ with $Y_i \subseteq X_i$ for all $i \in \ul{n}$,
      and for each $i \in \ul{n}$,
  let $a_i := |X_i|$ and $b_i := |Y_i|$. Then
  $\cofilter{\I (X \ohne Y)} = \{ \mono{\alpha} \mid
  \alpha \in \bigtimes_{i \in \ul{n}} [0, a_i) \setminus
    \bigtimes_{i \in \ul{n}} [a_i - b_i, a_i) \}$.
\end{lem}
\begin{proof}
  Let $g_i := \prod_{a \in X_i} (x_i - a)$, and 
  $l_i := \prod_{a \in Y_i} (x_i - a)$. Then by
  Theorem~\ref{thm:ballcn1},
  $G' := \{g_1, \ldots, g_n, \prod_{i=1}^n \frac{g_i}{l_i} \}$ is
  a Gr\"obner basis for $\I(X \setminus Y)$.
  Hence $\cofilter { \I(X \setminus Y)} =
         \cofilter {  G' }=$ \\ $
         \cofilter {\{g_1, \ldots, g_n\}} \, \cap \,
         \cofilter {\{\prod_{i=1}^n \frac{g_i}{l_i} \}}
         =
         \cofilter {\{g_1, \ldots, g_n\}} \ohne
         \filter {\{\prod_{i=1}^n \frac{g_i}{l_i} \}}
         = \{ \mono{\alpha} \mid  \alpha \in \bigtimes_{i \in \ul{n}} [0, a_i) \ohne
           \bigtimes_{i \in \ul{n}} [a_i - b_i , a_i) \}$.
\end{proof}  

\begin{thm}[Clark's Monomial Alon-F\"uredi Theorem \cite{Cl:ATCW}] \label{thm:afc1}
  Let $X$ be a finite subset of $\kn$, let $f \in \kxn$, and
  let $g \in \I(X) + \submod{f}$ with $g \neq 0$. Then
  \[
  |X \ohne \V (f)| \ge |\cofilter{\I (X)} \, \cap \, \filter{ \{\LM (g) \} }|
  \, .
  \]
\end{thm}
\begin{proof}
  Since $g \in \I(X) + \submod{f}$, $g$ vanishes on $\V(f) \cap X$,
  and thus $X \cap \V(f) \subseteq X \cap \V(g)$, and therefore
  $X \ohne \V(f) \supseteq X \ohne \V(g)$.
  Now by Theorem~\ref{thm:cf},
  we have $|X \ohne \V (g)| =
  | \cofilter{\I (X)} \ohne \cofilter{\I(X) + \submod{g}}|$.
  In addition, $\cofilter{\I (X)} \ohne \cofilter{\I(X) + \submod{g}} =
  \cofilter{\I (X)} \cap \filter{(\I(X) + \submod{g})}
  \supseteq
  \cofilter{\I(X)} \cap \filter{\{g\} } =
  \cofilter{\I(X)} \cap \filter{\{ \LM(g) \} }$.
  Altogether, $|X \ohne \V(f)| \ge
  |\cofilter{\I(X)} \cap \filter{\{ \LM(g) \} }|$.
\end{proof}

\begin{thm}[Alon-F\"uredi-Clark for punctured grids] \label{tm:afcp}
  Let $X = \bigtimes_{i=1}^n X_i, Y = \bigtimes_{i=1}^n Y_i$ be grids over the
   field $\kk$ with $Y_i \subseteq X_i$ for all $i \in \ul{n}$, let
   $P := X \setminus Y$, let
  let $f \in \kxn$, and
  for $i \in \ul{n}$, let
  $a_i := |X_i|$ and $b_i := |Y_i|$, and let $\lea$ be
  an admissible monomial ordering.
  Let $g \in \I(P) + \submod{f}$ with
  $\LM (g) = x_1^{e_1} \cdots x_n^{e_n}$ and $e_i < a_i$ for
  all $i \in \ul{n}$. Then
  \[
   |P \ohne \V (f)| \ge \prod_{i=1}^n (a_i - e_i)
  - \prod_{i = 1}^n \min (b_i, a_i - e_i).
  \]
\end{thm}
\begin{proof}
  By Theorem~\ref{thm:afc1}, we have
  \[
  |P \ohne \V(f)| \ge |\cofilter{\I (P)} \cap \filter{ \{ \LM(g) \} }|.
  \]
  By Lemma~\ref{lem:punctured}, we have
  $\cofilter{\I (P)} \cap \filter{ \{ \LM(g) \} }
  = \{ x^{\alpha} \mid \alpha \in E \}$,
  where $E$ is given by
  \[
    E = (\bigtimes_{i \in \ul{n}} [0, a_i) \setminus
         \bigtimes_{i \in \ul{n}} [a_i - b_i, a_i) )
           \cap
           \bigtimes_{i \in \ul{n}} [e_i, a_i).
  \]
  Then we have
  \begin{multline*}
     E =   \bigtimes_{i \in \ul{n}} [e_i, a_i) \ohne
           \bigtimes_{i \in \ul{n}} [a_i - b_i, a_i) )
       =   \bigtimes_{i \in \ul{n}} [e_i, a_i) \ohne
         (\bigtimes_{i \in \ul{n}} [e_i, a_i) \cap
           \bigtimes_{i \in \ul{n}} [a_i - b_i, a_i) ) \\
       =  \bigtimes_{i \in \ul{n}} [e_i, a_i) \ohne
         \bigtimes_{i \in \ul{n}} [\max (e_i, a_i - b_i), a_i).
           \end{multline*}
    Since $a_i - \max (e_i, a_i - b_i) = \min (a-e_i, b_i)$,       
    we can now compute $|E| = \prod_{i=1}^n (a_i - e_i) -
    \prod_{i=1}^n \min (b_i, a_i - e_i)$.
\end{proof}
We note that similar to Clark's version for unpunctured grids in \cite{Cl:ATCW},
this lower bound can be attained for every choice of $(e_1, \ldots, e_n)$
with $e_i < a_i$ for all $i \in \ul{n}$.
\begin{pro}
    Let $X = \bigtimes_{i=1}^n X_i, Y = \bigtimes_{i=1}^n Y_i$ be grids over the
   field $\kk$ with $Y_i \subseteq X_i$ for all $i \in \ul{n}$, and let
   $P := X \setminus Y$.
     For each $i \in \ul{n}$, let
     $a_i := |X_i|$, $b_i := |Y_i|$, let
     $e_i \in [0, a_i - 1)$ and let $E_i \subseteq X_i$ be such that
       $|E_i| = e_i$ and
       ($E_i \subseteq X_i \setminus Y_i$ or
        $X_i \setminus Y_i \subseteq E_i$).
       Let $f_i := \prod_{a \in E_i} (x_i - a)$ and
       $f := \prod_{i=1}^n f_i$.
       Then for every admissible monomial ordering,
       $\LM (f)= x_1^{e_1} \cdots x_n^{e_n}$, and
       $|P \setminus \V(f)| =  \prod_{i=1}^n (a_i - e_i)
       - \prod_{i = 1}^n \min (b_i, a_i - e_i)$.
\end{pro}
\begin{proof}
  It is easy to see that $\LM(f) = x_1^{e_1} \cdots x_n^{e_n}$ and
  that the nonzeros of $f$ on $X$
  are given by
  $X \setminus \V(f) = \bigtimes_{i=1}^n (X_i \ohne E_i)$,
  and hence $|X \setminus \V(f)| = \prod_{i=1}^n (a_i - e_i)$.
  We will now compute how many of these nonzeros lie in $Y$.
  To this end, we observe that
  \[
  \bigtimes_{i=1}^n (X_i \ohne E_i) \cap \bigtimes_{i=1}^n Y_i =
  \bigtimes_{i=1}^n (Y_i \ohne E_i).
  \]
  In the case that $E_i \subseteq X_i \setminus Y_i$,
  we have $Y_i \ohne E_i = Y_i$, and therefore
  $|Y_i \ohne E_i| = b_i$. In the case that
  $X_i \setminus Y_i \subseteq E_i$, we have
  $X_i \ohne E_i = (Y_i \union (X_i \setminus Y_i)) \ohne E_i
  = (Y_i \ohne E_i) \union ((X_i \ohne Y_i) \ohne E_i) =
  (Y_i \ohne E_i) \union \emptyset = Y_i \ohne E_i$,
  and therefore $|Y_i \ohne E_i| = a_i - e_i$.
  In each of these cases, $|Y_i \ohne E_i| = \min (a_i - e_i, b_i)$.
%
  Therefore, $|P \ohne \V(f)| = |X \ohne \V(f)| -
              |Y \ohne \V(f)| =  \prod_{i=1}^n (a_i - e_i)
       - \prod_{i = 1}^n \min (b_i, a_i - e_i)$.
\end{proof}  


Based on Theorem~\ref{tm:afcp},
we can now prove Theorem~\ref{thm:AFC-punct}.
\begin{proof}[Proof of Theorem~\ref{thm:AFC-punct}]
    We fix an admissible ordering $\lea$ such that
  $\sum_{i=1}^n \gamma_i < \sum_{i=1}^n \delta_i$ implies
  $\mono{\gamma} \lea \mono{\delta}$.

  For proving~\eqref{it:bin1},  
 we divide $f$ by $G'$, where $G'$ is the Gr\"obner basis
  of $\I (P)$ given in Theorem~\ref{thm:ballcn1} and obtain
  a standard expression $f = \sum_{i=1}^{n+1} h_i g'_{i} + r$ such
  that the remainder $r$ contains no monomial divisible
  by a $\LM(g')$ with $g' \in G'$. If $r = 0$, then
  $f \in \I(P)$, and thus $\I(P) \setminus \V(f) = \emptyset$.
  If $r \neq 0$, then $\deg (r) \le \deg (f)$.
  Let $(e_1, \ldots, e_n) := \LEXP (r)$.
  Now Theorem~\ref{tm:afcp} for $g := r$ yields
  $|P \ohne \V(f)| \ge \prod_{i=1}^n (a_i - e_i)
  - \prod_{i = 1}^n \min (b_i, a_i - e_i)$.
  Set
  $y_i := a_i - e_i$. Then $1 \le y_i \le a_i$.
  If $y_i \le b_i$ for all $i \in \ul{n}$, then
  $a_i - b_i \le e_i$ for all $i \in \ul{n}$, and
  thus $\LM (r)$ is divisible by the leading monomial
  $\prod_{i \in \ul{n}} x_i^{a_i - b_i}$ of one of the elements
  of $G'$.  Hence there is $i \in \ul{n}$ with
  $y_i > b_i$.
    Now $\sum_{i=1}^n y_i = \sum_{i=1}^n (a_i - e_i)
     = \sum_{i=1}^n a_i - \sum_{i=1}^n e_i =
       \sum_{i=1}^n a_i - \deg (r) \ge \sum_{i=1}^n a_i - \deg (f)$.
    Hence $(y_1, \ldots, y_n) \in A$, which proves
   \eqref{eq:Zf}.

   For proving~\eqref{it:bin2}, 
   let $(e_1, \ldots, e_n) := \LEXP (f)$.
  Now Theorem~\ref{tm:afcp} for $g := f$ yields
  $|P \ohne \V(f)| \ge \prod_{i=1}^n (a_i - e_i)
  - \prod_{i = 1}^n \min (b_i, a_i - e_i)$. Set
  $y_i := a_i - e_i$. Then since $e_i \le \deg_{x_i} (f)$,
  we have $a_i - \deg_{x_i} (f) \le y_i \le a_i$.
    Now $\sum_{i=1}^n y_i = \sum_{i=1}^n (a_i - e_i)
     = \sum_{i=1}^n a_i - \sum_{i=1}^n e_i =
       \sum_{i=1}^n a_i - \deg (f)$.
    Hence $(y_1, \ldots, y_n) \in B$, which proves
   \eqref{eq:Zf2}.
\end{proof}
Setting $Y_i := \emptyset$ for all $i \in \ul{n}$, one recovers
the classical Alon-F\"uredi Theorem for grids.
