\section{Selberg zeta function = Wilson spool for BTZ}\label{sec:BTZselbviaWS} 

\noindent Here, starting from the Wilson spool, we derive the representation theoretic expression for the Selberg zeta function for massive symmetric, transverse, traceless spin-$s$ fields on the (Euclidean) rotating BTZ black hole background. 

\subsection{Scalar case} \label{sec:scalarselb}


\noindent  We begin with a massive scalar field ($s=0$), 
where $j_L=j_R \equiv j$.
The 1-loop partition function computed using the spool (\ref{eq:spooladsZ1}) simplifies to
\begin{equation}\label{eq:spoolads}
    \log{Z_\Delta} = \frac{i}{4}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\text{Tr}_{\mathsf{R}_j}\left(\mathcal{P}e^{\frac{z}{2\pi}\oint_{\gamma_\phi} a_L}\right)\text{Tr}_{\mathsf{R}_j}\left(\mathcal{P}e^{-\frac{z}{2\pi}\oint_{\gamma_\phi} a_R}\right),
\end{equation}
where $\mathsf{R}_j$ is a lowest weight representation of $\mathfrak{sl}(2,\mathbb{R})$ with the lowest weight labeled by $j$. As reviewed above,  a weight $(\lambda_L,\lambda_R) \in   \mathsf{R}^{\text{LW}}_{j}\otimes\mathsf{R}^{\text{LW}}_{j},$
can be expressed as ascendants of the lowest weight state labeled by $j$. Using the decomposition (\ref{eq:1loopWSde}) gives 
\begin{align}\label{eq:spool0}
    \log{Z_\Delta} 
    &= \frac{i}{4}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\sum_{k_1=0}^{\infty}\sum_{k_2=0}^{\infty}e^{iz(h_L(j+k_1)-h_R(j+k_2))}~,
\end{align}
where we implemented the sum over lowest weights.

The derivation of the representation theory form of the Selberg zeta function essentially follows from an interchange 
of the infinite sums and contour integral in (\ref{eq:spool0}). It is worth performing this exchange carefully as it is not always possible (in fact, as we show in Section \ref{SEC:DS}, this interchange is not allowed for the Euclidean dS$_{3}$ 1-loop partition function).
To this end, following a standard prescription in complex analysis (cf. \cite{brown2009complex}), we decompose the infinite sums over $k_1$ and $k_2$ into finite sums along with a remainder
%in the second line into finite sums,
$\rho_{M,N}(z)$. Specifically, 
\beq
\begin{split}
 \sum_{k_{1},k_{2}=0}^{\infty}e^{iz(h_L(j+k_1)-h_R(j+k_2))}&
 =\sum_{k_1=0}^{M-1}\sum_{k_2=0}^{N-1}e^{iz(h_L(j+k_1)-h_R(j+k_2))}+\rho_{M,N}(z)\;,
 \end{split}
 \label{eq:remain}\eeq
with 
\beq \label{eq:remainder}
\begin{split} 
\rho_{M,N}(z)&\equiv e^{izj(h_{L}-h_{R})}\biggr[\sum_{k_{1}=0}^{M-1}e^{izk_{1}h_{L}}\sum_{k_{2}=N}^{\infty}e^{-izk_{2}h_{R}}+\sum_{k_{2}=0}^{N-1}e^{-izk_{2}h_{R}}\sum_{k_{1}=M}^{\infty}e^{ik_{1}h_{L}}\\
&+\sum_{k_{1}=M}^{\infty}e^{izk_{1}h_{L}}\sum_{k_{2}=N}^{\infty}e^{-izk_{2}h_{R}}\biggr]\;,
\end{split}
\eeq
for positive integers $M,N$. Evaluating the sums in the remainder gives\footnote{Recall $\sum_{k=M}^{\infty}e^{kx}=\frac{e^{Mx}}{1-e^{x}}$ and $\sum_{k=0}^{M-1}e^{kx}=\frac{e^{Mx}-1}{e^{x}-1}$.}
\beq 
\begin{split} 
\rho_{M,N}(z)&=
\frac{e^{\frac{iz}{2}[(2j-1)(h_{L}-h_{R})+2(Mh_{L}-Nh_{R})]}}{4\sin\left(\frac{zh_{L}}{2}\right)\sin\left(\frac{zh_{R}}{2}\right)}\left(e^{-izh_{L}M}+e^{izh_{R}N}-1\right)\;.
\end{split}
\label{eq:remainBTZsca}\eeq
With the decomposition (\ref{eq:remain}), the finite sums may be interchanged with the integral in (\ref{eq:spool0}). Subsequently taking the limit $M,N \rightarrow \infty$ gives,
\begin{align}\label{eq:spool4}
    \int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\sum_{k_1,k_2=0}^{\infty}e^{iz(h_L(j+k_1)-h_R(j+k_2))} &= \sum_{k_1,k_2=0}^{\infty}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}e^{iz(h_L(j+k_1)-h_R(j+k_2))}\nonumber \\  &+\lim_{M,N\rightarrow\infty}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\rho_{M,N}(z)~.
\end{align}
Thus, interchanging the sum and integral is valid provided the remainder (\ref{eq:remainBTZsca}) vanishes in the limit $M,N\rightarrow \infty$. 

For Euclidean BTZ, the holonomies (\ref{eq:btzhol}) have $ \operatorname{Im}(h_L) \neq 0 $ and $ \operatorname{Im}(h_R) \neq 0 $, such that the remainder will not contribute any poles that lie inside $\mathcal{C}$. The only poles lying inside $\mathcal{C}$ are first order poles located at $z=2\pi n$ for $n\in\mathbb{Z}$. Therefore, we can evaluate the contour integral for the remainder term by summing over the residues of the poles enclosed by $\mathcal{C}$. Convergence depends only on the convergence of the exponential terms in (\ref{eq:spool4}). The overall exponential will be damped, and in the limit $M,N\rightarrow 0$, we obtain
\begin{align}\label{eq:spool6}
    \lim_{M,N\to\infty}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\rho_{M,N}(z)dz = -4i\lim_{M,N\rightarrow\infty}\sum_{n=1}^{\infty}\frac{\rho_{M,N}(2\pi n)}{n} = 0~.
\end{align}
Thence,
the infinite sums and the integral in (\ref{eq:spool0}) can be interchanged, and the 1-loop determinant 
takes the form
\begin{align}
    \log{Z_\Delta} &= \frac{i}{4}\sum_{(\lambda_L,\lambda_R)}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}e^{iz(\lambda_L h_L-\lambda_R h_R)}\nonumber \\ 
    &= \log{\prod_{(\lambda_L,\lambda_R)}\left[1-e^{2\pi i\left(\lambda_Lh_L-\lambda_R h_R\right)}\right]^{-1}}.
\end{align}

It is now trivial to complete our derivation of the representation-theoretic form of the Selberg zeta function (\ref{eq:btzrepsel}). Using the relation (\ref{eq:selr}) between the Selberg zeta function and the 1-loop determinant and identifying the appropriate generator through \eqref{eq:partialphi}, we find
\begin{align}\label{eq:RepTheoryDerive}
    \zeta_{\Gamma} (\Delta) &= \prod_{(\lambda_L,\lambda_R)}\left(1-e^{2\pi i(h_L\lambda_L-\lambda_R h_R)}\right)\nonumber \\ 
    &= \prod_{\text{descendants}}\left<1-e^{2\pi\partial_{\phi}}\right>~,
\end{align}
precisely recovering the representation theory  construction of the BTZ Selberg zeta function established in \cite{Bagchi:2023ilg}.



In summary, we have seen that the logarithm of the Selberg zeta function can be directly obtained from the Wilson spool, through a simple interchange of a sum and integral. In equating the two, there are two key relations we would like to highlight:\\

\noindent {\bf States are those associated to the Wilson spool}: First, the states at play in the representation theory expression for the Selberg zeta function are nothing other than the states associated to the representation $\mathsf{R}_\Delta$, corresponding to matter propagating along the Wilson loop. The states in $\mathsf{R}_\Delta$ are summed over in the Wilson spool through the trace. Since the Wilson spool is logarithm of the Selberg zeta function, this corresponds to the product over descendants in the representation theory form of the zeta function. \\ 

\noindent{\bf Geodesic lengths are swapped for holonomies}: As was reviewed in Section~\ref{SEC:BTZ}, the Selberg zeta function is a zeta function constructed from the lengths of primitive geodesics, rather than prime numbers. In the language of the Wilson spool, the holonomies generalize geodesic lengths. To see this, recall  \eqref{eq:btzhol} expressed in terms of the (dimensionless) geodesic length, $\ell(p)=2\pi r_{+}/\ell_{\text{AdS}}$,
\begin{equation}\label{hol}
    h_{L} = -\frac{|r_{-}|}{\ell_{\text{AdS}}}+\frac{i\ell(p)}{2\pi}~,\indent h_{R} = -\frac{|r_{-}|}{\ell_{\text{AdS}}}-\frac{i\ell(p)}{2\pi}~.
\end{equation}
The zeta function~\eqref{eq:RepTheoryDerive} for BTZ  that was directly obtained from the Wilson spool, 
\begin{equation}\label{eq:selrep}
    \zeta_{\Gamma}(\Delta) =\prod_{k_1=0}^{\infty}\prod_{k_2=0}^{\infty}\left(1-e^{2\pi i(h_{L}(j+k_1)-h_R(j+k_2))}\right)~,
\end{equation}
 thus reduces to the geometric form of the Selberg zeta function (\ref{eq:selbzetabtz}) expressed in terms of the primitive geodesic length $\ell(p)$, 
\begin{equation}
    \zeta_{\Gamma}(\Delta) = \prod_{k_1=0}^{\infty}\prod_{k_2=0}^{\infty}\left(1-e^{-\left(2\pi i\frac{|r_{-}|}{\ell_{\text{AdS}}}+\ell(p)\right)k_1}e^{\left(2\pi i\frac{|r_{-}|}{\ell_{\text{AdS}}}-\ell(p)\right)k_2}e^{-\Delta \ell(p)}\right)\;,
\end{equation}
with the holonomies introducing $\ell(p)$.

Indeed, the Wilson spool may be naturally understood as a sum over primitive geodesics, just like  $\log\zeta_{\Gamma}$. To see this, recall that the  Wilson spool (\ref{eq:spoolads}) is understood as an object that implements a sum over Wilson loops wrapping $n$ times around the holonomy cycle, here $\gamma_\phi$. For the BTZ black hole, this is particularly clear when we evaluate the contour integral, leaving:
\begin{align}
    \frac{1}{4}\mathbb{W}_j[a_L,a_R] 
    &= \sum_{n=1}^{\infty}\frac{1}{n}W_j[a_L,-a_R]^n~,
\end{align}
where $W_j$ is an ordinary Wilson loop associated to the representation. Implementing the path ordered exponentials (\ref{eq:holBTZ}) together with identification (\ref{hol}) realizes the Wilson spool as the sum 
\beq 
    \frac{1}{4}\mathbb{W}_j[a_L,a_R]= \frac{1}{2}\sum_{n=1}^{\infty}\frac{1}{n}\frac{e^{-n\ell(p)(\Delta-1)}}{\left(\cosh{(n\ell(p))}-\cos{(2\pi n|r_-|/\ell_{\text{AdS}})}\right)}~.
\label{eq:Wspoolbtzsimp2}\eeq
This geodesic formulation of the Wilson spool is consistent with the well-known saddle-point approximation for Wilson loops in higher-spin gravity, which isolates the dominant geodesic contribution: $W_{j}\sim e^{-\sqrt{c_j}\ell}$ at large $c_j$, where $c_j$ is the Casimir and $\ell$ is a geodesic length~\cite{Ammon:2013hba}.




\subsection{Spinning case}\label{2}


\noindent Let us now generalize the previous analysis to bosonic fields of arbitrary spin $s\in\mathbb{Z}$. 
In particular, we begin with the higher spin Wilson spool (\ref{eq:spooladsZ1}),
\begin{equation}\label{eq:s2}
    \log{Z_{\Delta,s}} = \frac{i}{4}\sum_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\sum_{(\lambda_L,\lambda_R)}e^{iz(\lambda_L h_L-\lambda_R h_R)}~.
\end{equation}
The procedure for interchanging the infinite sums $(\lambda_L,\lambda_R)\in \mathcal{R}_{\Delta_s}^{\text{LW}}$ and contour integral works, \emph{mutatis mutandis}, as in the scalar field case.\footnote{The only difference is, in dilineating the infinite sums over $(\lambda_{L},\lambda_{R})$, we will have a remainder $\rho_{M}(z)$ term for both $(\lambda_L,\lambda_R)\in \mathsf{R}^{\text{LW}}_{j_L}\otimes\mathsf{R}^{\text{LW}}_{j_R}$ and $(\lambda_L,\lambda_R)\in \mathsf{R}^{\text{LW}}_{j_R}\otimes\mathsf{R}^{\text{LW}}_{j_L}$. For example, when $(\lambda_L,\lambda_R)\in \mathsf{R}^{\text{LW}}_{j_L}\otimes\mathsf{R}^{\text{LW}}_{j_R}$, the remainder $\rho_M(z)$ is (here we take $M=N$, without loss of generality)
$$\rho_M (z) = \frac{e^{-\frac{iz}{2}(h_L-h_R)}e^{iz(h_Lj_L-h_Rj_R)}}{4\sin{(\frac{z}{2}h_L)}\sin{(\frac{z}{2}h_R)}}\left(e^{-izMh_R}+e^{izMh_L}-e^{izM(h_L-h_R)}\right)\;.$$
As before in the scalar field case, $\rho_{M}(z)$ will not contribute any poles inside of the contour $\mathcal{C}$.
Further, with the holonomies (\ref{eq:btzhol}), and weights (\ref{eq:jljrAdS}), it is clear this term will vanish as $M\rightarrow\infty$. An analogous argument holds for $(\lambda_L,\lambda_R)\in \mathsf{R}^{\text{LW}}_{j_R}\otimes\mathsf{R}^{\text{LW}}_{j_L}$. }


Therefore, the 1-loop partition function becomes
\begin{align}\label{eq:hs1}
    \log{Z_{\Delta,s}} &= \frac{i}{4}\sum_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\sum_{(\lambda_L,\lambda_R)}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}e^{iz(\lambda_L h_L-\lambda_R h_R)} \nonumber\\
    &= \log{\prod_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\prod_{(\lambda_L,\lambda_R)}\left(1-e^{2\pi i((h_L \lambda_L -h_R \lambda_R))}\right)^{-1}}~.
\end{align}
Using the relation between the higher spin Selberg zeta function and $Z_{\Delta, s}$ from (\ref{eq:selr}) then allows us to identify the representation theory construction of the Selberg zeta function for arbitrary spin $s\in\mathbb{Z}$,
\begin{align}
    \zeta_{\Gamma}(\Delta_s) &= \prod_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\prod_{(\lambda_L,\lambda_R)}\left(1-e^{2\pi i((h_L \lambda_L -h_R \lambda_R))}\right)\nonumber \\ 
    &= \prod_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\prod_{(\lambda_L,\lambda_R)}\left<1-e^{2\pi  \partial_\phi} \right>~,
\end{align}
 generalizing \cite{Bagchi:2023ilg}. 

From this perspective, the factorization of the 1-loop determinant (\ref{eq:functionaldetAdS}) arises directly from the version of the spool \eqref{eq:spooladsZ1} that is expressed only using lowest weight representations. To see this, recall from \eqref{eq:reps2} that $\mathcal{R}_{\Delta_s}^{\text{LW}}$ includes representations with lowest weights given by either the pairs $(j_L,j_R)$ or $(j_R,j_L)$. Evaluating the product over these two possible representations gives
\begin{align}\label{eq:spinsel1}
    \zeta_{\Gamma}(\Delta_s) &= \prod_{\mathcal{R}_{\Delta_s}^{\text{LW}}}\prod_{(\lambda_L,\lambda_R)}\left<1-e^{2\pi  \partial_\phi} \right> \nonumber\\ 
    &=\prod_{k_1,k_2=0}^{\infty}\left(1-e^{2\pi i h_L k_1}e^{-2\pi ih_R k_2}e^{2(-a\Delta_{s}+ibs)}\right) \left(1-e^{2\pi i h_L k_1}e^{-2\pi ih_R k_2}e^{-2(a\Delta_{s}+ibs)}\right)\nonumber \\ 
    &= \zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}-\frac{isb}{a}\right)\cdot\zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}+\frac{isb}{a}\right).
\end{align}
This gives the lowest weight representation theory construction of the Selberg zeta function. However, because the Wilson spool can also be expressed using both lowest and highest weight representations in (\ref{eq:1loopWSde}), we are able to apply the formalism we have developed to reveal a further factorization of the Selberg zeta function,
\begin{equation}
    \zeta^2_{\Gamma} =\zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{LW}}-\frac{isb}{a}\right)\zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{LW}}+\frac{isb}{a}\right)\zeta_{\mathbb{H}^{3}/\Gamma}\left(-\Delta_{s}^{\text{HW}}+\frac{isb}{a}\right)\zeta_{\mathbb{H}^{3}/\Gamma}\left(-\Delta^{\text{HW}}_{s}-\frac{isb}{a}\right).
\end{equation}
Equating this to the square of (\ref{eq:spinsel1}) evaluated at $\Delta_s=\Delta_s^{\text{LW}}$ gives
\begin{equation}
    \zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{HW}}-\frac{isb}{a}\right)\zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{HW}}+\frac{isb}{a}\right) = \zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{LW}}-\frac{isb}{a}\right)\zeta_{\mathbb{H}^{3}/\Gamma}\left(\Delta_{s}^{\text{LW}}+\frac{isb}{a}\right)\;.
\end{equation}
Thus, the Selberg zeta function can be expressed through either lowest or highest weight representations. This underscores what was found previously for the higher spin Wilson spool, this time throught the lens of the Selberg zeta function.

















\section{Wilson spool from the $S^{3}$ trace formula}\label{SEC:DS}


\noindent Here we explicitly show how to recover the Wilson spool for three-dimensional Euclidean de Sitter space (EdS$_{3}$) via a trace formula for the sphere $S^{3}$. To this end, we begin by briefly reviewing the construction of the Wilson spool for $S^{3}$, focusing on the case of a massive scalar field (for higher-spin spools on EdS$_3$, see~\cite{Bourne:2024ded}). We will then show how analgous steps performed in Section~\ref{sec:BTZselbviaWS} to construct a Selberg-like zeta function from the spool 
fail in this case. Instead, we will construct a trace formula for $S^3$ and provide a new derivation of the $S^{3}$ Wilson spool from this trace formula. We also comment on how the Wilson spool itself can be considered a function that generalizes certain properties of the Selberg zeta function.

\subsection{Wilson spool for EdS$_3$: review}



\noindent Euclideanized de Sitter space has the geometry of a sphere. In three-dimensions, the metric (in Hopf or torus coordinates) is
\begin{equation}\label{Eq:desittermeteric}    
\frac{ds^2}{\ell^{2}_{\text{dS}}}=\cos^2{(\rho)}\,d t_{E}^2+d\rho^2+\sin^2{(\rho)}\,d\phi^2~,
 \end{equation}
 where $\ell_{\text{dS}}$ is the curvature scale of dS$_{3}$, $\rho\in[0,\pi/2)$, and $\phi\in[0,2\pi)$.  The horizon of dS$_{3}$ in static patch coordinates (whose Lorentzian metric follows via the Wick rotation $t=-it_{E}$) is located at $\rho=\pi/2$, resulting in a conical singularity in the Euclidean geometry (\ref{Eq:desittermeteric}) that is removed by identifying $ t_{E}\sim t_{E}+2\pi n$, for integer $n$. The isometry group for $S^{3}$ is $SO(4)\simeq SU(2)_{L}\times SU(2)_{R}/\mathbb{Z}_{2}$, for left/right group actions $L/R$. 




Accordingly, Euclidean dS$_{3}$ general relativity has a description in terms of a pair of $SU(2)$ Chern-Simons theories (see, e.g., Appendix A of \cite{Bourne:2024ded}). The background connections for the sphere  (\ref{Eq:desittermeteric}) are 
\begin{align}
    a_L &= i L_1 d\rho + i (\sin{\rho} L_2 - \cos{\rho} L_3)(d\phi - d t_{E})~,\nonumber \\
    a_R &= -i \bar{L}_2 - i(\sin{\rho} \bar{L}_2 + \cos{\rho} \bar{L}_3)(d\phi + d t_{E})~, 
\end{align}
where $\{L_{a}\}$ and $\{\bar{L}_{i}\}$ for $a=1,2,3$, denote the 
generators of the Lie algebras $\mathfrak{su}(2)_{L}$ and $\mathfrak{su}(2)_{R}$, respectively, obeying commutation relations $[L_{a},L_{b}]=i\epsilon_{ab}^{\quad c}L_{c}$, $[\bar{L}_{a},\bar{L}_{b}]=i\epsilon_{ab}^{\quad c}\bar{L}_{c}$, and $[L_{a},\bar{L}_{b}]=0$. These locally flat connections exhibit singularities when $\rho=0$ or $\rho=\pi/2$. Around these points, the connections have holonomies
\begin{equation}\label{eq:holdS}
\mathcal{P}e^{\oint_{\gamma}a_L} = g_L^{-1}e^{2\pi i h_L L_3}g_{L}~, \indent  \mathcal{P}e^{\oint_{\gamma}a_R} = g_R^{-1}e^{2\pi i h_R \bar{L}_3}g_{R}~,
\end{equation}
for periodic group elements $g_{L}=e^{iL_{1}\rho}$ and $g_{R}=e^{i\bar{L}_{1}\rho}$.  Specifically, for cycles $\gamma$ wrapping the horizon $\rho=\pi/2$, one has the holonomies
\begin{equation}
    h_L=1 \quad \text{and} \quad h_R =-1~.
\end{equation}
Meanwhile, cycles that wrap the singularity at the origin $\rho=0$ have $h_{L}=h_{R}=1$. 

In constructing the Wilson spool, it is necessary to specify representations that correspond to matter propagating on Wilson loops. Unlike for AdS$_3$, however, the EdS$_3$ spool for a massive scalar field is constructed from \emph{non-standard} representations that are distinct from the standard representations describing fields propagating on de Sitter (these were constructed specifically for the purposes of Chern-Simons theory in~\cite{Castro:2020smu,Castro:2023dxp}). Non-standard representations are highest-weight representations with highest weight $j$, but, unlike for the usual unitary $\mathfrak{su}(2)$ representations, $j$ can vary continuously. The Casimir is negative, indeed in terms of the mass $m$ of the scalar field it is
\begin{equation}
    j(j+1) = -\frac{1}{4}m^2 \ell_{\text{dS}}~,
\end{equation}
where $\ell_{\text{dS}}$ is the radius of curvature for the three-sphere. There are two relevant types non-standard representations. First, there are \emph{complementary type} representations, which have
\be j = -\frac{1}{2}(1+\nu)~,\indent \bar{j}=j~,\indent\nu\in (-1,1)\;.\ee
These correspond to a light massive scalar with $m^2\ell_{\text{dS}} =1-\nu^2 <1$. Meanwhile, the \emph{principal type} representations are those where the highest weights take values
\be j = -\frac{1}{2}(1-i\mu)~,\indent \bar{j} = -1-j~, \indent \mu\in \mathbb{R}~,\ee
corresponding to a heavy massive scalar with $m^2 \ell_{\text{dS}}^2 = \mu^2+1 > 1$.
These non-standard representations admit characters that play an important role in the Wilson spool. For definiteness, we will focus on the principal series character, $\chi_j$, given by
\begin{equation} \label{eq:chars}
    \chi_{j}(x) = \sum_{k=0}^\infty e^{2\pi i  (j-k)x} = \frac{e^{2\pi i (j+1)x}}{e^{2\pi ix}-1}\;, \quad \chi_{j}(-x)=-\chi_{\bar{j}}(x)\;.
\end{equation}

Given two highest weight $\mathfrak{su}(2)$ representations, i.e., $\mathfrak{su}(2)_{L}$ and $\mathfrak{su}(2)_{R}$, their associated highest weights $j_L$ and $j_R$ are related to the conformal dimension and spin via\footnote{The conformal dimension and spin are eigenvalues of particular generators of the conformal algebra $\mathfrak{so}(1,3)\simeq \mathfrak{su}(2)_{L}\oplus\mathfrak{su}(2)_{R}$, the Lie algebra associated with the isometry group $SO(1,3)$ of Lorentzian dS$_{3}$. Consequently, unitary representations of $\mathfrak{so}(1,3)$ are labeled by $\Delta$ and $s$.}
\be \Delta = -j_L-j_R~, \indent s = j_L-j_R~.\ee
For the spinless case, which will be our focus, then $j_L=j_R = j$ and $\Delta = -2j$. We will henceforth label these representations $\mathsf{R}_\Delta$, for either the principal or complementary type.
As in AdS$_{3}$, the shadow map $\Delta \rightarrow \bar{\Delta} = 2-\Delta$ leaves the Casimir invariant. Unlike for the BTZ black hole, however, where the shadow representations did not need to be considered due to boundary conditions, they must be included for Euclidean de Sitter \cite{Castro:2023dxp,Bourne:2024ded}.  The set of representations $\mathcal{R}_\Delta$ we include are therefore $ \mathcal{R}_{\triangle} = \{\mathsf{R}_{j}\otimes \mathsf{R}_{j},\mathsf{R}_{\bar{j}}\otimes \mathsf{R}_{\bar{j}}\}$.

We will not repeat the steps needed to derive the Wilson spool, and instead highlight elements relevant for the trace formula perspective (for a complete derivation, see~\cite{Castro:2023bvo,Bourne:2024ded}). As for the BTZ black hole, one follows a representation-theoretic DHS construction of the 1-loop determinant, e.g., for a real scalar field of mass $m$ (set by $\Delta$), 
\begin{equation}\label{eq:dsdet}
    Z_\Delta = \text{det}\left(-\nabla^2 + m^2\ell_{\text{dS}}^2\right)^{-1/2}~.
\end{equation}
Treat $Z_{\Delta}$ as a meromorphic function in $\Delta$. A necessary condition for a state $\ket{\psi}$ in representation $\mathcal{R}_{\Delta}$ to contribute a pole to $Z_{\Delta}$ is that $|\psi\rangle$ satisfy the mass shell condition
\begin{equation}\label{eq:massshellds}
    (-\nabla^2+m^2\ell_{\text{dS}}^2)\ket{\psi} = (2c_{2,L}+2c_{2,R}+m^2\ell_{\text{dS}}^2)\ket{\psi}=0~.
\end{equation}
Without analytically continuing the mass, this corresponds precisely to highest weight, non-standard representations, with the highest weight state labeled by $j<0$ satisfying
\begin{equation}\label{eq:msquared}
    j(j+1) = -\frac{1}{4}m^2 \ell_{\text{dS}}^2~.
\end{equation}
Once analytically continued, this also captures the standard $\mathfrak{su}(2)$ representations with positive Casimir. As emphasized in~\cite{Bourne:2024ded}, an additional condition of global hyperbolicity in fact excludes the non-standard representations. As such, the pole structure of $Z_{\Delta}$ is set entirely by the standard representations.



Following a similar set of steps laid out in Section \ref{sec:wsads}, the 1-loop partition function for massive scalar field on $S^{3}$ is 
\be \log{Z_\Delta} = \frac{1}{4}\mathbb{W}_j~,\label{eq:WilspoolS3Z1}\ee
for Wilson spool
\begin{align}\label{eq:spoolds}
    \mathbb{W}_j &= i\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\text{Tr}_{R_j}\left(\mathcal{P}e^{\frac{z}{2\pi}\oint a_L}\right)\text{Tr}_{R_j}\left(\mathcal{P}e^{-\frac{z}{2\pi}\oint a_R}\right) \nonumber\\ 
    &= -i\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\chi_j\left(\frac{x}{2\pi}\right)\chi_{\bar{j}}\left(-\frac{x}{2\pi}\right)\nonumber \\ 
    &= -\frac{i}{4}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin^3{(z/2)}}e^{iz(2j+1)}~.
\end{align}
Here the contour $\mathcal{C}$ is negatively oriented, wrapping once around $z=0$ and twice around the positive real axis, as depicted in Figure~\ref{fig:Contour2}. 
This will figure later in our discussion about the trace formula. 



\subsection{Selberg zeta function for $S^3$?}

\noindent The construction of the Selberg zeta function relies on the existence of nontrivial cycles with associated primitive geodesics, which exist for discrete quotient manifolds, such as $\mathbb{H}^n/\Gamma$. Since $S^3$ is not a discrete quotient of another manifold, one should not expect to successfully define a meaningful Selberg-like zeta function for the sphere. However, since $S^3$ is a special case of lens spaces $S^3/\Gamma$ (with $\Gamma$ a discrete subgroup of $SO(4)$), one can naively seek a Selberg-like zeta function for $S^3$, in analogy to the Wilson spool analysis for Euclidean BTZ in Section \ref{sec:BTZselbviaWS}. Indeed, the Wilson spool was explicitly constructed for $S^3$ using the fact that, while geodesics on the sphere are contractible to a point, $S^3$ admits non-trivial holonomies~\cite{Castro:2023dxp,Castro:2023bvo,Bourne:2024ded}. Thus, despite the lack of nontrivial primitive geodesics, it is natural to wonder if a representation-theoretic Selberg zeta function could be constructed from the Wilson spool for the sphere, as outlined in Section~\ref{sec:BTZselbviaWS} for the BTZ black hole.

It turns out this method for deriving a Selberg zeta function for the sphere is not possible. Recall that the derivation presented in Section \ref{sec:BTZselbviaWS}  involved a simple interchange of an infinite sum (corresponding to the trace over states in the representation) with the contour integral defining the spool. We carefully demonstrated this operation was allowed by splitting the sum into a finite piece and its remainder, $\rho_{M,N}(z)$.\footnote{Without loss of generality, we can let $M=N$ to write $\rho_M(z)=-\frac{e^{iz(2j-2M+1)}}{4\sin^2{(z/2)}}(1+4i\sin{(\frac{Mz}{2})}e^{\frac{iz}{2}M})$.}
Attempting this for the EdS$_3$ spool, however, we find
% Taking the limit $M,N\rightarrow\infty$, we find
\begin{equation}
    \lim_{M,N\rightarrow\infty}\int_{\mathcal{C}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}\rho_{M,N}(z) =\infty~.
\end{equation}
Thus, the remainder term diverges and interchanging the sum and integral is not allowed. 

Amusingly, had we naively interchanged the sum and the integral in (\ref{eq:spoolds}) while dropping the remainder $\rho_{M,N}(z)$ as well as the zero mode contribution, then 
\begin{align}
    \frac{i}{4}\sum_{k_1=0}^{\infty}\sum_{k_2=0}^{\infty}\int_{\mathcal{C}/\{0\}}\frac{dz}{z}\frac{\cos{(z/2)}}{\sin{(z/2)}}e^{iz(2j-k_1-k_2)} &= -\sum_{k_1=0}^{\infty}\sum_{k_2=0}^{\infty}\log{(1-e^{2\pi i(2j-k_1-k_2)})}~.
\end{align}
Introducing $\zeta_{S^{3}}$ through $\mathbb{W}_j/4 =-\log{\zeta_{S^{3}}}$, and expressing the product in terms of the generator of rotations along the angle corresponding to Euclidean time translations,
\be i \partial_{\tau} = L_0 + \bar{L}_0~, \ee
we obtain 
\begin{align}\label{eq:repsel}
    \zeta_{S^{3}}(j) &= \prod_{k_1=0}^{\infty}\prod_{k_2=0}^{\infty}\left(1-e^{2\pi i(2j-k_1-k_2)}\right)\nonumber \\  &= \prod_{\text{descendants}}\left<1-e^{-2\pi \partial_{\tau}}\right>~,
\end{align}
where the Euler-like product is taken over descendants within the representation $\mathsf{R}_{\Delta}$ associated to the Wilson spool. While $\zeta_{S^{3}}$ has a similar form to what would be obtained using the representation theory construction, it is deceptive since the overall $k_1,k_2$ dependence drops out, leading to a divergent infinite product.

While the Wilson spool no longer matches the (log of) the Selberg zeta function in Euclidean de Sitter as it does for BTZ, it retains some features reminiscent of the Selberg zeta function.
Indeed, the non-standard representations for the EdS$_3$ spool figure in a representation-theoretic expression for a sum over holonomies (the generalization of geodesics), just with the integral and sum left uninterchanged---an ``Euler-like'' product. Further, 
the poles of the spool lie precisely at the \emph{standard} $\mathfrak{su}(2)$ representations, in analogy with the zeros of the Selberg zeta function.  
%In fact there is more to this analogy. 
Additionally, just as the Selberg zeta function arose from a trace formula \cite{selberg1956harmonic,Voros:1986vw}, 
we will now demonstrate a trace formula for $S^{3}$ gives rise to the Wilson spool.


\subsection{Trace formula for $S^{3}$}\label{sec:traceformS3}

\noindent First we will construct a trace formula for $S^{3}$. Broadly speaking, a trace formula is a relation spectral data of particular operators and geometric data, i.e., integrals along orbits on a particular space. A simple example of a trace formula is the Poisson resummation formula
\begin{equation}\label{eq:pois}
    \sum_{m\in\mathbb{Z}}h(m)=\sum_{n\in\mathbb{Z}}\int_{\mathbb{R}}h(z)e^{2\pi inz}dz~,
\end{equation}
for a sufficiently smooth test function $h\in L^{1}(\mathbb{R})$. A relevant application of the Poisson resummation formula (\ref{eq:pois}) is that it can be used to re-express the spectral data of a Laplacian of a massive particle confined to a circle $S^{1}\simeq\mathbb{R}/\mathbb{Z}$. 

To see this, note the energy eigenvalue problem $\nabla^{2}\psi_{n}=E_{n}\psi_{n}$ for a particle of unit mass on $S^{1}$ of length $2\pi$ has the kinetic operator $(-\nabla^{2})=\partial_{x}^{2}/2$ with eigenfunctions $\psi_{n}=\frac{1}{\sqrt{2\pi}}e^{-inx}$ and energies $E_{n}=n^{2}/2$. 
The associated heat kernel has the spectral decomposition, $K^{S^{1}}(x,y;2\pi)=\sum_{n}\psi_{n}(x)\psi_{n}^{\ast}(y)e^{-2\pi E_{n}}$, such that 
\beq \text{tr}(e^{-2\pi\nabla^{2}})=\int_{S^{1}}K^{S^{1}}(x,x;2\pi)dx=\sum_{n\in\mathbb{Z}}e^{-2\pi E_{n}}\;,\label{eq:spectracS1}\eeq
which we can interpret as the canonical partition function for the system with (inverse) temperature $2\pi$. Applying the Poisson resummation formula (\ref{eq:pois}) with test function $h(z) = e^{-2\pi E_z}$, one may write 
\beq \text{tr}(e^{-2\pi \nabla^{2}})=\sum_{n\in\mathbb{Z}}\int_{\mathbb{R}}e^{-2\pi E_{z}}e^{2\pi inz}dz\;.\eeq
Thus, the Poisson resummation formula relates the trace of a kinetic operator to the sum over the periodic orbits of length $2\pi|n|$ on $S^{1}$. The above is easily generalizable for a circle of length $\beta$ (merely replace all factors of $2\pi$ for $\beta$), and the functional determinant for the kinetic operator is cast in terms of the trace formula,
\beq \log \text{det}(-\nabla^{2})=-\int_{0}^{\infty}\frac{d\beta}{\beta}\text{tr}(e^{-\beta \nabla^{2}})\;,\eeq
where to obtain this expression we have evaluated the one-loop determinant using the heat kernel trace and again applied the Poisson resummation formula. In general, for a free particle on a symmetric space, Poisson resummation relates the spectral sum of Laplacians to a sum over geodesics on a maximal torus, which has proven useful to show equivalence for various representations of the heat kernel (cf. Chapter 6 of \cite{Camporesi:1990wm}). Analogously,  the Selberg trace formula is viewed as a generalization of the Poisson resummation formula for discrete quotients of hyperbolic space (see, e.g.,  \cite{Balazs:1986uj,Voros:1986vw,Bytsenko:1994bc,marklof2004selberg} for pedagogical treatments).


Spectral trace formulae of the type (\ref{eq:spectracS1}) are well known for higher-dimensional spheres and their lens space quotients; indeed they have been used to evaluate 1-loop partition functions (see, e.g., \cite{David:2009xg}). Here, following the spirit of Voros' work on zeta function factorization \cite{Voros:1986vw}, we construct a different trace formula for a scalar field on the 3-sphere based on the Fredholm determinant.\footnote{Voros' work on zeta function factorizations was extended to $n$-dimensional spheres by Choi and Quine \cite{10.1216/rmjm/1181072081}, and used to compute spherical functional determinants. As far as we can tell, the trace formula we construct is new to the literature.} More specifically, our focus will be to find an appropriate test function, different than that used for generalizations of (\ref{eq:spectracS1}), which gives rise to a Hadamard factorization of the Fredholm determinant for a massive scalar on the 3-sphere. From this test function we will be able to directly construct the Wilson spool from a trace formula.

\subsection*{The Fredholm determinant and its trace formula}


\noindent Consider a sequence $\{\lambda_{\ell}\}$ of non-zero complex numbers (note that zero modes have to be dealt with separately). For our purposes, we are interested in the case when $\{\lambda_{\ell}\}$ characterize the eigen-spectrum of a kinetic differential operator $\hat{\mathcal{O}}$ on a compact manifold given by
\begin{equation}\label{eq:Oform}
    \hat{\mathcal{O}} =-\nabla^2 -\lambda~.
\end{equation}
A particular spectral function of interest is the Fredholm determinant, cast here as a canonically regularized infinite product\footnote{For $\lambda_{\ell}$ being eigenvalues of an elliptic (pseudo-) differential operator of order $m$ on a $d$-dimensional (compact) manifold, the sequence $\{\lambda_{\ell}\}$ has order $\mu\equiv d/m$, and the infinite product without the exponential factor only converges for sequences with $\mu<1$. Presently, $\mu>1$ and thus we use the Weierstrass canonical product, which introduces the exponential factor in (\ref{eq:fred}).}
\begin{equation}\label{eq:fred}
    \Delta (\lambda)\equiv \text{det}(\mathbbm{1}-\lambda\hat{\mathcal{O}}) =\prod_{\ell=0}^{\infty}\left(1-\frac{\lambda}{\lambda_\ell}\right)^{d_\ell}e^{\frac{\lambda}{\lambda_\ell}d_{\ell}}\;,
\end{equation}
with a real parameter $\lambda$, and where $d_{\ell}$ are degeneracies of eigenvalues $\lambda_{\ell}$. The Fredholm determinant thus generalizes the determinant of a finite linear operator, and has featured in various contexts ranging from nuclear physics, random matrices, to two-dimensional quantum gravity, cf. \cite{Wheeler:1937zz,Forrester+2010,Johnson:2021zuo}. Pertinently, $\Delta(\lambda)$ is related 
to 
the functional determinant $D(\lambda)\equiv \text{det}(\hat{\mathcal{O}})=\prod_{\ell}(\lambda_{\ell}-\lambda)^{d_{\ell}}$ via\footnote{Indeed, $\Delta(\lambda)=\left(\prod_{\ell}(\lambda_{\ell}-\lambda)^{d_{\ell}}\right)\left(\prod_{\ell}\lambda_{\ell}^{d_{\ell}}\right)\left(\prod_{\ell}e^{\frac{\lambda}{\lambda_{\ell}}\lambda}\right)=D(\lambda)e^{\zeta'_{\hat{\mathcal{O}}}(0)}e^{\lambda \zeta_{\hat{\mathcal{O}}}(1)}$. For a more complete derivation taking into account an appropriate regularization, see Appendix~\ref{app:genzetafuncs}.}
\beq D(\lambda)=\Delta(\lambda)e^{-\zeta'_{\hat{\mathcal{O}}}(0)}e^{-\lambda\zeta_{\hat{\mathcal{O}}}(1)}\;,\label{eq:22}\eeq
where $\zeta_{\hat{\mathcal{O}}}(s)=\sum_{\ell=0}^{\infty}d_{\ell}\lambda_{\ell}^{-s}$ denotes the spectral zeta function, with $\zeta'_{\hat{\mathcal{O}}}(s)\equiv\partial_{s}\zeta_{\hat{\mathcal{O}}}(s)$. Since we are focusing on scalar fields, the functional determinant is related to the 1-loop partition function via $D(\lambda)^{-1/2}=Z_{\Delta}$. Further, taking the logarithm and differentiating twice with respect to $\lambda$ gives $\partial^{2}_{\lambda}\log(D(\lambda))=\partial_{\lambda}^{2}\log(\Delta(\lambda))$. Since the Fredholm determinant is canonically regularized, we are guaranteed to be able to pass derivatives through the infinite sums appearing in $\log(D(\lambda))$. This fact is implicitly used when applying the Poisson resummation formula below. 
\par
From the Fredholm determinant~\eqref{eq:fred}, one can construct the trace of the resolvent, $R(\lambda)$, equal to the logarithmic derivative of $\Delta(\lambda)$,
\begin{equation}
    R(\lambda) \equiv -\frac{d}{d\lambda}\log{\Delta(\lambda)}=\sum_{\ell=0}^{\infty}\frac{d_{\ell}\lambda}{\lambda_{\ell}(\lambda_{\ell}-\lambda)}~. \label{eq:resolvent}
\end{equation}
In particular, we are interested in the derivative of the resolvent, 
\begin{align}\label{eq:Rpgen}
    R'(\lambda) %&=\frac{d^2}{d\lambda^2}\sum_{\ell=0}^{\infty}d_{\ell}\log{\left[\left(1-\frac{\lambda}{\lambda_\ell}\right)^{-1}e^{-\frac{\lambda}{\lambda_\ell}}\right]} \\ \nonumber
    &= \sum_{\ell=0}^{\infty}\frac{d_\ell}{(\lambda-\lambda_\ell)^2} ~.
\end{align}
Let us now apply the Poisson summation formula for the resolvent of the Fredholm determinant. To this end, consider a test function $h(z)$ with an associated degeneracy function $d(z)$, such that the combination $d(z)h(z)\in L^1(\mathbb{R})$, and is even in $z$. We pick the test function and degeneracy function to be one appropriate for expressing the resolvent as a sum over $\mathbb{Z}$, resulting in:
\beq R'(\lambda)=\frac{1}{2}\sum_{n\in\mathbb{Z}}d(n)h(n)=\frac{1}{2}\sum_{n\in\mathbb{Z}}\int^{\infty}_{-\infty}d(z)h(z)e^{2\pi i nz}dz\;,\label{eq:traceform}\eeq
where we used the Poisson resummation formula (\ref{eq:pois}) to arrive at the second equality. We will leave this test function unspecified for now, to account for any Fredholm determinant of the form \eqref{eq:fred}; in the next section, we will give an explicit form of this test function for the specific case of the three-sphere (see Appendix~\ref{app:traceformbeyondS3} for the lens space quotient of the 3-sphere). 

We can interchange the infinite sum and integral with an appropriate $i\epsilon$ prescription to ensure convergence. More carefully, using the even parity of $d(z)h(z)$ to split the integral over $\mathbb{R}$ into two integrals over $\mathbb{R}^{+}$, and rewriting the sum over $n$ into a sum over $|n|$ gives
\beq 
\begin{split}
 R'(\lambda)&=\frac{1}{2}\sum_{n\in\mathbb{Z}}\int_{0}^{\infty}d(z)h(z)e^{2\pi i |n|z}dz+\frac{1}{2}\sum_{n\in\mathbb{Z}}\int_{0}^{\infty}d(z)h(z)e^{-2\pi i |n|z}dz\;.
\end{split}
\eeq
We can then interchange the sum and integral in the first (second) term by deforming $z\to z+i\epsilon$ ($z\to z-i\epsilon$). In so doing, 
\begin{align}
    R'(\lambda)
    &= \frac{i}{2}\lim_{\epsilon\rightarrow0}\left(\int_{0 +i\epsilon}^{\infty+i\epsilon}+\int_{\infty-i\epsilon}^{0-i\epsilon}\right)d(z)h(z)\cot{(\pi z)}dz\;.
\end{align}
 Assuming the integrand does not have any poles at $z=0$, we may express the two integrals as a single integral over a contour $\Gamma$, such that 
\begin{equation}\label{eq:trS3}
  R'(\lambda)= \frac{1}{2}\sum_{n\in\mathbb{Z}}d(n)h(n)
    = \frac{i}{2}\int_{\Gamma}d(z)h(z)\cot{(\pi z)}dz\;,
\end{equation}
where $\Gamma$ is negatively oriented and wraps around the real axis, enclosing poles at $z=n$ for $n\in\mathbb{N}$ (see Figure \ref{fig:Contour2}). Note that while we uncovered this trace formula with the resolvent $R'(\lambda)$ in mind, the preceding derivation in fact holds for more general smooth test functions.\footnote{If the integrand has removable singularities, the Poisson summation formula may be used by introducing a shift $i\delta$ in a way that removes the singularities. The trace formula (\ref{eq:trS3}) can then be evaluated by taking $\delta\rightarrow 0$, omitting the removable singularity when summing the residues.}

From the relation (\ref{eq:22}), the functional determinant $D(\lambda)$ can be directly obtained from the resolvent operator $R'(\lambda)$ by an appropriate double integration
\begin{equation}\label{eq:intd}
    \log{D(\lambda)} = -\int_{-\infty}^{\lambda}\int_{-\infty}^{\lambda'}d\lambda'd\lambda'' R'(\lambda'')~.
\end{equation}
We will use this relation below when we construct the spool.

