\subsection{New derivation of the Wilson spool}\label{sec:4.2}
\noindent The Wilson spool for Euclidean de Sitter can be derived from the resolvent $R'(\lambda)$. 
Let $\hat{\mathcal{O}}$ be the massive scalar Laplacian on $S^{3}$, 
\begin{equation}
    \hat{\mathcal{O}} =-\nabla^2 +m^2~.
\end{equation}
Comparing to \eqref{eq:Oform} and \eqref{eq:msquared}, we make the identification
\be \label{eq:lambdatoj}
\lambda=-m^2~, \indent j=-\frac{1}{2}\left(1\pm \sqrt{1+\lambda}\right)\equiv-\frac{1}{2}\Delta_{\pm}~.
\ee
The massless scalar Laplacian $-\nabla^2$ on the three-sphere has eigenvalues and degeneracies
\begin{equation}
\lambda_{\ell}=\ell(\ell+2)~, \indent d_{\ell}=(\ell+1)^{2}~,
\end{equation}
for positive integer $\ell$. \par
For the purposes of deriving the Wilson spool, it will be useful to also define a Hadamard factorization of the Fredholm determinant. Specifically, we define
\begin{equation}
    \Delta^{+} (z)=\prod_{\ell=0}^{\infty}\left(1-\frac{z}{\ell+1}\right)^{d_{\ell}}e^{d_{\ell}\left(\frac{z}{\ell+1}+\frac{z^2}{2(\ell+1)^2}\right)},
\end{equation}
which factorizes $\Delta (\lambda)$ up to an entire function $Q(\ell)$ that vanishes when taking the derivatives with respect to $\lambda$:
\begin{equation}
\Delta(\lambda)=Q(\ell)\prod_{\ell=0}^{\infty}\left(1-\frac{1+\lambda}{(\ell+1)^2}\right)^{d_\ell}e^{\frac{d_\ell}{(\ell+1)^2}(\lambda+1)}=Q(\ell)\Delta^{+}(\sqrt{1+\lambda})\Delta^{+}(-\sqrt{1+\lambda})~.\label{eq:factorizedDelta}
\end{equation}
Importantly, this is expressed in terms of the squares $(\ell+1)^2$, which can be shifted to create an even test function, rather than eigenvalues $\{\lambda_\ell\}$.
\par
From \eqref{eq:Rpgen}, the derivative of the resolvent for $S^3$ is given by
\begin{align}\label{eq:Rp}
    R'(\lambda) 
   = \frac{1}{2}\sum_{n\in\mathbb{Z}}\frac{n^2}{(1+\lambda-n^2)^2}\;.
\end{align}
Thus, comparing to~\eqref{eq:traceform} the appropriate test function is
\beq h(n)=\frac{1}{(1+\lambda-n^{2})^{2}}~,\label{eq:testfuncRp}\eeq
with degeneracy function $d(n)=n^2$. For the derivation of the spool, it will be useful to decompose this test function into two terms that combine to give the full range of integration. We can find the canonical separation using the Hadamard factorization of the Fredholm determinant, \eqref{eq:factorizedDelta}. Taking the logarithmic derivative of $\Delta(\lambda)$ expressed in this factorized form, we obtain four terms, two from each of $\Delta^+(\pm \sqrt{1+\lambda})$. The contributions from the exponential parts cancel out, leaving 
\be 
 R'(\lambda)=\frac{1}{2}\sum_{n\in\mathbb{Z}}n^{2}h(n)~,
\ee
with the factorized test function given by
\begin{equation}
    h(n)
    = \frac{2\sqrt{1+\lambda}-n}{4\left(1+\lambda\right)^{3/2}(n-\sqrt{1+\lambda})^2}+\frac{2\sqrt{1+\lambda}+n}{4\left(1+\lambda\right)^{3/2}(n+\sqrt{1+\lambda})^2}~.
\end{equation}
This factorization of $\lambda$ corresponds to a factorization of both roots $\Delta_{\pm}$ of $j$ given in~\eqref{eq:lambdatoj}.\footnote{The factorization in terms of $\Delta_{\pm}$ is, $h(n)=\frac{-2(1-\Delta_+)-n}{4(1+\lambda)^{3/2}(n+1-\Delta_+)^2}+\frac{2(1-\Delta_-)+n}{4(1+\lambda)^{3/2}(n+1-\Delta_-)^2}$~.} For de Sitter, unlike for AdS, there are no boundary condition forbidding the $\Delta_-$ solution, and both representations can have important physical applications (see, e.g., \cite{Castro:2020smu, Xiao:2014uea}). 
\par
Inserting the factorized test function into the trace formula (\ref{eq:trS3}) and integrating twice using \eqref{eq:intd} gives
\begin{align}\label{eq:trw}
    \log{D(\lambda)} 
    = &-\frac{i}{8}\int_{-\infty}^{\lambda}\int_{-\infty}^{\lambda'}d\lambda'd\lambda'' \int_{\Gamma}\frac{z^2\left(2\sqrt{1+\lambda ''}-z\right)}{\left(1+\lambda ''\right)^{3/2}(z-\sqrt{1+\lambda ''})^2}\cot{(\pi z)}dz \nonumber  \\ 
    &-\frac{i}{8}\int_{-\infty}^{\lambda}\int_{-\infty}^{\lambda'}d\lambda'd\lambda'' \int_{\Gamma}\frac{z^2\left(2\sqrt{1+\lambda ''}+z\right)}{\left(1+\lambda ''\right)^{3/2}(z+\sqrt{1+\lambda ''})^2}\cot{(\pi z)}dz~.
\end{align}
We would like to interchange the $\lambda$ integrals with the contour integral over $\Gamma$. Because the pole structure of the integrand depends on $\lambda$, however, such an interchange is not allowed. To circumvent this, we re-express the function $h(z)$ using the following Laplace transform, 
\begin{equation}\label{eq:lapl}
    \mathcal{L}\Bigl\{\left(t\sqrt{1+\lambda}\pm 1\right)e^{\mp t\sqrt{1+\lambda}}\Bigr\}(z) = \int_{0}^{\infty}\left(t\sqrt{1+\lambda}\pm 1\right)e^{-t(z\pm \sqrt{1+\lambda})} dt = \frac{2\sqrt{1+\lambda}\pm z}{(z\pm\sqrt{1+\lambda})^2}~.
\end{equation} 
Since the bounds of integration for $\lambda$ extends from $-\infty$ to $\lambda$, the presence of $\sqrt{1 + \lambda}$ introduces a branch point at $\lambda = -1$. To handle this singularity, we employ a shift $t \rightarrow t \pm i\epsilon$ such that (\ref{eq:lapl}) converges for $t > 0$. We can insert the Laplace transformation (\ref{eq:lapl}) with the appropriate contour shift into (\ref{eq:trw}), then interchange and evaluate the $\lambda$ integrals to obtain:\footnote{In the limit $\lambda \rightarrow -\infty$,  convergence is determined by the exponential term. Taking the limit $\lambda \rightarrow -\infty$ is equivalent to taking $\sqrt{1 + \lambda} \rightarrow i\infty$. For the `$+$' term, we shift the contour to $t \rightarrow t - i\epsilon$ to ensure the integrand converges in the limit $\lambda \rightarrow -\infty$ for $t>0$. For the `$-$' term, we shift the contour by $t \rightarrow t + i\epsilon$. A hard cutoff at $t = 0$ regulates the $t = 0$ divergence that appears after integrating with respect to $\lambda$.}
\begin{align}\label{eq:lamshift}
    \log{D(\lambda)}=-\frac{i}{2}\sum_{\pm}\int_{\cross\pm i\epsilon}^{\infty\pm i\epsilon}\frac{dt}{t}\int_{\Gamma}z^2\cot{(\pi z)}e^{-t(z\mp\sqrt{1+\lambda})}dz.
\end{align}
After the $\lambda$ integrals are performed, we can take the limit $\epsilon\rightarrow 0$. Now we must regulate the $t=0$ divergence. This can be done by expanding (\ref{eq:lamshift}), flipping the bounds of integration and taking both $t\rightarrow -t$ and $z\rightarrow -z$ for one of the terms to obtain
\begin{align}\label{eq:W}
    \log{D(\lambda)}  
    &=- \frac{i}{2}\left[\int_{-\infty}^{-\cross}\frac{dt}{t}+\int_{\cross}^{\infty}\frac{dt}{t}\right]\int_{\Gamma} z^2\cot{(\pi z)}e^{-t(z-\sqrt{1+\lambda})}dz~.
\end{align}
The $i\epsilon$ prescription used above is to ensure convergence in the $\lambda$ integrals. A separate $i\epsilon$ prescription is used to regulated the $t=0$ divergence. This is done by inserting a hard cutoff at $t=\cross$, and defining $\mathcal{C}$ by the following $i\epsilon$ prescription,
\begin{equation}\label{eq:ieps}
    \left(\int_{-\infty}^{-\cross}\frac{dt}{t}+\int_{\cross}^{\infty}\frac{dt}{t}\right)f(t)
    = \frac{1}{2}\lim_{\epsilon\rightarrow 0}\sum_{\pm}\int_{-i\infty\pm \epsilon}^{i\infty\pm \epsilon}\frac{dt}{t}f(-it) = \frac{1}{2}\int_{\mathcal{C}}\frac{dt}{t}f(-it)~.
\end{equation}
We note that this is the same $i\epsilon$ prescription used to regulate the de Sitter Wilson spool. The contour, $\mathcal{C}$, runs upward along the imaginary axis, as shown in the left panel of Figure~\ref{fig:Contour3}. With this regularization prescription, (\ref{eq:W}) becomes
\begin{equation}
    \log{D(\lambda)} = -\frac{i}{4}\int_{\mathcal{C}}\frac{dt}{t}\int_{\Gamma} z^2 \cot{(\pi z)}e^{it(z-\sqrt{1+\lambda})}dz~. 
\end{equation}
The contour integral over $\Gamma$ can be evaluated by summing the residues, where the poles occur at $z=n$ for $n\in\mathbb{N}$. This gives
\beq 
    \log{D(\lambda)}= \frac{i}{8}\int_{\mathcal{C}}\frac{dt}{t}\frac{\cos{(t/2)}}{\sin^3{(t/2)}}e^{-it\sqrt{1+\lambda}}~. \label{eq:sphereDl}\eeq
Using $D(\lambda)^{-1/2} = Z_\Delta$, we recognize the above is precisely the Wilson spool (\ref{eq:spoolds}) for the scalar field on $S^{3}$, 
where recall from \eqref{eq:lambdatoj} that the highest weight $j$ is related to $\lambda$ via $1+\sqrt{1+\lambda}=\Delta_+=-2j$. 

