\section{Spectral functions for $S^3$} \label{app:genzetafuncs}

\noindent Let us briefly review spectral zeta functions corresponding to a general kinetic operator $\hat{\mathcal{O}}$ on the sphere:
\begin{equation}
    \hat{\mathcal{O}} =-\nabla^2 -\lambda\;.
\end{equation}
Here $\lambda$ is a real parameter, while
$-\nabla^2$ is the (massless) scalar Laplacian on the sphere $S^3$ with eigenvalues $\{\lambda_{\ell}\}$ degeneracies $d_{\ell}$,
\begin{equation}
    \lambda_\ell =\ell(\ell+2) \quad\text{and}\quad d_\ell=(\ell+1)^2\;,
\end{equation}
for $\ell\in\mathbb{Z}$. The  functional determinant $D(\lambda)$ of operator $\hat{\mathcal{O}}$ is given by
\begin{equation}\label{eq:detgen}
    D(\lambda) \equiv\text{det}(\hat{\mathcal{O}})=\prod_{\ell}(\lambda_{\ell}-\lambda)^{d_{\ell}}~,
\end{equation}
which in general will be an infinite product, and thus care is needed to ensure convergence. 

To evaluate the functional determinant (\ref{eq:detgen}), one often works with the (general) spectral zeta function 
\begin{equation}\label{eq:genzeta}
    \zeta_{\hat{\mathcal{O}}}(s,\lambda) \equiv \sum_{\ell=0}^{\infty}\frac{d_\ell}{(\lambda_\ell +\lambda)^s}~.
\end{equation}
For later convenience, we denote the zeta function for the special value $\lambda=0$ by $\zeta_{\hat{\mathcal{O}}}(s)\equiv \zeta_{\hat{\mathcal{O}}}(s,0)$. The zeta function (\ref{eq:genzeta}) may be expressed as a Mellin transform
% \begin{equation}\label{eq:tr55}
%     \zeta_{\hat{\mathcal{O}}}(s)\equiv \zeta_{\hat{\mathcal{O}}}(s,0)
% \end{equation} 
\begin{equation}\label{eq:tr5}
    \zeta_{\hat{\mathcal{O}}}(s,\lambda) = \frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta(t)e^{-\lambda t}~,
\end{equation}
for ``partition function'' or heat kernel trace
\begin{equation}\label{eq:kernS} \Theta(t) = \sum_{\ell=0}^{\infty}d_\ell e^{-\lambda_\ell t}~.
\end{equation}
It is easy to verify that the logarithm of the functional determinant can be cast as
\begin{equation}\label{eq:tr6}
    \log{\text{det}D(\lambda)} = -\lim_{s\rightarrow 0}\frac{\partial}{\partial s}\zeta_{\hat{\mathcal{O}}}(s,-\lambda) = -\lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)e^{\lambda t}\biggr\}~.
\end{equation}



\subsection*{Functional and Fredholm determinant}

\noindent Let us now establish the relationship (\ref{eq:22}) between the functional determinant $D(\lambda)$ and the (regularized) Fredholm determinant 
\begin{equation}\label{eq:heatkern}
    \Delta (\lambda) = \prod_{k=0}^{\infty}\left(1-\frac{\lambda}{\lambda_k}\right)^{d_k}e^{\frac{\lambda}{\lambda_k}d_k}\;.
\end{equation}
First, since the exponential in the expansion (\ref{eq:tr6}) is holomorphic everywhere on $\mathbb{C}$, we Taylor expand to find
\begin{align} \label{eq:logD}
    \log{D(\lambda)} = &-\lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)e^{\lambda t}\biggr\} \nonumber \\
    = &-\lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)\biggr\}-\lambda \lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{-s}}\Theta (t)\biggr\} \nonumber \\ 
    &- \lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)\sum_{m=2}^{\infty}\frac{\lambda^m}{m!}t^m\biggr\}~.
    \end{align}
By definition, the first term is
\begin{equation}\label{eq:fred3}
    \zeta_{\hat{\mathcal{O}}}'(0) \equiv \lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)\biggr\}~.
\end{equation}
Inserting a hard cutoff to regulate the divergence at $t=0$, such that 
\be \lim_{s\rightarrow 0}\frac{1}{\Gamma(s)}\frac{\partial}{\partial s}\int_{\cross}^{\infty}\frac{dt}{t^{-s}}\Theta(t)= \lim_{s\rightarrow 0}\frac{1}{\Gamma (s)}\int_{\cross}^{\infty}dt t^{s}\log{(t)}\Theta(t)=0~,\ee
we see that the second term evaluates to
\begin{align}
    \lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dt}{t^{-s}}\Theta (t)\biggr\} 
    &=\zeta_{\hat{\mathcal{O}}}(1)~.
\end{align}
The final term in (\ref{eq:logD}) may likewise be evaluated by removing the $t=0$ divergence using a hard cutoff, giving
\begin{align}\label{eq:fred2}
    \lim_{s\rightarrow0}\frac{\partial}{\partial s}\biggl\{\frac{1}{\Gamma(s)}\int_{\cross}^{\infty}\frac{dt}{t^{1-s}}\Theta (t)\sum_{m=2}^{\infty}\frac{\lambda^m}{m!}t^m\biggr\} 
    &= \sum_{m=2}^{\infty}\frac{\lambda^m}{m}\zeta_{\hat{\mathcal{O}}}(m)~.
\end{align}
It is easy to verify the result of (\ref{eq:fred2}) is equivalent to the logarithm of the Fredholm determinant,
\begin{align}
    \log{\Delta(\lambda)} &= \log{\prod_{\ell=0}^{\infty}\left(1-\frac{\lambda}{\lambda_{\ell}}\right)^{d_\ell}}e^{\frac{\lambda}{\lambda_{\ell}}d_\ell} 
    = -\sum_{m=2}^{\infty}\frac{\lambda^m}{m}\zeta_{\hat{\mathcal{O}}}(m)~.
\end{align}
Altogether, the Fredholm determinant (\ref{eq:heatkern}) is related to the functional determinant by
\begin{equation}\label{eq:tr12}
    D(\lambda) =\Delta(\lambda)e^{-\zeta_{\hat{\mathcal{O}}}'(0)}e^{-\lambda\zeta_{\hat{\mathcal{O}}}(1)}~,
\end{equation}
matching (\ref{eq:22}). 






\section{Trace formulae and test functions beyond $S^3$}  \label{app:traceformbeyondS3}

\noindent Here we extend our analysis of Section \ref{sec:traceformS3} for spaces beyond the 3-sphere. In particular, below we will construct the appropriate trace formula and test function to give a proposal for the Wilson spool for a massive real scalar field on: (i) lens space quotients of $S^{3}$, and (ii) the higher-dimensional sphere $S^{d}$ for odd $d$.





\subsection{Lens spaces} \label{app:lens}

\noindent For a pair of coprime integers $(p,q)$ ($\text{gcd}(p,q)=1$), a lens space $L(p,q)$ is a quotient of the three-sphere by the discrete subgroup $\mathbb{Z}_{p}$ of the isometry group $SO(4)$ of $S^{3}$. It has Hopf geometry (\ref{Eq:desittermeteric}), but now with coordinate identifications
\beq (t_{E},\phi)\sim (t_{E},\phi)+\left(\frac{2\pi n}{p},\frac{2\pi n q}{p}+2\pi m\right)\;,\label{eq:Lpqid}\eeq
for integers $m,n$.\footnote{Note that the prime integer $q$ labels the various ways the cyclic group $\mathbb{Z}_{p}$ can be embedded into $SO(4)$. Further note that a shift in $q$ by an integer multiple of $p$ may be absorbed into an appropriate shift in integers $n,m$, and hence $q$ is defined up to mod $p$.} Such a coordinate identification makes the Euclidean metric (\ref{Eq:desittermeteric}) smooth at the horizon $\rho=\pi/2$. Note that the sphere itself is a special case of a lens space, $L(1,0)=S^{3}$. 



The lens space identification (\ref{eq:Lpqid}) is generated by the operator $\rho\equiv e^{-2\pi\left(\frac{1}{p}H+i\frac{q}{p}J\right)}$,
where $H=i\partial_{t}$ is the generator of time-translations while $J\equiv i\partial_{\phi}$ the axial Killing vector. Thus, the lens space $L(p,q)$ can be thought of as defining a grand canonical ensemble with (inverse) temperature $\beta$ and angular potential $\vartheta$, 
\beq \beta=\frac{2\pi}{p}\;,\quad \vartheta=\frac{2\pi iq}{p}\;.\eeq
As such, a lens space is often referred to as a `thermal' quotient of the sphere.





\vspace{2mm} 

\noindent \textbf{Trace formula and test function.} The Fredholm determinant for the scalar Laplacian takes the same form as the sphere, $S^{3}$, given by (\ref{eq:fred}). 
The eigenspectrum is the same as the 3-sphere, $\lambda_\ell =\ell(\ell+2)$, but now the degeneracies are (cf. Eq. (43) of \cite{Martin:2020api} with $s=0$)
\begin{equation}\label{eq:ld}
    d_\ell = \frac{1}{p}\sum_{k\in\mathbb{Z}_p}\chi^F_{(\frac{\ell}{2})}(k\tau)\chi^F_{(\frac{\ell}{2})}(k\bar{\tau})\;,
\end{equation}
where $\chi^F_{(\ell)}(x)$ denote the standard (finite-dimensional) $\mathfrak{su}(2)$ characters,
\begin{equation}
    \chi^F_{(\ell)}(x) = \text{tr}_{(\ell)}(e^{\frac{ix}{2}\sigma_{3}}) = \frac{\sin{\left[\frac{x}{2}(2\ell+1)\right]}}{\sin{(x/2)}}~.
\end{equation}
 Here, $\sigma_{3}$ is the familiar Pauli matrix, $\ell$ is the highest weight of the representation, and $\tau$ and $\bar{\tau}$ are parameters defined as 
\begin{equation}
    \tau\equiv \frac{2\pi q}{p}-\frac{2\pi}{p}\;, \quad \bar{\tau} \equiv \frac{2\pi q}{p}+\frac{2\pi}{p}\;.
\end{equation}

These finite dimensional characters can also be expressed in terms of the non-standard characters \eqref{eq:chars} that appear in the de Sitter spool, using the relationship
\begin{equation}\label{eq:IDtoFDchars}
    \chi_{j}\left(\frac{x}{2\pi}\right)-\chi_{\bar{j}}\left(\frac{x}{2\pi}\right) = \frac{\sin{\left[\frac{x}{2}(2j+1)\right]}}{\sin{(\frac{x}{2})}}~.
\end{equation}
Recall also that
\begin{equation} \label{eq:Pinchars}
\chi_j\left(\frac{x}{2\pi}\right)\chi_{\bar{j}}\left(-\frac{x}{2\pi}\right) = -\sum_{k_1=0}^{\infty}\sum_{k_2=0}^{\infty}e^{ix(2j-k_1-k_2)}
=\frac{1}{4}\frac{e^{i x (2j+1)}}{\sin^2{(x/2)}}~.
\end{equation}

As before, the resolvent $R'(\lambda)$ is
\begin{align}\label{eq:Rplens}
    R'(\lambda) &\equiv -\frac{d^2}{d\lambda^2}\log{\Delta(\lambda)}= \frac{1}{2p}\sum_{n\in\mathbb{Z}}\sum_{k\in\mathbb{Z}_p}\frac{d_k(n)}{(\lambda+1-n^2)^2}~,
\end{align}
where the degeneracy function is given by
\begin{equation}\label{eq:deglens}
    d_k(n) \equiv  \chi^F_{(\frac{1}{2}(n-1))}(k\tau)\chi^F_{(\frac{1}{2}(n-1))}(k\bar{\tau}) = \frac{\sin{\left[\frac{nk\pi}{p}(q-1)\right]}\sin{\left[\frac{nk\pi}{p}(q+1)\right]}}{\sin{\left[\frac{k\pi}{p}(q-1)\right]}\sin{\left[\frac{k\pi}{p}(q+1)\right]}}~,
\end{equation}
which is clearly even in $n$. 
The form of (\ref{eq:Rplens}) is well suited for applying the Poisson resummation formula since the test function is the same as that of $S^{3}$.  To arrive at our proposal for the Wilson spool, we will use the factorized form of the test function,
\begin{align}
    h(n)
    &= \frac{2\sqrt{1+\lambda}-n}{4\left(1+\lambda\right)^{3/2}(n-\sqrt{1+\lambda})^2}+\frac{2\sqrt{1+\lambda}+n}{4\left(1+\lambda\right)^{3/2}(n+\sqrt{1+\lambda})^2}~.
\end{align}
Applying the generic trace formula (\ref{eq:trS3}), we have
\begin{equation}
    \frac{d^2}{d\lambda^2}\log{D(\lambda)} = -\frac{i}{2p}\int_{\Gamma}\sum_{k\in\mathbb{Z}_p}d_k(z) h(z)\cot{(\pi z)} dz~.
\end{equation}
This demonstrates how straightforward it can be to generalize results using the trace formula.

\vspace{2mm}

\noindent \textbf{Functional determinant.} We can solve for the functional determinant $D(\lambda)$ by integrating twice with respect to $\lambda$ as done in the main text, see (\ref{eq:intd}). To safely interchange and evaluate the $\lambda$ integrals, we apply the Laplace transform given by (\ref{eq:lapl}), noting that $d_k(z)$ is even in $z$. We must also apply shift in contour before performing the $\lambda$ integrals as done in (\ref{eq:lamshift}). Doing so yields
\begin{align}\label{eq:Wlens}
    \log{D(\lambda)}  
    &= -\frac{i}{2p}\left[\int_{\cross}^{\infty}\frac{dt}{t}+\int_{-\infty}^{-\cross}\frac{dt}{t}\right]\int_{\Gamma} \sum_{k\in\mathbb{Z}_p}d_k(z)\cot{(\pi z)}e^{-t(z-\sqrt{1+\lambda})}dz~.
\end{align}
The $t=0$ divergence can be regulated using the $i\epsilon$ prescription given by (\ref{eq:ieps}), and the integral over $\Gamma$ can be evaluated by summing over the first order poles that occur at $z=n$ for $n\in\mathbb{Z}$, to obtain
\be \label{eq:simplelens}
    \log{D(\lambda)}=\frac{i}{2p}\sum_{k\in\mathbb{Z}_p}\int_{\mathcal{C}}\frac{dt}{t}\frac{\cos{(t/2)}}{\sin{(t/2)}}\frac{\sin^2{(t/2)}\, e^{-it\sqrt{1+\lambda}}}{\left(\cos{(\frac{2\pi k}{p})-\cos{t}}\right)\left(\cos{(\frac{2\pi kq}{p})-\cos{t}}\right)}~.
\ee
Note that the integrand can be expressed in terms of non-standard characters using \eqref{eq:IDtoFDchars},\eqref{eq:Pinchars} and the relation $\sqrt{1+\lambda}=-(2j+1)$. Using \eqref{eq:IDtoFDchars}, this can be re-expressed using the characters $\chi_j$ as
 \begin{align}
     \log{D(\lambda)} = \frac{i}{p}\sum_{k\in\mathbb{Z}}\int_{\mathcal{C}}\frac{dt}{t}\sin{(t)}\,\chi_{j}\left(\frac{t}{2\pi}-\frac{k}{p}\right)\chi_{j}\left(\frac{t}{2\pi}+\frac{k}{p}\right)  \chi_{j}\left(\frac{t}{2\pi}-\frac{kq}{p}\right)\chi_{j}\left(\frac{t}{2\pi}+\frac{kq}{p}\right) e^{it\sqrt{1+\lambda}}.
 \end{align}
We have left the factor $e^{it\sqrt{1+\lambda}}$ in the integrand, but note that this can also be expressed in terms of non-standard characters using \eqref{eq:Pinchars}. To recover the sphere result (\ref{eq:sphereDl}) from the above, simply set $k=0$.


We can also check that this matches known expressions for the lens space one-loop determinant. To do this, we perform the integral over $\Gamma$ but leave the sum over poles unevaluated, converting it to a sum over $l=n-1$. Using \eqref{eq:ld} and \eqref{eq:deglens}, the degeneracy functions $d_k(z)$ and the sum over $k$ can be re-expressed in terms of the original degeneracies, $d_\ell$. We find
\begin{equation}\label{eq:lenscheck}
    \log{D(\lambda)} = -\sum_{\ell=0}^{\infty}d_{\ell}\int_{\cross}^{\infty}\frac{dt}{t}e^{-t(\ell+1+\sqrt{\lambda+1})}-\sum_{\ell=0}^{\infty}d_{\ell}\int_{\cross}^{\infty}\frac{dt}{t}e^{-t(\ell+1-\sqrt{\lambda+1})}~.
\end{equation}
Recalling $\Delta_{\pm}\equiv 1\pm\sqrt{1+\lambda}$, 
and using the integral representation of logarithm function through the Schwinger parameter in \eqref{eq:Schwinger}, we see that the functional determinant (\ref{eq:lenscheck}) is
\begin{equation}
    \log{D(\lambda)} = \sum_{\pm}\sum_{\ell=0}^{\infty}d_{\ell}\log{(\ell+\Delta_{\pm})}~,
\end{equation}
consistent with, e.g., (42) of \cite{Martin:2020api}. 




\subsection{Higher dimensional spheres} \label{app:higherd}

\noindent We can easily adapt our analysis to the odd $d$-dimensional sphere $S^{d}$. The (regularized) Fredholm determinant in this case is
\begin{equation}\label{eq:Sd}
    \Delta(\lambda) = \prod_{\ell=0}^{\infty}\left(1-\frac{\lambda}{\lambda_\ell}\right)^{d_{\ell}}\text{exp}\left[d_{\ell}\sum_{p=1}^{\alpha}\frac{\lambda^p}{p\lambda_{\ell}^p}\right]~,
\end{equation}
where we note the order of the Laplace operator on $S^d$ is $\mu=\frac{d}{2}$, and we introduced $\alpha \equiv \left\lfloor \frac{d}{2} \right\rfloor$. The eigenvalues and degeneracies of the scalar Laplacian are
\begin{equation}
    \lambda_{\ell} = \ell(\ell+d-1) \quad \text{and} \quad d_{\ell}=\frac{(2\ell+d-1)(\ell+d-2)!}{\ell!(d-1)!}~.
\end{equation}
\par
Meanwhile, in higher dimensions the resolvent $R(\lambda)$ is defined in terms of higher order derivatives such that the exponential terms in (\ref{eq:Sd}) disappear. That is, 
\begin{align}\label{eq:resdim}
    R^{(\alpha)}(\lambda) &= -\frac{d^{\alpha+1}}{d\lambda^{\alpha+1}}\log{\Delta (\lambda)}\nonumber \\ 
    &= \sum_{\ell=0}^{\infty}\frac{d_\ell \alpha!}{(\lambda_\ell-\lambda)^{\alpha+1}}~.
\end{align}
As before, the resolvent is related to the functional determinant, $D(\lambda)$, analogously to (\ref{eq:tr12}).
It can be solved for by integrating the resolvent,
\begin{equation}
    \log{D(\lambda)} = - \prod_{p=1}^{\alpha+1}\int_{-\infty}^{\lambda_p}d\lambda_p R^{(\alpha)}(\lambda_p)~.
\end{equation}

Following the procedure outlined for $S^3$, we again factorize the Fredholm determinant. Defining
\begin{equation}
    \Delta^{+}(z) = \prod_{\ell=0}^{\infty}\left(1-\frac{z}{\ell+\frac{d-1}{2}}\right)^{d_\ell}\text{exp}\left[d_{\ell}\sum_{p=1}^{\alpha+1}\frac{z^p}{p(\ell+\frac{d-1}{2})^p}\right]\;,
\end{equation}
we may factorize $\Delta(\lambda)$ up to an overall entire function $Q(\ell)$,
\begin{align}\label{eq:fact}
    \Delta(\lambda) &= Q(\ell)\prod_{\ell=0}^{\infty}\left(1-\frac{\kappa^2}{\left(\ell+\frac{d-1}{2}\right)^2}\right)^{d_\ell}\text{exp}\left[d_{\ell}\sum_{p=1}^{\alpha+1}\frac{\kappa^p+(-\kappa)^p}{p(\ell+\frac{d-1}{2})^p}\right]=Q(\ell)\Delta^{+}(\kappa)\Delta^{+}(-\kappa)~,
\end{align}
where
\begin{equation}
    \kappa^2= \left(\frac{d-1}{2}\right)^2+\lambda~.
\end{equation} 
\par
Consider, for example, $S^5$. Using (\ref{eq:fact}), the (log of the) Fredholm determinant can be written as a sum over $\mathbb{Z}$ as
\begin{align}\label{eq:fact2}
    \log&{\Delta^{+}(\kappa)\Delta^{+}(-\kappa)} = \sum_{\ell=0}^{\infty}d_\ell\log{\left[1+\frac{\kappa}{\ell+2}\right]}+\sum_{\ell=0}^{\infty}d_\ell\log{\left[1-\frac{\kappa}{\ell+2}\right]} +\sum_{\ell=0}^{\infty}\frac{d_\ell \kappa^2}{(\ell+2)^2}~
    \nonumber\\ 
    &= \frac{1}{12}\sum_{n=1}^{\infty}d(n)\log{\left[1+\frac{\kappa}{n+1}\right]} 
+\frac{1}{12}\sum_{n=3}^{\infty}d(-n)\log{\left[1+\frac{\kappa}{1-n}\right]} +\sum_{\ell=0}^{\infty}\frac{d_\ell \kappa^2}{(\ell+2)^2}~,
\end{align}
where $d(n)$ is the shifted degeneracy,
\begin{equation}
    d(n) =n(n+2)(n+1)^2~.
\end{equation}
For the first term in the second equality in \eqref{eq:fact2}, we shifted $n=\ell+1$, and we shifted $n=\ell+3$ for the second term. This is done to both convert into a sum over $\mathbb{Z}$, and to write the expression in a form such that parity in $n$ will be clear. We obtain
\begin{align}
    \log{\Delta^{+}(\kappa)\Delta^{+}(-\kappa)} &= \frac{1}{24}\sum_{n\in\mathbb{Z}}d(n)\log{\left[1+\frac{\kappa}{n+1}\right]}
+\frac{1}{24}\sum_{n\in\mathbb{Z}}d(-n)\log{\left[1+\frac{\kappa}{1-n}\right]} +\sum_{\ell=0}^{\infty}\frac{d_\ell \kappa^2}{(\ell+2)^2} ~.
\end{align}
From  (\ref{eq:resdim}), the resolvent for $S^5$ can be expressed as a sum over $\mathbb{Z}$ using the factorized Fredholm determinant (\ref{eq:fact2}), which can be written in the form of the trace formula (\ref{eq:trS3}) as\footnote{The trace formula (\ref{eq:trS3}) can be used since the combination $d(n)h_{+}(n)+d(-n)h_{-}(n)$ is even in $n$.}
\begin{align}\label{eq:hdr}
    R^{(\alpha)}(\lambda)  &= \frac{1}{2}\sum_{n\in\mathbb{Z}}d(n)h_{+}(n) + \frac{1}{2}\sum_{n\in\mathbb{Z}}d(-n)h_{-}(n)\nonumber \\ 
    &= \frac{i}{2}\int_{\Gamma}d(z)h_{+}(z)\cot{(\pi z)}dz+\frac{i}{2}\int_{\Gamma}d(-z)h_{-}(z)\cot{(\pi z)}dz~,
\end{align}
where $h_{\pm}(n)$ is the test function associated with the factorized Fredholm determinant (\ref{eq:fact2}),
\begin{align}
    h_{\pm}(n) &= \frac{-35-8\lambda-9\sqrt{4+\lambda}\mp3n(2\pm n+3\sqrt{4+\lambda})}{96(4+\lambda)^{5/2}(1\pm n+\sqrt{4+\lambda})^3}~.
\end{align}
The resolvent can be integrated with respect to $\lambda$ to express the functional determinant for $S^5$ as
\begin{equation}
    \log{D(\lambda)} = -\frac{i}{2}\prod_{p=1}^{3}\int_{-\infty}^{\lambda_p}d\lambda_p \int_{\Gamma} [d(z)h_{+}(z)+d(-z)h_{-}(z)]\cot{(\pi z)}dz~.
\end{equation}
To allow the $\lambda_p$ integrals to be interchanged with the integral over $z$, we write the test function as a Laplace transformation,
\begin{align}
        h_{\pm}(z) = -\mathcal{L}\Bigl\{\frac{\pm3+3t\sqrt{4+\lambda}\pm t^2(4+\lambda)}{96(4+\lambda)^{5/2}}e^{\mp t(1+\sqrt{4+\lambda})}\Bigr\}(z)~.
\end{align}
The $\lambda_p$ integrals may be interchanged and evaluated by applying an $i\epsilon$ shift, as done in (\ref{eq:lamshift}), to ensure convergence. After the integrals are evaluated, we can take $\epsilon\rightarrow0$ to express the functional determinant as
\begin{align}
    \log{D(\lambda)} = -\frac{i}{24}\left[\int_{-\infty}^{-\cross}+\int_{\cross}^{\infty}\right]\frac{dt}{t}e^{t(1+\sqrt{4+\lambda})}\int_{\Gamma}d(z)\cot{(\pi z)}e^{-tz}dz~, 
\end{align}
where the cutoff at $z=\cross$ is to regulate the $t=0$ divergence. Lastly, we can the $i\epsilon$ prescription (\ref{eq:ieps}) used for $S^3$ to obtain:
\begin{align}
    \log{D(\lambda)} &= -\frac{i}{48}\int_{\mathcal{C}}\frac{dt}{t}e^{-it(1+\sqrt{4+\lambda})}\int_{\Gamma}d(z)\cot{(\pi z)}e^{itz} dz \nonumber\\  
    &= -\frac{i}{32}\int_{\mathcal{C}}\frac{dt}{t}\frac{\cos{(t/2)}}{\sin^5{(t/2)}}e^{-it\sqrt{4+\lambda}}~.
\end{align}
Note that although $d(z)$ is not itself even under $z \to -z$, the total sum of residues remains unchanged. This symmetry allows the contour integrals to be combined. 
\par
 This procedure can be applied for any odd dimension  sphere, $S^d$. The result for the functional determinant is
\begin{equation}
    \log{D(\lambda)} = \left(\frac{-i}{2}\right)^d\int_{\mathcal{C}}\frac{dt}{t}\frac{\cos{(t/2)}}{\sin^d{(t/2)}}e^{-it\sqrt{\frac{1}{4}(d-1)^2+\lambda}}~.
\end{equation}
Note the appearance of the familiar dimension-dependent phase \cite{Polchinski:1988ua}. 




