    \|r\|&=\left\|(\tilde{x} \pdot \tilde{s})^{-{1}/{2}} \pdot (\tau e-x \pdot s) \right\|\\   
&\leq\|(\tilde{x} \pdot \tilde{s})^{-{1}/{2}}\|_\infty  \|x\pdot s-\tau e\|\\
&\quad\quad \text{(by Assumption \eqref{eqn_assumption_cen} of Theorem \ref{theorem_n_3_iteration})}\\
&\leq \|(\tilde{x} \pdot \tilde{s})^{-{1}/{2}}\|_\infty \cdot \alpha\tau  \qquad \text{(by Lemma \ref{lemma_scalar_rho}})\\
        &\leq (1+\delta) \alpha (1-\alpha)^{-{1}/{2}} \tau^{{1}/{2}}
    \end{aligned}
    \end{equation}
    which completes the proof of \eqref{eqn_p_q_r_a}.

Multiplying \eqref{eqn_approximate_c}  by $(\tilde{x}\pdot\tilde{s})^{-{1}/{2}}$ gives that
\begin{equation}
    p_r + q_r = (\tilde{x} \pdot \tilde{s})^{-{1}/{2}} \pdot (\tau e - x\pdot s) = r
\end{equation}
and, by \eqref{eqn_Delta_x_Delta_s_positive}, we have that
\[
    p_r^\top q_r = \Delta x^\top \Delta s\geq0.
\]
Then $\|r\|^2=\|p_r+q_r\|^2=\|p_r\|^2+2p_r^\top q_r + \|q_r\|^2\geq\|p_r\|^2+\|q_r\|^2$, which implies that $\|p_r\|\leq\|r\|$ and $\|q_r\|\leq\|r\|$, completing the proof of \eqref{eqn_p_q_r_b}.

Since $(\|p_r\|-\|q_r\|)^2 = \|p_r\|^2 - 2\|p_r\| \|q_r\| + \|q_r\|^2 \geq 0$, it holds that
\begin{equation}
\|p_r\| \|q_r\|\leq\frac{\|p_r\|^2+\|q_r\|^2}{2}\leq\frac{\|r\|^2}{2}.
\end{equation}
Thus,
\begin{equation}
       \|\Delta x \pdot \Delta s\| = \|p_r \pdot q_r\| \leq \|p_r\| \|q_r\| \leq \frac{\|r\|^2}{2},
\end{equation}
which completes the proof of \eqref{eqn_p_q_r_c}.

By $\|p_r\|^2+\|q_r\|^2\leq\|r\|^2$ and $\|p_r\| \|q_r\|\leq\frac{\|r\|^2}{2}$, we have that
\begin{equation}
\left(\|p_r\|+\|q_r\|\right)^2=\|p_r\|^2+\|q_r\|^2+2\|p_r\| \|q_r\| \leq 2\|r\|^2,
\end{equation}
That is,
$\|p_r\|+\|q_r\|\leq\sqrt{2}\|r\|$, which completes the proof of \eqref{eqn_p_q_r_d}.

Furthermore, we have that
\begin{equation}
\begin{aligned}
\left\|\frac{\Delta x}{x} \right\|&= \left \| \frac{\tilde{x}}{x} \frac{1}{\sqrt{\tilde{x} \pdot \tilde{s}}} \sqrt{\frac{\tilde{s}}{\tilde{x}}} \Delta x \right\| \\
&\leq\left\|\frac{\Tilde{x}}{x}\right\|_\infty  \left\|(\Tilde{x}\pdot\Tilde{s})^{-{1}/{2}} \right\|_\infty  \left\|p\right\|\\
&\quad\quad \text{(by Assumption (\ref{eqn_tilde_x_definition}), Lemma \ref{lemma_scalar_rho}, and  \eqref{eqn_p_q_r_b})} \\
&\leq(1+\delta)^2 (1-\alpha)^{-{1}/{2}} \tau^{-{1}/{2}}\|r\| \qquad \text{(by \eqref{eqn_p_q_r_a})} \\
&\leq\frac{(1+\delta)^3\alpha}{1-\alpha}=\eta.
\end{aligned}
\end{equation}
Similarly we have that $\left\|\frac{\Delta s}{s}\right\|\leq\eta$, which completes the proof of \eqref{eqn_p_q_r_e}.
\end{proof}

\begin{lemma}\label{lemma_bar_x_bar_s}
    Given the next iterate $(z^+,x^+,s^+)$ from \eqref{eqn_next_point}
    and under the assumptions of Theorem \ref{theorem_n_3_iteration}, then 
\begin{equation}
        \|x^+\pdot s^+-\tau e\|\leq\sigma\tau
\end{equation}
    where 
\begin{equation}
\sigma=\sqrt{2}\delta(1+\delta)^2\alpha\sqrt{\frac{1+\alpha}{1-\alpha}}+\frac{(1+\delta)^2\alpha^2}{2(1-\alpha)}.
\end{equation}
\end{lemma}
\begin{proof}
First, by \eqref{eqn_next_point} and \eqref{eqn_approximate_c}, we have that
    \[
    \begin{aligned}
        &~x^+\pdot s^+ = x\pdot s + (s\pdot\Delta x+x\pdot\Delta s) + \Delta x\pdot \Delta s \\
        &= x\pdot s + (\Tilde{s}\pdot\Delta x + \Tilde{x}\pdot\Delta s) + (s-\Tilde{s})\pdot\Delta x + (x-\Tilde{x})\pdot\Delta s\\
        &\quad +\Delta x\Delta s\\
        &=\tau e + (s-\Tilde{s})\pdot\Delta x + (x-\Tilde{x})\pdot\Delta s+\Delta x\pdot\Delta s.
    \end{aligned}
    \]
Then we have that
    \[
    \begin{aligned}
        &\quad\|x^+\pdot s^+-\tau e\|\\
        &\leq\|(s-\Tilde{s})\pdot\Delta x + (x-\Tilde{x})\pdot\Delta s\| + \|\Delta x\pdot\Delta s\|\\
        &=\left\|\sqrt{\Tilde{x}\pdot\Tilde{s}}\left(\frac{s-\Tilde{s}}{\Tilde{s}}\sqrt{\frac{\Tilde{s}}{\Tilde{x}}}\Delta x + \frac{x-\Tilde{x}}{\Tilde{x}}\sqrt{\frac{\Tilde{x}}{\tilde{s}}}\Delta s\right) \right\| + \|\Delta x\pdot\Delta s\|\\
        &\leq\left\|\sqrt{\tilde{x}\pdot\tilde{s}}\right\|_\infty \left(\left\|\frac{s-\tilde{s}}{\tilde{s}}\right\|_\infty \left\|p_r\right\|  + \left\|\frac{x-\tilde{x}}{\tilde{x}}\right\|_\infty \left\|q_r\right\| \right)  \\
        &\quad + \|\Delta x\pdot\Delta s\|\\
        &\quad\text{(by Lemma \ref{lemma_scalar_rho}, Assumptions (\ref{eqn_tilde_x_definition}), (\ref{eqn_tilde_s_definition}), and  \eqref{eqn_p_q_r_b})}\\
    &\leq (1+\delta)(1+\alpha)^{{1}/{2}}\tau^{{1}/{2}}\left(\delta \left \|p_r\right\| + \delta\left\|q_r \right\|\right) + \frac{\|r\|^2}{2}\\
&\quad\text{(by \eqref{eqn_p_q_r_d})} \\
&\leq(1+\delta)(1+\alpha)^{{1}/{2}}\tau^{{1}/{2}} \delta \sqrt{2} \|r\|+ \frac{\|r\|^2}{2}\\
 &\quad\text{(by \eqref{eqn_p_q_r_a})}\\
&\leq\Bigg(\sqrt{2}\delta(1+\delta)^2\alpha\sqrt{\frac{1+\alpha}{1-\alpha}}+\frac{(1+\delta)^2\alpha^2}{2(1-\alpha)}\Bigg)\tau\\
&=\sigma\tau,
    \end{aligned}
    \]
    which completes the proof.
\end{proof}

Now, we are ready to provide the proof of Theorem \ref{theorem_n_3_iteration}.

\textbf{(1) Proof of \eqref{eqn_next_iterate_center}:} according to the choice of the approximation parameter $\delta$ in  \eqref{eqn_alpha_delta_beta} and by  \eqref{eqn_p_q_r_e}. we have that
\begin{equation}
\begin{aligned}
&\left\|\frac{\Delta x}{x}\right\|_\infty \leq \left\|\frac{\Delta x}{x}\right\|\leq\frac{(1+\delta)^3\alpha}{1-\alpha}<1,\\
&\left\|\frac{\Delta s}{s}\right\|_\infty \leq \left\|\frac{\Delta s}{s}\right\|\leq\frac{(1+\delta)^3\alpha}{1-\alpha}<1.
\end{aligned}
\end{equation}
That is, based on $(x,s)>0$, we have that
\begin{equation}
x^+=x+\Delta x>0,\quad s^+=s+\Delta s>0.
\end{equation}
Furthermore, by Lemma \ref{lemma_bar_x_bar_s} and Assumption \eqref{eqn_assumption_tau}, we have that
\begin{equation}\label{eqn_next_x_s_mu}
\begin{aligned}
\xi^+&\triangleq\frac{\left\|x^+\pdot s^+-\tau^+e\right\|}{\tau^+}\\
&=\frac{\left\|x^+\pdot s^+-\tau e + \tau e - \tau^+e \right\|}{\tau^+}\\
&\leq\frac{\left\| x^+\pdot s^+-\tau e\right\| + \left\|\tau^+e - \tau e\right\|}{\tau^+}\\
    &=\frac{\left\| x^+\pdot s^+-\tau e\right\| + \sqrt{2n}\left|\tau^+-\tau\right|}{\tau^+}\\
    &\quad\text{(by Lemma \ref{lemma_bar_x_bar_s} and  \eqref{eqn_assumption_tau})}\\
&\leq\frac{\sigma+\beta}{1-\frac{\beta}{\sqrt{2n}}}.
\end{aligned}    
\end{equation}
To make $\frac{\sigma+\beta}{1-\frac{\beta}{\sqrt{2n}}}=\alpha$, we choose $ \beta=\frac{\alpha-\sigma}{1+\frac{\alpha}{\sqrt{2n}}}>0$, which is  \eqref{eqn_alpha_delta_beta}, and we have that
\[
\xi^+\leq\alpha.
\]
which completes the proof of  \eqref{eqn_next_iterate_center} of Theorem \ref{theorem_n_3_iteration}. 

\textbf{(2) Proof of \eqref{eqn_number_iterations}:} let $\tau^k$ and $\tau^0$ denote the $k$th and initial value of $\tau$ ($\tau^0=1$), and according to  Assumption \eqref{eqn_assumption_tau}, we have that
\[
\tau^k=\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}\tau^0=\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}
\]
Let $(x^k,s^k)$ be the $k$th iterate% and $\tau^k$, 
then the duality gap $(x^k)^\top s^k$ has
\[
\begin{aligned}
(x^k)^\top s^k&= e^\top (x^k\pdot s^k) = e^\top \left(\tau^k e+(x^k\pdot s^k-\tau^k e) \right)\\
&=2n\tau^k + e^\top (x^k\pdot s^k-\tau^k e).    
\end{aligned}
\]
By the Cauchy-Schwarz inequality, we have that
\[
|e^\top (x^k\pdot s^k-\tau^k e) |\leq\|e\|_2 \|x^k\pdot s^k-\tau^k e\|_2=\sqrt{2n} \|x^k\pdot s^k-\tau ^ke\|.
\]
Then, by the proof \eqref{eqn_next_iterate_center}, all iterates are positive and lie in the narrow neighborhood: $\|x^k\pdot s^k-\tau ^ke\|\leq\alpha\tau^k$. We have that
\[
2n\tau^k-\sqrt{2n}\alpha\tau^k\leq(x^k)^\top s^k\leq 2n\tau^k+\sqrt{2n}\alpha\tau^k,
\]
namely, that
\begin{equation}\label{eqn_iteration_inequality}
\begin{aligned}
&(2n-\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}\leq(x^{k})^\top s^{k}\\
&\quad\quad\leq(2n+\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}.  
\end{aligned}
\end{equation}
Hence, $(x^k)^\top s^k\leq\epsilon$ holds if
\begin{equation}
(2n+\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}\leq\epsilon.
\end{equation}
Taking the logarithm of both sides gives that
\begin{equation}
k\log\!\left(1-\frac{\beta}{\sqrt{2n}} \right)+\log\!\left(2n+\alpha\sqrt{2n}\right)\leq\log(\epsilon),
\end{equation}
which holds if 
\begin{equation}
k\geq\frac{\log\left(\frac{\epsilon}{2n+\alpha\sqrt{2n}}\right)}{\log\left(1-\frac{\beta}{\sqrt{2n}}\right)}=\frac{\log\left(\frac{2n+\alpha\sqrt{2n}}{\epsilon}\right)}{-\log\left(1-\frac{\beta}{\sqrt{2n}}\right)}
\end{equation}
Thus, after at most
\[
\mathcal{N}_\mathrm{iter}=\!\left\lceil\frac{\log\left(\frac{2n+\alpha\sqrt{2n}}{\epsilon}\right)}{-\log\left(1-\frac{\beta}{\sqrt{2n}}\right)}\right\rceil
\]
iterations, $(x^0)^\top s^0\leq\epsilon$.

Furthermore, the above worst-case iteration complexity can be proved to be \textbf{exact} by using \eqref{eqn_iteration_inequality}. For the $(k-1)$th iteration,  we have that
\begin{equation}
\begin{aligned}
&(2n-\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k-1}\leq(x^{k-1})^\top s^{k-1}\\
&\quad\quad\leq(2n+\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k-1}.  
\end{aligned}
\end{equation}
The duality gap will reach the optimality level $\epsilon$ no earlier than and no later than $\mathcal{N}_\mathrm{iter}$ iterations if
\[
(2n-\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k}\leq(2n+\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)^{\!\!k-1},
\]
that is,  
\[
(2n-\alpha\sqrt{2n})\left(1-\frac{\beta}{\sqrt{2n}}\right)\leq2n+\alpha\sqrt{2n}, \ \forall n=1,2,\cdots
\]
Substituting $\beta=\frac{\alpha-\sigma}{1+\frac{\alpha}{\sqrt{2n}}}$ into the above inequality, we need to prove that
\begin{equation}
(\sqrt{2n}-\alpha)(\sqrt{2n}+\sigma)\leq(\sqrt{2n}+\alpha)^2,
\end{equation}
that is, $\sigma\sqrt{2n}\leq3\alpha\sqrt{2n}+\alpha^2+\alpha\sigma$, which is always true as $\alpha^2+\alpha\sigma>0$ and we can prove $\sigma\leq3\alpha$ by $\sigma=\sqrt{2}\delta(1+\delta)^2\alpha\sqrt{\frac{1+\alpha}{1-\alpha}}+\frac{(1+\delta)^2\alpha^2}{2(1-\alpha)}$ with $\alpha=0.3, \delta=0.15$. This completes the proof of \eqref{eqn_number_iterations} of Theorem \ref{theorem_n_3_iteration}. 


\subsection{Proof of Corollary \ref{corollary_n_35}}\label{sec_corollary_n_35}
\begin{proof}
Corollary \ref{corollary_n_35} is a special case of Theorem \ref{theorem_n_3_iteration} when $\delta=0$, thus their proof is similar. Taking $\delta=0$ can easily prove that
\begin{itemize}
\item[1)] \[
\left\|(x\pdot s)^{{1}/{2}} \right\|_\infty \leq (1-\alpha)^{-{1}/{2}} \tau^{-{1}/{2}}
        \]
\item[2)] Denote $v\triangleq(x\pdot s)^{-{1}/{2}} \pdot (\tau e-x\pdot s)$, then 
\[
\|v\|\leq\alpha(1-\alpha)^{-{1}/{2}}\tau^{{1}/{2}}
\]
\item[3)] Denote $p_v\triangleq\sqrt{\frac{s}{x}}\Delta x,~q_v\triangleq \sqrt{\frac{x}{s}}\Delta s$, then
\[
\|p_v\|\leq\|v\|,\quad \|q_v\|\leq\|v\|.
\]
\item[4)] \[
        \|\Delta x\pdot\Delta s\|\leq \frac{\|v\|^2}{2}
        \]
\item[5)]\[
        \|p_r\| + \|q_r\|\leq\sqrt{2}\|v\|
        \]
\item[6)] \[        \left\|\frac{\Delta x}{x}\right\|\leq\frac{\alpha}{1-\alpha},\quad \left\|\frac{\Delta s}{s}\right\|\leq\frac{\alpha}{1-\alpha}.
        \]
    \end{itemize}
Then we have that
    \[
    \begin{aligned}
\xi^+&=\frac{\left\|x^+\pdot s^+-\tau^+e \right\|}{\tau^+}\\ &=\frac{\left\|x\pdot s+x\pdot\Delta s+s\pdot\Delta x+\Delta x\pdot\Delta s-\tau^+e \right\|}{\tau^+}\\
&=\frac{\left\|\tau e+\Delta x\pdot\Delta s-\tau^+e \right\|}{\tau^+}\\
&\leq\frac{\|\Delta x\pdot\Delta s\|}{\tau^+} + \frac{\sqrt{2n}|\tau-\tau^+|}{\tau^+}\\
        &\leq \frac{\|v\|^2}{2\tau^+}+ \frac{\sqrt{2n}|\tau-\tau^+|}{\tau^+}\\
&\leq\frac{\sigma+\beta}{1-\frac{\beta}{\sqrt{2n}}},
\end{aligned}
    \]
where $\sigma=\frac{\alpha^2}{2(1-\alpha)}$. To make $\frac{\sigma+\beta}{1-\frac{\beta}{\sqrt{2n}}}=\alpha$, we choose $ \beta=\frac{\alpha-\sigma}{1+\frac{\alpha}{\sqrt{2n}}}>0.$

    The remaining proof is similar to the \textbf{Proof of \eqref{eqn_number_iterations}} in Appendix \ref{sec_theorem_sqrt_n}.
\end{proof}



\subsection{Proof of Theorem \ref{theorem_num_rank}}\label{sec_theorem_num_rank}
For the $k$th iteration of Algorithm \ref{alg_n_3}, the total number of rank-1 updates is bounded by 
\[
\sum_{k=1}^{\mathcal{N}} |I_{\gamma}^k\cup I_{\theta}^k\cup I_{\phi}^k\cup I_{\psi}^k|\leq\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}I_{\gamma}^k+\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\theta}^k+\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\phi}^k+\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\psi}^k
\]
where $\mathcal{N}_\mathrm{iter}$ is the total number of iterations from  \eqref{eqn_number_iterations}. 


\begin{definition}
    For every element $i=1,\cdots{},n$ in $\gamma,\theta,\phi,\psi$, define the sets $\mathcal{K}_{\gamma_i},\mathcal{K}_{\theta_i},\mathcal{K}_{\phi_i},\mathcal{K}_{\psi_i}$, the subsequences of $\{1,\cdots{},\mathcal{N}_\mathrm{iter}\}$, such that:
    \[
    \begin{aligned}
    &\text{Let } \mathcal{K}_{\gamma_i}=\{1\}, \text{and } k\in\{2,\cdots{},\mathcal{N}_\mathrm{iter}\} \text{ to } \mathcal{K}_{\gamma_i} \text{ iff } i\in I_{\gamma}^k,\\
    &\text{Let } \mathcal{K}_{\theta_i}=\{1\}, \text{and } k\in\{2,\cdots{},\mathcal{N}_\mathrm{iter}\} \text{ to } \mathcal{K}_{\theta_i} \text{ iff } i\in I_{\theta}^k,\\
    &\text{Let } \mathcal{K}_{\phi_i}=\{1\}, \text{and } k\in\{2,\cdots{},\mathcal{N}_\mathrm{iter}\} \text{ to } \mathcal{K}_{\phi_i} \text{ iff } i\in I_{\phi}^k,\\
    &\text{Let } \mathcal{K}_{\psi_i}=\{1\}, \text{and } k\in\{2,\cdots{},\mathcal{N}_\mathrm{iter}\} \text{ to } \mathcal{K}_{\psi_i} \text{ iff } i\in I_{\psi}^k.
    \end{aligned}
    \]
\end{definition}
\begin{remark}
    By the definition of the sets $\mathcal{K}_{\gamma_i},\mathcal{K}_{\theta_i},\mathcal{K}_{\phi_i},\mathcal{K}_{\psi_i}$, summarizing the cardinality of the set $\mathcal{K}_{\gamma_i},\mathcal{K}_{\theta_i},\mathcal{K}_{\phi_i},\mathcal{K}_{\psi_i}$ for all elements $i=1,\cdots{},n$ in $\gamma,\theta,\phi,\psi$, we have that \begin{equation}\label{eqn_I_x}
    \begin{aligned}
&\sum_{i=1}^{n}\left|\mathcal{K}_{\gamma_i} \right|-n=\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_{\gamma}^k \right|,~\sum_{i=1}^{n}\left|\mathcal{K}_{\theta_i} \right|-n=\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_{\theta}^k \right|\\
&\sum_{i=1}^{n}\left|\mathcal{K}_{\phi_i} \right|-n=\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_{\phi}^k \right|,~\sum_{i=1}^{n}\left|\mathcal{K}_{\psi_i} \right|-n=\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_{\psi}^k \right| 
    \end{aligned}
    \end{equation}
    where the term ``$-n$" comes from the fact that, at the first iteration ($k=1$): $I_\gamma^1=\emptyset, I_{\theta}^1=\emptyset, I_{\phi}^1=\emptyset, I_{\psi}^1=\emptyset$ and all $\mathcal{K}_{\gamma_i},\mathcal{K}_{\theta_i},\mathcal{K}_{\phi_i},\mathcal{K}_{\psi_i}$ ($i=1,\cdots{},n$) already include the first iteration ($k=1$) case.
\end{remark}
\begin{lemma}\label{lemma_j_th_number_rank_1_update}
    For every $i=1,\cdots{},n$, we have that
\begin{subequations}
        \begin{align}
&|\mathcal{K}_{\gamma_i} |-1 \leq\frac{\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\gamma_i^{k+1}-\gamma_i^k|}{\gamma_i^k}\right)}{\left(1-\eta\right)\log(1+\delta)}\label{eqn_K_gamma}\\
&|\mathcal{K}_{\theta_i} |-1 \leq\frac{\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\theta_i^{k+1}-\theta_i^k|}{\theta_i^k}\right)}{\left(1-\eta\right)\log(1+\delta)}\label{eqn_K_theta}\\
&|\mathcal{K}_{\phi_i} |-1 \leq\frac{\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\phi_i^{k+1}-\phi_i^k|}{\phi_i^k}\right)}{\left(1-\eta\right)\log(1+\delta)}\label{eqn_K_phi}\\
&|\mathcal{K}_{\psi_i} |-1 \leq\frac{\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\psi_i^{k+1}-\psi_i^k|}{\psi_i^k}\right)}{\left(1-\eta\right)\log(1+\delta)}\label{eqn_K_psi}        \end{align}
    \end{subequations}
\end{lemma}
\begin{proof}
By \eqref{eqn_p_q_r_e} in Lemma \ref{lemma_dx_ds_u}, we have that
\begin{equation}
\left\|\frac{\Delta x}{x}\right\|_\infty \leq \left\|\frac{\Delta x}{x}\right\|\leq\eta,~\left\|\frac{\Delta s}{s}\right\|_\infty \leq \left\|\frac{\Delta s}{s}\right\|\leq\eta.
\end{equation}
Moreover, $(x,s)$ stays positive during the whole iterations, so for all $i=1,\cdots{},n$, we have that, $\forall k=1,\cdots{},\mathcal{N}_\mathrm{iter}-1$,
\begin{equation}
\begin{aligned}
&\frac{|\gamma_i^{k+1}-\gamma_i^{k}|}{\gamma_i^k}\leq\eta,
\quad \frac{|\theta_i^{k+1}-\theta_i^{k}|}{\theta_i^k}\leq\eta,\\
&\frac{|\phi_i^{k+1}-\phi_i^{k}|}{\phi_i^k}\leq\eta, \quad \frac{|\psi_i^{k+1}-\psi_i^{k}|}{\psi_i^k}\leq\eta.
\end{aligned}
\end{equation}
These inequalities directly lead to, $\forall k=1,\cdots{},\mathcal{N}_\mathrm{iter}-1,$
\begin{equation}
    \begin{aligned}
    &(1-\eta)\gamma_i^k\leq \gamma_i^{k+1}\leq(1+\eta)\gamma_i^k,\\
    &(1-\eta)\theta_i^k\leq \theta_i^{k+1}\leq(1+\eta)\theta_i^k,\\ 
    &(1-\eta)\phi_i^k\leq \phi_i^{k+1}\leq(1+\eta)\phi_i^k,\\ 
    &(1-\eta)\psi_i^k\leq \psi_i^{k+1}\leq(1+\eta)\psi_i^k,
    \end{aligned}
\end{equation}


Thus, for all $i=1,\cdots{},n$, we have that, $\forall k=1,\cdots,\mathcal{N}_\mathrm{iter}-1$,
\begin{equation}\label{eqn_x_j_k}
    \begin{aligned}
    \frac{|\gamma_i^{k+1}-\gamma_i^{k}|}{\gamma_i^{k+1}}&=\frac{\gamma_i^k}{\gamma_i^{k+1}}\frac{|\gamma_i^{k+1}-\gamma_i^{k}|}{\gamma_i^{k}}\leq\frac{1}{1-\eta}\frac{|\gamma_i^{k+1}-\gamma_i^{k}|}{\gamma_i^k},\\
     \frac{|\theta_i^{k+1}-\theta_i^{k}|}{\theta_i^{k+1}}&=\frac{\theta_i^k}{\theta_i^{k+1}}\frac{|\theta_i^{k+1}-\theta_i^{k}|}{\theta_i^{k}}\leq\frac{1}{1-\eta}\frac{|\theta_i^{k+1}-\theta_i^{k}|}{\theta_i^k},\\
    \frac{|\phi_i^{k+1}-\phi_i^{k}|}{\phi_i^{k+1}}&=\frac{\phi_i^k}{\phi_i^{k+1}}\frac{|\phi_i^{k+1}-\phi_i^{k}|}{\phi_i^{k}}\leq\frac{1}{1-\eta}\frac{|\phi_i^{k+1}-\phi_i^{k}|}{\phi_i^k},\\
    \frac{|\psi_i^{k+1}-\psi_i^{k}|}{\psi_i^{k+1}}&=\frac{\psi_i^k}{\psi_i^{k+1}}\frac{|\psi_i^{k+1}-\psi_i^{k}|}{\psi_i^{k}}\leq\frac{1}{1-\eta}\frac{|\psi_i^{k+1}-\psi_i^{k}|}{\psi_i^k},  
    \end{aligned}
\end{equation}


Taking the proof of \eqref{eqn_K_gamma} related to $\mathcal{K}_{\gamma_i}$ as an example, let $k_1$ and $k_2$ be every pair of consecutive indices in the set $\mathcal{K}_{\gamma_i}$. By the definition of the set $\mathcal{K}_{\gamma_i}$, we have that
\begin{equation}
\frac{\gamma_i^{k_2}}{\gamma_i^{k_1}}\notin \left[\frac{1}{1+\delta},1+\delta \right],
\end{equation}
    that is,  $1+\delta<\frac{\gamma_i^{k_2}}{\gamma_i^{k_1}}$. Taking logarithms gives that
\begin{equation}
    \begin{aligned}
        \log(1+\delta)&\leq |\log(\gamma_i^{k_2})-\log(\gamma_i^{k_1})|\\
        &= \left|\int_{\gamma_i^{k_1}}^{\gamma_i^{k_2}}\frac{1}{\gamma}d\gamma \right|\\
        &\leq \sum_{k=k_1}^{k_2-1}\max\left\{ \frac{|\gamma_i^{k+1}-\gamma_i^k|}{\gamma_i^{k+1}}, \frac{|\gamma_i^{k+1}-x_i^k|}{\gamma_i^k}\right\}\\
         &\quad\text{(by inequality \eqref{eqn_x_j_k}) )}\\
        &\leq\sum_{k=k_1}^{k_2-1}\frac{1}{1-\eta}\left(\frac{|\gamma_i^{k+1}-\gamma_i^k|}{\gamma_i^k}\right).
    \end{aligned}
\end{equation}
    As there are $(|\mathcal{K}_{\gamma_i}|-1)$ pairs of consecutive indices for such as $k_1$ and $k_2$, then taking the summation of those inequalities, we have that
    \[
    (|\mathcal{K}_{\gamma_i}|-1)\log(1+\delta)\leq\frac{1}{(1-\eta)}\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\gamma_i^{k+1}-\gamma_i^k|}{\gamma_i^k}\right)
    \]
     which completes the proof of \eqref{eqn_K_gamma}. The proofs of \eqref{eqn_K_theta}, \eqref{eqn_K_phi}, and \eqref{eqn_K_psi} are similar.
\end{proof}

Now, it is ready to present the proof of Theorem \ref{theorem_num_rank}. Taking the proof of the bound of $\sum_{k=1}^{\mathcal{N}}I_{\gamma}^k$ as an example, applying the Cauchy–Schwarz inequality for vectors $\left| \frac{\gamma^{k+1}-\gamma^k}{\gamma^k}\right|$ and $e=(1,\cdots,1)\in\rr^{n}$ results in
\begin{equation}
\begin{aligned}
\sum_{i=1}^{n}\left|\frac{\gamma_i^{k+1}-\gamma_i^k}{\gamma_i^k}\right|\cdot 1&\leq\sqrt{\left(\sum_{i=1}^{n} \left| \frac{\gamma_i^{k+1}-\gamma_i^k}{\gamma_i^k}\right|^2\right)}\cdot\sqrt{\sum_{i=1}^{n} 1^2}\\
&=\sqrt{n}\left\|\frac{\gamma^{k+1}-\gamma^k}{\gamma^k}\right\|.
\end{aligned}
\end{equation}
By Lemma \ref{lemma_j_th_number_rank_1_update}, taking the summation of all inequalities \eqref{eqn_K_gamma}, we have that
\begin{equation}
\begin{aligned}
\sum_{i=1}^{n}\left|\mathcal{K}_{\gamma_i} \right| -n &\leq\frac{\sum_{i=1}^{n}\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\left(\frac{|\gamma_i^{k+1}-\gamma_i^k|}{\gamma_i^k}\right)}{\left(1-\eta\right)\log(1+\delta)}   \\
&\leq\frac{\sum_{k=1}^{\mathcal{N}_\mathrm{iter}-1}\sqrt{n}\left\|\frac{\gamma^{k+1}-\gamma^k}{\gamma^k}\right\|}{\left(1-\eta\right)\log(1+\delta)}
% &\text{(by Eqn. \eqref{eqn_p_q_r_e} in Lemma \ref{lemma_dx_ds_u}}\\
% &\leq\frac{(\mathcal{N}-1)(\eta\sqrt{2n})}{\left(1-\eta\right)\log(1+\delta)},
\end{aligned}
\end{equation}
Eqn.\  \eqref{eqn_p_q_r_e} in Lemma \ref{lemma_dx_ds_u}} can be written as
\begin{equation}
\begin{aligned}
\sqrt{\sum_{i=1}^{n} \left| \frac{\gamma_i^{k+1}-\gamma_i^k}{\gamma_i^k}\right|^2 + \sum_{i=1}^{n} \left| \frac{\theta_i^{k+1}-\theta_i^k}{\theta_i^k}\right|^2}\leq\eta,\\  
\sqrt{\sum_{i=1}^{n} \left| \frac{\phi_i^{k+1}-\phi_i^k}{\phi_i^k}\right|^2 + \sum_{i=1}^{n} \left| \frac{\psi_i^{k+1}-\psi_i^k}{\psi_i^k}\right|^2}\leq\eta.
\end{aligned}
\end{equation}
That is, we have that
\begin{equation}
\begin{aligned}
    &\left\|\frac{\gamma^{k+1}-\gamma^k}{\gamma^k}\right\|=\sqrt{\sum_{i=1}^{n} \left| \frac{\gamma_i^{k+1}-\gamma_i^k}{\gamma_i^k}\right|^2}\leq\eta\\
    &\left\|\frac{\theta^{k+1}-\theta^k}{\theta^k}\right\|=\sqrt{\sum_{i=1}^{n} \left| \frac{\theta_i^{k+1}-\theta_i^k}{\theta_i^k}\right|^2}\leq\eta\\
    &\left\|\frac{\phi^{k+1}-\phi^k}{\phi^k}\right\|=\sqrt{\sum_{i=1}^{n} \left| \frac{\phi_i^{k+1}-\phi_i^k}{\phi_i^k}\right|^2}\leq\eta\\
    &\left\|\frac{\psi^{k+1}-\psi^k}{\psi^k}\right\|=\sqrt{\sum_{i=1}^{n} \left| \frac{\psi_i^{k+1}-\psi_i^k}{\psi_i^k}\right|^2}\leq\eta
\end{aligned}
\end{equation}
Finally, by \eqref{eqn_I_x}, we have that
\[
\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_\gamma^k \right| = \sum_{i=1}^{n}\left|\mathcal{K}_{\gamma_i} \right|-n\leq\frac{\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)}.
\]
Similarly, we can prove that
\begin{equation}
\begin{aligned}
&\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_\theta^k \right|\leq\frac{\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)},\\
&\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_\phi^k \right|\leq\frac{\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)},\\
&\sum_{k=1}^{\mathcal{N}_\mathrm{iter}}\left|I_\psi^k \right|\leq\frac{\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)}.
\end{aligned}
\end{equation}
Thus the total number of rank-1 updates is bounded as
\[
\begin{aligned}
    \mathcal{N}_{
    \mathrm{rank}-1}&=\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} |I_{\gamma}^k\cup I_{\theta}^k\cup I_{\phi}^k\cup I_{\psi}^k|\\
    &\leq\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\gamma}^k +\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\theta}^k +\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\phi}^k+\sum_{k=1}^{\mathcal{N}_\mathrm{iter}} I_{\psi}^k\\
    &\leq\frac{4\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)}\\
    &\leq\left\lceil\frac{4\eta(\mathcal{N}_\mathrm{iter}-1)\sqrt{n}}{\left(1-\eta\right)\log(1+\delta)}\right\rceil,
\end{aligned}
\]
which completes the proof of Theorem \ref{theorem_num_rank}.

\subsection{SVM and SVR to Box-QP}\label{sec_SVM_BoxQP}
Both SVM and SVR can be equivalently transformed into a Box-QP. This subsection takes SVM as an example to illustrate this transformation. 

Given a set of instance-label paris $(x_i,y_i),~i=1,2,\cdots{},m,~x_i\in\mathbb{R}^n,~y_i\in\left\{-1,+1\right\}$, SVM usually first maps training vectors into a high-dimensional feature space via a nonlinear function $\varphi=\varphi(x)$ and then aims to find a hyperplane that separates the points $x_i$ into two groups: one where $y_i=1$, and another where $y_i=-1$:
\begin{equation}
\textrm{find}~w,b~\text{s.t.}~y_i(\varphi_i^\top w+b)\geq1.
\end{equation}
The bias term $b$ is often dealt with by adding an extra dimension to each instance,
\begin{equation}
\varphi_i\leftarrow \mathrm{col}(\varphi_i, 1),\quad  w\leftarrow \mathrm{col}(w, b).
\end{equation}
To address the problems of nonseparable datasets, as well as sensitivity to outliers, the key is to soften the constraints by introducing the slack variables $\zeta$:
\begin{equation}
\textrm{find}~w ~\text{s.t.}~y_i(\varphi_i^\top w)\geq1-\zeta_i,\ \zeta_i\geq0.
\end{equation}
Then, a soft-margin SVM problem is 
\begin{equation}\label{problem_SVM}
    \begin{aligned}
    \min&~\frac{1}{2}w^\top w+ \rho e^\top \zeta\\
    \text{s.t.}&~y_i(\varphi_i^\top w)\geq1-\zeta_i,~\zeta_i\geq0,\ i=1,\cdots{},m.
\end{aligned}
\end{equation}
where $\rho>0$ is a regularization parameter that balances the trade-off between model complexity and training error.
\begin{lemma}
    The optimal solution $w^*$ of soft-margin SVM \eqref{problem_SVM} can be recovered with
    \[
    w^*=\sum_{i=1}^mz_i^*y_i\varphi_i
    \]
    where $z^*$ is the optimal solution of the  Box-QP: \begin{equation}\label{eqn_SVM_BoxQP}
    \begin{aligned}
    \min_{z\in\rr^m}&~\frac{1}{2}\sum_{i=1}^mz_iy_i\varphi_i^\top \sum_{i=1}^mz_iy_i\varphi_i -\sum_{i=1}^mz_i\\
    \mathrm{s.t. }&~0\leq z \leq \rho
    \end{aligned}
    \end{equation}
\end{lemma}
\begin{proof}
According to \cite[Ch 5]{boyd2004convex}, the Karush–Kuhn–Tucker (KKT) condition of soft-margin SVM \eqref{problem_SVM} is
\begin{equation}
\begin{aligned}
    &w - \sum_{i=1}^mz_iy_i\varphi_i=0,\\
    &v + z = \rho e, \\
    &v\pdot \zeta=0,\\
    &v\geq0,~\zeta\geq0,\\
    &z_i \cdot  \left[y_i(\varphi_i^\top w)-1+\zeta_i\right]=0,i=1,\cdots,m,\\
    &z_i\geq0,~y_i(\varphi_i^\top w)-1+\zeta_i\geq0,i=1,\cdots,m,
\end{aligned}
\end{equation}
where $z,v$ denote the Lagrangian dual variables for the inequality constraint $y_i(\varphi_i^\top w)-1+\zeta_i=0,~\zeta_i\geq0~(i=1,\cdots,m)$, respectively. 

By eliminating $w$ with $w=\sum_{i=1}^mz_iy_i\varphi_i$, the KKT conditions of the soft-margin SVM \eqref{problem_SVM} and the Box-QP \eqref{eqn_SVM_BoxQP} are the same, which completes the proof.
\end{proof}
The Box-QP \eqref{eqn_SVM_BoxQP} can be easily scaled to Box-QP \eqref{eqn_box_QP}. The feature space can blow up in size and even be infinite-dimensional. A kernel function $k(x_i,x_j)$ can express a dot product in a (possibly infinite-dimensional) feature space (Mercer’s theorem), that is, $\varphi_i^\top \varphi_j=\varphi(x_i)^\top\varphi(x_j)=k(x_i,x_j)$, to save computations. Therefore, the prediction classifier is $y(x)=\sum_{i=1}^mz_i^*y_ik(x,x_i)$.


