\subsection{Weighted Signal Temporal Logic}

% Introduce wSTL syntax
We consider wSTL syntax \cite{mehdipour_specifying_2021} defined recursively as
% \begin{multline}
    $\phi := \top \mid \psi \mid \neg\phi \mid 
    \bigwedge_{i=1}^N{}^{w} \phi_i \mid
    \bigvee_{i=1}^N{}^{w} \phi_i \mid \mathcal{G}_I^{w} \phi \mid \mathcal{F}_I^{w} \phi$,
% \end{multline}
where $\top$ is the logical \textit{True} value, $\psi := f(s) \geq c$ is an atomic predicate given a function $f:S \rightarrow \mathbb{R}$ with constant $c \in \mathbb{R}$, and $\neg$, $\wedge$, and $\vee$ are Boolean \textit{negation}, \textit{conjunction}, and \textit{disjunction} operators, respectively.
% Some existing works require $f$ to be a Lipschitz continuous function \cite{mehdipour_specifying_2021}; we relax this requirement because its gradient does not affect the neural network design proposed in this work. 
For conjunctive and disjunctive operators, we define the weights as $w:=[w_i]_{i=1:N} \in \mathbb{R}^N_{>0}$, where $N$ is the number of subformulae in the operator. For temporal operators, we define the weights as $w := [w_k]_{k\in I} \in \mathbb{R}^{\abs{I}}_{>0}$ for interval $I$. 
For notational simplicity, we use the following notation interchangeably: $\bigwedge_{i=1}^N{}^{w} \phi_i = \bigwedge_{i=1}^N w_i\phi_i$ and $\bigvee_{i=1}^N{}^{w} \phi_i = \bigvee_{i=1}^N w_i \phi_i$.
%where $\abs{I}$ is the number of timesteps in interval $I$ and $\sum_{i=1}^{\abs{I}} w_i = 1$.

\subsection{Normalized wSTL}

Our neural network architecture proposed in \Cref{subsec:nn-architecture} requires the weights within each operator to be normalized.
We discuss the reasons for this requirement in \Cref{subsec:theory}.
Given this requirement, we define normalized wSTL syntax recursively as
    $\phi := \top \mid \psi \mid \neg\phi \mid 
    \bigwedge_{i=1}^N{}^{w} \phi_i \mid
    \bigvee_{i=1}^N{}^{w} \phi_i \mid \mathcal{G}_I^{w} \phi \mid \mathcal{F}_I^{w} \phi_i,$
where all terminology carries over from wSTL, except we further require $\sum_{i=1}^N w_i = \sum_{k\in I} w_k = 1$, where $w_i, w_k \in [0,1]$. % for $i=1:N$ and $k\in I$.
We allow the weights to be zero because the zero weights do not influence the overall robustness \cite{yan_stone_2021}.

% Introduce robustness
To avoid large input values to our neural network, we also define normalized quantitative satisfaction semantics, or \emph{robustness}, by extending \cite{mehdipour_specifying_2021} as follows,
\begin{align}
    &r(\psi, \tau, t) &:=& \begin{cases}
        \frac{f(s_t) - c }{\sup_{s\in S} f(s) - c} & \text{if $f(s_t) - c \geq 0$,}\\
        \frac{f(s_t) - c }{\inf_{s \in S} f(s_t) - c} & \text{otherwise}
    \end{cases},\\
    &r(\neg\phi, \tau,  t) &:=& -r(\phi, \tau, t), \\
    &r\left(\bigwedge_{i=1}^N{}^{w} \phi_i, \tau, t\right) &:=& \otimes^\wedge(w, [r(\phi_i,\tau, t)]_{i = 1:N}), \\
    &r\left(\bigvee_{i=1}^N{}^{w} \phi_i, \tau, t\right) &:=& \oplus^\vee(w, [r(\phi_i, \tau, t)]_{i = 1:N}),\\
    &r\left(\mathcal{G}^{w}_I \phi, \tau, t \right) &:=& \otimes^\mathcal{G}_I(w, [r(\phi,\tau, t')]_{t' \in t + I }),\\
    &r\left(\mathcal{F}^{w}_I \phi, \tau, t \right) &:=& \oplus^\mathcal{F}_I(w, [r(\phi, \tau, t')]_{t' \in t + I }),
\end{align}
where the aggregation functions $\otimes^\wedge:\mathbb{R}^N_{\geq0}\times\mathbb{R}^N\rightarrow\mathbb{R}, \otimes^\vee:\mathbb{R}^N_{\geq0}\times\mathbb{R}^N\rightarrow\mathbb{R}, \otimes^\mathcal{G}:\mathbb{R}^{\abs{I}}_{\geq0}\times\mathbb{R}^{\abs{I}}\rightarrow\mathbb{R}$, and $\otimes^\mathcal{F}:\mathbb{R}^{\abs{I}}_{\geq0}\times\mathbb{R}^{\abs{I}}\rightarrow\mathbb{R}$ correspond to the operators $\wedge, \vee, \mathcal{G}$, and $\mathcal{F}$, respectively.
