Building from \cite{yan_stone_2021}, we define the aggregation functions with a scaling constant $\sigma > 0$ as follows,
    \begin{align}
        \otimes^\wedge(w, [r_{\tau t}^{\phi_i}]_{i = 1:N})
        &:= \frac{\sum_{i=1}^N w_i r_{\tau t}^{\phi_i}\exp(\frac{-r_{\tau t}^{\phi_i}}{\sigma})}{\sum_{i=1}^N w_i\exp(\frac{-r_{\tau t}^{\phi_i}}{\sigma})},\\
        \oplus^\vee(w, [r_{\tau t}^{\phi_i}]_{i = 1:N})
        &:= \frac{\sum_{i=1}^N w_i r_{\tau t}^{\phi_i}\exp(\frac{r_{\tau t}^{\phi_i}}{\sigma})}{\sum_{i=1}^N w_i\exp(\frac{r_{\tau t}^{\phi_i}}{\sigma})},\\
        \otimes^\mathcal{G}(w, [r_{\tau t'}^\phi]_{t' \in t + I })
        &:= \frac{\sum_{t' \in t + I} w_{t'} r_{\tau t'}^\phi\exp(\frac{-r_{\tau t'}^\phi}{\sigma})}{\sum_{t' \in t + I} w_{t'}\exp(\frac{-r_{\tau t'}^\phi}{\sigma})},\\
        \oplus^\mathcal{F}(w, [r_{\tau t'}^\phi]_{t' \in t + I })
        &:= \frac{\sum_{t' \in t + I} w_{t'} r_{\tau t'}^\phi\exp(\frac{r_{\tau t'}^\phi}{\sigma})}{\sum_{t' \in t + I} w_{t'}\exp(\frac{r_{\tau t'}^\phi}{\sigma})}.
