\subsection{Neural Network Architecture}
\label{subsec:nn-architecture}

% class of wSTL of structures
% \tlnet infers a wSTL explanation from a set of agent trajectories.
Let $\Psi =\Set{\psi_i}_{i=1: N_\mathrm{AP}}$ be a predefined set of atomic predicates and $\Psi_{\neg} = \Set{\neg\psi_i}_{i=1: N_\mathrm{AP}}$ be a set of their negations.
We focus on representing  normalized wSTL structures composed of temporal operators containing these predicates in conjunctive normal form (CNF), as follows,
% \begin{multline}
%     \phi=\\
%     0.5\mathcal{F}_I^{\bar{w}}\left(\bigwedge_{i=1}^{N_\mathrm{AP}}\bigvee_{j=1}^{N_\mathrm{AP}} w_i^\mathcal{F} w_{ij}^\mathcal{F} \psi_{j} \vee \bigvee_{j=N_\mathrm{AP}+1}^{2N_\mathrm{AP}} w_i^\mathcal{F} w_{ij}^\mathcal{F} \neg\psi_{j}\right)\\
%      \wedge 0.5\mathcal{G}_I^{\bar{w}}\left(\bigwedge_{i=1}^{N_\mathrm{AP}}\bigvee_{j=1}^{N_\mathrm{AP}} w_i^\mathcal{G} w_{ij}^\mathcal{G} \psi_{j} \vee \bigvee_{j=N_\mathrm{AP}+1}^{2N_\mathrm{AP}} w_i^\mathcal{G} w_{ij}^\mathcal{G} \neg\psi_{j}\right),
%     \label{eqn:nn_templ}
% \end{multline}
\begin{align}
    \phi = \notag
     &0.5\mathcal{F}_I^{\bar{w}}\left[\bigwedge_{i=1}^{N_\mathrm{AP}} w_{i}^\mathcal{F} \bigvee_{j=1}^{2N_\mathrm{AP}}w_{ij}^\mathcal{F} \psi_{j}\right] \\
     \wedge & 0.5\mathcal{G}_I^{\bar{w}}\left[\bigwedge_{i=1}^{N_\mathrm{AP}}w_{i}^\mathcal{G} \bigvee_{j=1}^{2N_\mathrm{AP}}w_{ij}^\mathcal{G} \psi_{j}\right],
    \label{eqn:nn_templ_standard}
\end{align}
where $w_{i}^\mathcal{F}, w_{ij}^\mathcal{F}, w_{i}^\mathcal{G}, w_{ij}^\mathcal{G} \in [0, 1]$ are importance weights and $\psi_j \in \Psi \cup \Psi_\neg$ are predefined atomic predicates.
% We define the weights $\bar{w}$ for temporal operators over interval $I$ to be $\bar{w} = \{\bar{w}_k = 1/\abs{I} | k =  1, \dots, \abs{I}, I = [0, H] \}$ $\bar{w}_k = 1/\abs{I}$ for $k =  1, \dots, \abs{I}$, where $I = [0, H]$ for trajectory $\tau$.
We define the weights $\bar{w}$ for temporal operators over interval $I = [0, H]$ to be $\bar{w} = [\bar{w}_k = 1/\abs{I}]_{k=1:\abs{I}}$ for trajectory $\tau$.
We define the conjunction weights of the temporal clauses to be 0.5 to equally weigh the importance of the task ($\mathcal{F}$) and constraint ($\mathcal{G}$) parts of the explanation.
We choose this class of structures because they allow us to represent a general class of robot policies aiming to complete a task while satisfying a set of constraints \cite{li_formal_2019,yuasa_generating_2024}.
% The only weights which are optimized are the ones in the temporal clauses.

% neural network architecture
% \todo{something about key idea behind using NNs to represent and learn these weights.}
% are the specification weights that are optimized, 
% The architecture of \tlnet is designed to ensure the built-in architectural interpretability of the network weights, achieved by the bijective correspondence of the network weights and the importance weights of \Cref{eqn:nn_templ}.
We represent specifications of the form given in \Cref{eqn:nn_templ_standard} by designing a neural network $f_\mathbf{w}$ parameterized by $\mathbf{w}$, where $\mathbf{w}$ defines the importance weights of the currently represented specification $\phi_\mathbf{w}$.
The input to the neural network is a sequence of the robustness values for each predicate $\psi \in \Psi \cup \Psi_\neg$ for each timestep in a trajectory $\tau$.
The output is the robustness of the current specification, $r(\phi_\mathbf{w},\tau)$, for that trajectory.
The neural network is trained to minimize a regularized classification loss (discussed in \Cref{subsec:simplification-process}), given a labeled dataset $\mathcal{T}$.

