\subsection{Simplification Process}
\label{subsec:simplification-process}
% Transition to simplification process and give the overview of the process
A key component of \tlnet is its simplification process, which aims to produce more human-interpretable wSTL explanations while preserving classification performance.
This process consists of three steps: a predicate filter, loss regularization, and weight pruning.

% Explain the predicate filter
\subsubsection{Predicate Filter} As a pre-processing step, we implement a predicate filter that eliminates predicates that exhibit similar behavior across both positive and negative trajectory sets, as they contribute little to discriminating between those sets and may introduce unnecessary complexity. 
Given an arbitrary dataset of trajectories $\mathcal{D}$ and an atomic predicate $\psi$, we define the \emph{robustness distribution} for $\psi$ as,
\begin{equation}
    d(\mathcal{D}, \psi) = \frac{1}{|\mathcal{D}|}\left[\abs{\mathcal{D}_1}, \abs{\mathcal{D}_2}, \abs{\mathcal{D}_3}\right],    
\end{equation}
% $d(\mathcal{D}, \psi) = \frac{1}{|\mathcal{D}|}[\abs{\mathcal{D}_1}, \abs{\mathcal{D}_2}, \abs{\mathcal{D}_3}]$ where 
% where,
\begin{align}
    \mathcal{D}_1 &:= \set{\tau | r(\psi,\tau,t)\geq0 \quad \forall t\in [0,H], \tau \in \mathcal{D}},\\
    \mathcal{D}_2 &:= \mathcal{D} \setminus (\mathcal{D}_1\cup \mathcal{D}_3),\\
    \mathcal{D}_3 &:= \set{\tau | r(\psi,\tau,t)<0 \quad \forall t\in [0,H], \tau \in \mathcal{D}, }.
\end{align}
% $\mathcal{D}_1 = \set{\tau_i | \tau_i \in \mathcal{D}, r(\psi,\tau_i,t')>0, \forall t'\in t+I}$ \todo{finish}.
That is, $\mathcal{D}_1$ is the set of trajectories where $\psi$ is always satisfied, $\mathcal{D}_2$ is the set where $\psi$ is satisfied at least once, and $\mathcal{D}_3$ is the set where $\psi$ is never satisfied.

Now, let $\mathcal{T}_p = \{(\tau, l) | l = 1, (\tau, l)\in\mathcal{T}\}$ be the positive set of trajectories in $\mathcal{T}$ and $\mathcal{T}_n = \mathcal{T} \setminus \mathcal{T}_p$ be the negative set.
For each predicate $\psi \in \Psi$, we then calculate $d(\mathcal{T}_p,\psi)$ and $d(\mathcal{T}_n,\psi)$, and then calculate the cosine similarity $S$ between those distributions.
% as a three-dimensional vector, where $d_1$ is proportion of trajectories falling into one of the following categories: (i) all timestep-wise robustness values are positive, (ii) a mix of positive and negative robustness values, and (iii) all robustness values are negative. 
% For example, if half of the trajectories satisfy the predicate at all timesteps and the other half violate it at all timesteps, the distribution is given by $(0.5, 0, 0.5)$.
% To assess similarity between the distributions of a predicate over the positive and negative trajectory sets, we use a similarity metric. 
% In this work, we adopt cosine similarity, though other metrics may be substituted. 
We then remove predicates from the set $\Psi$ (and their negation from $\Psi_\neg$) which have a cosine similarity $S> S_\mathrm{th}$, where $S_\mathrm{th}$ is a user-defined threshold.


%  Introduce the regularization step
\subsubsection{Loss Regularization}
The regularization step uses two regularizers to improve the conciseness of inferred explanations.
The first regularizer, a \textit{ temporal clause regularizer}, $R_\mathrm{T}$, is defined as,
    % \begin{align}
    %     w^{'\mathcal{F}} =\left[\max\left(\sum_{j=1}^{N_\mathrm{AP}}w_i^\mathcal{F} w_{ij}^\mathcal{F},\sum_{j=N_\mathrm{AP}+1}^{2N_\mathrm{AP}}w_i^\mathcal{F} w_{ij}^\mathcal{F}\right)\right]_{i=1:N_\mathrm{AP}},\\
    %     w^{'\mathcal{G}} =\left[\max\left(\sum_{j=1}^{N_\mathrm{AP}}w_i^\mathcal{G} w_{ij}^\mathcal{G},\sum_{j=N_\mathrm{AP}+1}^{2N_\mathrm{AP}}w_i^\mathcal{G} w_{ij}^\mathcal{G}\right)\right]_{i=1:N_\mathrm{AP}}.
    % \end{align}
\begin{multline}
R_\mathrm{T}(\mathbf{w}) := \sum_{j=1}^{N_\mathrm{AP}} \max\left(\sum_{i=1}^{N_\mathrm{AP}}\tilde{w}_{ij}^\mathcal{F},\sum_{i=1}^{N_\mathrm{AP}}\tilde{w}        _{i(j+N_\mathrm{AP})}^\mathcal{F}\right)\\ 
\max\left(\sum_{i=1}^{N_\mathrm{AP}}\tilde{w}_{ij}^\mathcal{G},\sum_{i=1}^{N_\mathrm{AP}}\tilde{w}s_{i(j+N_\mathrm{AP})}^\mathcal{G}\right).
    % \left[\max_{\{j,j+N_\mathrm{AP}\}}\left(\sum_{i=1}^{N_\mathrm{AP}}w_{ij}^\mathcal{F},\sum_{i=1}^{N_\mathrm{AP}}w_{i(j+N_\mathrm{AP})}^\mathcal{F}\right)\right]_{j=1:N_\mathrm{AP}}\\
    % \cdot \left[\max_{\{j,j+N_\mathrm{AP}\}}\left(\sum_{i=1}^{N_\mathrm{AP}}w_{ij}^\mathcal{G},\sum_{i=1}^{N_\mathrm{AP}}w_{i(j+N_\mathrm{AP})}^\mathcal{G}\right)\right]_{j=1:N_\mathrm{AP}}.
\end{multline}
Intuitively, this regularizer encourages the task and constraint clauses to contain different atomic predicates.
% \begin{dfn}[Temporal Clause Regularizer]
% The intuition behind the max operation is to choose the larger sum of weights of a predicate and those of its negation.

The second regularizer, a \textit{disjunctive clause regularizer}, $R_\mathrm{D}$, is defined as,
\begin{equation}
    R_\mathrm{D}(\mathbf{w}^\mathcal{O}) := \sum_{i=1}^{N_\mathrm{AP}-1} \sum_{j=i+1}^{N_\mathrm{AP}} \sum_{k=1}^{2N_\mathrm{AP}} \tilde{w}^\mathcal{O}_{ik} \tilde{w}^\mathcal{O}_{jk},
\end{equation}
where $\mathbf{w}^\mathcal{O} \in \{\mathbf{w}^\mathcal{F}, \mathbf{w}^\mathcal{G}\}$ defines the weights within one of our temporal operators and $\tilde{w}^\mathcal{O}_{ij}, \tilde{w}^\mathcal{O}_{jk} \in \mathbf{w}^\mathcal{O}$.
Intuitively, this regularizer encourages disjunctive clauses within a temporal clause to contain different predicates.
% as $R_\mathrm{D}:= R_\mathrm{D}^\mathcal{F} + R_\mathrm{D}^\mathcal{G}$, where
% \begin{align}
%     R_\mathrm{D}^\mathcal{F} &:= \sum_{i=1}^{N_\mathrm{AP}-1} \sum_{j=i+1}^{N_\mathrm{AP}} \langle [w_i^\mathcal{F} w_{ik}^\mathcal{F}]_{k=1:2N_\mathrm{AP}}, [w_j^\mathcal{F} w_{jk}^\mathcal{F}]_{k=1:2N_\mathrm{AP}} \rangle,\\
%     R_\mathrm{D}^\mathcal{G} &:= \sum_{i=1}^{N_\mathrm{AP}-1} \sum_{j=i+1}^{N_\mathrm{AP}} \langle [w_i^\mathcal{G} w_{ik}^\mathcal{G}]_{k=1:2N_\mathrm{AP}}, [w_j^\mathcal{G} w_{jk}^\mathcal{G}]_{k=1:2N_\mathrm{AP}} \rangle.
%  \end{align}
 % \begin{align}
 %    R_\mathrm{D}^\mathcal{F} &:= \sum_{i=1}^{N_\mathrm{AP}-1} \sum_{j=i+1}^{N_\mathrm{AP}} \langle [w_{ik}^\mathcal{F}]_{k=1:2N_\mathrm{AP}}, [w_{jk}^\mathcal{F}]_{k=1:2N_\mathrm{AP}} \rangle,\\
 %    R_\mathrm{D}^\mathcal{G} &:= \sum_{i=1}^{N_\mathrm{AP}-1} \sum_{j=i+1}^{N_\mathrm{AP}} \langle [w_{ik}^\mathcal{G}]_{k=1:2N_\mathrm{AP}}, [w_{jk}^\mathcal{G}]_{k=1:2N_\mathrm{AP}} \rangle.
 % \end{align}
% The intuition behind these terms, $R_\mathrm{D}^\mathcal{F}$ and $R_\mathrm{D}^\mathcal{G}$, is that each term calculates the sum of the inner products of all possible non-repeating combinations of weights of disjunctive clauses.
% The intuition is that each term calculates the sum of the inner products of all possible non-repeating combinations of weights of disjunctive clauses.
% For example, when there are three disjunctive clauses, the number of combinations is ${}_3 \mathrm{C} {}_2 = 6$. 
% The intuition behind the formulation is to differentiate the used predicates in a disjunctive clause in CNF from the predicates in the other disjunctive clauses within a temporal clauses.

% \end{dfn}
Given $(\tau, l) \in \mathcal{T}$, our overall loss, $\Tilde{\mathcal{L}}$, is then,
\begin{align}
    \tilde{\mathcal{L}}(\tau, l, \mathbf{w}) =  \mathcal{L}(\tau, l, \mathbf{w}) + & \lambda_{R_\mathrm{T}} R_\mathrm{T}(\mathbf{w})\notag\\
    + & \lambda_{R_\mathrm{D}} [R_\mathrm{D}(\mathbf{w}^\mathcal{F})+R_\mathrm{D}(\mathbf{w}^\mathcal{G})],
    \label{eqn:loss_all}
\end{align}
where $\mathcal{L}$ is a classification loss and $\lambda_{R_\mathrm{T}}, \lambda_{R_\mathrm{D}} \in \mathbb{R}_{\geq 0}$ are regularizer hyperparameters.
We use $\lambda_{R_\mathrm{T}} = 0.01$ and $ \lambda_{R_\mathrm{D}} = 0.1$ for this work.
We use the classification loss from \cite{yan_stone_2021},
\begin{align}
    \mathcal{L}(\tau, l, \mathbf{w}) = \exp(-\zeta l r(\phi_\mathbf{w}, \tau)),
\end{align}
where $\zeta \in \mathbb{R}_{>0}$ is a hyperparameter ($\zeta = 1$ for this work).

% Explain pruning
\subsubsection{Weight Pruning}
The weight pruning step further simplifies the currently inferred explanation by removing unnecessary weights.
% This step proceeds in two phases. 
First, all weights with a value of zero are removed from the network. 
Then, among the remaining weights, the $N_\mathrm{w} \in \mathbb{Z}_{>0}$ smallest weights---where $N_\mathrm{w}$ is a user-specified hyperparameter---are removed to eliminate the least contributing parts of the specification.
The remaining weights are then normalized.
The pruning process terminates if there is only one non-zero weight in $\mathbf{w}^\mathcal{F}$ or $\mathbf{w}^\mathcal{G}$ to ensure the task-constraint structure of the inferred explanation.
% (including the weights for $\mathcal{F}$ and $\mathcal{G}$ if needed).

\subsection{Trajectory Sampling}
% As described in \Cref{sec:bg}, the neural network is trained as a binary classifier to distinguish between positive and negative trajectories. 
We obtain positive trajectories in $\mathcal{T}$ by executing the target policy in the environment. 
These trajectories can also be sampled from existing datasets. 
We obtain negative trajectories in $\mathcal{T}$ by executing a random-walk policy in the environment. 


\subsection{Explainability Evaluation Metrics}
% Recap why we care about the explainability metrics
Beyond classification performance, \tlnet also emphasizes the human-interpretability of inferred explanations.
% While alignment is ultimately subjective and often requires qualitative assessment, 
We quantify this emphasis by introducing three explainability metrics---\emph{conciseness}, \emph{consistency}, and \emph{strictness}. 

Let $\phi$ be a wSTL explanation we want to evaluate and $N$ be the number of temporal clauses that we expect to appear in the explanation.
For example, in this work, we expect the inferred explanations to have one $\mathcal{F}$ clause and one $\mathcal{G}$ clause (thus $N=2$) because we assume there should be a task component and a constraint component.
Now, let $\phi_n$ be the $n$-th expected temporal clause in $\phi$, where $\phi_n = \emptyset$ if that clause does not exist in $\phi$.
Let the (unweighted) STL counterpart of $\phi_n$ be $\hat{\phi}_n$, where $n \in \{1,\dots N\}$.
For example, in our work, if $\phi = \mathcal{G}(0.1\psi_1 \wedge 0.9 \psi_2)$, then $\phi_1 = \emptyset$, $\hat{\phi}_1 = \emptyset$, $\phi_2 = \mathcal{G}(0.1\psi_1 \wedge 0.9 \psi_2)$, and $\hat{\phi}_2 = \mathcal{G}(\psi_1 \wedge \psi_2)$.

\subsubsection{Conciseness}
% Let $\phi$ be a wSTL explanation we want to evaluate and $N$ be the number of temporal clauses that we expect to appear in the explanation.
% For example, our specifications expect $N=2$ temporal clauses because we assume there should be a task component and a constraint component within inferred explanations.
% To motivate these metrics, we consider three example specifications:
% $\phi_1 = 0.5\mathcal{F}_I^{\bar{w}}[1.0 \psi_\mathrm{ba,rf}] \wedge$ \\ $0.5\mathcal{G}_I^{\bar{w}}[0.35 \psi_\mathrm{ba,rf} \vee 0.65 \neg\psi_\mathrm{ra,bf}]$, 
% $\phi_2 = 0.5\mathcal{F}_I^{\bar{w}}[1.0 \psi_\mathrm{ba, rf}] \wedge 0.5\mathcal{G}_I^{\bar{w}}[0.21 \neg\psi_\mathrm{ra, bf} \wedge 0.47 \psi_\mathrm{ba, rf}
%               \wedge (0.04 \neg\psi_\mathrm{ra, bf} \vee 0.05 \neg\psi_\mathrm{ra, df}) \wedge (0.18 \psi_\mathrm{ba, rf} \vee
%               0.03 \psi_\mathrm{ra, df} \vee 0.04 \neg\psi_\mathrm{ra, bf} \vee 0.02 \neg\psi_\mathrm{ra, bt})]$, and
% $\phi_3 = \mathcal{F}_I^{\bar{w}}[1.0 \psi_\mathrm{ba,bt}]$.
% Assuming all three achieve similar classification accuracy, $\phi_2$ is the most verbose, whereas $\phi_3$ is concise but lacks a constraint clause. 
% $\phi_1$ provides a balance between brevity and coverage. 
% These distinctions illustrate the need for a more nuanced evaluation beyond accuracy alone.
% Introduce conciseness
We define the \emph{conciseness} of $\phi$ as,
\begin{equation*}
    \mathrm{Conciseness} := \frac{1}{N} \sum_{n=1}^{N}
    \begin{cases}
        \frac{1}{m_n} & \text{if $m_n \neq 0$},\\
        0 & \text{otherwise},
    \end{cases}
\end{equation*}
where $m_n$ is the number of  predicates present in $n$-th expected temporal clause $\phi_n$.
Conciseness ranges from 0 to 1, with higher scores implying a shorter explanation with at least one predicate inside each expected temporal clause.

% Intorudce consistency
% We now define a consistency metric.
% \begin{dfn}[Consistency]
\subsubsection{Consistency}
Let $\Phi = [ \phi^k ]_{k=1:K}$ be a sequence of $K$ explanations for the same policy (e.g., from different training seeds).
Then, let $\Phi_n = [\phi_n^k ]_{k=1:K}$ be the sequence of the $n$-th expected temporal clauses in $\Phi$, where $\phi_n^k$ is the $n$-th expected temporal clause for $\phi^k$.
Let the STL counterpart of $\Phi_n$ be $\hat{\Phi}_n$.
% % and $\phi^k_n$ be the $n$-th temporal clause expected to appear within $\phi^k$.
% For example, the expected structure  $\phi^{1} = 0.5\mathcal{F}() \wedge 0.5\mathcal{G}$ and $\phi_2 = \mathcal{F}()$.
% Then, $\mathcal{}$
% For the $n$-th temporal clause expected to appear, let $\Phi_n = \Set{\phi^k_{n}}_{k=1:K}$ be the set of subformulae defining those clauses.
% \todo{Give an example}
Then, let the set of unique elements of $\hat{\Phi}_n$ be $\Sigma_n = \{\hat{\phi}_n \in \hat{\Phi}_n\}$.
% We define a set of unique temporal clause structures $\Sigma^n \subseteq \hat{\Phi}_n$. % for a set of the structures of $n$-th temporal clause $\bar{\Phi}_n$. 
% Here, a unique temporal clause structure is 
% Each unique structure $\sigma_n \in \sigma_n$ has $c_{\sigma^n}$ temporal clauses from $\Phi_n$ satisfying $\sigma^n$.
% We define the number of unique structures $M_n$ of the set of $n$-th temporal clauses $\Set{\phi_{kn}}_{k=1:K}$.
% Each unique architecture has $c_{nm}$ temporal clauses from $\Set{\phi_{kn}}_{k=1:K}$ matching with the architecture, where $m\in[1,M_n]$.
We define the \textit{consistency} of $\Phi$ as,
\begin{align*}
    &\mathrm{Consistency} := \\ &\frac{1}{N}\sum_{n=1}^N 
    \begin{cases}
        \max_{\sigma_n \in \Sigma_n}\sum_{\hat{\phi}_n \in \hat{\Phi}_n} \frac{\mathbf{1}_{\sigma_n}(\hat{\phi}_n)}{K\abs{\Sigma_n}} & \text{if $\Sigma_n \neq \emptyset$},\\
        0 & \text{otherwise},
    \end{cases}
\end{align*}
where $\mathbf{1}_{\sigma_n}(\cdot)$ is the indicator function for $\sigma_n$.
Consistency ranges from 0 to 1, with % a higher score implies fewer unique architectures with at least one predicate present inside of each temporal clause.
higher scores indicating greater agreement in clause structures across explanations, reflecting structural stability in learned explanations.

\subsubsection{Strictness}
% Introduce strictness
Finally, let $P$ be the number of potentially present predicates in $\phi$ (e.g., $P = 2N_\mathrm{AP}$ in \tlnet).
Denote the numbers of conjunctions and disjunctions in $\phi_n$ as $C_n$ and $D_n$, respectively.
We define the \textit{strictness} of $\phi$ as,
\begin{equation*}
    \mathrm{Strictness} := \frac{1}{N} \sum_{n=1}^N 
        \begin{cases}
            \frac{1}{P - C_n + D_n} &\text{if $\phi_n \neq \emptyset$},\\
            0 &\text{otherwise.}
        \end{cases}
\end{equation*}
Strictness ranges from 0 to 1, with higher scores implying stricter logical expressions by rewarding conjunctions and penalizing disjunctions.

