\subsection{Weight Distribution in wSTL}
\label{subsec:theory}
% Explain what this subsection is for
A key assumption in \tlnet is that the weights can be distributed across Boolean and temporal clauses.
% We introduce a fundamental property of weighted signal temporal logic (wSTL) formulas---namely, the distributivity of weights---which, to the best of our knowledge, has not been explicitly addressed in prior work. 
% This property underpins key steps in our methodology, particularly in the neural network design as well as simplification and optimization of inferred explanations.
% Formalize the weight distributivity of Boolean operators first
We now prove that such a distribution is theoretically sound.
% To formalize the this property, we leverage the property of conjunctive normal form of logical formulae.
% \begin{fact}(Conjunctive Normal Form)
% Recall that an arbitrary Boolean formula $\phi$ can be expressed in CNF. 
% as,
% \begin{equation}
% \label{eq:cnf}
%     \phi = \bigwedge_{i=1}^n\bigvee_{j=1}^{m_i} (\neg)\psi_{ij},
% \end{equation}
% where $n, m_i\in\mathbb{Z}_{>0}$ and $\psi_{ij}$ are predicates.
% \end{fact}
The normalized weights of a wSTL formula in CNF can be syntactically distributed across Boolean operators as follows.
\begin{thm}[Syntactic Weight Distributivity of Boolean Operators]
    \label{thm:bool_dist}
    A normalized wSTL formula $\phi$ in CNF can be represented as follows,
    \begin{align}   
        \phi = \bigwedge_{i=1}^n w_i\bigvee_{j=1}^{m_i} w_{ij}(\neg)\psi_{ij} \equiv \bigwedge_{i=1}^n \bigvee_{j=1}^{m_i}\tilde{w}_{ij}(\neg)\psi_{ij},
    \end{align}
    where $n, m_i\in\mathbb{Z}_{>0}$, $ w_i, w_{ij}\in\mathbb{R}_{>0}$, $\tilde{w}_{ij}:=w_i w_{ij}$, $\sum_{i=1}^n w_i = \sum_{j=1}^{m_i} w_{ij} = 1$, and $\psi_{ij}$ are predicates.
    Furthermore, the weights $\tilde{w}_{ij}$ satisfy $\sum_{i=1}^n \sum_{j=1}^{m_i} \tilde{w}_{ij} = 1$.
    \begin{proof}    
        % ($\Rightarrow$) Firstly, start from the LHS to get the RHS :
        \begin{align*}
            \{\text{LHS}\} &= w_1(w_{11}(\neg)\psi_{11} \vee ... \vee w_{1m_1}(\neg)\psi_{1m_1})\\
            % &\wedge w_2(w_{21}(\neg)\psi_{21} \vee ... \vee w_{2m_2}(\neg)\psi_{2m_2})\\
            ...&\wedge w_n(w_{n1}(\neg)\psi_{n1} \vee ... \vee w_{nm_n}(\neg)\psi_{nm_n})\\
            &= (w_1 w_{11}(\neg)\psi_{11} \vee ... \vee w_1 w_{1m_1}(\neg)\psi_{1m_1})\\
            % &\wedge (w_2 w_{21}(\neg)\psi_{21} \vee ... \vee w_2 w_{2m_2}(\neg)\psi_{2m_2})\\
            ...&\wedge (w_n w_{n1}(\neg)\psi_{n1} \vee ... \vee w_n w_{nm_n}(\neg)\psi_{nm_n})\\
            &=\bigwedge_{i=1}^n\bigvee_{j=1}^{m_i} w_i w_{ij}(\neg)\psi_{j} =\{\text{RHS}\}.
        \end{align*}
    \end{proof}
\end{thm}

