\begin{theorem}\label{41_22}{\ }
\begin{enumerate}[label=(\arabic*)]
\item $\gamma(\eta^\omega(\normaltt{0}))$ contains exactly 16 palindromes and is $\tfrac{41}{22}^+$-free.
\item Every bi-infinite ternary $\tfrac{52}{27}$-free word containing at most $16$ palindromes has the same factor set as either $\gamma(\eta^\omega(\normaltt{0}))$ or $\gamma(\eta^\omega(\normaltt{0}))^R$.
\item Every recurrent ternary $\tfrac{25}{13}$-free word containing at most $17$ palindromes has the same factor set as either $\gamma(\eta^\omega(\normaltt{0}))$ or $\gamma(\eta^\omega(\normaltt{0}))^R$.
\end{enumerate}
\end{theorem}
\begin{proof}
Let us prove the first item.
$\gamma(\eta^\omega(\texttt{0}))$ contains the palindromes $\varepsilon$, \texttt{0}, \texttt{1}, \texttt{2}, the six palindromes
of the form $bcb$ and the six palindromes of the form $abcba$. It is easy to check that it contains no other palindrome.
To show that $\gamma(\eta^\omega(\texttt{0}))$ is $\tfrac{41}{22}^+$-free, we consider the morphic word
$g(h^\omega(\texttt{0}))$ defined by the following morphisms $h$ and $g$.
\begin{align*}
    h(\texttt{0}) &= \texttt{01213012} & g(\texttt{0}) &= \texttt{0102012}\\
    h(\texttt{1}) &= \texttt{31} & g(\texttt{1}) &= \texttt{0212}\\
    h(\texttt{2}) &= \texttt{01201312} & g(\texttt{2}) &= \texttt{0121012}\\
    h(\texttt{3}) &= \texttt{0121301312} & g(\texttt{3}) &= \texttt{01020121012}
\end{align*}
We check that $g(h^\omega(\texttt{0}))$ avoids $F_\gamma$. We will show in Section~\ref{sec:ce} that $g(h^\omega(\texttt{0}))$ is $\tfrac{41}{22}^+$-free.
In particular, $g(h^\omega(\texttt{0}))$ is square-free and thus $g(h^\omega(\texttt{0}))$ is $\gamma$-good. By Lemma~\ref{ggood},
$g(h^\omega(\texttt{0}))$ and $\gamma(\eta^\omega(\texttt{0}))$ have the same factor set.\footnote{Notice that $g(h^\omega(\texttt{0}))$ is not bi-infinite,
as required by Lemma~\ref{ggood}. However, $g(h^\omega(\texttt{0}))$ is uniformly recurrent, which is somehow a stronger condition for our purpose.}
Thus, $\gamma(\eta^\omega(\texttt{0}))$ is also $\tfrac{41}{22}^+$-free.

Let us prove the second item.
We say that a ternary word (finite or infinite) is 16-good if it is $\tfrac{52}{27}$-free and contains at most $16$ palindromes.
We construct the set $S_{16}^{21}$ defined as follows:
a word $v$ is in $S_{16}^{21}$ if and only if there exists a 16-good word $pvs$ such that $|p|=|v|=|s|=21$.
Then we construct the Rauzy graph $G_{16}^{21}$ based on $S_{16}^{21}$, that is, such that vertices correspond to factors of length 20 and arcs correspond to factors of length 21.
We notice that $G_{16}^{21}$ consists of two connected components that are images of each other with respect to reversal.
Moreover, the connected component containing the factor \texttt{0120} is equal to the Rauzy graph
of the factors of order 21 of $\gamma(\eta^\omega(\texttt{0}))$.
Let $w$ be a bi-infinite 16-good word living in this connected component, that is, $w$ contains \texttt{0120}.
Since $\max_{f\in F_\gamma}|f|=21$, $w$ is $\gamma$-good. Then by~\Cref{ggood}, $w$ has the same factor set as $\gamma(\eta^\omega(\texttt{0}))$.
By symmetry, this proves the second item.

Let us prove the third item.
We say that a ternary word (finite or infinite) is 17-good if it is $\tfrac{25}{13}$-free and contains at most $17$ palindromes.
Let $w$ be a recurrent 17-good word.
We check by backtracking that no infinite 17-good word avoids $\texttt{01210}$.
By symmetry, $w$ must contain the six palindromes of the form $abcba$.
Thus, $w$ contains the 16 palindromes of $\gamma(\eta^\omega(\texttt{0}))$.
Notice that $w$ cannot contain a palindrome of the form $abacaba$ since $abacaba$
cannot be extended into a ternary square-free word.
So, without loss of generality, we assume that the potential 17th palindrome of $w$ is \texttt{0120210}.
We say that a ternary word (finite or infinite) is 17-better if it is 17-good and every palindrome it contains is a factor of \texttt{0120210}, \texttt{01210}, \texttt{02120}, \texttt{10201}, \texttt{20102}, or \texttt{21012}.
Thus $w$ is 17-better. We construct the set $S_{17}^{21}$ defined as follows:
a word $v$ is in $S_{17}^{21}$ if and only if there exists a 17-better word $pvs$ such that $|p|=|v|=|s|=21$.
Then we construct the Rauzy graph $G_{17}^{21}$ based on $S_{17}^{21}$.
Since $w$ is recurrent, $w$ lives in a strongly connected component of $G_{17}^{21}$.
We have checked that the graph induced by the strongly connected components of $G_{17}^{21}$
is isomorphic to $G_{16}^{21}$.
Similarly, this shows that $w$ has the same factor set as either
$\gamma(\eta^\omega(\texttt{0}))$ or $\gamma(\eta^\omega(\texttt{0}))^R$.

% The critical exponent $\eta^\omega(\texttt{0})$ is $\tfrac{37}{20}=1.85$ ($\tfrac{111}{60}$).
% Whereas $\tfrac{41}{22}=1.8636363..$
\end{proof}


