\title{Resolving the singularities of splitting loci} %Singularities of splitting loci %Resolving the singularities of splitting loci}
\author{Feiyang Lin}


\begin{document}

\begin{abstract}
We construct modular resolutions of singularities for splitting loci, and use them to show that tame splitting loci have rational singularities. As a corollary of our results and Hurwitz-Brill-Noether theory, we prove that if $C$ is a general $k$-gonal curve, the components of $W^r_d(C)$ have rational singularities. We also recover the classical Gieseker-Petri theorem. Along the way, we prove a cohomology vanishing statement for certain tautological vector bundles on $\Quott$, which may be of independent interest.
\end{abstract}


\maketitle

\tableofcontents

\section{Introduction} 
A vector bundle on a scheme $B \times \bP^1$ leads to a stratification of the base $B$ according to how the vector bundle splits when it is restricted to each fiber. The strata that arise are called splitting loci. The aim of this paper is to produce a modular resolution of singularities for these strata and use the resolution to study the singularities of splitting loci in the case of the universal family. 

Let $\vbst$ be the moduli stack of rank $r$, degree $d$ vector bundles on $\bP^1$. The data of how a vector bundle of rank $r$ and degree $d$ splits is captured by a splitting type $\vec{e} = (e_1, \dots, e_r)$, where $e_1 \leq e_2 \leq \cdots \leq e_r$ and $\sum_{i=1}^r e_i = d$. We define $\SplittOpen$ to be the locally closed substack in $\vbst$ parametrizing families of vector bundles each with splitting type $\vec{e}$, and define $\Splitt$ as the closure of $\SplittOpen$ in $\vbst$. For convenience, we write $\cO(\vec{e}) \coloneq \cO(e_1) \oplus \cdots \oplus \cO(e_r)$.

\begin{definition}
A splitting type $\vec{e} = (e_1, \dots, e_r)$ is balanced if $|e_r - e_1| \leq 1$, or equivalently if $h^1 \cEnd(\cO(\vec{e})) = 0$. If there exists some $1 \leq k \leq r$ such that $\vec{f} = (e_1, \dots, e_k)$ and $\vec{g} = (e_{k+1}, \dots, e_r)$ are both balanced, then  we say that the splitting type $\vec{e}$ is tame.
\end{definition}

For example, all rank two splitting types are tame. $(1,2,5,6)$ is tame, but $(0,2,4)$ is not. Recall that a scheme $X$ has rational singularities if there exists a resolution of singularities $\rho: \nye{X} \to X$ such that $R^{> 0} \rho_* \cO_{\nye{X}} = 0$ and the natural map $\cO_X \to \rho_* \cO_{\nye{X}}$ is an isomorphism. One checks that having rational singularities is a smooth-local property, in the sense of \cite[\href{https://stacks.math.columbia.edu/tag/0348}{Tag 0348}]{stacks-project}. So it makes sense to say that an algebraic stack has rational singularities.

Our main theorem is the following.
\begin{theorem} \label{thm:rational} Let $k$ be an algebraically closed field of characteristic $0$. Over $\Spec k$, for tame splitting types $\vec{e}$, $\Splitt$ has rational singularities.
\end{theorem}

Combined with Hurwitz-Brill-Noether theory \cite{Larson2021}, \cite{LLV}, our result implies the following corollary.
\begin{corollary} Let $C$ be a general $k$-gonal curve. Then components of $W^r_d(C)$ have rational singularities.
\end{corollary}
\begin{proof}
\cite{Larson2021} proves that for a general degree $k$ cover $f: C \to \bP^1$, the morphism $\Pic_d(C) \to \cB_{k, d-g+1-k}$ induced by pushing forward line bundles along $f$ is smooth. The same paper plus the work of \cite{Coppens2025} prove that the components of $W^r_d(C)$ correspond to the maximal splitting types with at least $r+1$ sections, which are tame.
\end{proof}

The construction of a modular resolution of singularities for $\Splitt$ is essential to the proof of Theorem \ref{thm:rational}. To describe the resolution, for $\ur = (r_1, \dots, r_m), \ud = (d_1, \dots, d_m)$, let us define the hyper-Quot stack
$\FQuot(\vbst, \cE_{\univ}; \ur, \ud) \to \vbst$ to be the algebraic stack representing the following functor: 
\begin{align*}
  \left (T \to \Spec k \right ) 
  & \mapsto 
  \left \{
    \begin{tabular}{lll}
      \text{A vector bundle $\cE$ of rank $r$ and fiberwise degree $d$  } \\
      \text{and a flag of subsheaves $\cE_1 \hookrightarrow \cE_2 \hookrightarrow \dots \hookrightarrow \cE_{m+1} = \cE$ on $T \times \bP^1$ } \\
      \text{such that $\cE_{i}$ is locally free of rank $r-r_i$ and fiberwise} \\
      \text{degree $d-d_i$, and each quotient $\cE/\cE_i$ is flat over $T$}
    \end{tabular}
  \right\} / \sim. 
\end{align*}

\begin{theorem} 
\label{thm:smooth1}
Let $E = \cO(\vec{e})$ be a vector bundle on $\bP^1$, and let 
\[
  E_1 \subset E_2 \subset \cdots \subset E_{m+1} = E
\]
be a sequence of subbundles such that for all $1 \leq i \leq m$, each quotient sheaf $E_{i+1}/E_i$ is a nonzero balanced vector bundle, and up to automorphisms of $E_i$, the inclusion $E_i \subset E_{i+1}$ is the unique injective map $E_i \hookrightarrow E_{i+1}$. Let $\ur = (r_1, \dots, r_m), \ud = (d_1, \dots, d_m)$ be the ranks and degrees of $E/E_i$. Then $\FQuot(\vbst,\cE_{\univ}; \ur, \ud)$ is a smooth and irreducible algebraic stack proper over $\vbst$. It maps surjectively onto $\Splitt$ and it is an isomorphism over the dense open $\SplittOpen$.
\end{theorem}
Note that the Harder-Narasimhan flag of subbundles of $\cO(\vec{e})$ always satisfies the conditions of Theorem \ref{thm:smooth1}, but for any given $\vec{e}$, there may be more than one choice (see Example \ref{ex:e-admissible-sets}). 

Combined with Hurwitz-Brill-Noether theory, Theorem \ref{thm:smooth1} recovers the classical Gieseker-Petri theorem.

\begin{corollary}[Gieseker-Petri] Let $C$ be a general curve of genus $g$. Then $G^r_d(C)$ is smooth. 
\end{corollary}
\begin{proof}
Let $k$ be sufficiently large and let $f: C \to \bP^1$ be a general cover of degree $k$ and genus $g$. Then by Hurwitz-Brill-Noether theory, $W^r_d(C) = W^{\vec{e}_{\max, r}}(C)$, where \[\vec{e}_{\max, r} = ((-2)^{g-d+r}, (-1)^{k-g+d-2r-1}, 0^{r+1}),\] and exponents mean repeated entry. Moreover, for any line bundle $L \in W^r_d(C)$, we know that $f_* L = \cO(\vec{e})$, where 
\[\vec{e} = ((-2)^{h^1(L)}, (-1)^{k-h^1(L)-h^0(L)}, 0^{h^0(L)}),\] and $h^0(L) \geq r+1$. So to give an $(r+1)$-dimensional subspace $V \subseteq H^0(C, L)$ is the same as giving an inclusion $\cO^{\oplus (r+1)} \hookrightarrow f_*L$. Therefore, the relative Quot construction corresponding to the one-step inclusion
$
  \cO^{\oplus (r+1)} \subseteq \cO(\vec{e}_{\max, r}),
$
when base-changed to $\Pic_d(C)$, is precisely $G^r_d(C)$. Hence Theorem \ref{thm:smooth1} implies that $G^r_d(C)$ is smooth.
\end{proof}


Tame splitting loci admit a resolution of singularities by a relative Quot construction, and do not require a hyper-Quot construction, which is necessary in general. To show that the higher derived pushforward of the structure sheaf vanishes (and thus $\Splitt$ has rational singularities), we embed this resolution inside a fiber bundle of Quot schemes $\Quott$, where it is cut out by the section of a vector bundle. This reduces the vanishing of higher pushforwards to a cohomology vanishing statement for certain tautological bundles on $\Quott$. While this approach parallels the classical proof that determinantal varieties have rational singularities, the lack of a Borel-Weil-Bott type statement for $\Quot$ schemes presents substantial challenges at this step. To access the desired cohomology vanishing statement, we appeal to Str{\o}mme's embedding of Quot schemes on $\bP^1$ into a product of Grassmannians and further reduce the problem to a cohomology vanishing statement for certain tautological vector bundles on a product of Grassmannians. The desired statement then follows from an application of Borel-Weil-Bott and an involved combinatorial analysis.

Quot schemes on $\bP^1$ were first systematically studied by Str{\o}mme \cite{Stromme1987}, where they showed that $\Quott$ is a nonsingular, irreducible, projective, rational variety. More recently, motivated by analogies to the Hilbert scheme of points on a surface and computations of the quantum cohomology of the Grassmannian, there has been a lot of research towards understanding the cohomology of tautological bundles on Quot schemes on curves, such as \cite{Oprea_Sinha_2022}, \cite{Marian_Oprea_Sam_2023}, \cite{Marian_Negut_2024}, \cite{Sinha_Zhang_2024}. However, most results in the literature focus on punctual Quot schemes (the case where $r = 0$), whereas our result applies to Quot schemes parametrizing higher rank quotients. 

Here is the cohomology vanishing theorem we prove. Let $d > 0$ and $N \geq r \geq 0$. Let $\cQ$ be the universal quotient on $\Quott \times \bP^1$, and let $p: \Quott \times \bP^1 \to \Quott$ be the projection to the first factor. Then for $m \geq -1$, $p_* \cQ(m)$ is a vector bundle on $\Quott$. Let $\cE_m = (p_* \cQ(m))^{\vee}$. Given a partition $\lambda$, we write $\bfS_{\lambda}$ to denote the Schur functor associated to $\lambda$. When $\lambda = (1^k)$, $\bfS_{\lambda} \cE = \wedge^k \cE$; and when $\lambda = (k)$, $\bfS_{\lambda} \cE = \text{Sym}^k \cE$.

\begin{theorem} \label{thm:general_vanishing}
Let $m \geq -1$ be an integer. Let $\lambda_{-1}, \lambda_0, \lambda_1, \dots, \lambda_m$ be partitions, at least one of which is nonempty. Let $D = |\lambda_{-1}| + \cdots + |\lambda_m|$. Then 
\[
  H^{> D}(\Quott, 
  \otimes_{i = -1}^m \bfS_{\lambda_i} \cE_i) = 0.
\]
\end{theorem}

