\begin{remark}
	\begin{enumerate}
		\item 
		In the context of 3-dimensional defect TQFTs, orbifold data~$\mathbb A$ as above can be used to label the Poincar\'e duals of oriented triangulations of 3-manifolds: $(a,\phi)$ then labels 3-strata, $(A,\psi)$ labels 2-strata, $T$ labels 1-strata, and $\alpha,\overline{\alpha}$ label positively/negatively oriented 0-strata. 
		As explained in \cite{Carqueville2017}, the defining conditions of orbifold data in Figure~\ref{fig:OrbifoldDatumAxioms} ensure independence of the choice of triangulation in the construction. 
		In the special cases relevant for our applications in subsequent sections, $(A,\psi)$ turns out to be a separable symmetric Frobenius algebra as in \Cref{subsubsec:2dOrbDat}. 
		\item 
		Just like every 2-dimensional orbifold datum is in particular an associative algebra in its ambient 2-category, every 3-dimensional orbifold datum~$\mathbb{A}$ is in particular a (weakly) associative algebra in its ambient 3-category. 
		Indeed, it follows from the conditions~\eqref{eq:O2} and~\eqref{eq:O3} that $\alpha,\overline\alpha$ are invertible, and hence the ``multiplication''~$T$ is weakly associative. 
		Moreover, condition~\eqref{eq:O1} says that~$\alpha$ and~$\overline{\alpha}$ satisfy the pentagon identity up to the isomorphism~$\psi^2$. 
	\end{enumerate}
\end{remark}

\begin{example}
	\label{exa:3dOrbifoldData}
	Let~$\mathcal C$ be a ribbon category, and let~$\mathcal D_{\mathcal C}$ be the Gray category with duals as in \Cref{exa:3dCategoriesWithAdjoints}. 
	As shown in \cite[Sect.\,3.2]{Carqueville2017} and \cite[Sect.\,5.2]{Mulevicius2022a}, an orbifold datum~$\mathbb A$ in~$\mathcal D_{\mathcal C}$ is equivalently described by
	\begin{itemize}
		\item 
		a separable symmetric Frobenius algebra $(A,\psi)$ in~$\mathcal C$, 
		\item 
		an $(A,A\otimes A)$-bimodule~$T$ in~$\mathcal C$, 
		\item 
		$(A,A\otimes A\otimes A)$-bimodule morphisms $\alpha\colon T\otimes_2 T \to T\otimes_1 T$ and $\overline\alpha\colon T\otimes_1 T\to T\otimes_2 T$, 
		\item 
		an invertible scalar $\phi \in \C^\times$, 
	\end{itemize}
	subject to the relations in Figure~\ref{fig:OrbifoldDatumAxiomsInDC}. 
