\subsection{1-form Symmetries}
\label{sec:1-form specialisation}

We now consider the other edge case where in a crossed module $(G,H,t,\phi)$ all of $G,t,\phi$ are trivial, and we are left only with the group~$H$. 
Due to~\eqref{eq:Peiffer identity}, $H$ is necessarily commutative. 
Put differently, we consider a pure \textsl{1-form symmetry} based on~$H$. 
The functor \eqref{eq:3d 2-group symmetry} then takes the form 
\begin{equation}
	R\colon \mathrm{B}^2\underline{H}\longrightarrow \mathcal{D}\,.
\end{equation} 
For the pivotal braided category of $2$-endomorphisms of $R(\id_\ast)$ we write  
\begin{equation}
	\mathcal{C} := \textrm{End}_{\mathcal D}\big(R(\id_*)\big) 
\end{equation} 
where~$*$ is the unique object in $\mathrm{B}^2\underline{H}$. 
The category~$\mathcal C$ inherits its pivotal braided monoidal structure from~$\mathcal D$ (cf.\ \cite[Lem.\,2.18]{Barrett2012}), while~$\underline{H}$ is naturally equipped with such a structure because~$H$ is commutative. 
Using this, one finds that (up to strictification)~$R$ descends to and is equivalently described by a braided monoidal functor 
\begin{equation}
	\label{eq:Ras1functor}
	\overline{R}\colon \underline{H} \longrightarrow \mathcal{C} \, .
\end{equation}

In this section, we construct a new orbifold datum $\mathbb{A}_{A_{\overline{R}}}$ from the functor~$\overline{R}$ using methods similar to those of \Cref{subsec:GeneralCase} and \cite{Carqueville2020}. 
We show in \Cref{prop:Orbifold datum from 1form symmetry as composite} that the construction reproduces the orbifold datum~$\mathbb{A}_R$ from the general construction in \Cref{prop:2group orbifold datum}.
The new presentation of the orbifold datum allows for various new tools in calculating orbifold data, such as \Cref{prop:orbifold data for compositions of functors}.

\medskip 

\begin{proposition}[label=prop:FrobeniusAlgebra from 1form symmetry]
	Given a braided monoidal functor $\overline{R}\colon \underline{H}\longrightarrow \mathcal{C}$, we set
	\begin{gather}
	\begin{alignat}{2}
		A_{\overline{R}}&:= \;\,\bigoplus_{h\in H}\;\, \overline{R}(h)\,,&&
		\\
		\mu&:=\bigoplus_{h,h^\prime\in H}\overline{R}^2_{h,h^\prime} \colon & &A_{\overline{R}}\otimes A_{\overline{R}}\longrightarrow A_{\overline{R}}\,,
		\\
		\Delta&:=\bigoplus_{h,h^\prime\in H}\frac{1}{|H|}\Big(\overline{R}^2_{h,h^\prime}\Big)^{-1}\!\colon  &&A_{\overline{R}}\longrightarrow A_{\overline{R}}\otimes A_{\overline{R}}\,,
		\\
		\eta&:=\mathrm{incl}_{\overline{R}(e)}\circ \overline{R}^0\colon &&\mathds{1}\longrightarrow \overline{R}(e)\longrightarrow A_{\overline{R}}\,,
		\\
		\varepsilon&:=|H| \cdot (\overline{R}^0)^{-1}\circ \pr_{\overline{R}(e)}\colon &&A_{\overline{R}}\longrightarrow \overline{R}(e)\longrightarrow\mathds{1}\,.
	\end{alignat}
	\end{gather}
	Then $(A_{\overline{R}},\mu,\Delta,\eta,\varepsilon)$ is a commutative $\Delta$-separable Frobenius algebra. 
	If~$\overline{R}$ is pivotal, then~$A_{\overline{R}}$ is symmetric.
\end{proposition}

\begin{proof}
	With the exception of commutativity, the proof is the same as that of \Cref{lem:Frobenius algebra structure on AH}.
	To show commutativity, we note that the braiding on~$\underline{H}$ is trivial since~$H$ is commutative. 
	Therefore, since~$\overline{R}$ is braided, the braiding on $A_{\overline{R}}\otimes A_{\overline{R}}$ (in~$\mathcal{C}$) is given by 
	\begin{equation}
		\label{eq:braiding on A}
		c_{A_{\overline{R}},A_{\overline{R}}}=\bigoplus _{h,h^\prime\in H}\Big(\overline{R}^2_{h,h^\prime}\Big)^{-1}\circ \overline{R}^2_{h^\prime,h}\,. 
	\end{equation}
	Note that this is different from $\Delta\circ\mu$ which includes additional terms $(\overline{R}^2_{h_1,h_1^\prime})^{-1} \circ \overline{R}^2_{h_2^\prime,h_2}$ for any two pairs of group elements satisfying $h_1h_1^\prime=h_2 h^\prime_2$. 
	When we compose $c_{A_{\overline{R}},A_{\overline{R}}}$ with~$\mu$, terms cancel in such a way that the result is again~$\mu$. 
	Hence~$A_{\overline{R}}$ is commutative.
\end{proof}

Recall the 3-category~$\mathcal D_{\mathcal C}$ that we associated to a ribbon category~$\mathcal C$ in \Cref{exa:3dCategoriesWithAdjoints}. 
Every commutative $\Delta$-separable symmetric Frobenius algebra in~$\mathcal C$ can be turned into an orbifold datum: 

\begin{proposition}[name={\cite[Prop.~3.15]{Carqueville2020}}, label=prop:orbifold datum from Frobenius algebra] 
	Let~$\mathcal{C}$ be a braided fusion category and let $(A,\mu,\Delta,\eta,\varepsilon)$ be a commutative $\Delta$-separable symmetric Frobenius algebra in~$\mathcal{C}$. 
	Then 
	\begin{equation}
	\label{eq:orbdat from cssFrob}
		\mathbb{A}_A 
			:=
			\big(\mathcal{C}, \, A, \, T=A, \, \alpha=\overline{\alpha}=\Delta\circ\mu, \,  \psi=\eta, \, \phi=1\big)
	\end{equation}
	is a (special) orbifold datum in~$\mathcal{D}_\mathcal{C}$, where the $(A,A\otimes A)$-bimodule structure of $T$ is given by various applications of $\mu$.
\end{proposition}

Since $\Delta$-separable Frobenius algebras are in particular separable, we have $\mathrm{B}(\mathrm{B} \mathcal C)_\text{orb}\subset D_{\mathcal C}$. 
We want to generalise \Cref{prop:orbifold datum from Frobenius algebra} to any 3-category which is equivalent to a Gray category with duals, using the category of 2-endomorphisms of the identity 1-morphism on some object~$a$ as~$\mathcal{C}$, i.e.\ $\mathcal{C}=\End_\mathcal{D}(\id_a)$. 
In this setting, we have (recall the discussion around~\eqref{eq:DHomorb})
\begin{equation}
	\mathrm{B}(\mathrm{B} \mathcal{C})_\text{orb}\longhookrightarrow \Homorb{\mathcal D}\,,
\end{equation} 
and thus the orbifold datum constructed in \eqref{eq:orbdat from cssFrob} is an orbifold datum in $\Homorb{\mathcal D}$.

\medskip

\begin{proposition}[label=prop:Orbifold datum from 1form symmetry as composite]
	The orbifold datum~$\mathbb{A}_R$ associated to a $1$-form symmetry $R\colon \mathrm{B}^2\underline{H} \longrightarrow \mathcal{D}$ coincides with the one constructed by combining \Cref{prop:FrobeniusAlgebra from 1form symmetry} and \Cref{prop:orbifold datum from Frobenius algebra},
	\begin{equation}
		\mathbb{A}_R=\mathbb{A}_{A_{\overline{R}}}\,.
	\end{equation}
	In particular, if a 1-form symmetry~$R$ has pivotal 2-functor components on $\Hom$ 2-categories, then \Cref{prop:2group orbifold datum} yields an orbifold datum (and not just an algebra).
\end{proposition}

\begin{proof}
	We assume that $R=(R,\chi,\iota,\omega,\gamma,\delta)$ is sufficiently strictified, such that $R(\id_\ast)=\id_{R(\ast)}$, and the unital data $\iota,\gamma,\delta$ from \Cref{subsubsec:3cats} are identities. 
	Then the 2-morphism components of~$\chi$ are given by unitors in~$\mathcal{D}_\mathcal{C}$. 
	From the fact that $\overline{R}{}^2=R^2$ and $\overline{R}{}^0=R^0$ where applicable, it follows that the algebras~$A_{\overline{R}}$ from \Cref{prop:FrobeniusAlgebra from 1form symmetry} and~$A_H$ defined in~\eqref{eq:1-morphism of general 2group orb dat} and~\eqref{eq:Frob structure on AH} are identical.

	Next we show that the orbifold datum of \Cref{prop:2group orbifold datum} reduces to the one built from~$A_H$ via \Cref{prop:orbifold datum from Frobenius algebra}.
	To this end, we can identify $\boxtimes$-products and $\otimes$-products between $2$-morphisms in $\End_{\mathcal D_{\mathcal C}}(\id_a)$ by an Eckmann--Hilton argument. 
	More precisely, we have a 3-isomorphism
	\begin{equation}
		r_{\id_a}\otimes (f\boxtimes g)\cong (f\otimes g)\otimes r_{\id_a}\,,
	\end{equation}
	given by unitors and the coherence morphism $\boxtimes^2$. 
	In a Gray category, the right unitors in this equation are identities and the 3-isomorphism reduces to the tensorator. 
	Under this identification, we can show that the 3-morphism components of~$\chi$ are given by~$R^2$, by starting with~\eqref{eq:naturality and unitality of chi} and applying invertibility of~$R^2$. 
	Using these identifications, it follows that $T=A_H=A_{\overline{R}}$ as objects and the module structure on~$T$ is given by the multiplication~$\mu$ on~$A_H$. 
	Therefore, the identity also holds on the level of modules. 
	Similarly, the bimodule morphisms~$\alpha$ and~$\overline{\alpha}$ of~\eqref{eq:3-morphism of general 2group orb dat} reduce to $\Delta\circ \mu$ by the (co)unitality axioms of $A_H$.
\end{proof}

\medskip

Recall from \cite[Def.\,5.12]{Mulevicius2022a} the notion of transport of an orbifold datum~$\mathbb{A}$ in a Gray category with duals of the type~$\mathcal{D}_{\mathcal{C}_1}$ along a braided strong monoidal functor~$F\colon\mathcal{C}_1\longrightarrow\mathcal{C}_2$. 
This produces an orbifold datum $F(\mathbb{A})$ in~$\mathcal{D}_{\mathcal{C}_2}$, given by
\begin{equation}
\label{eq:orbifold transport in DC}
 	F(\mathbb{A}):= \big(F(A),F(T),\alpha_F,\overline{\alpha}_F, \psi_F,\phi_F\big)
\end{equation}
where $F(A)$ is given by \eqref{eq:Frobenius transport}, $F(T)$ is similarly given by the underlying object with module structure composed with (the sum over)~$F^2$, and~$\alpha$ and~$\overline{\alpha}$ are also composed with~$F^2$ and its inverse. 
There is an additional assumption of compatibility between~$F$ and~$\mathbb{A}$ which ensures that suitable~$\psi_F$ and~$\phi_F$ exist, see \cite[Def.\,5.10]{Mulevicius2022a} for details.

As with \Cref{prop:orbifold datum from Frobenius algebra}, there is a direct generalisation of this construction to the setting of the present section. 
Orbifold data from 1-form symmetries are compatible with transport along such functors in the following sense.

\begin{proposition}[label=prop:orbifold data for compositions of functors]
	Let $\overline{R}\colon \underline{H}\to\mathcal{C}$ and $F\colon\mathcal{C}\to\mathcal C'$ be ribbon functors.
	\begin{enumerate}
	\item
	Given any commutative $\Delta$-separable symmetric Frobenius algebra~$A$ in~$\mathcal{C}$, the transport of the associated orbifold datum \eqref{eq:orbdat from cssFrob} (with $\psi_F=\eta_F$ and $\phi_F=1$) is the orbifold datum associated to $F(A)$:
	\begin{equation}
		F(\mathbb{A}_A)=\mathbb{A}_{F(A)}.
	\end{equation}
	\item 
	The orbifold data associated to 1-form symmetries~$\overline{R}$ and $F\circ \overline{R}$ are related by transport along~$F$:
	\begin{equation}
		F(\mathbb{A}_{A_{\overline{R}}})=\mathbb{A}_{F(A_{\overline{R}})}=\mathbb{A}_{A_{F\circ \overline{R}}}\,.
	\end{equation}
	\end{enumerate}
\end{proposition}

\begin{proof}
	The first statement is obvious by comparing definitions \eqref{eq:Frobenius transport}, \eqref{eq:orbifold transport in DC}, and \Cref{prop:orbifold datum from Frobenius algebra}: the underlying algebra is the same by definition, the module structure of $F(T)=F(A)$ is given by $F(\mu)\circ F^2_{A,A}$ in both cases, and similarly $\alpha_F=\Delta_F\circ\mu_F$. 
	The second statement then follows from the observation that $F(A_{\overline{R}})=A_{F\circ \overline{R}}$ which follows from unravelling the definition of composition of monoidal functors.
\end{proof}


\section{Symmetries from $\boldsymbol{G}$-crossed Braided Fusion Categories}
\label{sec:SymmetriesFromGCrossedBraidedCategories}

In this section we discuss a specific class of categories (of line defects) where we can gauge a finite group-like symmetry. 
To this end, we consider $G$-crossed braided fusion categories which in particular carry a $G$-action for some finite group~$G$.
We gauge this $G$-action in two ways: 
On the one hand, given a $G$-crossed braided fusion category we can directly apply the standard equivariantisation construction (which we recall in \Cref{sec:General theory of (De)Equivariantisation}), while on the other hand we can also produce a 3-functor (a $G$-symmetry) and its associated orbifold datum from it (\Cref{sec:equivariantisation is orbifolding}) via the methods of Section~\ref{sec:0-form specialisation}. 
The latter recovers the orbifold datum of \cite[Thm.\,5.1]{Carqueville2020}.
In \Cref{sec:equivalence of equivariantisation and orbifolding} we prove that both paths lead to equivalent results. 

\Cref{sec:Deeq is 1-form orbifolding} is dedicated to undoing the gauging of the $G$-symmetry by gauging an emergent dual symmetry. 
This is called de-equivariantisation, and can also be understood as gauging a $1$-form symmetry. 
When~$G$ is non-commutative, this symmetry is non-invertible and thus falls outside our previous discussion. 
However, we identify an orbifold datum that achieves the de-equivariantisation in either case, leading to a clear and general picture. 


\subsection{Equivariantisation and De-equivariantisation}
\label{sec:General theory of (De)Equivariantisation}

In this section we review group-like actions on (braided) monoidal categories and the related constructions of equivariantisation and de-equivariantisation. 
Our main application is in terms of $G$-crossed braided fusion categories, for which we also collect the relevant details. 
Our main references for this section are \cite[Sect.\,4]{Drinfeld2009} and \cite[Sect.\,7]{etingof2009fusioncategorieshomotopytheory}. 

\medskip 

Given monoidal categories $V$ and $\mathcal{C}$, recall that an \textsl{action of~$V$ on~$\mathcal{C}$} is a monoidal functor $V\longrightarrow \End^\otimes(\mathcal{C})$ into the category of monoidal endofunctors. 
Equivalently, this is a functor 
\begin{equation}
	\label{eq:module category action}
	V\times \mathcal{C}\longrightarrow\mathcal{C} 
\end{equation}
equipped with additional associativity and unitality coherence isomorphisms, subject to the usual pentagon and triangle conditions, which involve the associators and unitors of both the action as well as those in~$V$; see e.g.\ \cite{Ostrik2006} for details.

A special case is a \textsl{$G$-action on a monoidal category~$\mathcal C$} for some group~$G$, by which we mean a monoidal functor\footnote{By the superscript ``rev'' we indicate the reversal of the monoidal product. This means that we use right $G$-actions in accordance with \cite[Sect.\,5]{Carqueville2020}.}
\begin{equation}
	\rho\colon \underline{G}^\text{rev}\longrightarrow \Aut^{\otimes}(\mathcal{C}) \, . 
\end{equation}
Here~$\underline{G}$ denotes the monoidal category whose objects are group elements $g\in G$, the tensor product is group multiplication, and~$\underline{G}$ has only identity morphisms. The codomain $\Aut^{\otimes}(\mathcal{C})$ is the category of monoidal autoequivalences.
For every $g\in G$, we abbreviate $\rho_g := \rho(g)$ and we denote its monoidal structure isomorphisms as
\begin{equation}
	\rho_g^2\colon\! \otimes\circ\, (\rho_g\times\rho_g) \Longrightarrow \rho_g\circ \otimes
		\, , \quad 
	\rho^0_g\colon \mathds{1}\longrightarrow \rho_g(\mathds{1}) \, .
\end{equation}
Since~$\rho$ itself is also monoidal, it also comes with structure isomorphisms given by invertible natural transformations 
\begin{equation}
	\rho^2\colon \rho_{(-)} \circ \rho_{(-)} \Longrightarrow\rho_{(-)\cdot(-)}
		\, , \quad 
	\rho^0\colon \id_\mathcal{C}\Longrightarrow \rho_e \, ,
\end{equation}
where~$\rho^0$ is monoidal and~$\rho^2$ has components which are themselves monoidal natural transformations, 
\begin{equation}
	\rho^2_{g,h}\colon \rho_g\circ\rho_h\Longrightarrow\rho_{hg} \, .
\end{equation}
Note that all of (the component morphisms of) these natural transformations can be distinguished by their sub- and superscripts.

From now on we assume that the group~$G$ is finite. 

\begin{definition}[label=def:equivariantisation]
	Let~$\mathcal{C}$ be a fusion category, and let $\rho\colon \underline{G}^\text{rev}\longrightarrow \Aut^\otimes(\mathcal{C})$ be a monoidal functor.
	\begin{enumerate}
		\item 
		A \textsl{$G$-equivariant object} in~$\mathcal{C}$ is a pair $(X, u:= \lbrace u_g\rbrace_{g\in G})$ with $X \in \mathcal{C}$ and a family of isomorphisms 
		\begin{equation}
			u_g\colon \rho_g(X)\stackrel{\cong}{\longrightarrow} X
		\end{equation}
		such that 
		%$u_g\circ\rho_g(u_h)=u_{hg}\circ(\rho^2_{g,h})_X$, i.e.\ 
		the following diagram commutes:
		\begin{equation}
		\label{eq:defining property of equivariant structure}
			\begin{tikzcd}[column sep= 40,row sep= 30, ampersand replacement=\&]
			\rho_g(\rho_h(X))
			\arrow[d, "{(\rho^2_{g,h})_X}"{left}]
			\arrow[r, "{\rho_g(u_h)}"]
			\& \rho_g(X)
			\arrow[d, "{u_g}"]\\
			\rho_{hg}(X)
			\arrow[r, "u_{hg}"{below}]
			\& X			
			\end{tikzcd}
		\end{equation}
		\item 
		The \textsl{equivariantisation} of~$\mathcal{C}$ (with respect to~$\rho$) is the category~$\mathcal{C}^G$ whose objects are $G$-equivariant objects in $\mathcal{C}$ and whose morphisms $(X,u)\longrightarrow (Y,v)$ are morphisms $f\colon X\longrightarrow Y$ in~$\mathcal{C}$ such that
		\begin{equation}
		\label{eq:defining property of morphisms in equivariantisation}
		\begin{tikzcd}[column sep= 40,row sep= 30, ampersand replacement=\&]
			\rho_g(X)
			\arrow[d, "{u_g}"{left}]
			\arrow[r, "{\rho_g(f)}"]
			\& \rho_g(Y)
			\arrow[d, "{v_g}"]\\
			X
			\arrow[r, "f"{below}]
			\& Y
		\end{tikzcd} 
		\end{equation}
		commutes for all $g\in G$. 
	\end{enumerate}
\end{definition}

Note that the above definition of~$\mathcal C^G$ as a mere category does not use the fact that~$G$ acts through \textsl{monoidal} automorphisms $(\rho_g,\rho_g^2,\rho_g^0)$. 
However, we can use this additional structure to give a monoidal structure on the equivariantisation $\mathcal{C}^G$. 
For further details see e.g.\ \cite[Sect.\,4]{Drinfeld2009} or \cite[App.\,5]{Turaev2010}:

\begin{lemma}
	The equivariantisation~$\mathcal{C}^G$ has a monoidal structure with $(X,u)\otimes (Y,v):=(X\otimes Y, w)$, where
	\begin{equation}
		w_g := \Big( \!
		\begin{tikzcd}[column sep= 40,row sep= 30, ampersand replacement=\&]
			\rho_g(X\otimes Y)
			\arrow[r, "(\rho_g^2)^{-1}_{X,Y}"]
			\& 
			\rho_g(X)\otimes\rho_g(Y)
			\arrow[r, "u_g\otimes v_g"]
			\&
			X\otimes Y 
		\end{tikzcd} 
		\!\Big) , 
	\end{equation}
	and the monoidal unit is $(\mathds{1},\lbrace (\rho^0_g)^{-1}\colon \rho_g(\mathds{1})\longrightarrow \mathds{1}\rbrace_{g\in G})$.
\end{lemma} 

We briefly pause to outline the interpretation of~$\mathcal C^G$, how it fits into the structure of the remainder of this paper, and how it connects with our motivation from topological quantum field theory. 
In the context of Reshetikhin--Turaev theory, the underlying category~$\mathcal{C}$ is interpreted as the category of line defects. 
While local operators in the gauged theory have to be invariant under the $G$-action, line defects may have non-trivial junctions between them. 
Therefore, instead of demanding $\rho_g(X)=X$ for a line operator $X\in\mathcal{C}$, we can impose $\rho_g(X)\cong X$ and choose a set of such isomorphisms (junctions) compatible with group multiplication.
Hence, the equivariantisation is the category of line defects in the gauged theory. 
One should also include twisted sectors, which we do in \Cref{def:G-crossed braided category}.
Assuming $\rho_g(\mathds{1})=\mathds{1}$ and $\rho^0_g=\id_\mathds{1}$ for the moment, we also recover the invariant local operators as endomorphisms of the ``transparent'' line defect $\mathds{1}$, i.e.\ $(\End_\mathcal{C}(\mathds{1}))^G=\End_{\mathcal{C}^G}(\mathds{1},\id_\mathds{1})$.
The physics literature then provides arguments that this new theory features ``Wilson lines'' that implement a potentially non-invertible symmetry, see e.g.\ \cite{Gaiotto_2015, furlan2024finitegroupglobalgauged}, and whose gauging undoes the gauging of the 0-form symmetry~$R$.
We turn to describe it as a $\Rep(G)$-action on~$\mathcal C^G$, and we will discuss its gauging in \Cref{sec:Deeq is 1-form orbifolding}. 

\medskip 

We start by noting that if we equip $\Vect$ with the trivial $G$-action, then its equivariantisation is simply the category of finite-dimensional $G$-representations, $\Vect^G = \Rep(G)$. 
Next, observe that any fusion category~$\mathcal C$ has an action \eqref{eq:module category action} of $\Vect$, where for a vector space~$V$ and an object $X\in \mathcal C$, the object $V\otimes X \in \mathcal C$ is the one which represents the functor $V\otimes_\C \Hom_\mathcal{C}(X,-)$, and we take tensor products on morphisms.
A choice of basis in~$V$ induces the identification $V\otimes X\cong X^{\oplus \mathrm{dim}(V)}$. If we restrict to the action on the unit object in~$\mathcal{C}$, this induces an inclusion $\Vect\longrightarrow \mathcal{C}$ as a subcategory (which is full if the unit object is simple). We can equivariantise this action to obtain the functor 
\begin{align}
	\Rep(G)\times \mathcal{C}^G &\longrightarrow \mathcal{C}^G
	\nonumber 
	\\
	\big((V,\phi),(X,u)\big)&\longmapsto \big(V\otimes X, \lbrace \phi(g)\otimes u_g\rbrace_{g\in G}\big) \,,
	\label{eq:RepGCGCG}
\end{align}
which describes precisely a $\Rep(G)$-symmetry. Here, $(V,\phi)$ denotes a representation with underlying vector space~$V$ and right $G$-action $\phi\colon G^\text{rev}\longrightarrow \Aut(V)$.

By restricting the functor~\eqref{eq:RepGCGCG} to the unit in the second argument, we obtain  an inclusion 
\begin{align}
	\label{def:inclusion of RepG}
	I\colon \Rep(G)\longrightarrow \mathcal{C}^G
\end{align}
of $\Rep(G)$ into~$\mathcal C^G$ as a full monoidal subcategory.
This functor allows us to undo the equivariantisation, as we recall in~\eqref{eq:eq-deeq equivalence} below. 
For this, first note that the $\C$-algebra $\C(G)$ of functions on~$G$ can be naturally lifted to an algebra in $\Rep(G)$ through the action 
\begin{equation}
	\label{eq:right action on alg of functions}
	\big(\phi^\textrm{r}_g(f)\big)(h):=f(hg^{-1}) \, ,
\end{equation} 
where $g,h\in G$ and $f\in \C(G)$. Recall that an algebra in $\Rep(G)$ is a $\C$-algebra with $G$-action whose multiplication is $G$-equivariant. 
This holds for $\phi^\textrm{r}$ because 
\begin{equation}
	\phi^\textrm{r}_g(f_1f_2)(h)=(f_1f_2)(hg^{-1})=\phi^\textrm{r}_g(f_1)(h)\phi^\textrm{r}_g(f_2)(h) \, .
\end{equation}

Now let~$\mathcal B$ be a monoidal category, and let $J\colon\Rep(G)\longrightarrow Z(\mathcal{B})$ be a braided monoidal functor. 
Recall that the Drinfeld centre $Z(\mathcal{B})$ is the category whose objects are pairs $(X,\theta)$ consisting of an object $X\in\mathcal B$ and a half-braiding $\theta\colon (-)\otimes X \longrightarrow X \otimes (-)$, and morphisms in~$Z(\mathcal{B})$ are morphisms of the underlying objects compatible with the half-braidings. 
We use the standard symmetric braiding on $\Vect$ and the canonical braiding~$c$ on $Z(\mathcal{B})$, with components $c_{(X,\theta),(X^\prime,\theta^\prime)}=\theta^\prime_X$. 
Then the image of $\C(G)$ is 
\begin{equation}
	(A,\theta) := J(\C(G)) \in Z(\mathcal{B})
\end{equation}
which inherits an algebra structure via transport along~$J$ as described in~\eqref{eq:Frobenius transport}. 
In this setting we have (see \cite[Thm.\,8.23.3]{EGNO2015} and \cite[Sect.\,4.2.4]{Drinfeld2009} for details): 

\begin{definition}
	Let~$\mathcal B$ be a monoidal category, and let $J\colon\Rep(G)\longrightarrow Z(\mathcal{B})$ be a braided monoidal functor. 
	The \textsl{de-equivariantisation} of~$\mathcal B$ (with respect to~$J$) is the category~$\mathcal{B}_G$ of $A$-modules in~$\mathcal B$, 
	\begin{equation}
		\mathcal{B}_G \;:=\; A\text{-}\Mod(\mathcal B) \, . 
	\end{equation}
\end{definition}
We note that there is a monoidal structure on~$\mathcal{B}_G$ which requires the half-braidings~$\theta$, and that the left action of~$G$ on $\C(G)$ induces a right action on~$\mathcal{B}_G$.

\medskip 

Equivariantisation and de-equivariantisation induce equivalences between the 2-categories of monoidal categories~$\mathcal C$ with $G$-action and of \textsl{monoidal categories over $\Rep(G)$}, i.e.\ monoidal categories~$\mathcal B$ equipped with a braided functor $\Rep(G)\longrightarrow {Z}(\mathcal{B})$ as above, see \cite[Prop.\,4.19]{Drinfeld2009}.
In particular, we have
\begin{align}
	\mathcal{C} \cong (\mathcal{C}^G)_G \label{eq:eq-deeq equivalence}
		\, , \quad 
	\mathcal{B} \cong (\mathcal{B}_G)^G
\end{align}
as equivalences in the respective 2-categories. 
On the left-hand side, we used a functor $J\colon \Rep(G)\longrightarrow Z(\mathcal{C}^G)$  extracted from~$I$ in~\eqref{def:inclusion of RepG}. 
The image of~$I$ is essentially direct sums of the monoidal unit, and thus it carries canonical half-braidings via unitors, and the functor is braided.  
Explicitly, the first equivalence in~\eqref{eq:eq-deeq equivalence} is given by
\begin{align}
	\mathcal{C}& \stackrel{\cong}{\longrightarrow} (\mathcal{C}^G)_G 
	\nonumber 
	\\
	X & \longmapsto \mathrm{Ind}(X):=\bigoplus_{g\in G} \rho_g(X)
	\label{eq:eq-deeq-eq}
\end{align}
with an $I(\C(G))$-module structure as follows. 
Choosing the basis $\{\delta_h\}_{h\in G} \subset \C(G)$ of functions supported only on a single element~$h$ (with value~1), we get that 
\begin{equation}
	\C(G)\otimes_\C \mathrm{Ind}(X)
		\cong 
		\bigoplus_{g,h\in G}\C\langle \delta_h\rangle \otimes_\C \rho_g(X)
		\cong 
		\bigoplus_{g,h\in G}\rho_g(X) \, . 
\end{equation}
The module structure is given by the projection onto the diagonal, i.e.\ those summands for which we have $g=h$. 
In other words, we think of a function $f\in\C(G)$ as acting on $\mathrm{Ind}(X)$ by $\bigoplus_{g\in G}f(g)\cdot \id_{\rho_g(X)}$, and so~$\delta_h$ projects out $\rho_h(X)$. 

\medskip 

Our last preparatory step is to enhance the above constructions with braidings, which is required in order to use \Cref{prop:FrobeniusAlgebra from 1form symmetry} in Section~\ref{sec:equivariantisation is orbifolding} below. 
More precisely, what we need is a ``braiding'' that is twisted by the $G$-action (\cite[Sect.\,4.4.3]{Drinfeld2009}): 

