\begin{lemma}
	The ingredients described above assemble into a 3-functor
	\begin{equation}
		\label{eq:0-form symmetry functor}
		R\equiv(R,\chi,\iota,\omega,\gamma, \delta)
			:= 
			\Big( \mathrm{B}\underline{G} 
			\longhookrightarrow 
			\mathcal{G}_{\mathcal{C}^\times_G}
			\stackrel{M_G}{\longrightarrow} 
			\mathcal{D}_{\mathcal{C}_e} \Big) .
	\end{equation}
\end{lemma}

\begin{proof}
	Since the inclusion $\mathrm{B}\underline{G} \longhookrightarrow \mathcal{G}_{\mathcal{C}^\times_G}$ is a strict 3-functor, what has to be checked is that the structure morphisms of~$M_G$ satisfy the coherence axioms of a 3-functor. 
