\begin{lemma}[label=lem:equivariant structure on Y is well-defined]
	The pair $(Y_{G,e}, u^{(Y,\tau)})$ is an equivariant object, i.e.\ an object of $(\Gcbc)^G$.
\end{lemma}

\begin{proof}
	The fact that the right-hand side of \eqref{eq:equivariant structure on preimage} is the inverse of the left-hand side follows from the fact that the coupons labelled by $\gamma$ and its inverse cancel each other, the remaining parts are inverses of each other by the same argument as in the proof of \Cref{lem:gamma is natural}. 

	It remains to check the defining property~\eqref{eq:defining property of equivariant structure} of an equivariant structure, i.e.\ 
	\begin{equation}
		u^{(Y,\tau)}_g\circ\rho_g(u^{(Y,\tau)}_h)=u^{(Y,\tau)}_{hg}\circ(\rho^2_{g,h})_X\,. 
	\end{equation}
	Note that if we insert the string diagram for $\gamma^{\bar{h}gh,e,\bar{h}}_Y$, then the composition $u^{(Y,\tau)}_g\circ\rho_g(u^{(Y,\tau)}_h)$ contains~$\tau_1$ and~$\tau_2$ twice each, in alternating order. 
	We apply the identity \eqref{eq:T2} to swap the order of the two morphisms in the middle, then we use \eqref{eq:T3} on the two~$\tau_2$ at the bottom and \eqref{eq:T1} on the two~$\tau_1$ at the top, leaving us with the desired result containing one copy of each. 
	In doing so, loops with $\psi^2$-insertions have to be added and removed to create the necessary copies of~$\alpha$.
\end{proof}

Using the notation of~\eqref{eq:Ygh}, \eqref{eq:relative tensor products of morphisms in CAR} and~\eqref{eq:YGe}, we have: 

\begin{lemma}
	The following assignment is a functor: 
	\begin{align}
		 E\colon  \mathcal{C}_{\mathbb{A}_R}&\longrightarrow (\mathcal{C}^\times_G)^G
		\nonumber\\
		(Y,\tau_i,\overline{\tau}_i)&\longmapsto \big(Y_{G,e},\, u^{(Y,\tau)}\big)
		\nonumber\\
		\big(f\colon Y\longrightarrow Y^\prime\big) &\longmapsto f_{G,e} :=\bigoplus_{g\in G} f_{g,e} \, . 
	\end{align} 
\end{lemma}

\begin{proof}
	\Cref{lem:equivariant structure on Y is well-defined} states that~$E$ is well-defined on objects. 
	For a morphism $f\colon Y\longrightarrow Y^\prime$ in $\mathcal{C}_{\mathbb{A}_R}$, we have $u^{(Y^\prime,\tau^\prime)}_g\circ \rho_g(f_{G,e})=f_{G,e}\circ u^{(Y,\tau)}_g$. 
	The $G$-crossed naturality of the braiding removes the action~$\rho_g$, and since~$f$ is a morphism in $\mathcal{C}_{\mathbb{A}_R}$, it commutes with~$\tau_2$. 
	Therefore, $f_{G,e}$ is a well-defined morphism in $(\Gcbc)^G$. 
	Clearly, $E$ preserves composition and identity morphisms.
\end{proof}

Lastly, we describe the evaluation and coevaluation morphisms for the adjunction between~$E$ and~$F$.  
Identifying $m_g\otimes_{A_g}m_g^*=\mathds{1}$ as before, we have $ E( F(X,u))=(X,u^{ F(X,u)})$ and similarly on morphisms, $ E( F(f))=f$. 
Hence we define a natural isomorphism $\eta\colon \id_{(\Gcbc)^G}\Longrightarrow  E\circ F$ whose components are morphisms in $(\Gcbc)^G$ whose underlying morphisms in $\Gcbc$ are all identity morphisms. 
To show that these are morphisms $(X,u)\longrightarrow (X,u^{ F(X,u)})$ in $(\Gcbc)^G$, one checks that $u^{ F(X,u)}_g=u_g$ for all $g\in G$.

To show that~$\eta$ is a coevaluation witnessing the adjunction $F \dashv E$, we provide a natural isomorphism $\epsilon\colon F\circ E\Longrightarrow \id_{\mathcal{C}_{\mathbb{A}_{\scaleto{R}{3pt}}}}$ which is the associated evaluation. 
Its components are given by
