\end{proof}

It is now straightforward to arrive at the main result of \Cref{sec:equivalence of equivariantisation and orbifolding}:

\begin{theorem}[label=thm:eq is orbifolding]
	Let~$\mathcal{C}^\times_G$ be a $G$-crossed braided fusion category. 
	There is an equivalence of ribbon categories between the equivariantisation $(\mathcal{C}^\times_G)^G$ and the fusion category~$\mathcal{C}_{\mathbb{A}_R}$ associated to the orbifold datum~$\mathbb{A}_R$ (of \Cref{lem:0form orb dat from Gcbrc}) given by the functor
	\begin{equation}
		 F\colon \left(\mathcal{C}^\times_G\right)^G\stackrel{\cong}{\longrightarrow}\mathcal{C}_{\mathbb{A}_R}
	\end{equation}
	of \Cref{lem:Phi is well-defined}. 
\end{theorem}

To prove \Cref{thm:eq is orbifolding}, it remains to be shown that $\eta$ and $\epsilon$ are indeed isomorphisms and that everything is well-defined. 
Invertibility of $\eta$ is obvious, invertibility of $\epsilon$ follows from invertibility of~$\gamma$, and the inverse is given by the mirror image of \eqref{eq:counit in adjunction} along the horizontal line, replacing~$\gamma$ with its inverse and the module structure with the induced comodule structure.
We shall not add to our previous comments or expand on the proof here, as it involves the same techniques that have been used throughout this section. 
Instead, we prove directly that~$F$ is an equivalence in \Cref{sec:proof of Equivalence}.

\begin{remark}
	Given an adjoint equivalence where one functor is equipped with a (braided) strong monoidal structure, there is a canonical (braided) strong monoidal structure on the adjoint functor \cite[Rem.\,2.4.10]{EGNO2015}, such that the natural transformations involved in the adjunction are monoidal. 
	In our case, this equips~$ E$ with a braided monoidal structure, so we omit its explicit description here. 
	In short, we have
	\begin{align}
		 E^2_{Y,Y^\prime}&:= E(\epsilon_Y\otimes_{A_G}\epsilon_{Y^\prime})\circ  E( F^2_{ E(Y), E(Y^\prime)})^{-1}\circ \eta_{ E(Y)\otimes E(Y^\prime)}\,,
		 \\
		 E^0&:= E( F^0)^{-1}\circ \eta_{\mathds{1}}\,.
	\end{align}
\end{remark}


\subsection{Proof of Equivalence}
\label{sec:proof of Equivalence}

In this section we prove that the functor $F\colon (\mathcal{C}^\times_G)^G \to \mathcal{C}_{\mathbb{A}_R}$ of \Cref{lem:Phi is well-defined} is an equivalence. 
In \Cref{subsec:fullyfaithful} we argue that~$F$ is fully faithful, and in \Cref{subsec:surjective} we use a result of \cite{Mulevicius2022} to show that it is essentially surjective. 


\subsubsection[$ F$ is Fully Faithful]{$\boldsymbol{ F}$ is Fully Faithful}
\label{subsec:fullyfaithful}

We first show that~$F$ is full. 
Then we use pivotality of~$F$ together with a result of \cite{Mulevicius2022a} to find that~$F$ is also faithful. 

\begin{lemma}[label=lem:identification of relative tensor products of morphisms]
	For all $g,h,k \in G$ and all $(X,u) \in (\Gcbc)^G$, we have
	\begin{equation}
		\gamma_{ F(X,u)}^{g,h,k}=\id_{X_{gh^{-1}}}
	\end{equation}
	under the identification $ F(X)_{g,h}=X_{gh^{-1}}= F(X)_{gk,hk}$. 
\end{lemma}

\begin{proof}
	Inserting the relevant ingredients \eqref{eq:FonX}--\eqref{eq:tau structure of monoidal unit in CAR} of $F(X,u)$ into the expression~\eqref{eq:component def of gamma} with $Y=F(X,u)$, one obtains an explicit string diagrammatic presentation for $\gamma_{ F(X,u)}^{g,h,k}$. 
	We claim that it is equal to $\id_{X_{gh^{-1}}}$. 
	This can be seen by explicitly including section and retraction for the relative tensor products in domain and codomain, which for $m_g\otimes_{A_g}m_g^*$ are evaluation and coevaluation, where the latter comes with an insertion of~$\psi^2$. 
	We are then left with a number of loops which cancel their $\psi^2$-insertions, leaving only the identity on~$X_{gh^{-1}}$.
\end{proof}

As a consequence of \Cref{lem:identification of relative tensor products of morphisms}, for any morphism $f\colon  F(X,u)\longrightarrow F(X^\prime,u^\prime)$ in $(\Gcbc)^G$, naturality of $\gamma^{g,e,h}$, i.e.\ $\gamma_{ F(X,u)}^{g,e,h}\circ f_{gh,h}=f_{g,e}\circ \gamma_{ F(X^\prime,u^\prime)}^{g,e,h}$, implies
\begin{equation}
	\label{eq:identification of relative tensor products of morphisms}
	f_{gh,h}=f_{g,e}
\end{equation}
for the components of~$f$ introduced in~\eqref{eq:relative tensor products of morphisms in CAR}. 
We claim that $f_{G,e} = \bigoplus_{g\in G}f_{g,e}$ is a preimage of~$f$ under~$F$. 
The is straightforward to check:
\begin{align*}
	 F(f_{G,e})&\stackrel{\hphantom{\eqref{eq:identification of relative tensor products of morphisms}}}{=}\bigoplus_{g,h\in G} m^*_{gh}\otimes f_{g,e}\otimes m_h\\
	&\stackrel{\eqref{eq:identification of relative tensor products of morphisms}}{=} \bigoplus_{g,h\in G} m^*_{gh}\otimes f_{gh,h}\otimes m_h\\
	&\stackrel{\eqref{eq:relative tensor products of morphisms in CAR}}{=}\bigoplus_{g,h\in G} m^*_{gh}\otimes (m_{gh}\otimes_{A_{gh}} f\otimes_{A_h}m_h^*)\otimes m_h\\
	&\stackrel{\hphantom{\eqref{eq:identification of relative tensor products of morphisms}}}{=}\bigoplus_{g,h\in G} A_{gh}\otimes_{A_{gh}} f\otimes_{A_h}A_h\\
	&\stackrel{\hphantom{\eqref{eq:identification of relative tensor products of morphisms}}}{=} f \, .
\end{align*}
Thus~$F$ is full. 
Since it is also pivotal by \Cref{lem:Phi is well-defined}, it follows from \cite[Prop.\,2.3]{Mulevicius2022a} that~$F$ is fully faithful.


\subsubsection[$F$ is Essentially Surjective]{$\boldsymbol{F}$ is Essentially Surjective}
\label{subsec:surjective}

We prove that~$F$ is essentially surjective by showing that the induced map between isomorphism classes of simple objects is surjective. 
We do so by showing that the images of simple objects saturate the global dimension, i.e.\ adding the squares of their dimensions gives the global dimension of $\CAR$.

\medskip

Recall from \cite[Thm.\,3.17]{Mulevicius2022} the formula for the global dimension of the category associated to an orbifold datum:
\begin{equation}
	\dim(\CAR)=\frac{\dim(\mathcal{C})}{\phi^8(\tr_{\mathcal{C}}(\omega_A^2))^2}\,,
\end{equation}
where we continue to denote $\mathcal{C}\equiv\mathcal{C}_e$. 
To calculate the denominator, we note that
\begin{equation}
	\tr_{\mathcal{C}}(\omega_A^2)=\bigoplus_{g\in G}\,
	\begin{tikzpicture}[very thick,scale=0.6,color=red!50!black, baseline]
		\draw[directedred] 
		(2,0) .. controls +(0,-1) and +(0,-1) .. (1,0) node[pos=0.8](psi){};
		\draw[directedred] 
		(1,0) .. controls +(0,1) and +(0,1) .. (2,0) node[pos=1](g){};
		\draw[directedred] 
		(0,0) .. controls +(0,-2) and +(0,-2) .. (3,0) node[pos=0.2](psi2){};
		\draw[redirectedred] 
		(0,0) .. controls +(0,2) and +(0,2) .. (3,0)node[pos=1](g2){};
		% labels: 
		\fill(psi)  circle (2.9pt)
		(psi2) circle (2.9pt);
		\draw ($(psi)+(0.4,0.15)$) node {{\tiny$\psi^2$}}
		($(psi2)+(0.4,0.15)$) node {{\tiny$\psi^2$}}
		($(g)+(0.3,0)$) node{{\scriptsize$g$}}
		($(g2)+(0.3,0)$) node{{\scriptsize$g$}};
	\end{tikzpicture}	\!
	=\bigoplus_{g\in G}\id_\mathds{1}= |G|
\end{equation}
because of~\eqref{eq:PsiMaps} and~\eqref{eq:psiInAR}, and we have $\phi^{-8}=|G|^4$ by~\eqref{eq:phiInAR}. 
Thus 
\begin{equation}
	\label{eq:dimCAR}
	\dim(\CAR)=|G|^2\dim(\mathcal{C}) \, . 
\end{equation}

For $(\Gcbc)^G$, recall from \cite[Eq.\,(6.7)]{Mulevicius2022a} that for a commutative $\Delta$-separable symmetric haploid Frobenius algebra~$B$ we have
\begin{equation}
	\dim \Big(B\text{-}\Mod^\textrm{loc}\big((\Gcbc)^G\big)\Big)= \frac{\dim\big((\Gcbc)^G\big)}{\big(\!\dim_{(\Gcbc)^G}(B)\big)^2}\,.
\end{equation}
On the other hand, by \cite[Prop.\,2.23]{BB2017}, pivotal functors preserve dimensions of objects. Since the functor~$I\colon\Rep(G)\longrightarrow (\Gcbc)^G$ (cf.~\eqref{def:inclusion of RepG}, with~$\mathcal C$ replaced by $\Gcbc$) is pivotal, the dimension of $B=I(\C(G))$ is
\begin{equation}
	\label{eq:dimBIsG}
	\dim_{(\Gcbc)^G}(B)=\dim_{\Rep(G)}(\C(G))=|G|\,.
\end{equation}
As a result, we find that the global dimensions of $\CAR$ and $(\Gcbc)^G$ are the same, 
\begin{align}
	\dim(\CAR)&\stackrel{\eqref{eq:dimCAR}}{=}|G|^2\dim(\mathcal{C}) 
	\nonumber 
	\\
	&\stackrel{\hphantom{(}\ref{thm:inversion of 0form by 1form}\hphantom{)}}{=}|G|^2\dim\big(\big((\Gcbc)^G\big)_{\mathbb{A}_B}\big) 
	\nonumber 
	\\
	&\stackrel{\eqref{eq:orbifold category of a condensable algebra}}{=}|G|^2\frac{\dim\big((\Gcbc)^G\big)}{\big(\!\dim_{(\Gcbc)^G}(B)\big)^2}
	\nonumber 
	\\
	&\stackrel{\eqref{eq:dimBIsG}}{=}\dim\big((\Gcbc)^G\big)\,.
\end{align}

By \cite[Prop.\,6.3.1]{EGNO2015}, a fully faithful functor between fusion categories sends simple objects to simple ones. 
Combining this with the fact that~$F$ preserves dimensions of objects (because~$F$ is pivotal), denoting the set of chosen representatives of isomorphism classes of simple objects in a category~$\mathcal{B}$ by $\mathcal{I}_\mathcal{B}$, and abbreviating $F(X) \equiv F(X,u)$, we have
\begin{equation}
\label{eq:dimension of Geq}
	\sum_{X\in\mathcal{I}_{(\mathcal{C}^{\scaleto{\times}{3pt}}_{\scaleto{G}{3pt}})^{\scaleto{G}{3pt}}}}\dim_{\mathcal{C}_{\mathbb{A}_{\scaleto{R}{3pt}}}}\big( F(X)\big)^2=\sum_{X\in\mathcal{I}_{(\mathcal{C}^{\scaleto{\times}{3pt}}_{\scaleto{G}{3pt}})^{\scaleto{G}{3pt}}}}\dim_{(\Gcbc)^G}(X)^2=\dim \big((\Gcbc)^G\big)=\dim(\CAR)\,.
\end{equation}
Note that since~$ F$ is fully faithful, non-isomorphic simple objects have non-isomorphic images. Therefore we have 
\begin{equation}
\label{eq:dimension of CAR dissected}
	\dim(\CAR)=\sum_{X\in\mathcal{I}_{(\mathcal{C}^{\scaleto{\times}{3pt}}_{\scaleto{G}{3pt}})^{\scaleto{G}{3pt}}}}\dim_{\mathcal{C}_{\mathbb{A}_{\scaleto{R}{3pt}}}}\big( F(X)\big)^2 +\sum_{Y\in \mathcal{I}_{\mathcal{C}_{\mathbb{A}_{\scaleto{R}{3pt}}}}\setminus F(\mathcal{I}_{(\mathcal{C}^{\scaleto{\times}{3pt}}_{\scaleto{G}{3pt}})^{\scaleto{G}{3pt}}})}\dim_{\mathcal{C}_{\mathbb{A}_{\scaleto{R}{3pt}}}}(Y)^2 \,.
\end{equation}
By \cite[Thm.\,7.21.12]{EGNO2015}, dimensions of simple objects in fusion categories have strictly positive squares. Comparing \eqref{eq:dimension of Geq} and \eqref{eq:dimension of CAR dissected},  the second sum in \eqref{eq:dimension of CAR dissected} must therefore be zero. 
This implies that there is no isomorphism class of simple objects in $\CAR$ which does not have a representative of the form $ F(X)$. 
It follows that the map between sets of isomorphism classes of simple objects induced by~$ F$ is surjective, and hence~$ F$ is essentially surjective.

\medskip

In summary, the results of \Cref{subsec:fullyfaithful,subsec:surjective} show that~$F$ is an equivalence, thus completing the proof of \Cref{thm:eq is orbifolding}. 


