\subsection{Error localization using DCT Decoder}
%Let, $\{\mathbf{R}_{i} \in \mathbb{R}^{m\times m} ~|~ i \in [N]\}$ denote the set of computations returned by the workers such that $\mathbf{R}_{i} = f(\hat{\textbf{X}}_{i_a}) + \mathbf{E}_{i}$ if $i = i_{a}$ for some $a \in [A]$, otherwise, $\mathbf{R}_{i} = f(\hat{\textbf{X}}_{i_a})$ in infinite precision. However, with finite precision $\mathbf{R}_{i} = f(\hat{\textbf{X}}_{i_a}) + \mathbf{E}_{i}$ + $\mathbf{P_{i}}$, where $\mathbf{P_{i}}\in$ $\mathbb{R}^{m\times m}$ captures the precision noise. As discussed in the previous section, for every $\bar{m} \in [m], \bar{n} \in [m]$, the received vector at the master indicated by, $\mathbf{r}_{\bar{m}\bar{n}} = [\mathbf{R}_{1}(\bar{m}, \bar{n}) ~\mathbf{R}_{2}(\bar{m}, \bar{n}) ~\ldots~ \mathbf{R}_{N}(\bar{m}, \bar{n})]$ can be represented as a codeword of $K_{1}$ dimensional of DCT code of block length $N$. More specifically, $\mathbf{r}_{\bar{m}\bar{n}}$ represents a codeword of $(N,K_{1})$ DCT code, therefore, in the presence of adversarial noise master retrieves a total of $M=m\times m$ noisy codewords. In order to recover the correct codeword master applies DCT decoder on each codeword independently. Although DCT codes are not BCH but because of its decomposition of the parity check matrix as, $\mathbf{H_c^t}=\mathbf{A}\mathbf{X}\mathbf{U}$, BCH like characterization is possible and hence decoding algorithm analogous to BCH code can be applied \cite{2}. In general, their implementation involves the following steps: (i) Computing of syndrome vector, (ii) estimation of the number of errors, (iii) identifying the location of errors, and (iv) estimation of error magnitudes.

Recall, with the received codeword $\mathbf{r}_{\bar{m}\bar{n}}$ we obtain modified syndrome vector denoted by, $z=\mathbf{A}^{-1}s=\mathbf{XU}\mathbf{r'}_{\bar{m}\bar{n}}$. Using the modified syndrome vector $z$, we can further estimate the number of errors and the coefficients of the error locator polynomial, however, with finite precision estimation of the number of error and the coefficients of the error locator polynomial may  not be perfect. Note that, we infinite precision roots of the error locator polynomial accurately provides the location of error, with finite precision it may not provide.

\noindent Towards detecting the error locations corresponding to the vector $\mathbf{r}_{\bar{m}\bar{n}}$ for a given $K_{1}$ with finite precision, we first estimate the number of errors $A \leq v \triangleq \lfloor \frac{N-K_{1}}{2}\rfloor$ using the modified syndrome vector $z$ following the approach in \cite{2}. Further, let $\bar{\Lambda}_{\bar{u}\bar{f}}(x)$ denote the error-locator polynomial of degree $A$ given by $\bar{\Lambda}_{\bar{u}\bar{f}}(x) = \Lambda_{\bar{u}\bar{f}}(x) + e_{\bar{u}\bar{f}}(x),$ where $\Lambda_{\bar{u}\bar{f}}(x)$ denotes the actual error-locator polynomial computed using the syndrome vector with infinite precision and $e_{\bar{u}\bar{f}}(x)$ is the error polynomial due to precision errors. Let the coefficients of $e_{\bar{u}\bar{f}}(x)$ be i.i.d. as $\mathcal{N}(0, \sigma^{2}_{p})$. However, with precision errors, one needs to evaluate $||\bar{\Lambda}_{\bar{u}\bar{f}}(X_{q})||^2$, where $X_{q} = \cos\frac{(2q+1)\pi}{2N}$ for each $q\in[N]$ and arrange the evaluations in the ascending order. Subsequently, the $A$ smallest evaluations and its corresponding set $\hat{\mathcal{L}} = \{\hat{i}_1,\hat{i}_2, \ldots, \hat{i}_A\}$ are treated as the detected error locations.
% In the context of BACC, let the received vector of results from the N worker nodes be denoted by $\mathbf{r}_{\bar{m}\bar{n}}$. Also, let the original codeword be denoted by $\mathbf{y}_{\bar{m}\bar{n}}$  and the error vector due to adversarial nodes be denoted by $\mathbf{e}_{\bar{m}\bar{n}}$ such that $\mathbf{r}_{\bar{m}\bar{n}}$=$\mathbf{y}_{\bar{m}\bar{n}}$+$\mathbf{e}_{\bar{m}\bar{n}}$. Therefore, the modified syndrome at the decoder is given by $z=XU \mathbf{r}_{\bar{m}\bar{n}}$. Using the modified syndrome, we estimate the number of errors and the location of the errors. 
However, due to the inherent precision noise during the process of recovering the location of the adversaries, the true locations of the error $\mathcal{L} = \{i_{1}, i_{2}, \ldots, i_{A}\}$ is incorrectly detected as, $\hat{\mathcal{L}} = \{\hat{i}_1,\hat{i}_2, \ldots, \hat{i}_A\}$. Therefore, to characterize the event of probability of error localization and look into the pair wise probability of error localization  between the neighbouring indices $i_{a}$ and $i_{b}$, given by,
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{eq:PEP}
PEP_{dom} = P(||\Lambda_{\bar{u}\bar{f}}(X_{i_{a}})||^2\leq ||\Lambda_{\bar{u}\bar{f}}(X_{i_{b}})||^2),
\end{equation} where $P(\cdot)$ is the probability operator.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
\label{eq:lower_bound1}
For a given $N$, $A$, $\sigma_{p}^2$, the lower bound on the pairwise error probability in \ref{eq:PEP} can be expressed as
    \begin{equation}
PEP_{dom} \geq PEP_{L} \triangleq \frac{\sqrt{2}\sigma_{p}}{(\sqrt{\eta+\beta})\sqrt{var(t)}}e^{-\frac{\eta c_I^2\beta}{8\sigma^2_p(\eta+\beta)}},
\end{equation}
where $\eta, c_I$, $c_{Q}$ are constants, 
$\beta=\frac{4\sigma_p^2}{var(t)}$
%$\kappa =\frac{2}{\eta \sum_{j = 1}^{A}(\mbox{cos}^2(\theta_{1})- \mbox{cos}^2(\theta_{a})})$
and $var(t)=\sigma_p^2\sum_{k = 1}^{A}(\mbox{cos}^k\theta_{1}- \mbox{cos}^k \theta_{a})^2$
\end{theorem}
\begin{IEEEproof}
    Supplementary Material.
\end{IEEEproof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{corollary}
    The lower bound on PEP in Theorem \ref{eq:lower_bound1} is a non-decreasing function of $\sigma_p^2$.
\end{corollary}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\noindent However, note that, for a given $K_{1}$, the code can correct up to $\lfloor \frac{N-K_{1}}{2}\rfloor$ no. of error. Therefore, for a given $A$, the accuracy of the estimation of the number of errors and the location of the error depend on the parameter $K_{1}$. Therefore, backed by the Theorem \ref{eq:lower_bound1}, we provide the following proposition in the context of choosing the parameter $K_{1}$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}
\label{prop:small K1}
For a given $\sigma_{p}^2,$ $N$ and $A$ the lower bound in Theorem \ref{eq:lower_bound1} is an increasing function of $K_{1}$.
\end{proposition}
\begin{IEEEproof}
In the presence of precision noise with variance $\sigma_p^2$, the accuracy of the localization of error depends on how accurately we can estimate the no. of errors and coefficients of the error locator polynomial. Therefore, with finite precision, we suggest to use the least squares (LS) solution proposed in\cite{2} in order to estimate the no. of errors. To determine the number of error in the presence of precision noise, we compute the eigenvalues of the syndrome covariance matrix $\mathbf{R_{p}}$ where, $\mathbf{R_p}= \mathbf{\bar{z}}_{p}\mathbf{\bar{z}}_{p}^{\dagger}$ here, $\mathbf{\bar{z}}_{p}$ indicates the perturbed syndrome matrix formed by distorted syndrome vector $\mathbf{\bar{z}_{\bar{m}\bar{n}}}$. Therefore, with finite precision, estimation of no. of errors improves as we use more syndrome samples \cite{2}. Again, in the absence of precision noise, only $v$ syndrome samples are sufficient to determine the $v$ error values and $2v$ syndrome samples to determine the location of errors. However, for $A<v$, in the presence of precision noise, instead of using a limited no. of syndrome samples we can use remaining $2v-A$ samples to enhance the estimation of no. of errors as well as the location and magnitude of $v$ errors. More precisely, the estimation of the coefficients of error locator polynomial, $\Lambda=[\Lambda_{A},\Lambda_{A-1},\ldots\,\Lambda_{1}]$ is more accurate if we find LS solution where the accuracy of the estimation depends on the number of equations per unknown. Note that, for a given $A \leq v \triangleq \lfloor \frac{N-K_{1}}{2}\rfloor$ and number of equations which is  $2v-A$ ; the accuracy of estimation is proportional to $\frac{2v-A}{A}$. Therefore, for a given value of $A$, a smaller value of $K_{1}$ will enhance the estimation accuracy. This comes from the fact that as the number of equations per unknowns increases we are effectively averaging the precision noise variance $\sigma_{p}^2$ i,e.; $\sigma_p^2\propto \frac{1}{2v-A}$. As for a given $A$, the lower bound in Theorem \ref{eq:lower_bound1} is a non-decreasing function of $\sigma^2_p$, therefore, when $\sigma_p^2$ decreases, the lower bound on $PEP$ is decreases.
\end{IEEEproof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proposition}
For a given $N$, $\sigma_p^2$, smaller value of $K_{1}$ effects the accuracy of error localization.
\end{proposition}
\begin{IEEEproof}
Note that, we assume $f$ to be infinitely differentiable such that $f$ has Taylor series expansion, therefore, in general the message $f(u(z))$ can have infinite dimension. Therefore, in order to represent the received vector at the master $\mathbf{r}_{\bar{m}\bar{n}} = [\mathbf{R}_{1}(\bar{m}, \bar{n}) ~\mathbf{R}_{2}(\bar{m}, \bar{n}) ~\ldots~ \mathbf{R}_{N}(\bar{m}, \bar{n})]$ which are the evaluation of the message $f(u(z))$ at $z_{i}$, as a codeword of DCT code we treated the message $f(u(z)$ to have a finite dimension $K_{1}$ such that it represents a codeword of $(N,K_{1})$ DCT code. While doing so, we truncate the $f$ to a finite degree in order to represent it as polynomial approximation of Taylor series expansion of the original function, which in turn transform the message symbols $f(u(z))$ into a finite dimension, $K_{1}$ in order to represent its evaluation at $z_{i}$ as a codeword of $(N,K_{1})$ of DCT code. More precisely, we divide the Taylor series expansion of $f(u(z))$ into two parts, $f(u(z))= f(u(z))|_{K_{1}}+\Delta$ where, first $K_{1}$ term represented by, $f(u(z))|_{K_{1}}$ indicate the message symbols of dimension $K_{1}$ whereas, the remaining term $\Delta$ captures the higher order terms of the series expansion of the function $f$. Further, the higher order term $\Delta$ acts as residual noise which inherently effects  the error localization block of the DCT decoder in a deterministic manner. Therefore, for a smaller value of $K_{1}$, it further increases the magnitude of residual noise $\delta$ and hence decreases the performance of error localization.
\end{IEEEproof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\noindent Recall the proposition \ref{prop:small K1}, which states that for a given $A$, and when $A$ is small, smaller value of $K_{1}$ helps in estimation of coefficients of the error locator polynomial $\Lambda=[\Lambda_{A},\Lambda_{A-1},\ldots\,\Lambda_{1}]$ by averaging the variance $\sigma_p^2$ and there by it improves the localization accuracy. Therefore, in the context of choosing an optimal value of $K_{1}$ we propose the following theorem.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{theorem}
\label{eq:lower_bound_opt_k}
For a given $N$, $A$, $K_{1}$, $\sigma_{p}^2$ and $\Delta$ the lower bound on the pairwise error probability in \ref{eq:PEP} can be expressed as,
\begin{equation}
PEP_{dom} \geq PEP_{L} \triangleq \frac{\sqrt{2}\sigma_{p}}{(\sqrt{\eta+\beta})\sqrt{var(t)}}e^{-\frac{\eta c_I^2\beta}{8(\sigma^2_p+\Delta^2)(\eta+\beta)}},
\end{equation}
where $\eta, c_I$, $c_{Q}$ are constants, 
$\beta=\frac{4\sigma_p^2}{var(t)}$
%$\kappa =\frac{2}{\eta \sum_{j = 1}^{A}(\mbox{cos}^2(\theta_{1})- \mbox{cos}^2(\theta_{a})})$
and $var(t)=\sigma_p^2\sum_{k = 1}^{A}(\mbox{cos}^k\theta_{1}- \mbox{cos}^k \theta_{a})^2$
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{corollary}
    The lower bound on PEP in Theorem \ref{eq:lower_bound_opt_k} is a non-decreasing function of $\sigma_p^2+\Delta^2$.
\end{corollary}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Note that, for a given value of $A$ as $K_{1}$ increases magnitude of $\delta^2$ decreases but it further decreases the performance of error localization. We refer this term as, effective precision noise indicated by, $\sigma_{p_{eff}}= \sigma^2_p+\Delta^2$ which is a function of $K_{1}$. Note that, $\sigma_{p_{eff}}$ is a function of two parameter one is increasing function of $K_{1}$ whereas other is decreasing function of $K_{1}$. Moreover, the lower bound in $PEP$ is a decreasing function of  $\sigma_{p_{eff}}$, therefore, we argue that for a given $N$ and $A$ there exist a optimal value of $K_{1}$, $K_{1}^{*}$ which minimize the effective precision noise $\sigma_{p_{eff}}$ and improves the error localization and thereby decreases $PEP_{L}$.

\section{Limitation of the existing BACC scheme}
\label{sec: limitation of BACC}
In this section, we state the major limitation of the proposed sets of interpolation points in contrast to the BACC scheme with adversarial workers. Although the proposed BACC scheme is proven to be straggler-resilient, it is not proven to be resilient against the adversarial workers that return erroneous computation results to the master. On top of that, we also show that, with the proposed sets of interpolation points, $z_i = \cos \left( \frac{i \pi}{N} \right), i \in [N-1]$ which is Chebyshev points of second kind, the erroneous computation results returned by the adversarial worker nodes cannot be corrected. Therefore, in this section we first introduce the existing BACC scheme in the presence of adversarial workers. 
In contrast to the proposed BACC scheme \cite{2}, we consider a setting wherein $A$ out of the $N$ workers sends erroneous computation results to the master. Let, $i_{1}, i_{2}, \ldots, i_{A}$ be the indices of the adversarial workers, wherein the adversary $i_{a}$ is expected to return $\hat{\textbf{Y}}_{i_a}= f(\hat{\textbf{X}}_{i_a})$ for each $a \in [A]$ where $f : \mathbb{R}^{m \times m} \to \mathbb{R}^{m \times m}$ represents an arbitrary function that can represent either a polynomial or a non-polynomial function. Therefore, assuming the additive adversarial model, if node $i_{a}$ is an adversarial worker, it is assumed to return a corrupted version of $\hat{\textbf{Y}}_{i_a}$ represented by, $\textbf{R}_{i_{a}} = f(\hat{\textbf{X}}_{i_a})+\mathbf{E}_{i_{a}} \in \mathbb{R}^{m\times m}$ where $\mathbf{E}_{i_{a}} \in \mathbb{R}^{m \times m}$ is the noise matrix chosen by the adversary $i_{a}$. 
Towards solving the problem of BACC with adversarial workers, let $\{\mathbf{R}_{i} \in \mathbb{R}^{m\times m} ~|~ i \in [N]\}$ denote the set of computations returned by the workers such that $\mathbf{R}_{i}\approx f(\hat{\textbf{X}}_{i_a}) + \mathbf{E}_{i}$ if $i = i_{a}$ for some $a \in [A]$, otherwise, $\mathbf{R}_{i}= f(\hat{\textbf{X}}_{i_a})$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}
\label{prop:limitation of previous point}
    The proposed angle  $z_i = \cos \left( \frac{i \pi}{N} \right),\quad i \in [N-1]$ i,e Chebyshev points of the second kind does not provide security guarantees. 
\end{proposition}
\begin{IEEEproof} 
For every $\bar{m} \in [m], \bar{n} \in [m]$, let $\mathbf{r}_{\bar{m}\bar{n}} = [\mathbf{R}_{1}(\bar{m}, \bar{n}) ~\mathbf{R}_{2}(\bar{m}, \bar{n}) ~\ldots~ \mathbf{R}_{N}(\bar{m}, \bar{n})]$, represent a vector constructed from the $(\bar{m}, \bar{n})$-th entry of each $\mathbf{R}_{i}$. In the presence of $A$ adversarial worker nodes, the received vector $\mathbf{r}_{\bar{m}\bar{n}}$ represents a noisy vector. Therefore, in the presence of adversarial workers in the system, the master needs to employ certain error detection and correction algorithm that can detect the position of the adversarial workers and correct the errors introduced by the workers from the received vector $\mathbf{r}_{\bar{m}\bar{n}}$. Further, in order to employ the error correction algorithm, the received vector $\mathbf{r}_{\bar{m}\bar{n}}$ should represent a $K$-dimensional codeword of blocklength $N$. More specifically, it should represent a codeword from $(N,K)$ code. Note that, while giving the shares to the worker node master evaluated the rational function $u(z)$ at $N$  Chebyshev point of second kind $z_i = \cos \left( \frac{i \pi}{N} \right), \quad i \in [N-1]$; therefore, the computation over those shares, $f(u(z_{i})$ should represent a $K$-dimensional codeword of $(N, K)$ code. Treating $f(u(z))$ as the message symbols and its evaluation at $z_i = \cos \left( \frac{i \pi}{N} \right), \quad i \in [N-1]$ as codeword, the $k$-th column of the generator matrix of the code can be represented as, $[1, \cos(w_{k}), \cos^2(w_{k}) \ldots, \cos^{(K-1)}(w_{k})]$ where, $w_{k}=\cos \frac{k\pi}{N}$, $k= 0,1,2,\dots, N-1$, which represents Vandermonde matrix of dimension $K\times N$. In order to construct the required generator matrix we first construct the generator matrix with the given sets of evaluation points i,e. $z_i = \cos \left( \frac{i \pi}{N} \right)$. Note that, with $z_{i},i\in[N-1]$ the $(i,j)$-th element of the generator matrix can be constructed as, $G(i,j)= \cos \frac{j\cdot i\pi}{N}$ where $j\in[N-1]$ and $i\in[K-1]$. The corresponding parity check matrix is given by,
$$
\mathbf{H}_c^t=\left[\begin{array}{cccc}1 & \cos \left(\frac{(N-d) \pi}{N}\right) & \cdots & \cos \left(\frac{(N-d)(N-1) \pi}{N}\right) \\ \vdots & \vdots & \ddots & \vdots \\ 1 & \cos \left(\frac{(N-2) \pi}{N}\right) & \cdots & \cos \left(\frac{(N-2)(N-1) \pi}{N}\right) \\ 1 & \cos \left(\frac{(N-1) \pi}{N}\right) & \cdots & \cos \left(\frac{(N-1)(N-1) \pi}{N}\right)\end{array}\right],$$
 where, $d=N-K$. Further, following the approach given in \cite{2}, the conjugate transpose of the parity check matrix can be decomposed as, $\mathbf{H}_c^t=\mathbf{A X U}$ which corresponds to BCH-like code, where $\mathbf{X}$ is a Vandermonde matrix of dimension $d\times N $, which $k$-th column is given by, $[1, \cos(w_{k}), \cos^2(w_{k}) \ldots, \cos^{(K-1)}(w_{k})]$, the matrix $\mathbf{A}$ is a $d\times d$ is a lower triangular coefficient matrix and  $\mathbf{U}$ is a diagonal matrix with the $i$-th diagonal entry equal to $u_{i}$. Note that, in the special case, when $\mathbf{A}=I_{d}$ and $\mathbf{U}=I_{N}$, they are BCH. If we can decompose the given parity check matrix $\mathbf{H}_c^t$ obtained by, $z_i = \cos \left( \frac{i \pi}{N} \right)$ as $\mathbf{H}_c^t=\mathbf{AXU}$ it will represent a code from class of codes which are BCH-like \cite{2}. However, the BCH decoding can still be applied to decode and correct the errors given the no. of error doesnot exceed $\lfloor \frac{N-K}{2}\rfloor$. Therefore, by rearranging the rows in reverse order and using basic trigonometric relations for the above matrix $\mathbf{H}_c^t$, it can be expressed as,
\[
\mathbf{H}_c^t = 
\begin{bmatrix}
1 & -\cos \frac{\pi}{N} & \cos \frac{2\pi}{N} & \cdots & (-1)^{N-1} \cos \frac{(N-1)\pi}{N} \\
1 & -\cos \frac{2\pi}{N} & \cos \frac{2\cdot 2\pi}{N} & \cdots & (-1)^{N-1} \cos \frac{2\cdot(N-1)\pi}{N} \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
1 & -\cos \frac{d\pi}{2N} & \cos \frac{d\cdot 2\pi}{N} & \cdots & (-1)^{N-1} \cos \frac{d\cdot(N-1)\pi}{2N}
\end{bmatrix},
\]
We use the following trigonometric identity,
\begin{align*}
\cos (n \beta) = \frac{1}{2} \left\{ (2 \cos \beta)^n - n (2 \cos \beta)^{n-2}
+ \frac{n}{2} \binom{n-3}{1} \\
(2 \cos \beta)^{n-4} - \cdots \right\}
\end{align*}
and decompose, $\mathbf{H}_c^t=\mathbf{AXU}$ where, $\mathbf{X}$ is a $d\times N$ matrix which can be expressed as,
\[
\mathbf{X}= \begin{bmatrix}
\cos \frac{0\cdot\pi}{N} & \cos \frac{\pi}{N} & \cos \frac{2\pi}{N} & \cdots & \cos \frac{(N-1) \pi}{N} \\
\cos^{2}\frac{0\cdot\pi}{N} & \cos^{2} \frac{\pi}{N} & \cos^{2} \frac{2\pi}{N} & \cdots & \cos^{2} \frac{(N-1) \pi}{N} \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
\cos^{d} \frac{0\cdot\pi}{N} & \cos^{d} \frac{\pi}{N} & \cos^{d} \frac{2\pi}{N} & \cdots & \cos^{d} \frac{(N-1) \pi}{N}
\end{bmatrix}_{d\times N},\]
The matrix $\mathbf{A}$, which contains the coefficients of the above series can be expressed as, .
\[\mathbf{A}=\left[\begin{array}{cccccc} 0&1 & & &\\-1 & 0 & 2 & & & \\ 0 &-3 & 0 &  4 \\ \vdots & \ddots & \ddots &  \ddots & \\ \cdots & -d 2^{d-3} & & 0 & 2^{d-1}\end{array}\right],\] and the matrix $\mathbf{U}$ is a diagonal matrix with diagonal entries $(-1)^j$ for $j\in \{0,1,2,\ldots, N-1\}$. Note that, the $k$-column of the matrix $\mathbf{X}$ is given by, $[\cos(w_{k}), \cos^2(w_{k}) \ldots, \cos^d(w_{k})]$ where, $w_{k}=\cos \frac{k\pi}{N}$, $k= 0,1,2,\dots,N-1$. Therefore, it may be easily observed that the above matrix $\mathbf{X}$ cannot be expressed in the Vandermonde form, and the matrix $\mathbf{A}$ cannot be represented as a lower triangular matrix and it is not a invertible matrix; therefore, we cannot decompose the above parity check matrix $\mathbf{H}_c^t$ in terms $\mathbf{AXU}$, which means BCH-like characterization is not possible. 
\end{IEEEproof}
