\begin{lemma}\label{lem:v}
    All other parameters being positive, for all $\vare,\gamma\geq 0$ there exists a unique positive solution $v = v\left( \varepsilon, \gamma, \sigma^2 T, \sigma_\Xi^2, \sigma_\beta^2 \right) > 0$ to the equation
    $$ 
   0=
    \frac{\left( 
     \frac{\sigma_{e}}{v}-\vare \gamma
     \right)^2}
     {1 - \gamma\sigma^2 T (\frac{\sigma_{e}}{v}-\vare\gamma) } 
     - 
     \frac{2\vare }{\sigma^2 T } 
     \log \left( 1-\gamma\sigma^2 T \left(\frac{\sigma_{e}}{v}-\vare\gamma\right)  \right)
     -
      \left( \frac{\sigma_\Xi^2}{\sigma^2 T}+\vare^2\gamma^2 \frac{\sigma_\beta^2}{\sigma^2 T} \right) 
$$
satisfying 
\begin{equation}\label{bound:v}
1>\frac{v\vare\gamma}{\sigma_{e}}>\frac{1}{1+\frac{1}{\vare\gamma^2 \sigma^2 T}} \ .
\end{equation}
\end{lemma}

\begin{rmk}
    (i) Thanks to \eqref{bound:v}, we define 
    \begin{align}\label{eq:terminallambda} 
    \Lambda:=\frac{\sigma_{e}}{v}-\vare\gamma>0
    \end{align}
    which will turn out to be the value of Kyle's lambda, i.e. sensitivity of the price in the total demand $Y$, at time $t=T$, see Eq. \eqref{eq:pricedyn}. 


    (ii) For $\vare=0$, we have that $ \Xi =V_f$ and $v$ solves the quadratic equation
        $$ \frac{v^2}{\sigma^2 T} 
   =
    \frac{1}
     {1 -  \frac{\sigma_\Xi\gamma\sigma^2 T}{v} } \ .
$$
In this case, the solution of this equation is $v= \frac{1}{2}\sigma_\Xi \gamma \sigma^2 T + \frac{\sigma\sqrt{T}}{2}\sqrt{4+\gamma^2 \sigma_\Xi^2 \sigma^2 T}$, which is in agreement with \cite[Proposition 3]{cho}.

(iii) For $\gamma=0$, the informed trader is risk neutral and optimizes her expected wealth and $v^2=\sigma^2 T$ leads to the classical Kyle model with Gaussian information \cite{kyle}.
\end{rmk}
In order to construct an equilibrium, given $v$ in Lemma \ref{lem:v} and $\Lambda$ in \eqref{eq:terminallambda}, define the following deterministic continuous functions
\begin{align}\label{eq:defdet}
    p_t & = \frac{1}{\Lambda^{-1}-{\gamma\sigma^2}(T-t)} \ ,\quad 
    k_t    = \frac{1-\frac{v\vare\gamma}{\sigma_e}\gamma\sigma^2\Lambda(T-t)}{1-\gamma\sigma^2\Lambda(T-t)} \ ,\quad 
    \rb_t  = \frac{k_t\ub}{\sigma_e v} \\ \, \notag
    \Sigma_t &=\begin{bmatrix}
     \sigma^2 t + \sigma_\beta^2 & 0\\ 
    0           & \sigma^2_\Xi
   \end{bmatrix}
   -
   \frac{\sigma^2 \int_0^t k_{s}^2 ds}
        {\sigma_e^2 v^2}
   \ub \ub^\top. 
   \end{align}
   Define also $m$ as the root of the equation 
   $$-m+\frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{\Lambda} (k_0-1)=0$$ and
   \begin{align*}
 q_t   &= \frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{1-\Lambda{\gamma\sigma^2}(T-t)} \ , \quad  
        \ab_t  = \begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix} + \frac{b_t}{\sigma_e v} \ub \ ,\\
     b_t  &=  -m + \int_t^T\gamma\sigma^2 q_s \left( k_s - \frac{v \varepsilon \gamma}{\sigma_e} \right) ds \ . \nonumber
   \end{align*}
Additionally, define the projection
$$x\in \R^2\mapsto\Phi(x)   = x - \frac{\wb^\top x}{\wb^\top \ub } \ub =x - \frac{\wb^\top x}{\sigma_e^2 } \ub$$
and 
$ \left( \Phi_{s,t} \ ; \ s \leq t < T \right)$ the flow of the equation
\begin{align}\label{eq:resolvent}
    dx_t=-\sigma^2 \rb_t  \left(\rb_t -e_1\right)^\top \Sigma_t^{-1}x_t dt
\end{align}
so that $t\mapsto\Phi_{s,t}(x)$ solves this equation with initial value $\Phi_{s,s}(x)=x\in \R^2$. %Here $e_1$ is the first canonical basis vector. 

The following Lemma lists properties of these quantities that we will use. As we will see, $\Sigma_T$ will not be invertible. In particular, this non-invertibility of $\Sigma_T$ requires us to explicitly compute the expansion of $\Sigma^{-1}_t$ as $t\to T$. This point will be needed to study the mean-reversion properties of $\Phi_{s,t}$, which will play an important role.

   \begin{lemma}\label{lem:sigma}
   Given the choice of $v$ as in Lemma \ref{lem:v},
 $\Sigma_t$ is invertible for $t<T$ with inverse given by
\begin{align*}%\label{eq:sigma-1}
    \Sigma_t^{-1}  & =     \begin{bmatrix}
     \sigma^2 t + \sigma_\beta^2 & 0 \\
    0           & \sigma^2_\Xi
   \end{bmatrix}^{-1} \\ \notag
  & \quad  +
   \frac{\sigma^2 \int_0^t k_{s}^2 ds}
        {\sigma_{e}^2 v^2}
   \frac{
   \begin{bmatrix}
