\section{Necessary conditions on Markovian equilibria}
\label{s.PricingRule}

In this section we follow the methodology of \cite{cho} to obtain necessary conditions on inconspicuous equilibria. In particular, we see the natural appearance of the state variable $\chi$ and the measure $\Q$ for example. In subsequent sections, we use these necessary conditions to construct the candidate equilibrium strategies of each agents and prove the existence of the equilibrium. Although these steps are not needed for the proof of the main theorems, we below they are informative on the obtaining the structure of the equilibrium.
Thus, we assume the existence of an equilibrium, where 
$$ dX^*_t=\theta_t dt \ $$
and satisfying the inconspicuousness condition $$\E[\theta_t|\Fc_t^Y]=0 \ .$$

We first focus on the path-dependence of the pricing rule. 
If the informed trader is risk neutral, it is known that $Y_t$ is the relevant state variable and both $\theta$ and the price are functions of $Y_t$ (see \cite{kyle, back1992}). However, in the case the informed trader is risk averse, it is known that $Y$ does not carry all the information needed to construct the equilibrium (see \cite{cho,bose2020kyle,bose2021multidimensional}). In \cite{cho}, it is shown that one needs to introduce a new state variable 
$$d\xi_t=\lambda_t dY_t$$
and in \cite{bose2020kyle,bose2021multidimensional} it is assumed that 
\begin{align*}%\label{eq:defxi}
d\xi_t=\frac{dY_t}{\partial_\xi \chi(t,\xi)}
\end{align*}
for some function $\chi(t,\xi)$. Then, different ingredients of the equilibrium can be written as functions of the current value of $(t,\xi_t)$ and the dependence of $\xi$ on the path of $Y$ carries all the path-dependence in the problem. We note that by applying It\^o's formula to $\chi(t,\xi_t)$, one can show that in all these papers, there exists a new state variable 
$\chi_t$ that 
carries all the path-dependence of the problem and it has the dynamics  
\begin{align}\label{eq:defchi} 
\notag
d\chi_t &= dY_t + B(t,\chi_t)dt \\
\chi_0&=0
\end{align}
for some function $B$. 
The following Proposition shows that in any equilibrium where there is such a state variable satisfying \eqref{eq:defchi}, one has very strong conclusion on the pricing rule and an optimality criterion for the informed trader. Note that we study such equilibria because the equilibrium we construct has this form. Define the surplus function 
\begin{align}\label{eq:surplus}
        \Sc\left( x,\xi \right)
        = \xi x - g \left(x\right)=\xi x - \frac{\varepsilon \gamma}{2} x^2  \ . 
\end{align}
%that will be relevant for our optimal transport formulation of the problem.

\begin{proposition}\label{p:opt1}
    Let $(X^*,\fP^*)$ be an equilibrium such that there exist continuous functions $P,B:[0,T]\times \R\mapsto \R$ such that the pricing rule $\fP^*$ and the absolutely continuous trading strategy  $X^*$ satisfy 
    $\fP^*_t(\tilde Y)=P(t,\chi_t(\tilde Y))$, where
    $$
        \chi_t(\tilde Y)= \int_0^t B(s,\chi_s(\tilde Y))ds+\tilde Y_t \quad \mbox{ and } \quad \E\left[\frac{dX^*_t}{dt}|\Fc_t^{X^*+Z}\right]=0\mbox{ for all }t\in[0,T] \ .
    $$
    Denote $\Gamma(\chi):=\int_0^\chi P(T,s)ds$, and \begin{align}\label{eq:gammac}
    \Gamma^c(z,\xi):=\sup_{x\in \R}\left[\Sc (x-z, \xi)-\Gamma(x) \right] \ . 
    \end{align}
    Assume for all $z,\xi$, \eqref{eq:gammac} admits an optimizer and that the parabolic PDE 
    \begin{align}\label{pde:chi1}0 &=   \ \pa_t u+\frac{\sigma^2}{2}\pa_{\chi\chi}u+\frac{1}{2}\gamma\sigma^2(\pa_\chi u)^2 \\
    u(T,\chi)&=\Gamma(\chi) \notag
    %\label{pde:chi2}
    \end{align}
    admits a smooth solution $u \in C^{1,2}([0,T]\times \R)$.
    For any admissible trading strategy $X$, and $t\geq 0$, define the probability measure $\Q$ by
\begin{align*}
       \left.\frac{d\Q}{d\P}\right|_{\Fc_t}
:= & \ \exp\left( -\gamma\int_0^t  P_s dZ_s-\gamma\int_0^t \frac{\gamma \sigma^2 P_s^2}{2}ds\right) \ , 
\end{align*}
where $P_s=P(s,\chi_s(X+ Z))$.
%\todo{assumptions on $\gamma P$ to have martingality above?}
Then, 
\begin{align}\label{eq:pathdep}
        B(t,\chi)=\gamma\sigma^2 P(t,\chi)=\gamma\sigma^2 \pa_\chi u(t,\chi) \ ,
    \end{align} 
the process 
\begin{align*}
Z_t^\Q := & \ Z_t+\gamma\sigma^2 \int_0^tP_sds
\end{align*} 
is a $(\Q,\Fc)$-Brownian motion, and 
\begin{align}\label{eq:eqlaw}
\Lc^\Q\left(  Z_T^\Q-\beta,  \Xi  \right)    = \mu \otimes \nu =\Lc\left(Z_T-\beta,  \Xi  \right) \ .
\end{align}
    Additionally, any choice of absolutely continuous admissible strategy $X$ ensuring the point wise optimality criterion
\begin{align}\label{eq:target}
\chi_T\in \argmax_{x \in \R}\left[ \Sc \left(x-\left(Z^\Q_T-\beta\right),  \Xi \right)-\Gamma(x) \right]
\end{align}
is optimal and leads to the optimal utility
 \begin{align}
 & -e^{-\gamma u(0,0)}  
   \E\left[\exp\left(-\gamma \Gamma^c(Z_T-\beta, \Xi )\right)| \Xi ,\beta\right] \ .
 \label{eq:optimal_utility}
\end{align}

\end{proposition}

\begin{rmk}
    (i) Although the new measure $\Q$ depends on the strategy $X$ through $\chi$, the optimal utility \eqref{eq:optimal_utility} is independent of $X$. This point is crucial to be able to use this proposition for an optimality criterion.  

   (ii) Since not all vector fields in multi-dimensions are gradient vector fields, the Proposition requires an additional condition if one wants to study this problem in the multi-dimensional case: the terminal pricing function $\chi\mapsto P(T,\chi)$ is a gradient vector field.


    (iii) This Proposition justifies the introduction of $\chi^*$ in \eqref{eq:chi}, where 
    $$dY_t=\sigma^2 (\rb_t-e_1)^\top \Sigma_t^{-1}((Z_t^\Q-\beta, \Xi )^\top-\mu^\P_t)dt+dZ_t$$
    is the equilibrium total demand. 
\end{rmk}

\begin{proof}[Proof of Proposition \ref{p:opt1}]
    We split the proof of the Proposition in two parts. We first show the property of the pricing rule in \eqref{eq:pathdep}. Then, we show the optimality criterion \eqref{eq:target} and the optimal utility \eqref{eq:optimal_utility}.

\medskip

{\it Step 1: Proof of \eqref{eq:pathdep}}. 
Since $X^*$ is optimal, it is a fortiori optimal among all absolutely continuous strategies. Fix an absolutely continuous trading strategy $X$ admissible for $\fP^*$. Without loss of generality, we assume that it can be written as 
$dX_t= \theta_t dt$ for some $\Fc$-adapted process $\theta$ and 
\begin{align}\label{eq:evchi}
    d\chi_s=B(s,\chi_s)ds+dX_s+dZ_s=(B(s,\chi_s)+\theta_s)ds +\sigma dB_s \ .
\end{align}
Following the optimization problem from \eqref{eq:problem}, we assume that the informed trader starts at time $t$ from position $X_t+\beta=x$ in stock and $0$ in cash so that
the wealth of the informed trader can be written as
$$ \Wc:=(X_T+\beta)( \Xi -G) - \int_t^T  P(s,\chi_s) \theta_sds \ .
$$
And we introduce the optimal control problem
 \begin{align}
 \label{eq:def_J}
 J(t,\chi,x) = \ \sup_{\theta} e^{\gamma  \Xi  x} \E\left[-\exp\left(-\gamma\Wc \right) \ | \ \Fc_t, \chi_t = \chi, X_t+\beta=x\right] \ , 
\end{align}
where the state is $(\chi_t,X_t+\beta)$ and evolves according to \eqref{eq:evchi} and 
$$d(X_s+\beta)=\theta_sds$$
given control $\theta$. 
By the independence of $G$, we can write the utility as 
\begin{align*}
     &\E\left[-\exp\left(\frac{\gamma^2 \varepsilon (X_T+\beta)^2}{2}+ \gamma\int_t^T  (P(s,\chi_s)- \Xi ) \theta_sds \right) \ | \ \Fc_t, \chi_t = \chi, X_t+\beta=x\right]
\end{align*}
and we obtain the following dynamic programming equation for $J$
\begin{align*}
    &\pa_t J+\frac{\pa_{\chi\chi} J\sigma^2}{2}+\pa_\chi J B+\sup_{\theta\in \R}\{\theta (\pa_\chi J+\pa_xJ +\gamma(P- \Xi ))\}=0 \ . 
\end{align*}
The final condition of $J$ is
$J(T,\chi,x)=-e^{\frac{\gamma^2 \varepsilon x^2}{2}}$.



Since the control variable $\theta$ is unconstrained, the optimization on the variable $\theta$ is over all of $\R$. Necessarily, we obtain the pair of the equations 
\begin{align*}
&\pa_t J +\frac{\sigma^2}{2}\pa_{\chi\chi} J + B\pa_\chi J =0  \ , \\
&\pa_\chi J+\pa_xJ +\gamma(P- \Xi ) = 0 \ , 
\end{align*}
or, equivalently,
\begin{align}
\label{eq:lnj}
&  \pa_t \ln |J|
 + \frac{\sigma^2}{2} \pa_{\chi\chi} \ln|J|
 + \frac{\sigma^2}{2} \left( \pa_\chi \ln |J| \right)^2
 + B \pa_\chi \ln|J| = 0 \ , \\
&
\label{eq:lnj_2}
P= \Xi -\frac{ \partial_\chi \ln |J| + \partial_x \ln |J| }{\gamma} \ .
\end{align}
Thus, differentiating \eqref{eq:lnj} in each variable $\chi$ and $x$, while setting $V= \pa_\chi \ln |J|$ and $\tilde V= \pa_x \ln |J|$, we obtain
\begin{align*}
\pa_tV+\frac{\sigma^2}{2} V_{\chi\chi}+ V_\chi (B+\sigma^2V)+VB_\chi &=0 \ , \\
\pa_t\tilde V+\frac{\sigma^2}{2} \tilde V_{\chi\chi}+ \tilde V_\chi (B+\sigma^2V) &=0 \ .
\end{align*}
Thus, adding these two expressions and using \eqref{eq:lnj_2}, we have
\begin{align*}
\pa_t P+\frac{\sigma^2}{2} \pa_{\chi\chi} P + \pa_\chi P (B+\sigma^2V)-\frac{V \pa_\chi B}{\gamma} &=0 \ .
\end{align*}
The inconspicuousness condition 
$\E\left[\frac{dX^*_t}{dt}|\Fc_t^{X^*+Z}\right]=0$ implies that 
$\chi_t(X^*+Z)-\int_0^t B(s,\chi_s(X^*+Z))ds=X^*_t+Z_t$ is $\Fc^{X^*+Z}$-martingale.  
Invoking the martingality condition for $P$, we obtain the following important necessary condition on $B$ for the martingality of $\fP^*_t(X^*+Z)$
$$ \gamma\sigma^2 \pa_\chi P = \pa_\chi B \ , $$
which suggest that $B=\gamma\sigma^2 P$ up to the addition of a deterministic function of time $f = f(t)$. So, we have 
$$d\chi_t=dY_t+\gamma\sigma^2 (P(t,\chi_t)-f(t))dt \ .$$
Since it does not have informational value, we take $f=0$ and obtain
$$d\chi_t=dY_t+\gamma\sigma^2 P(t,\chi_t)dt \ .$$
%\todo{TODO: better justification of $f=0$? $f$ is deterministic and does not bring any information to the dynamics}

Injecting the value of $B$, the martingality condition for $P$ is 
$$ \pa_t P+\frac{\sigma^2}{2} \pa_{\chi\chi} P + \gamma\sigma^2 P \pa_\chi P=0 \ .
$$
We now integrate this equality in space. 
If $P(t,\chi)$ is the gradient of some function  $u(t,\chi)$, then this function has to solve
\begin{align*}
0 = & \  \pa_t u+\frac{\sigma^2}{2}\pa_{\chi\chi} u +\frac{1}{2}\gamma\sigma^2 (\pa_\chi u )^2\\
  = &  \ \pa_t u+\frac{\sigma^2}{2}\pa_{\chi\chi} u +\frac{1}{2}\gamma\sigma^2P^2
\end{align*}
which concludes the proof of \eqref{pde:chi1}-\eqref{eq:pathdep}.

\medskip


{\it Step 2: Joint law of  $ \Xi $ and $Z_T^\Q-\beta$. }
 The change of measure is 
\begin{align*}
       \left.\frac{d\Q}{d\P}\right|_{\Fc_t}
 = & \ \exp\left( -\gamma\int_0^t  P_s dZ_s-\gamma\int_0^t \frac{\gamma \sigma^2 P_s^2}{2}ds\right) \\
 = & \ \exp\left( -\gamma \left( u(t, \chi_t) - u(0,0) \right) + \gamma \int_0^t P(s,\chi_s) dX_s \right) \\
 = & \ \exp\left( -\gamma \left( u(t, \chi_t) - u(0,0) \right) + \gamma \int_0^t \partial_\chi u(s,\chi_s) dX_s \right) \ .
\end{align*}
%{\color{red} DEf 2.2 needs to be modified so that Girsanov is legit here}
Thanks to Girsanov, we have indeed a $\sigma^2$-Brownian motion in the form of
\begin{align*}
Z_t^\Q := &  \ Z_t+\gamma\sigma^2 \int_0^tP(s,\chi_s)ds \ .
\end{align*} 

Now, let us prove Eq. \eqref{eq:eqlaw}. Indeed, since $P = \left( P_t \ ; \ t \geq 0 \right)$ is $\Fc^Y$-adapted, for any bounded continuous functions $f$ and $h$, we have
$$\E^\Q[f(Z_T^\Q)h( \Xi ,\beta)]=\E\left[\E[e^{-\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma\sigma^2 P_s^2}{2}ds}f(Z_T^\Q)|\Fc_0]h( \Xi ,\beta)\right] \ .$$
By the properties of conditioning, 
$$\E[e^{-\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma\sigma^2 P_s^2}{2}ds}f(Z_T^\Q)|\Fc_0]=\E[e^{-\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma\sigma^2 P_s^2}{2}ds}|\Fc_0] \ \E^\Q[f(Z_T^\Q)|\Fc_0] \ .$$
Since $Z$ is a $(\Fc,\P)$-Brownian motion, $\E[e^{-\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma\sigma^2 P_s^2}{2}ds}|\Fc_0]=1$. The fact that $Z^\Q$ is a $(\Fc,\Q)$-Brownian motion leads to
$$\E^\Q[f(Z_T^\Q)|\Fc_0]=\E^\Q[f(Z_T^\Q)]$$
which is a deterministic integral against Gaussian density. 
Thus, 
$$\E^\Q[f(Z_T^\Q)h( \Xi ,\beta)]=\E^\Q[f(Z_T^\Q)] \ \E[h( \Xi ,\beta)]$$
which concludes the proof of Eq. \eqref{eq:eqlaw}. 

\medskip

{\it Step 3: Proof of optimality criteria \eqref{eq:target}-\eqref{eq:optimal_utility}}.
Since $u$ is assumed to be smooth, by the Itô's formula, we have
\begin{align*}
    du(t,\chi_t)
= & \ \left( \pa_t u+\frac{\sigma^2}{2}\pa_{\chi\chi} u \right) dt
    + \pa_\chi u d\chi_t\notag\\
= & \ P(t,\chi_t)d\chi_t-\frac{1}{2}\gamma\sigma^2P^2(t,\chi_t)dt\notag\\
= & \ P(t,\chi_t)dX_t+P(t,\chi_t)dZ_t+\frac{1}{2}\gamma\sigma^2P^2(t,\chi_t)dt \ . %\label{eq:gamma_ito}
\end{align*}
The change of measure is
$$\frac{d\Q}{d\P}=\exp\left( -\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma \sigma^2 P_s^2}{2}ds\right)= \exp\left( -\gamma \left( u(T, \chi_T) - u(0,0) \right) + \gamma \int_0^T P_s dX_s \right)$$
so that the value function satisfies
 \begin{align}
  & e^{-\gamma  \Xi  \beta}J(0,0,\beta)\notag\\
= & \sup_{(X)}  \E\left[-e^{\gamma (g (X_T+\beta)- \Xi  (X_T+\beta))+\gamma\int_0^T  P_t dX_t}|\Fc_0\right]\notag\\
= & e^{-\gamma u(0,0)}  
    \sup_{(X)}\E\left[-e^{\gamma (g (X_T+\beta)- \Xi (X_T+\beta)+u(T,\chi_T))-\gamma\int_0^T  P_s dZ_s-\gamma\int_0^T \frac{\gamma \sigma^2 P_s^2}{2}ds}|\Fc_0\right]\notag\\
= & e^{-\gamma u(0,0)}  
    \sup_{(X)}\E\left[-e^{\gamma (g (X_T+\beta)- \Xi (X_T+\beta)+u(T,\chi_T)) }
                       \frac{d\Q}{d\P} \ | \ \Fc_0\right]\notag \\
= & e^{-\gamma u(0,0)} 
    \sup_{(X)}\E^\Q\left[-e^{\gamma (g (X_T+\beta)- \Xi  (X_T+\beta)+u(T,\chi_T)) }\ | \ \Fc_0\right] \ .\label{eq:uti2}
\end{align}
By the definition of $\chi$, we have 
\begin{align*}
   X_T+\beta=\chi_T-\int_0^T \gamma\sigma^2 P(s,\chi_s)ds-Z_T+\beta=\chi_T-Z_T^\Q+\beta
\end{align*}
and 
\begin{align*}
    \E^\Q\left[-e^{\gamma (g (X_T+\beta)- \Xi  (X_T+\beta)+u(T,\chi_T)) }\ | \ \Fc_0\right]&= \E^\Q\left[-e^{\gamma (g (\chi_T-Z_T^\Q+\beta)- \Xi  (\chi_T-Z_T^\Q+\beta)+u(T,\chi_T)) }\ | \ \Fc_0\right]\\
    &= \E^\Q\left[-e^{-\gamma (\Sc(\chi_T-(Z_T^\Q-\beta), \Xi )-u(T,\chi_T)) }\ | \ \Fc_0\right]\\
    &\leq \E^\Q\left[-e^{-\gamma (\sup_x\Sc(x-(Z_T^\Q-\beta), \Xi )-u(T,x)) }\ | \ \Fc_0\right]\\
    &\leq \E\left[-e^{-\gamma \Gamma^c(Z_T-\beta, \Xi ) }\ | \ \Fc_0\right]
\end{align*}
where we used \eqref{eq:eqlaw} at the last line. Thus, we obtain the upper bound \eqref{eq:optimal_utility}. For any strategy satisfying \eqref{eq:target}, all inequalities above are equalities and we obtain the optimality criterion.  


\end{proof}

