\section{Optimal transport}
\label{sect:StructureOptimizer}

%{\color{red} In the subsequent section we always considered transport maps of $ \Xi -m_\Xi $ and $Z_T^\Q-\beta+m_\beta$. Thus, at the end $m=0$. So take $m=0$ starting here.}
The Proposition \ref{p:opt1} and Eq.\eqref{eq:target} show that the fundamental quantity to pinpoint in equilibrium is $\eta := \Lc^\Q( \chi_T)= \Nc(m, v^2)$. Indeed, the distribution of $(Z_T^\Q - \beta, \Xi )$ under $\Q$ and and the surplus function $\Sc$ are known. If we also know $\eta = \Lc^\Q( \chi_T)= \Nc(m, v^2)$, $\Gamma$ can be constructed by solving an optimal transport problem described below. We refer to \cite{villani,santambrogio2015optimal} for their proofs.

\begin{proposition}\label{prop:OT}
For any probability distribution $\eta$ on $\R$, denote $\Gamma(\chi;\eta)$ and $\Gamma^c(z,\xi;\eta)$ the Kantorovich potentials for the transport problem
\begin{align}\label{eq:optt}
\sup_{\pi \in \Pi(\mu\otimes \nu, \eta)}\iiint\Sc (\chi-z, \xi)d\chi dzd\xi \ , 
\end{align}
where the surplus function is defined is \eqref{eq:surplus}, and under $\pi$, the $\chi$ marginal is distributed according to $\eta$ and the law of $(z, \xi)$ is $\mu\otimes \nu$. 
By definition, these functions satisfy the duality relations
\begin{align*}%\label{eq:dualinequality}
    \Gamma(\chi;\eta)+\Gamma^c(z,\xi;\eta)\geq \Sc (\chi-z, \xi)
\end{align*}
for all $(\chi,z,\xi)$ and there exists a mapping $I(z,\xi;\eta)$ so that  
$I\left( \cdot \ ;\eta \right)_\sharp (\mu\otimes \nu) = \eta$
and 
\begin{align*}%\label{eq:dualequality}
    \Gamma(I(z,\xi;\eta);\eta)+ \Gamma^c(z,\xi;\eta)= \Sc (I(z,\xi;\eta)-z, \xi)
\end{align*}
for $\mu\otimes \nu$ almost every $(z,\xi).$
Note that a consequence of this equality is the fact that for $\mu\otimes \nu$ almost every $(z,\xi)$,
\begin{align}\label{eq:defI}
I(z,\xi;\eta)\in \argmax\{\Sc (x-z, \xi)-\Gamma(x;\eta)\} \ .
\end{align}


We denote
\begin{align}\label{eq:defoptcoupling}
    \pi^*(d\chi,dz,d\xi;\eta):=((I(\cdot;\eta),\id)_\sharp(\mu\otimes \nu) )(d\chi,dz,d\xi)
\end{align}
and 
\begin{align*}
   \chi\mapsto \pi^*_\chi(dz,d\xi;\eta)
\end{align*}
the disintegration of this measure on the $\chi$ marginal. This means that 
$$ \pi^*(d\chi,dz,d\xi;\eta)=\pi^*_\chi(dz,d\xi;\eta)\eta(d\chi) \ .$$
\end{proposition}

Eq. \eqref{eq:defI} (and therefore \eqref{eq:target}) is in fact the main relation we use from optimal transport theory. This result says that if we take $\Gamma$ in \eqref{eq:target} to be the Kantorovich potential $\Gamma(\cdot;\eta)$, then the law of $\chi_T=I(Z_T^\Q - \beta, \Xi )$ under $\Q$  will indeed be $\eta$. This provides a way to pinpoint the solution to \eqref{pde:chi1} by finding its terminal condition as a Kantorovich potential if we know $\eta$. 



If the measures $\mu$ and $\eta$ are Gaussian, we can explicitly compute these quantities as functions of the mean and the variance of $\eta$. 

\begin{lemma}
\label{lemma:gaussian_transportfinalcondition}
Assume that $\eta$ is normal with mean $m$ and variance $v^2>0$ and denote $\Lambda:=\frac{\sigma_{e}}{v}-\vare\gamma$. For the transport problem \eqref{eq:optt} with Gaussian marginals 
\begin{align}\label{Assump:Gaussian}
 \mu \otimes \nu 
 & = \mathcal{L}^\Q (Z_T^\Q-\beta,   \Xi  )
 = \Nc\left(-m_\beta,\sigma^2 T + \sigma^2_\beta \right) \otimes \Nc\left(m_\Xi ,\sigma^2_\Xi\right)  \ , \\
    \eta &= \mathcal{L}^{\mathbb{Q}}(\chi_T) 
        = \mathcal{N}(m, v^2) \ ,  \nonumber
\end{align}
the Kantorovich potentials are
\begin{align}
\label{eq:gausstransport}
\Gamma(\chi;\eta)&=\frac{1}{2}\Lambda(\chi-m)^2+(m_\Xi -\vare\gamma (m_\beta+m))(\chi-m) - \frac{\vare\gamma m^2}{2}  
\\
    \Gamma^c(z,\xi;\eta)&=\frac{1}{2}\left( - 2\xi z -{\vare\gamma}z^2+\frac{v}{\sigma_{e}}(\xi-m_\Xi  +{\varepsilon \gamma} (z+m_\beta))^2+2m (\xi +{\varepsilon \gamma} z)\right) \ \notag\end{align}
and the optimal transport maps are
\begin{equation} \label{eq:OTmapGaussian}
    I(z,\xi;\eta)=m+\frac{v}{\sigma_{e}}((\xi-m_\Xi ) +{\varepsilon \gamma} (z+m_\beta)) \ .
\end{equation}

If the joint law of $\left(\chi_T,  Z^\Q_T-\beta,  \Xi  \right) $  is $ \pi^*$, then under this coupling we have the equality in law
$$ \left( \begin{pmatrix} Z^\Q_T-\beta\\  \Xi \end{pmatrix} \ | \ \chi_T \right)
   \
   \eqlaw 
   \
   \frac{\chi_T-m}{\sigma_{e} v} 
   \ub
   +
   \begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix}
   +
   \Nc 
   \frac{\sigma_\Xi \sqrt{\sigma^2 T + \sigma_\beta^2} }{\sigma_{e}} 
   \vb
   \ 
$$
where $\Nc$ is an independent standard normal random variable. 
\end{lemma}

\begin{proof}
The optimal transport problem in hand is
\begin{align*}%\label{eq:optt2}
&\sup_{\pi \in \Pi(\mu\otimes \nu, \eta)}\iiint\Sc (\chi-z, \xi)\pi(d\chi, dz,d\xi)\\
=&\sup_{\pi \in \Pi(\mu\otimes \nu, \eta)}\iiint \big( \xi (\chi-z) - \frac{\varepsilon \gamma}{2} \left(\chi-z\right)^2 \big) \ \pi(d\chi, dz,d\xi)\\
=&\iint \big( -z\xi  - \frac{\varepsilon \gamma}{2} z^2+m(\xi +{\varepsilon \gamma} z) \big) \ (\mu\otimes \nu)(dz,d\xi)\\
& \quad +\int \big( (m_\Xi -\vare\gamma m_\beta)(\chi-m) -\frac{\varepsilon \gamma}{2}\chi^2 \big) \ \eta(d\chi)\\
& \quad + \sup_{\pi \in \Pi(\mu\otimes \nu, \eta)}\iiint  (\chi-m)(\xi-m_\Xi  +{\varepsilon \gamma}(z+m_\beta)) 
\ \pi(d\chi, dz,d\xi)\notag \ . 
\end{align*}
%Recalling the definition of $\sigma_{e}$ in Eq. \eqref{def:lambda},
The last term on the right is the optimal coupling between 
$$\Nc(m,v^2)\mbox{ and }\Nc(m_\Xi -\gamma \vare m_\beta,\sigma_{e}^2 ) \ .$$
The potentials are \begin{align*}
   \Gamma(\chi;\Nc(m,v^2))&=\frac{1}{2}\Lambda(\chi-m)^2+(m_\Xi -\vare\gamma (m_\beta+m))(\chi-m) - \frac{\vare\gamma m^2}{2} \\
    \Gamma^c(z,\xi;\Nc(m,v^2))&=\frac{1}{2}\left( - 2\xi z -{\vare\gamma}z^2+\frac{v}{\sigma_{e}}(\xi-m_\Xi  +{\varepsilon \gamma} (z+m_\beta))^2+2m (\xi +{\varepsilon \gamma} z)\right) \ .
\end{align*}
This is easily verified using the $\vare$-Young inequality. Because the optimal transport is linear for Gaussians, the optimizer is 
$$I(z,\xi;\Nc(m,v^2))=m+\frac{v}{\sigma_{e}}((\xi-m_\Xi ) +{\varepsilon \gamma} (z+m_\beta)) \ .$$

It remains to compute the conditional distribution $\pi^*_{\chi}(dz,d\xi;\Nc(m,v^2))$. Thanks to \eqref{eq:defoptcoupling}, we know that under $\pi^*$, 
$$ \chi_T = \ I(Z^\Q_T-\beta, \Xi ;\Nc(m,v^2))
          = \ m+\frac{v}{\sigma_{e}}( \Xi -m_\Xi  +{\varepsilon \gamma} (Z^\Q_T-\beta+m_\beta)) 
          \eqlaw \ \Nc(m, v^2) \ .$$
As such, the vector $\left( Z^\Q_T-\beta, \Xi ,\chi_T \right)^\top$ is a Gaussian vector with mean $(-m_\beta, m_\Xi , m)^\top$ and (degenerate) covariance matrix 
$$
\Sigma_{ext}
=
\begin{bmatrix}
\sigma^2 T +\sigma_\beta^2&     0    & \frac{v\varepsilon \gamma}{\sigma_{e}} (\sigma^2 T +\sigma_\beta^2)\\
0  &       \sigma_\Xi^2 &  \frac{v\sigma_\Xi^2}{\sigma_{e}} \\
\frac{v\varepsilon \gamma}{\sigma_{e}} (\sigma^2 T +\sigma_\beta^2)&\frac{v\sigma_\Xi^2}{\sigma_{e}} & v^2 
\end{bmatrix}
\ .
$$

The Schur complement formula states that $\left( (Z^\Q_T-\beta, \Xi )^\top \ | \  \chi_T \right)$ is Gaussian with explicit mean and covariance using block operations. More precisely, the mean is
\begin{align*}
    \E^\Q\left[ (Z^\Q_T-\beta, \Xi )^\top \ | \ \chi_T \right]
= & \ \E^\Q\left[ (Z^\Q_T-\beta, \Xi )^\top \right]
    + 
      \frac{1}{\sigma_{e} v} \left( \chi_T - m \right) \ub \\
= & \ \frac{\chi_T - m}{ \sigma_{e} v}
      \ub +\begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix}\ ,
\end{align*}
and the covariance is
\begin{align*}
    \Cov\left( (Z^\Q_T-\beta, \Xi )^\top \ | \ \chi_T \right)
= & \ \begin{bmatrix}
\sigma^2 T +\sigma_\beta^2 &         0    \\
0  &       \sigma_\Xi^2  \\
\end{bmatrix}
    - \frac{1}{\sigma_{e}^2 }
      \ub
      \ub^\top \ .\end{align*}
 Recalling that $\sigma_{e}^2=\sigma^2_\Xi+\vare^2\gamma^2( \sigma^2 T+\sigma^2_\beta)$, we see that
\begin{align*}
  & \Cov\left( (Z^\Q_T-\beta, \Xi )^\top \ | \ \chi_T \right) \\
= & \begin{bmatrix}
\sigma^2 T +\sigma_\beta^2& 0 \\ 0 & \sigma_\Xi^2
\end{bmatrix}
 - \frac{1}{\sigma_{e}^2 }
   \left( \varepsilon \gamma(\sigma^2 T +\sigma_\beta^2), \sigma_\Xi^2 \right)^\top
   \left( \varepsilon \gamma(\sigma^2 T +\sigma_\beta^2), \sigma_\Xi^2 \right)\\
= & \frac{1}{\sigma_{e}^2}
 \begin{bmatrix}
 (\sigma^2_\Xi+\vare^2\gamma^2(\sigma^2 T +\sigma_\beta^2)) (\sigma^2 T +\sigma_\beta^2) & 0 \\
 0 & (\sigma^2_\Xi+\vare^2\gamma^2 (\sigma^2 T +\sigma_\beta^2)) \sigma_\Xi^2
 \end{bmatrix}\\
 &-\frac{1}{\sigma_{e}^2}
 \begin{bmatrix}
 (\varepsilon \gamma (\sigma^2 T +\sigma_\beta^2))^2 & \varepsilon \gamma (\sigma^2 T +\sigma_\beta^2) \sigma_\Xi^2 \\
 \varepsilon \gamma (\sigma^2 T +\sigma_\beta^2) \sigma_\Xi^2 & (\sigma_\Xi^2)^2
 \end{bmatrix} 
 \\
= & \frac{1}{\sigma_{e}^2 }
 \begin{bmatrix}
 \sigma^2_\Xi (\sigma^2 T +\sigma_\beta^2) & -\varepsilon \gamma (\sigma^2 T +\sigma_\beta^2) \sigma_\Xi^2 \\
     -\varepsilon \gamma (\sigma^2 T +\sigma_\beta^2) \sigma_\Xi^2 & \vare^2\gamma^2(\sigma^2 T +\sigma_\beta^2)\sigma_\Xi^2
     \end{bmatrix}\\
 = & \frac{(\sigma^2 T +\sigma_\beta^2)\sigma^2_\Xi}{\sigma_{e}^2 }
     \begin{bmatrix}
     1 & -\varepsilon \gamma \\
     -\varepsilon \gamma & \vare^2\gamma^2
     \end{bmatrix}= \frac{(\sigma^2 T +\sigma_\beta^2)\sigma^2_\Xi}{\sigma_{e}^2 }
     \vb\vb^\top
 \end{align*}
which yields the result. 


\end{proof}


\begin{rmk}
    %Unless otherwise specified, we use the vectors $\ub$ and $\vb$ as in \eqref{def:uv} in the rest of this paper. Additionally, 
    In the remainder of the section, we take $\Gamma(x)=\Gamma(x;\Nc(m,v^2))$, $I(z,\xi)=I(z,\xi;\Nc(m,v^2))$ and drop the dependence of these functions on $m,v.$
\end{rmk}


