The next Lemma states that if $\eta=\Nc(m,v^2)$ is given,  Proposition \ref{p:opt1} fully determines the pricing rule of the market maker. 
\begin{lemma}
\label{lemma:gaussian_solvability_price}
Assuming $m,v$ are given, the maps $u(t,\chi)$ and $P(t,\chi)$ are
$$ u(t,\chi)
   =
   \frac{p_t}{2}\chi^2 + q_t \chi + s_t \ ,
   \quad \quad
   P(t,\chi)= p_t\chi  + q_t \ , $$
where
{
\begin{align*}%\label{eq:pq}
p_t & :=\frac{1}{\Lambda^{-1}-{\gamma\sigma^2}(T-t)} \ , \quad 
q_t  := \frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{1-\Lambda{\gamma\sigma^2}(T-t)} \ , \\
s_t & := \frac{1}{2\gamma} \log \left( 1-\Lambda{\gamma\sigma^2}(T-t)\right) 
			 - \frac{(m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m)^2}{ 2\Lambda} \left(
								\frac{1}{1 -  \Lambda{\gamma\sigma^2}(T-t)} -1
								\right)\\
         & \quad \quad
         +\frac{\sigma_e m^2}{2v} - m(m_\Xi -\vare\gamma m_\beta)
\ .
\end{align*}
}
In particular, for any inconspicuous strategy, 
$$ d\chi_t = dY_t + \gamma \sigma^2 P(t,\chi_t) dt \ $$
is an inhomogeneous Ornstein--Uhlenbeck process under $\P$ and the price satisfies the dynamics 
$$dP(t,\chi_t)=\frac{dY_t}{\Lambda^{-1}-{\gamma\sigma^2}(T-t)} \ .$$
\end{lemma}

\begin{proof}
Since $P(t,\chi) = \partial_\chi u(t,\chi)$ from Proposition \ref{p:opt1}, the first expression readily yields the second one by differentiation. In order to compute $u(t,\chi)$, recall that it is the solution to the PDE \eqref{pde:chi1}. Moreover, in the current Gaussian setup, the terminal condition is given from Eq. \eqref{eq:gausstransport}  by 
\begin{equation*}
    %\label{eq:price_terminal_cond}
    u(T, \chi) = \Gamma(\chi; \mathcal{L}^{\Q}(\chi_T) )= \frac{p_T}{2}\chi^2 + q_T \chi + s_T \ , 
\end{equation*}
where
\begin{align*}
%\label{FinalCondLemma5.1}
p_T :=  \frac{\sigma_e}{v} - \vare\gamma=\Lambda \ ,
   \quad
   q_T := m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m \ , 
   \quad
   s_T : = \frac{\sigma_e m^2}{2v} - m(m_\Xi -\vare\gamma m_\beta) \ .
\end{align*} 
The PDE \eqref{pde:chi1} for $u$ is a well-behaved parabolic PDE and has obviously a unique solution. Therefore, it suffices to check that the proposed $u$ with $p_t, q_t, s_t$ satisfies the PDE \eqref{pde:chi1}.
%After all, the candidate solution certainly preserves the quadratic structure. This remark is the basis of the standard Riccati trick in Gaussian filtering. 
Given a solution as in the statement, we have:
\begin{align*}
0 = & \ \partial_t u +\frac{\sigma^2}{2}(\partial_{\chi\chi} u +\gamma(\partial_\chi u )^2) \\
  = & \ \frac{p_t'}{2} \chi ^2+q_t'\chi +s_t'
        + \frac{\sigma^2}{2}\left( p_t + \gamma \left( p_t \chi + q_t \right)^2 \right) \\
  = & \ \frac{1}{2}\left( p_t' + \gamma \sigma^2 p_t^2
                   \right)\chi^2
        + \left( q_t' + \gamma\sigma^2 p_t q_t \right)\chi
        + s_t'+\frac{\sigma^2}{2}\left( p_t + \gamma q_t^2 \right) \ .
\end{align*}
Identifying terms, we necessarily have
{
$$  p'_t+{\gamma\sigma^2} p_t^2=0 \ ,
    \quad
q_t' + \gamma\sigma^2 p_t q_t =0 \ , 
	\quad
s_t'+\frac{\sigma^2}{2}\left( p_t + \gamma q_t^2 \right) =0 \ .
 $$
 }


As such, we can solve the ODEs successively. First, we have:
$$ p_t^{-1} = p_T^{-1} - \int_t^T d p_s^{-1} 
            = \Lambda^{-1} {+} \int_t^T \frac{p_s'}{p_s^2} ds
            = \Lambda^{-1} {-} \gamma \sigma^2 (T-t) \ .
$$
{
Then,
\begin{align*}%\label{eq:intp}
	\int_t^T p_s ds = & \int_0^{T-t} \frac{ds}{\Lambda^{-1} {-} \gamma  \sigma^2 s}\\
							= & -\frac{1}{\gamma \sigma^2} \left[ \log \big( \Lambda^{-1}-{\gamma\sigma^2}s \big) \right]_0^{T-t} \\
							= &  -\frac{1}{\gamma \sigma^2} \log \left( 1-\Lambda{\gamma\sigma^2}(T-t)\right) \ .
\end{align*}
Hence,
\begin{align*}
	q_t = q_T \exp\Big(\gamma\sigma^2 \int_t^T p_s ds \Big) 
			= \frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{1-\Lambda{\gamma\sigma^2}(T-t)} \ .
\end{align*}
So, it gives
\begin{align*}
	\int_t^T q_s^2 ds = & q_T^2 \int_0^{T-t} \frac{ds}{( 1 - \Lambda{\gamma\sigma^2}s )^2} \\
								= & \frac{q_T^2}{ \Lambda{\gamma\sigma^2}} \left(
								\frac{1}{1 -  \Lambda{\gamma\sigma^2}(T-t)} -1
								\right) \ .
\end{align*}
Since $s_T = \frac{\sigma_e m^2}{2v} - m(m_\Xi -\vare\gamma m_\beta)$, we now have
\begin{align*}
	s_t = \frac{1}{2\gamma} \log \left( 1-\Lambda{\gamma\sigma^2}(T-t)\right) 
			- \frac{ q_T^2}{2\Lambda} 
        \left(\frac{1}{1 -\Lambda{\gamma\sigma^2}(T-t)} -1
								\right)
        + \frac{\sigma_e m^2}{2v} - m(m_\Xi -\vare\gamma m_\beta)
        \ .
\end{align*}
}

\end{proof}
We conclude this section by explaining how to obtain the expressions in \eqref{eq:defdet}.
Given the Proposition \ref{p:opt1}, we expect that the quantity that the market maker has to filter is $(Z_t^\Q - \beta, \Xi)$. If we know $m$ and $v$, then we know the $\Q$ distribution of $(Z_T^\Q - \beta, \Xi)$ conditional on $\Fc^\chi_T$ thanks to the Lemma \ref{lemma:gaussian_transportfinalcondition}. Assume that we have an equilibrium where the inconspicuous trading property holds. Then, the $\Q$ martingality of $(Z_t^\Q - \beta, \Xi)$ allows us to characterize the $\Fc^\chi_t$ conditional law of $(Z_t^\Q - \beta, \Xi)$ under $\Q$ as $\Nc(\mu^\Q_t,\Sigma_t)$, where
$$   \mu^\Q_t
 :=   \E^\Q\left[ (Z_t^\Q - \beta, \Xi)^\top \ | \ \Fc_t^\chi \right]
 =\begin{pmatrix}-m_\beta\\m_\Xi\end{pmatrix}
   +
   \frac{\int_0^t k_{s} dY^\Q_s}{\lambda v} 
   \ub
$$ 
and covariance 
$$ \Sigma_t= \Cov\left( (Z_t^\Q - \beta, \Xi)^\top \ | \ \Fc_t^\chi \right)
  =  \begin{bmatrix}
     \sigma^2 t + \sigma_\beta^2 & 0\\
    0           & \sigma^2_\Xi
   \end{bmatrix}
   -
   \frac{\sigma^2 \int_0^t k_{s}^2 ds}
        {\lambda^2 v^2}
   \ub \ub^* \ ,
$$
where $dY^\Q$ is the innovation process under $\Q$ and $k_s$ is $\Fc^\chi$-adapted that we need to determine. 
Thus, the optimal transport and martingale methods give us a parametric form for the conditional covariance of $(Z_t^\Q - \beta, \Xi)$ that only depends on the correct choice of $k_s.$ Starting from this ansatz on $\Sigma_t$, one can use \cite[Theorem 12.7]{liptser1977statistics} to find an expression for $X^*$. This forces us to study the filtering problems under both $\Q$ and $\P$. Then, we can find the correct expression for $k_s$ in \eqref{eq:defdet} by studying the conditional means $\mu^\Q_t, \mu^\P_t$ as in the Proof of Theorem \ref{thm:main} which can be found in Section \ref{s.ProofMain}.



