\subsection{Proof of Lemma \ref{lem:v}}
\label{proof-1}

%\begin{proof}[Proof of Lemma \ref{lem:v}]
The function 
$$x\mapsto F(x):= \frac{x^2}
     {1 - \gamma\sigma^2 T x } 
     - 
     \frac{2\vare }{\sigma^2 T } 
     \log \left( 1-\gamma\sigma^2 T x \right)$$
     is clearly increasing for $x\in [0,\frac{1}{\gamma \sigma^2T}]$ with 
     \begin{align*}
         F(0)=0,\,\lim_{x\uparrow\frac{1}{\gamma \sigma^2T}} F(x)=+\infty \ .
     \end{align*}
    Thus, there exists a unique root $x\in (0,\frac{1}{\gamma\sigma^2 T})$ to
      $F(x)=
