\subsection{Proof of Theorem \ref{thm:main}}
\label{s.ProofMain}

\medskip

{\textbf{Step 1: Existence of solution to the linear system.}}
The existence of solution to the system \eqref{eq:chi}-\eqref{eq:expmup} is obvious for $t<T$ due to the linearity of the system and the invertibility of $\Sigma_t$ for $t<T$. The existence on $[0,T]$ will be shown below by showing the existence of a limit as $t\to T$. 
Injecting in \eqref{eq:expmup}, the expression of $\Phi$ and $\rb$, we obtain 
\begin{align*}
        \mu_t^\P &=  \ab_t +\rb_t \chi^*_t+\gamma\sigma^2\int_0^t (p_s\chi^*_s+q_s)  \left(e_1-\rb_s  -\frac{\wb^\top (e_1-\frac{k_s\ub}{\sigma_e v})}{\sigma_e^2 } \ub\right) ds\\
         &=  \ab_t +\frac{k_t\chi^*_t\ub}{\sigma_e v} +\gamma\sigma^2\int_0^t (p_s\chi^*_s+q_s)  \left(e_1  - \frac{\gamma \vare}{\sigma_e^2} \ub\right) ds \ . 
\end{align*}
Differentiating this equality and using the equalities 
    $ k_t' = \gamma \sigma^2 p_t ( \frac{v \varepsilon \gamma}{\sigma_e} -k_t )  $, $\ab'_t=-\gamma\sigma^2 q_t \left(\frac{k_t}{\sigma_e v} - \frac{\gamma \vare}{\sigma_e^2}\right)\ub$,
we obtain 
\begin{align*}
        d\mu_t^\P 
         &=  \ab'_tdt +\frac{k_t'\chi^*_t\ub}{\sigma_e v}dt+\left(\frac{k_t}{\sigma_e v} - \frac{\gamma \vare}{\sigma_e^2}\right)\gamma\sigma^2 (p_t\chi^*_t+q_t)\ub dt\\
         & \quad + \gamma\sigma^2(p_t\chi^*_t+q_t)  e_1  dt+\rb_t(dX^*_t +dZ_t)\\
        &= \gamma\sigma^2(p_t\chi^*_t+q_t)  e_1  dt+\rb_t(dX^*_t +dZ_t) \ .
\end{align*}
We also differentiate \eqref{eq:chi} to obtain
\begin{align}
\notag
    d\mu_t^\P&=\gamma\sigma^2 (p_t \chi^*_t +q_t) e_1 dt+\rb_t(dX^*_t +dZ_t)\label{eq:dynp}\\
    d\begin{pmatrix}
    Z^\Q_t-\beta\\ \Xi 
    \end{pmatrix}&=\gamma\sigma^2 (p_t \chi^*_t +q_t) e_1 dt+e_1 dZ_t 
\end{align}
so that 
\begin{align*}
 d\left(\begin{pmatrix}     Z^\Q_t-\beta\\ \Xi      \end{pmatrix}-\mu_t^\P\right)&=-\rb_t dX^*_t+\left(e_1-\rb_t \right) dZ_t\\
 &=-\rb_t \sigma^2 \left(\rb_t -e_1\right)^\top \Sigma_t^{-1}\left(\begin{pmatrix}
    Z^\Q_t-\beta\\ \Xi 
    \end{pmatrix}-\mu^\P_t\right)dt+\left(e_1-\rb_t \right) dZ_t \ .
\end{align*}
Recalling that $\vb,\wb$ are orthogonal, multiplying the equation above with $\vb$ and $\wb$, and using the expression of $\rb$ in \eqref{eq:defdet}, the processes defined by 
$$A^1_t:=\vb^\top\left(\begin{pmatrix}
    Z^\Q_t-\beta\\ \Xi 
    \end{pmatrix}-\mu_t^\P\right),
    \quad
    A^2_t:=\wb^\top\left(\begin{pmatrix}
    Z^\Q_t-\beta\\ \Xi 
    \end{pmatrix}-\mu_t^\P\right)$$
satisfy the linear equation in $(A^1,A^2)$, 
\begin{align*}
 dA^1_t=&-\frac{k_t\vb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\ub}{\sigma_{e} v}-e_1\right)^\top \Sigma_t^{-1}\frac{\vb}{|\vb|^2}A^1_tdt\\
 &-\frac{k_t\vb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\sigma_{e}}{ v}-\gamma\vare\right) \frac{\wb^\top \Sigma_t^{-1}\wb}{|\wb|^4}A^2_tdt\\
 &-\frac{k_t\vb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\ub^\top\vb}{\sigma_{e} v}-e_1^\top\vb\right)\frac{\vb^\top \Sigma_t^{-1}\wb}{|\wb|^4}A^2_tdt+\vb^\top\left(e_1-\rb_t\right) dZ_t \ , \\
  dA^2_t=&-\frac{k_t\wb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\ub}{\sigma_{e} v}-e_1\right)^\top \Sigma_t^{-1}\frac{\vb}{|\vb|^2}A^1_tdt\\
 &-\frac{k_t\wb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\sigma_{e}}{ v}-\gamma\vare\right) \frac{\wb^\top \Sigma_t^{-1}\wb}{|\wb|^4}A^2_tdt\\
 &-\frac{k_t\wb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\ub^\top\vb}{\sigma_{e} v}-e_1^\top\vb\right)\frac{\vb^\top \Sigma_t^{-1}\wb}{|\wb|^4}A^2_tdt+\wb^\top\left(e_1-\rb_t\right) dZ_t \ .
