We have that
\begin{align*}
    \wb^\top \ub>0, \quad \frac{k_t\sigma_{e}}{ v}-\vare\gamma \to_{t\to T}\frac{\sigma_{e}}{ v}-\vare\gamma=\Lambda  >0
\end{align*}
and \eqref{eq:sigma-equivalent} shows that 
$$ \frac{\wb^\top \Sigma_t^{-1}\wb}{|\wb|^4}\sim_{t\to T}\frac{1}{\sigma^2 (T-t) \left(\frac{\sigma_{e}^2}{v^2}-\gamma^2\vare^2\right)}\mbox{ and }\vb^\top \Sigma_t^{-1}\wb,\, \vb^\top \Sigma_t^{-1}\vb\mbox{ are bounded.}$$

Thus, the leading term of $dA^2_t$ is $-\frac{k_t\wb^\top \ub}{\sigma_{e} v}\sigma^2 \left(\frac{k_t\sigma_{e}}{ v}-\gamma\vare\right) \frac{\wb^\top \Sigma_t^{-1}\wb}{|\wb|^4}A^2_tdt$ and it is equivalent to $\frac{-c A^2_t}{T-t}$ for some $c>0$ as $t\to T$. Due to this reversion to $0$, $A^2_t\to 0$ as $t\to T$ and 
$\int_0^t k_s\left(\frac{k_s\sigma_{e}}{ v}-\gamma\vare\right) \frac{\wb^\top \Sigma_s^{-1}\wb}{|\wb|^4}A^2_sds$
admits a limit as $t\to T$. Thus, $A^1$ is well defined on $[0,T]$ and admits a limit as $t\to T$. 
Given the orthogonality of $\vb$ and $\wb$, we easily see that $\left(\begin{pmatrix}
    Z_t^\Q-\beta\\ \Xi 
    \end{pmatrix}-\mu_t^\P\right)$ admits a limit as $t\to T$ with 
\begin{align}\label{eq:A2}
    A^2_T:=\lim_{t\to T}A^2_t=\wb^\top\left(\begin{pmatrix}
    Z^\Q_T-\beta\\ \Xi 
    \end{pmatrix}-\mu_T^\P\right)=0 \ .
\end{align}
Thus, the system \eqref{eq:chi}-\eqref{eq:expmup} admits a solution on $[0,T]$.

\medskip

{\textbf{Step 2: Solution to the filtering problem and \eqref{eq:incons}. }}
We first compute $\ab_0$. 
Thanks to the equality  $ k_t' = \gamma \sigma^2 p_t ( \frac{v \varepsilon \gamma}{\sigma_e} -k_t )  $ we have 
\begin{align*}
   &\gamma\sigma^2 q_t \left(k_t- \frac{v\gamma \vare}{\sigma_e}\right)\\
    &=\frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{\Lambda}\gamma\sigma^2 p_t \left(k_t- \frac{v\gamma \vare}{\sigma_e}\right)=-\frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{\Lambda}k'_t \ .
\end{align*}
Thus, 
\begin{align*}
    b_t=-m+\int_t^T  \gamma\sigma^2 q_s \left(k_s- \frac{v\gamma \vare}{\sigma_e}\right)ds=-m-\frac{m_\Xi -\vare\gamma m_\beta - \frac{\sigma_e}{v}m}{\Lambda}(k_T-k_t) \ .
\end{align*}
Due to the definition of $m$, this implies that $b_0=0$. Therefore, 
\begin{align}
    \label{eq:ab0}\ab_0=\begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix} \ .
\end{align}

Let $\Q$ be the probability measure defined in Proposition \ref{p:opt1} with $P_t=P(t,\chi^*_t)=p_t \chi^*_t+q_t$ so that $Z^\Q$ is a Brownian motion under $\Q$. Denote $\mu_t^\Q$ and $\tilde \mu_t^\P$ the $\Fc^Y_t=\Fc^\chi_t$ conditional expectation of $(Z_t^\Q-\beta, \Xi )^\top$ under respectively $\Q$ and $\P$. Our aim is to show that $\mu^\P$ defined in \eqref{eq:expmup} is indeed $\tilde \mu^\P$. 

Similarly to \eqref{eq:eqlaw}, $\Lc^\Q\left( -\beta, \Xi \right) =\Lc^\P\left( -\beta, \Xi  \right)$ so that $\mu_0^\Q=\tilde \mu_0^\P=\begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix}= \ab_0=\mu_0^\P$. Using
the filtering equations in \cite[Theorem 12.7]{liptser1977statistics} the conditional covariance matrix $\gamma^\P_t$ of $(Z_t^\Q-\beta, \Xi )^\top$ 
satisfies 
$$\frac{d\gamma^\P_t}{dt}=\sigma^2 e_1 e_1^\top-{\sigma^2}\left( e_1+ \gamma^\P_t\Sigma_t^{-1}\left(\rb_t-e_1\right)\right)\left( e_1+ \gamma^\P_t\Sigma_t^{-1}\left(\rb_t-e_1\right)\right)^\top \ . $$
Note that at $t=0$, $\gamma^\P_t\Sigma_t^{-1}$ is the identity matrix. Furthermore, by direct differentiation of the definition of $\Sigma_t$,  
$$\frac{d\Sigma_t}{dt}=\sigma^2 e_1 e_1^\top-{\sigma^2}\left( e_1+ \left(\rb_t-e_1\right)\right)\left( e_1+ \left(\rb_t-e_1\right)\right)^\top $$
and we obtain $\Sigma_t=\gamma^\P_t$.
Applying \cite[Theorem 12.7]{liptser1977statistics} under $\Q$, we easily find that $\Sigma_t$ is also the $\Q$ conditional covariance matrix. 
The same theorem under each probability also leads to 
\begin{align*}
    d\tilde \mu^\P_t&=
    \gamma\sigma^2  P(t,\chi^*_t)
    e_1 dt
    +\rb_t dY_t \ , \\
  d\mu^\Q_t &= \gamma\sigma^2  P(t,\chi^*_t)\rb_t dt-\sigma^2\rb_t \left(\rb_t-e_1\right)^\top \Sigma_t^{-1}(\mu^\Q_t-\mu^\P_t) dt+\rb_t dY_t \ .
\end{align*}
Note that $\tilde \mu^\P_t$ and $ \mu^\P_t$ have the same dynamics and initial conditions. Thus, they are equal. 
The equality $\tilde \mu^\P_t=\mu_t^\P$ and the expression of $X^*$ easily yield the inconspicuousness condition \eqref{eq:incons}.

\medskip

\textbf{Step 3: Optimality of the criterion of the informed trader. }
Taking the difference of $ d \mu^\P_t$ and $ d \mu^\Q_t$ we have
\begin{align}\label{eq:diff}
  d(\mu^\Q_t- \mu^\P_t) =&-\sigma^2\rb_t \left(\rb_t-e_1\right)^\top \Sigma_t^{-1}(\mu^\Q_t-\mu^\P_t) dt-  \gamma\sigma^2 P(t,\chi^*_t)
    \left(e_1-\rb_t \right) dt \ .
\end{align}
Integrating \eqref{eq:diff} and using the equality $\m_0^\P=\mu_0^\Q$ and the definition of $\Phi_{s,t}$ as the flow \eqref{eq:resolvent}, we have 
\begin{align*}
    \mu^\Q_t- \mu^\P_t
    =&- \int_0^t \gamma\sigma^2 P(s,\chi^*_s) \Phi_{s,t}\left(e_1- \rb_s \right) ds \ .
\end{align*}
Thus, 
\begin{align*}
    \mu^\Q_T- \mu^\P_T
    =&- \int_0^T \gamma\sigma^2 P(s,\chi^*_s) \Phi_{s,T}\left(e_1- \rb_T \right) ds- \int_0^T \gamma\sigma^2 P(s,\chi^*_s) \Phi_{s,T}\left(\rb_T- \rb_s \right) ds \ .
\end{align*}
Note that $\rb_T- \rb_s$ is proportional to $\ub$ and $\Phi_{s,T}\ub=\Phi\ub=0.$
By direct computations, we obtain 
$\wb^\top \Phi_{s,T}\left(e_1-\rb_T \right)=\wb^\top \Phi\left(e_1-\rb_T \right)=0$.
Thus, $\wb^\top\mu^\Q_T=\wb^\top\mu^\P_T=\wb^\top\ab_T+\wb^\top\frac{ \ub}{\sigma_{e} v}\chi^*_T=\wb^\top\begin{pmatrix}-m_\beta\\m_\Xi \end{pmatrix}+\frac{\chi^*_T - m }{ \sigma_{e} v}\wb^\top\ub
     \ $, where we used the expression of $\mu_T^\P$ and $\ab_T$. 
We now use \eqref{eq:A2} to obtain 
\begin{align*}
    0&=\wb^\top\left(\mu_T^\P-\begin{pmatrix}Z^\Q_T-\beta\\ \Xi \end{pmatrix}\right)=\wb^\top\left(\mu_T^\Q-\begin{pmatrix}Z^\Q_T-\beta\\ \Xi \end{pmatrix}\right)\\
    &=\frac{\chi^*_T - m }{ \sigma_{e} v}\wb^\top\ub-\wb^\top\begin{pmatrix}Z^\Q_T-\beta+m_\beta\\ \Xi -m_\Xi \end{pmatrix}=\frac{\sigma_{e}}{  v}(\chi^*_T - m )-\wb^\top\begin{pmatrix}Z^\Q_T-\beta+m_\beta\\ \Xi -m_\Xi \end{pmatrix} \ , 
\end{align*}
 and it leads to 
\begin{align*}
    \chi^*_T&= m+ \frac{v}{ \sigma_{e}}\wb^\top\begin{pmatrix}Z^\Q_T-\beta+m_\beta\\ \Xi -m_\Xi \end{pmatrix}=I(Z^\Q_T-\beta, \Xi ;\Nc(m,v^2))
\end{align*}
which is the optimality condition \eqref{eq:target}. Thus, we have the optimality of \eqref{eq:gausscontrol}. 

\medskip

\textbf{Step 4: Martingality of the price and its terminal condition.}
By direct computation 
$$dP(t,\chi^*_t)=\frac{dY_t}{\Lambda^{-1}-{\gamma\sigma^2}(T-t)} \ .$$
Additionally the inconspicuous trading property \eqref{eq:incons} implies that $Y$ is a $\Fc^Y$ martingale. Thus $P(t,\chi^*_t)$ is a $(\P,\Fc^Y)$ martingale with final value 
\begin{align*}
P(T,\chi_T^*)&=p_T \chi^*_T +q_T \\
& =\frac{\sigma_{e}}{v}\chi^*_T -\vare\gamma \chi^*_T -\frac{\sigma_e}{v}m +m_\Xi -\vare \gamma m_\beta \\
&= \wb^\top\begin{pmatrix}Z^\Q_T-\beta+m_\beta\\ \Xi -m_\Xi \end{pmatrix}
-\vare\gamma\chi^*_T
+m_\Xi -\vare \gamma m_\beta \\
&=  \Xi -\gamma \vare (\chi^*_T-Z^\Q_T+\beta)
= \Xi -\gamma \vare (X^*_T+\beta)
\end{align*}
which gives that we indeed have 
$P(t,\chi^*_t)=\E[ \Xi -\gamma \vare (X^*_T+\beta)|\Fc^{X^*+Z}_t].$


