\subsection{Proof of Theorem \ref{thm:prop}}
\label{proof-3}

   (1): Eq. \eqref{eq:pricedyn} (and by definition \eqref{eq:kyleslambda}) is a direct consequence of differentiation of $\fP^*_t(  Y )=p_t\chi_t(Y)+q_t.$  The value of the terminal price $\fP^*_T(  Y )$ is obtained in Step 4 of Proof of Theorem \ref{thm:main}.

   (2): The monotonicity and limits of $\Lambda $ as $\vare,\gamma \downarrow 0$ are direct consequences of taking limits in Lemma \ref{lem:v}. 

    (3): For the proof of \eqref{eq:utii}, by Proposition \ref{p:opt1}, when all the random variables are normally distributed, the expected utility of the informed trader conditional to her private information $\{ \Xi = \xi ;\beta=b\}$ is 
\begin{align*}
   & -e^{-\gamma u(0,0)}  
   \E\left[\exp\left(-\gamma \Gamma^c(Z_T-b, \xi )\right)\right]\\
   = &
-e^{-\gamma u(0,0)}  
   \E\Big[\exp\Big(-
   \frac{\gamma}{2} \Big(-2  \xi  (Z_T-b) -{\vare\gamma}(Z_T-b)^2\\
   & \quad \quad \quad
   +\frac{v}{\sigma_{e}}( \xi -m_\Xi  +{\varepsilon \gamma} (Z_T-b+m_\beta))^2 
       +2m ( \xi  +{\varepsilon \gamma} (Z_T-b)) \Big)
   \Big) \Big]  \ . 
\end{align*}
Without loss of generality, let $m_\Xi  = 0$ and $m_\beta = 0$. Then, by completing the square and simplifying, we have
\begin{align*}
   & -e^{-\gamma u(0,0)}  
   \E\left[\exp\left(-\gamma \Gamma^c(Z_T-b, \xi )\right)\right]\\
   = &
-e^{-\gamma u(0,0)}  
   \E\Big[\exp\Big(
\frac{\vare \gamma^2 v \Lambda}{2\sigma_e}\big(
Z_T - b - \frac{\sigma_e}{\vare \gamma v \Lambda} 
(m\vare \gamma -  \xi  \frac{v\Lambda}{\sigma_e})
\big)^2
   \Big) \Big] \\
   & \quad \times \exp\Big(
    -\frac{\gamma}{2}(\frac{ \xi ^2}{\vare \gamma} + \frac{\vare \gamma \sigma_e}{v\Lambda} m^2)
   \Big) \ . 
\end{align*}
Now, since $Z_T \sim N(0, \sigma^2 T)$, we have
\begin{align*}
   &\E\Big[\exp\Big(
\frac{\vare \gamma^2 v \Lambda}{2\sigma_e}\big(
Z_T - b - \frac{\sigma_e}{\vare \gamma v \Lambda} 
(m\vare \gamma -  \xi  \frac{v\Lambda}{\sigma_e})
\big)^2
   \Big) \Big] \\
 = &
 \frac{1}{\sqrt{2\pi \sigma^2 T}}
\int \exp\Big(
\frac{\vare \gamma^2 v \Lambda}{2\sigma_e}\big(
x - b - \frac{\sigma_e}{\vare \gamma v \Lambda} 
(m\vare \gamma -  \xi  \frac{v \Lambda}{\sigma_e})
\big)^2
\Big)
e^{-\frac{x^2}{2 \sigma^2 T}}
dx\\
    = &
\frac{1}{\sqrt{1-\frac{v\Lambda}{\sigma_e}\vare \gamma^2 \sigma^2 T}}    
\exp\left(
\frac{\varepsilon \gamma^2}{2}\frac{ v \Lambda}{\sigma_e} 
\frac{\alpha^2}{1 - \frac{v\Lambda}{\sigma_e}\vare \gamma^2 \sigma^2 T}\right) \ ,
 \end{align*}
 where 
    $$\alpha = 
 b + \frac{\sigma_e}{\varepsilon \gamma v \Lambda} \left( m \varepsilon \gamma -  \xi  \frac{v \Lambda}{\sigma_e} \right) 
 = b + m \frac{\sigma_e}{v\Lambda} - \frac{1}{\vare\gamma} \xi 
 \ . 
    $$
So, we have the expected utility of the informed trader as
\begin{align*}
   -e^{-\gamma u(0,0)} 
   \frac{1}{\sqrt{1-\frac{v\Lambda}{\sigma_e}\vare \gamma^2 \sigma^2 T}}   
   \exp\Big(
    -\frac{\gamma}{2}(\frac{ \xi ^2}{\vare \gamma} + \frac{\vare \gamma \sigma_e}{v\Lambda} m^2)
    + \frac{\varepsilon \gamma^2}{2}\frac{ v \Lambda}{\sigma_e} 
\frac{\alpha^2}{1 - \frac{v\Lambda}{\sigma_e}\vare \gamma^2 \sigma^2 T}
   \Big) \ . 
\end{align*}


    (4): For the proof of \eqref{eq:wealthMM}, we note that $-Y_t$ is the position of the market maker. Thus, the expected profit of the market maker is 
\begin{align}\label{eq:valuemm}
    &\E\left[-Y_T(V_f-P_T)-\int_0^T Y_s dP_s\right]=-\vare\gamma \E\left[Y_T(X_T+\beta)\right]=-\vare\gamma \E\left[Y_T(\chi^*_T-e_1^\top\mu^\P_T)\right]
\end{align}
where we have used the martingality of $P$, the expression for $V_f-P_T$ and the conditioning of $(X_T+\beta)$ in $\Fc^Y_T.$ 
Note that under $\P$, $Y$ is a Brownian motion and 
thanks to \eqref{eq:chi}, 
$$d\chi^*_t= \gamma\sigma^2 (p_t \chi^*_t+q_t)dt+d Y_t \ .$$
Thus, 
\begin{align*}
    d\E\left[Y_t\chi^*_t\right]=\gamma\sigma^2 p_t \E\left[Y_t\chi^*_t\right]dt+\sigma^2 dt \ ,
\end{align*}
which implies that 
$$\E\left[Y_T\chi^*_T\right]=\sigma^2\int_0^Te^{\gamma\sigma^2\int_s^T p_rdr}ds=\sigma^2\int_0^T\frac{1}{\left( 1-\Lambda{\gamma\sigma^2}(T-s)\right)}ds=-\frac{\ln \left( 1-\Lambda{\gamma\sigma^2}T\right)}{\Lambda\gamma} \ . $$
Expanding \eqref{eq:valuemm} using this expression, we obtain that this expected wealth is
\begin{align*}    &-\vare\gamma \E\left[Y_T\left(\chi^*_T(1-\vare\gamma \frac{\sigma^2T+\sigma^2_\beta}{\sigma_{e} v})+m_\beta + \frac{m \gamma \vare (\sigma^2 T + \sigma_\beta^2)}{\sigma_e v}
\right)\right]   \\ 
& =-\vare\gamma \left(1-\vare\gamma \frac{\sigma^2T+\sigma^2_\beta}{\sigma_{e} v}\right)\E\left[Y_T\chi^*_T\right]\\
    &=\frac{\vare}{\Lambda} \left(1-\vare\gamma \frac{\sigma^2T+\sigma^2_\beta}{\sigma_{e} v}\right)\ln(1-\gamma\sigma^2 T \Lambda) <0 \ .
\end{align*}







