Calculate $\bm{\alpha}^{(0)}, \bm{\vartheta}^{(0)}$ with $\bm{x}^{(0)} = (\bm{e_1},\cdots,\bm{e_M})^\intercal$, $\varphi_n^{(0)}=0.5$, $\phi_{n,m}^{(0)}=\frac{1}{N}$, $\rho_n^{(0)}=1$, $\zeta_{n,m}^{(0)}=\frac{1}{N}$, $\psi_n^{(0)}=1$, $\gamma_{n,m} = 0.5$;

\Repeat{$\frac{V_{\mathbb{P}_{3}}(\bm{x}^{(i+1)}, \bm{\varphi}^{(i+1)}, \bm{\phi}^{(i+1)}, \bm{\rho}^{(i+1)}, \bm{\zeta}^{(i+1)}, \bm{\psi}^{(i+1)})}{V_{\mathbb{P}_{3}}(\bm{x}^{(i)}, \bm{\varphi}^{(i)}, \bm{\phi}^{(i)}, \bm{\rho}^{(i)}, \bm{\zeta}^{(i)}, \bm{\psi}^{(i)})}- 1 \leq \epsilon_3$, where $\epsilon_3$ is a small positive number}{
Let $i\leftarrow i+1$;

Initialize $j = -1$; 

Calculate $\bm{\upsilon}^{(i,0)}$ with $\bm{x}^{(i)}, \bm{\varphi}^{(i)}, \bm{\phi}^{(i)}, \bm{\rho}^{(i)}, \bm{\zeta}^{(i)}, \bm{\psi}^{(i)}$;

Set $[\bm{\phi}^{(i,0)}, \bm{\rho}^{(i,0)}, \bm{\zeta}^{(i,0)}, \bm{\psi}^{(i,0)}, \bm{T}^{(i,0)}]\leftarrow$ $[\bm{\phi}^{(i)}, \bm{\rho}^{(i)}, \bm{\zeta}^{(i)}, \bm{\psi}^{(i)}, \bm{T}^{(i)}]$;

\Repeat{$\frac{V_{\mathbb{P}_{5}}(\bm{\phi}^{(i,j+1)}, \bm{\rho}^{(i,j+1)}, \bm{\zeta}^{(i,j+1)}, \bm{\psi}^{(i,j+1)})}{V_{\mathbb{P}_{5}}(\bm{\phi}^{(i,j)}, \bm{\rho}^{(i,j)}, \bm{\zeta}^{(i,j)}, \bm{\psi}^{(i,j)})}- 1 \leq \epsilon_1$, where $\epsilon_1$ is a small positive number}{
Let $j\leftarrow j+1$;

Obtain $[\bm{\phi}^{(i,j+1)}, \bm{\rho}^{(i,j+1)}, \bm{\zeta}^{(i,j+1)}, \bm{\psi}^{(i,j+1)}, \bm{T}^{(i,j+1)}]$ by solving Problem $\mathbb{P}_{5}$ with $\bm{\upsilon}^{(i,j)}$;

Update $\bm{\upsilon}^{(i,j+1)}$ with $[\bm{\phi}^{(i,j+1)}, \bm{\rho}^{(i,j+1)}, \bm{\zeta}^{(i,j+1)}, \bm{\psi}^{(i,j+1)}, \bm{T}^{(i,j+1)}]$;
}
Return $[\bm{\phi}^{(i,j+1)}, \bm{\rho}^{(i,j+1)}, \bm{\zeta}^{(i,j+1)}, \bm{\psi}^{(i,j+1)}]$ as a solution to Problem $\mathbb{P}_{5}$;

Set $[\bm{\phi}^{(i+1)}, \bm{\rho}^{(i+1)}, \bm{\zeta}^{(i+1)}, \bm{\psi}^{(i+1)}]$ $\leftarrow$ $[\bm{\phi}^{(i,j+1)}, \bm{\rho}^{(i,j+1)}, \bm{\zeta}^{(i,j+1)}, \bm{\psi}^{(i,j+1)}]$;

Initialize $j = -1$;

Set $[\bm{x}^{(i,0)}, \bm{\varphi}^{(i,0)}] \leftarrow [\bm{x}^{(i)}, \bm{\varphi}^{(i)}]$;

Initialize $[\bm{T}^{(i,0)}, \bm{A}^{(i,0)}, \bm{B}^{(i,0)}, C^{(i,0)}, \bm{P}_k^{(i,0)}]\leftarrow$ $[\bm{T}^{(i)}, \bm{A}^{(i)}, \bm{B}^{(i)}, C^{(i)}, \bm{P}_k^{(i)}]$, where $k \in \{1,2,\cdots,8\}$;

\Repeat{$\frac{V_{\mathbb{P}_{12}}(\bm{x}^{(i,j+1)}, \bm{\varphi}^{(i,j+1)}}{V_{\mathbb{P}_{12}}(\bm{x}^{(i,j)}, \bm{\varphi}^{(i,j)})}- 1 \leq \epsilon_2$, where $\epsilon_2$ is a small positive number}{
Let $j\leftarrow j+1$;

Obtain $[\bm{x}^{(i,j+1)}, \bm{\varphi}^{(i,j+1)}]$ of continuous values by solving Problem $\mathbb{P}_{12}$;

Update $[\bm{T}^{(i,j+1)}, \bm{A}^{(i,j+1)}, \bm{B}^{(i,j+1)}, C^{(i,j+1)}, \bm{P}_k^{(i,j+1)}$ with $[\bm{x}^{(i,j+1)}, \bm{\varphi}^{(i,j+1)}]$;
}

Return $[\bm{x}^{(i,j+1)}, \bm{\varphi}^{(i,j+1)}]$ as a solution to the SDR Problem $\mathbb{P}_{12}$;

Use the rank-1 approximation method to obtain the discrete association results as $\bm{x}_\star^{(i,j+1)}$.

Set $[\bm{x}^{(i+1)}, \bm{\varphi}^{(i+1)}]\leftarrow$ $[\bm{x}_\star^{(i,j+1)}, \bm{\varphi}^{(i,j+1)}]$;


Update $[\bm{\alpha}^{(i+1)}, \bm{\vartheta}^{(i+1)}]$ with $[\bm{x}^{(i+1)}, \bm{\varphi}^{(i+1)}, \bm{\phi}^{(i+1)}, \bm{\rho}^{(i+1)}, \bm{\zeta}^{(i+1)}, \bm{\psi}^{(i+1)}]$;
}
Return $[\bm{x}^{(i+1)}, \bm{\varphi}^{(i+1)}, \bm{\phi}^{(i+1)}, \bm{\rho}^{(i+1)}, \bm{\zeta}^{(i+1)}, \bm{\psi}^{(i+1)}]$ as a solution $[\bm{x}^\star, \bm{\varphi}^\star, \bm{\phi}^\star, \bm{\rho}^\star, \bm{\zeta}^\star, \bm{\psi}^\star]$ to Problem $\mathbb{P}_{3}$.
\end{algorithm}
\subsection{Performance comparison between optimization with and without dropping the rank-1 constraint}
In this section, we study which method (drop the rank-1 constraint or not) is better to solve Problem $\mathbb{P}_{10}$. 

First, we try to find a suitable penalty weight parameter $\varpi$ to perform optimization of Problem $\mathbb{P}_{12}$. In Fig. \ref{fig.comparison_varpi}, the final penalty term values after solving Problem $\mathbb{P}_{12}$ of different penalty weights, i.e., $\varpi$ are given. The value of the penalty term on the Y-axis of Fig. \ref{fig.comparison_varpi} is the value of $(\text{Tr}(\bm{S}) - \lVert \bm{S} \rVert_2)$. From this figure, it is known that a larger $\varpi$ would be better to force the penalty term to approach zero. However, when $\varpi$ is greater than 175, the order of the penalty term value will not change much. The larger numbers of penalty weights do not significantly affect the value of the penalty term. Therefore, we set the penalty weight $\varpi$ as 175.

In Fig. \ref{fig.comparison_sdp}, we compare the objective function value of Problem $\mathbb{P}_{1}$ with the solutions to Problem $\mathbb{P}_{10}$ by dropping or retaining the rank-1 constraint (i.e., $\text{rank} (\bm{S}) = 1$). Three use-server configurations are chosen as $(N, M) \in \{(10, 2), (20, 3), (30, 4)\}$. The results in Fig. \ref{fig.comparison_sdp} indicate that retaining the rank-1 constraint provides a slight improvement over dropping it. The reason for those results is that dropping the rank-1 constraint may lead to higher-rank or less structured results, which also introduces instability or numerical issues. Thus, in this paper, retaining the rank-1 constraint method is chosen to solve the SDP problem.

