\begin{talign}
    &cost^{(s)}_{n,m} = \omega_t (T^{(ut)}_{n,m} + T^{(sp)}_{n,m} + T^{(sg)}_{n,m} + T^{(bp)}_{n,m} + T^{(sv)}_{n,m}) \nonumber \\ 
    &+ \omega_e (E^{(ut)}_{n,m} + E^{(sp)}_{n,m} + E^{(sg)}_{n,m}),  cost^{(s)}_{n,m} \leq \frac{c_{n,m}x_{n,m}\varphi_nd_n}{\vartheta_{n,m}^{(s)}} \nonumber \\
    &\Rightarrow \omega_t (T^{(ut)}_{n,m} + T^{(sp)}_{n,m} + T^{(sg)}_{n,m} + T^{(bp)}_{n,m} + T^{(sv)}_{n,m}) \nonumber \\ 
    &+ \omega_e (E^{(ut)}_{n,m} + E^{(sp)}_{n,m} + E^{(sg)}_{n,m})\leq \frac{c_{n,m}x_{n,m}\varphi_nd_n}{\vartheta_{n,m}^{(s)}} \nonumber \\
    &\Rightarrow \omega_t(T^{(ut)}_{n,m} + T^{(sp)}_{n,m} + T^{(sg)}_{n,m} + T^{(bp)}_{n,m} + T^{(sv)}_{n,m}) \nonumber \\ 
    &+ \omega_e \{\frac{x_{n,m}\rho_np_n\varphi_nd_n}{r_{n,m}} + \kappa_mx_{n,m}\varphi_nd_n\eta_m(\gamma_{n,m}\zeta_{n,m}f_m)^2 \nonumber \\ 
