    &\omega_t T^{(u)}_n + \omega_e \kappa_n(1-\varphi_n)d_n\eta_n(\psi_nf_n)^2 - \frac{c_n(1-\varphi_n)d_n}{\vartheta_n^{(u)}}\leq 0,\\
    &\omega_t T^{(s)}_{n,m} \!+ \!\omega_e \{\frac{x_{n,m}\rho_np_n\varphi_nd_n}{r_{n,m}} \!+ \!\kappa_mx_{n,m}\varphi_nd_n\eta_m(\gamma_{n,m}\zeta_{n,m}f_m)^2 \nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b [(1-\gamma_{n,m})\zeta_{n,m}f_m]^2\} \nonumber \\
    &- \frac{c_{n,m}x_{n,m}\varphi_nd_n}{\vartheta_{n,m}^{(s)}} \leq 0, \\
