\section{Proof of \textbf{Lemma \ref{lemma_p2top3}}}\label{append_lemma_p2top3}
\begin{proof}
Here we analyze part of the KKT condition of Problem $\mathbb{P}_{2}$ to facilitate our subsequent analysis. We introduce non-negative variables $\alpha^{(u)}_n$ and $\alpha^{(s)}_{n,m}$ as the multipliers. Let $\bm{\alpha^{(u)}}:=[\alpha^{(u)}_n]|_{n\in\mathcal{N}}$, $\bm{\alpha^{(s)}}:=[\alpha^{(s)}_{n,m}]|_{n\in\mathcal{N},m\in\mathcal{M}}$, and $\bm{\alpha}:=\{\bm{\alpha^{(u)}}, \bm{\alpha^{(s)}}\}$. The Lagrangian function is given as follows:
\begin{talign}
    &L_{\mathbb{P}_{2}}(\bm{x},\bm{\varphi},\bm{\gamma},\bm{\phi},\bm{\rho},\bm{\zeta},\bm{\psi}, \bm{\vartheta}, \bm{T}, \bm{\alpha}) \nonumber \\
    &= - \sum_{n \in \mathcal{N}} \vartheta_n^{(u)} -\sum_{n \in \mathcal{N}} \sum_{m \in \mathcal{M}} \vartheta_{n,m}^{(s)} \nonumber \\
    &+ \sum_{n \in \mathcal{N}} \alpha^{(u)}_n \cdot [\vartheta_n^{(u)}cost^{(u)}_n - c_n(1 - \varphi_n)d_n] \nonumber \\
    &+ \sum_{n \in \mathcal{N}}\sum_{m \in \mathcal{M}}\alpha^{(s)}_{n,m} \cdot [\vartheta_{n,m}^{(s)}cost^{(s)}_{n,m} - c_{n,m}x_{n,m}\varphi_n d_n] \nonumber \\
    &+ \hat{L}_{\mathbb{P}_{2}},
\end{talign}
where $\hat{L}_{\mathbb{P}_{2}}$ is the remaining Lagrangian terms that we don't care about. Next, we analyze some stationarity and complementary slackness properties of $L_{\mathbb{P}_{2}}$.

\textbf{Stationarity:}
\begin{talign}
    &\frac{\partial L_{\mathbb{P}_{2}}}{\partial \vartheta_n^{(u)}} = -1 + \alpha^{(u)}_n cost^{(u)}_n=0, \forall n \in \mathcal{N},\\
    &\frac{\partial L_{\mathbb{P}_{2}}}{\partial \vartheta_{n,m}^{(s)}} = -1 + \alpha^{(s)}_{n,m} cost^{(s)}_{n,m}=0, \forall n \in \mathcal{N}, \forall m \in \mathcal{M}.
\end{talign}

\textbf{Complementary slackness:}
\begin{talign}
    &\alpha^{(u)}_n \cdot [\vartheta_n^{(u)}cost^{(u)}_n - c_n(1 - \varphi_n)d_n] = 0,\forall n \in \mathcal{N},\\
    &\alpha^{(s)}_{n,m} \cdot (\vartheta_{n,m}^{(s)}cost^{(s)}_{n,m} - c_{n,m}x_{n,m}\varphi_n d_n) = 0, \nonumber \\
    &\forall n \in \mathcal{N}, \forall m \in \mathcal{M}.
\end{talign}
Thus, at KKT points of Problem $\mathbb{P}_{2}$, we can obtain that 
\begin{talign}
    &\alpha^{(u)}_n = \frac{1}{cost^{(u)}_n},\\
    &\alpha^{(s)}_{n,m} = \frac{1}{cost^{(s)}_{n,m}},\\
    &\vartheta_n^{(u)} = \frac{c_n(1 - \varphi_n)d_n}{cost^{(u)}_n},\\
    &\vartheta_{n,m}^{(s)} = \frac{c_{n,m}x_{n,m}\varphi_n d_n}{cost^{(s)}_{n,m}}.
\end{talign}
Based on the above discussion, Problem $\mathbb{P}_{2}$ can be transformed into Problem $\mathbb{P}_{3}$.

\textbf{Lemma \ref{lemma_p2top3}} holds.
\end{proof}

\section{Proof of \textbf{Lemma \ref{lemma_p4top5}}}\label{append_lemma_p4top5}
\begin{proof}
We introduce one auxiliary variable $\upsilon^{(s)}_{n,m}$, where
\begin{talign}
    \upsilon^{(s)}_{n,m} = \frac{1}{2x_{n,m}\rho_np_n\varphi_nd_nr_{n,m}}.
\end{talign}
Then, $cost^{(s)}_{n,m}$ can be rewritten as:
\begin{talign}
    &\widetilde{cost}^{(s)}_{n,m} = \omega_t T^{(s)}_{n,m} + \omega_e \{(x_{n,m}\rho_np_n\varphi_nd_n)^2\upsilon^{(s)}_{n,m} + \frac{1}{4r_{n,m}^2\upsilon^{(s)}_{n,m}}\nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m(\gamma_{n,m}\zeta_{n,m}f_m)^2 \nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b [(1-\gamma_{n,m})\zeta_{n,m}f_m]^2\}. \label{eq.vartheta_s_new}
\end{talign}
Since $x_{n,m}, \varphi_n, \gamma_{n,m}, \upsilon^{(s)}_{n,m}$ is given, Equation (\text{\ref{eq.vartheta_s_new}}) is a convex function.

Let $\chi(\rho_n) = x_{n,m}\rho_np_n\varphi_nd_n$ and $\varsigma(\phi_{n,m},\rho_n) = r_{n,m}$, where $r_{n,m} = \phi_{n,m}b_m\log_2(1 + \frac{\rho_np_ng_{n,m}}{\sigma^2\phi_{n,m}b_m})$. It's easy to know that $\chi(\rho_n)$ is convex of $\rho_n$ and $\varsigma(\phi_{n,m},\rho_n)$ is jointly concave of $(\phi_{n,m},\rho_n)$. We define two following functions:
\begin{talign}
    &\mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},T^{(s)}_{n,m}) = \omega_t T^{(s)}_{n,m} + \omega_e \{\frac{\chi(\rho_n)}{\varsigma(\phi_{n,m},\rho_n)} \nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m(\gamma_{n,m}\zeta_{n,m}f_m)^2 \nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b [(1-\gamma_{n,m})\zeta_{n,m}f_m]^2\},
\end{talign}
\begin{talign}
    &\mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},T^{(s)}_{n,m}) = \omega_t T^{(s)}_{n,m} \nonumber \\ 
    &+ \omega_e \{\chi(\rho_n)^2\upsilon^{(s)}_{n,m} + \frac{1}{4\varsigma(\phi_{n,m},\rho_n)^2\upsilon^{(s)}_{n,m}}\nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m(\gamma_{n,m}\zeta_{n,m}f_m)^2 \nonumber \\ 
    &+ \kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b [(1-\gamma_{n,m})\zeta_{n,m}f_m]^2\}.
\end{talign}
The partial derivative of $T^{(s)}_{n,m}$ is given by
\begin{talign}
    \frac{\partial\mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial T^{(s)}_{n,m}} = \omega_t,\\
    \frac{\partial\mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial T^{(s)}_{n,m}} = \omega_t.
\end{talign}
We can easily get that
\begin{talign}
    \frac{\partial\mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial T^{(s)}_{n,m}} = \frac{\partial\mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial T^{(s)}_{n,m}}.
\end{talign}
The partial derivative of $\zeta_{n,m}$ is
\begin{talign}
    &\frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \zeta_{n,m}} = 2\kappa_mx_{n,m}\varphi_nd_n\eta_m\zeta_{n,m}(\gamma_{n,m}f_m)^2 \nonumber \\
    &+ 2\kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b \zeta_{n,m}[(1-\gamma_{n,m})f_m]^2,\\
    &\frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \zeta_{n,m}} = 2\kappa_mx_{n,m}\varphi_nd_n\eta_m\zeta_{n,m}(\gamma_{n,m}f_m)^2 \nonumber \\
    &+ 2\kappa_mx_{n,m}\varphi_nd_n\eta_m \omega_b \zeta_{n,m}[(1-\gamma_{n,m})f_m]^2.
\end{talign}
We find that
\begin{talign}
    \frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \zeta_{n,m}} = \frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \zeta_{n,m}}.
\end{talign}
The partial derivative of $\rho_n$ is shown as follows:
\begin{talign}
    &\frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \rho_n} \nonumber \\ 
    &= \omega_e\frac{\frac{\partial \chi(\rho_n)}{\partial \rho_n}\varsigma(\phi_{n,m},\rho_n) - \chi(\rho_n) \frac{\partial \varsigma(\phi_{n,m},\rho_n)}{\partial \rho_n}}{\varsigma(\phi_{n,m},\rho_n)^2},\\
    &\frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \rho_n} \nonumber \\
    &= \omega_e (2\upsilon^{(s)}_{n,m} \chi(\rho_n) \frac{\partial \chi(\rho_n)}{\partial \rho_n} - \frac{1}{2\upsilon^{(s)}_{n,m} \varsigma(\phi_{n,m},\rho_n)^3}\frac{\partial \varsigma(\phi_{n,m},\rho_n)}{\partial \rho_n}).
\end{talign}
When $\upsilon^{(s)}_{n,m} = \frac{1}{2x_{n,m}\rho_np_n\varphi_nd_nr_{n,m}}$, we can get that
\begin{talign}
    \frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \rho_n} = \frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \rho_n}.
\end{talign}
The partial derivative of $\phi_{n,m}$ is
\begin{talign}
    &\frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \phi_{n,m}} = -\frac{\omega_e\chi(\rho_n)}{\varsigma(\phi_{n,m},\rho_n)^2}\frac{\partial \varsigma(\phi_{n,m},\rho_n)}{\partial \phi_{n,m}},\\
    &\frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \phi_{n,m}} = -\frac{\omega_e}{2\upsilon^{(s)}_{n,m}\varsigma(\phi_{n,m},\rho_n)^3}\frac{\partial \varsigma(\phi_{n,m},\rho_n)}{\partial \phi_{n,m}}.
\end{talign}
When $\upsilon^{(s)}_{n,m} = \frac{1}{2x_{n,m}\rho_np_n\varphi_nd_nr_{n,m}}$, we can obtain that
\begin{talign}
    \frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \phi_{n,m}} =\frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial \phi_{n,m}}.
\end{talign}
Based on the above discussion, we can obtain that
\begin{talign}
     \frac{\partial \mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial (\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})} =\frac{\partial \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}{\partial (\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})}.
\end{talign}
Besides, it's easy to know that 
\begin{talign}
    &\mathcal{F}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m})\nonumber \\ 
    &= \mathcal{G}(\rho_n,\phi_{n,m},\zeta_{n,m},\vartheta^{(s)}_{n,m},T^{(s)}_{n,m}),
\end{talign}
when $\upsilon^{(s)}_{n,m} = \frac{1}{2x_{n,m}\rho_np_n\varphi_nd_nr_{n,m}}$. Therefore, the function of $\mathcal{F}(\cdot)$ is the same as that of $\mathcal{G}(\cdot)$. Let $\bm{\upsilon^{(s)}} := [\upsilon^{(s)}_{n,m}|_{\forall n \in \mathcal{N},\forall m \in \mathcal{M}}]$. Problem $\mathbb{P}_{4}$ can be transformed into Problem $\mathbb{P}_{5}$. In Problem $\mathbb{P}_{5}$, if given $\bm{\upsilon^{(s)}}$, it would be a convex optimization problem.

At the $i$-th iteration, if we first fix $\bm{\upsilon}^{\bm{(s)}(i-1)}$, Problem $\mathbb{P}_{5}$ would be a concave optimization problem. Then we optimize $\bm{\phi}^{(i)},\bm{\rho}^{(i)},\bm{\zeta}^{(i)}$, $\bm{\psi}^{(i)}, \bm{T}^{(i)}$. After we obtain the results of them, we then update $\bm{\upsilon}^{\bm{(s)}(i)}$ according to those results. Because the alternative optimization of the Problem $\mathbb{P}_{5}$ is non-decreasing, as $i\rightarrow\infty$, we can finally obtain the optimal solutions of Problem $\mathbb{P}_{5}$ (i.e., $\bm{\phi}^{(\star)}$, $\bm{\rho}^{(\star)}$, $\bm{\zeta}^{(\star)}$, $\bm{\psi}^{(\star)}$, $\bm{T}^{(\star)}$, $\bm{\upsilon}^{\bm{(s)}(\star)}$). We know that $\upsilon^{(s)}_{n,m} = \frac{1}{2x_{n,m}\rho_np_n\varphi_nd_nr_{n,m}}$. Thus, with $\bm{\upsilon}^{\bm{(s)}(\star)}$, we can find $\bm{\phi}^{(\star)},\bm{\rho}^{(\star)},\bm{\zeta}^{(\star)},\bm{\psi}^{(\star)}, \bm{T}^{(\star)}$, which is a stationary point of Problem $\mathbb{P}_{5}$.

\textbf{Lemma \ref{lemma_p4top5}} is proven.
\end{proof}

\section{Proof of \textbf{Lemma \ref{lemma_gamma}}}\label{append_lemma_gamma}
\begin{proof}
    We first analyze $\vartheta_{n,m}^{(s)}cost_{n,m}^{(s)}$, and write the explicit expression of it:
\begin{talign}
    &\vartheta_{n,m}^{(s)}cost_{n,m}^{(s)} \nonumber \\
    &= \vartheta_{n,m}^{(s)}\omega_t T^{(s)}_{n,m} + \vartheta_{n,m}^{(s)}\omega_e \frac{\rho_n p_n d_n}{r_{n,m}}x_{n,m}\varphi_n \nonumber \\
    &+ \vartheta_{n,m}^{(s)}\omega_e \{\kappa_m d_n \eta_m\zeta_{n,m}^2 f_m^2 [\gamma_{n,m}^2 + \omega_b (1-\gamma_{n,m})^2]x_{n,m}\varphi_n\},
\end{talign}
where $\gamma_{n,m}^2 + \omega_b (1-\gamma_{n,m})^2$ is independent of the others except $T^{(s)}_{n,m}$. when $\gamma_{n,m} = \frac{\omega_b}{1+\omega_b}$, $\gamma_{n,m}^2 + \omega_b (1-\gamma_{n,m})^2$ takes the minimum value. In $T^{(s)}_{n,m}$, the terms $T^{(sp)}_{n,m}$, $T^{(sg)}_{n,m}$, and $T^{(sv)}_{n,m}$ are related to $\gamma_{n,m}$. Since $T^{(sv)}_{n,m}$ is generally much smaller than $T^{(sp)}_{n,m}$ and $T^{(sg)}_{n,m}$, we only focus on $T^{(sp)}_{n,m}$ and $T^{(sg)}_{n,m}$ here. It's easy to know that when $\gamma_{n,m} = \frac{1}{1+\omega_b}$, $T^{(sp)}_{n,m} + T^{(sg)}_{n,m}$ takes the minimum value according to basic inequality. Following are the detailed steps:
\begin{talign}
    T^{(sp)}_{n,m} + T^{(sg)}_{n,m} \geq 2\sqrt{T^{(sp)}_{n,m} T^{(sg)}_{n,m}},
\end{talign}
where if and only if $T^{(sp)}_{n,m} =T^{(sg)}_{n,m}$, ``$=$'' can be obtained.
\begin{talign}
    &\quad \quad T^{(sp)}_{n,m} =T^{(sg)}_{n,m},\nonumber \\
    &\Rightarrow \frac{x_{n,m}\varphi_nd_n\eta_m}{\gamma_{n,m}\zeta_{n,m}f_m} = \frac{x_{n,m}\varphi_nd_n\omega_b\eta_m}{(1-\gamma_{n,m})\zeta_{n,m}f_m}, \nonumber \\
    &\Rightarrow \gamma_{n,m} = \frac{1}{1+\omega_b}.
\end{talign}
We set $\omega_b = 1$ and then $\frac{\omega_b}{1+\omega_b} = \frac{1}{1+\omega_b}$, in which case, $cost_{n,m}^{(s)}$ would take the minimum leading to Problem $\mathbb{P}_{7}$ take the maximum value. Based on the above discussion, we can obtain the optimal value of $\gamma_{n,m}$ that $\gamma_{n,m}^\star = \frac{\omega_b}{1+\omega_b}$ or $\frac{1}{1+\omega_b} = \frac{1}{2}$. 

Thus, \textbf{Lemma \ref{lemma_gamma}} is proven.
\end{proof}

\section{Proof of \textbf{Lemma \ref{lemma_p8top9}}}\label{append_lemma_p8top9}
\begin{proof}
Let $\bm{P}_0:=\bm{I}_{NM+N\times N} \bm{I}_{N\rightarrow NM} \text{diag}(\bm{B})\bm{e}_{N+1,NM+N}$ and we can represent $\sum_{n \in \mathcal{N}}\sum_{m \in \mathcal{M}}B_{n,m} x_{n,m} \varphi_n$ as $\bm{Q}^\intercal \bm{P}_0 \bm{Q}$. Let $\bm{W}_0^\intercal:=\bm{A}^\intercal\bm{e}_{1,N}$ and the term $\sum_{n \in \mathcal{N}}A_n \varphi_n$ can be rewritten as $\bm{W}_0^\intercal \bm{Q}$.  Let $P_{0,n}^{(T_u)}:= - \frac{\alpha^{(u)}_n \vartheta_n^{(u)} \omega_t d_n\eta_n}{\psi_nf_n}$, $P_1^{(T_u)}:=\sum_{n \in \mathcal{N}}\frac{\alpha^{(u)}_n \vartheta_n^{(u)} \omega_t d_n\eta_n}{\psi_nf_n}$, $\bm{P}_0^{(T_u)}:=[P_{0,n}^{(T_u)}]|_{n \in \mathcal{N}}$, and ${\bm{P}_2^{(T_u)}}^\intercal:={\bm{P}_0^{(T_u)}}^\intercal\bm{e}_{1,N}$. Then, the constraint (\ref{Tu_constr1}) can be represented by 
\begin{talign}
    {\bm{P}_2^{(T_u)}}^\intercal \bm{Q} + P_1^{(T_u)} \leq T^{(u)}.
\end{talign}
Let 
\begin{talign}
&P_{0,n,m}^{(T_s)}:=\frac{d_n}{r_{n,m}} + \frac{d_n\eta_m}{\gamma_{n,m}\zeta_{n,m}f_m} + \frac{d_n\omega_b\eta_m}{(1-\gamma_{n,m})\zeta_{n,m}f_m},\\
&\bm{P}_0^{(T_s)}:=[P_{0,n,m}^{(T_s)}]|_{n \in \mathcal{N},m \in \mathcal{M}},\\
&P_1^{(T_s)}:=\sum_{n \in \mathcal{N}}\sum_{m \in \mathcal{M}}\frac{S_b}{R_m} + \text{max}_{m^\prime\in\mathcal{M}\setminus\{m\}}\frac{\eta_v}{(1-\gamma_{n,m^\prime})\zeta_{n,m^\prime}f_m^\prime}.
\end{talign}
Similar to $\bm{P}_0$, let 
\begin{talign}
\bm{P}_2^{(T_s)}:= \bm{I}_{NM+N\times N} \bm{I}_{N\rightarrow NM} \text{diag}(\bm{P}_0^{(T_s)})\bm{e}_{N+1,NM+N}.
\end{talign}
Then, the constraint (\ref{Ts_constr1}) can be transformed into
\begin{talign}
    \bm{Q}^\intercal \bm{P}_0^{(T_s)} \bm{Q} + P_1^{(T_s)} \leq T^{(s)}.
\end{talign}
