\section{Csisz\'ar's Expurgated Error Exponents}
In this section, we introduce definitions and summarize existing expurgated results in JSCC that are relevant to this work.
%
The source reliability function \cite[Ch.~9]{csiszar2011information} is given by
\begin{align}
	e(R, P_V) &\triangleq \min_{Q: H(Q) \geq R} D(Q \| P_V),
\end{align}
or, in the dual domain \cite{Jel68}, as
\begin{align}
	e(R, P_V) &= \sup_{\rho \geq 0} \Big\{ \rho R - E_s(\rho, P_V) \Big\},
\end{align}
where
\begin{align}
	E_s(\rho, P_V) &\triangleq \log \bigg( \sum_{v \in \mcl{V}} P_V(v)^{\frac{1}{1+\rho}}\bigg)^{1+\rho}.
\end{align}
The weak channel expurgated exponent is given by
\begin{align} \label{eq-weak-exp}
	\!E_{\mathrm{ex}}^{\prime}(Q, R) \!
	\triangleq \!\! \min_{\substack{P_{X\bar{X}}: P_X = Q \\ I_P(X; \bar{X}) \leq R}} \mathbb{E}_P\big[ d_B(X, \bar{X}) \big] \!+\! I_P(X; \bar{X})\! -\! R,
\end{align}
where $\!d_B(x, \bar{x}) \!\!\triangleq\!\! -\log \sum_y \sqrt{W(y|x) W(y|\bar{x})}$
is the Bhattacharyya distance.
This expression is referred to as ``weak'' since it is looser than the Csisz\'ar-K\"orner-Marton (CKM) expurgated exponent \cite{1056281}, given by
\begin{align}
	E_{\mathrm{ex}}(Q, R) 
	&\triangleq \!\!\! \min_{\substack{P_{X\bar{X}}\\ P_X=P_{\bar{X}}=Q\\I_P(X;\bar{X})\leq R}} \!\!\! \mathbb{E}_P\!\big[d_B(X,\bar{X}) \big] \!+\! I_P(X;\bar{X}) \! - \! R.
\end{align}
The dual expression of~\eqref{eq-weak-exp}, as given in~\cite[Eq.~9]{8006660}, is
\begin{align}
	E_{\mathrm{ex}}^{\prime}(Q, R) = \sup_{\rho \geq 1} E_{\mathrm{x}}^{\prime}({Q}, \rho) - \rho R,
\end{align}
where
\begin{align}
	E_{\mathrm{x}}^{\prime}({Q}, \rho) \triangleq
	\min _{Q^{\prime}}-\rho \sum_x Q(x) \log \sum_{\bar{x}} Q^{\prime}(\bar{x}) \, e^{-\frac{d_B(x, \bar{x})}{\rho}}.
\end{align}
