As a first step, we consider an arbitrary partition of the source sequences and derive an error bound for the code in Lemma~\ref{lem-expurgation-jscc}.
\begin{lemma} \label{lem-primal-given}
%	, where $|\mcl{T}^n(Q_c)| > |\mathcal{A}_c|$ for all $c = 1, \ldots, m$.
	Let $\mcl{A}_1, ..., \mcl{A}_m$ be a given arbitrary partition of the source sequence, each associated with a codeword distribution $Q_c \in \mathcal{P}_n(\mathcal{X})$.
%	, each containing one or more full type classes. 
%	For each source sequence $\bs{v} \in \mcl{A}_c$, the codeword $\bs{x}(\bs{v}) \in \mathcal{X}^n$ is drawn independently and uniformly from the type class $\mcl{T}^n(Q_c)$, 
%	where the size of the type class must satisfy $\left|\mathcal{T}^n(Q_c)\right| \geq \left|\mcl{A}_c\right|$ for all $c = 1, \ldots, m$.
	Then there exists a codebook such that
	\begin{align}
		p_e \, \dot{\leq} 
		\sum_{c=1}^{m} \sum_{i \in \Lambda_c} \exp\!\left(\!-n\!\left[t{e}\!\left(\frac{R_i}{t}, P_V\!\right)\! +\! E_{\mathrm{ex}}^{\prime}(Q_c, R_i) \right]\!\right).
	\end{align}
\end{lemma}
In the next theorem, we consider the partitioning that maximizes the exponent in Lemma~\ref{lem-primal-given}.

\begin{theorem} \label{thm-primal-best-partition}
	For a given set of codeword distributions $\mcl{Q}_m = \{ Q_1, Q_2, \ldots , Q_m \}$, 
	there exists a partition of the source sequences into $m$ disjoint sets such that the following exponent is achievable\
	\begin{align}
		\!\!\!{E}_{J, \mathrm{ex}}^{\mathrm{primal}}(t, \mcl{Q}_m)
		&\!\triangleq\min _{R}\!\left[t {e}\Big(\frac{{R}}{t},  P_V\Big) \!+\! \max _{{Q} \in \mcl{Q}_m} \!\! {E}_{\mathrm{ex}}^{\prime}({Q}, {R})\right] .
	\end{align}
\end{theorem}

\begin{remark}
	If  the distribution in $\mcl{Q}_m$ that maximizes $ {E}_{\mathrm{ex}}^{\prime}({Q}, {R})$ is independent of $R$, 
	then 
	\begin{align} \label{eq-remark-primal}
		\!\!{E}_{J, \mathrm{ex}}^{\mathrm{primal}}(t, \mcl{Q}_m)
		&\!=\!\!\max _{{Q}  \in \mcl{Q}_m} \! \min _{R}\!\left[t {e}\Big(\frac{{R}}{t},  P_V\Big)\! + \! {E}_{\mathrm{ex}}^{\prime}({Q}, {R})\right] .
	\end{align}
\end{remark}
Note that the exponent in \eqref{eq-remark-primal} can be achieved without partitioning, 
by generating all codewords from the type class of the distribution in $\mcl{Q}_m$ that maximizes ${E}_{\mathrm{ex}}^{\prime}({Q}, {R})$.
However, if it were known in advance that all codewords share the same composition,
%, as in the setting used by Csisz\'ar to derive $E_{J, 1}^{\mathrm{ex}}(t, P_V)$ given in \eqref{eq-csiszar-org-1},
then ${E}_{\mathrm{ex}}^{\prime}(Q, R)$ in~\eqref{eq-remark-primal} would be replaced by ${E}_{\mathrm{ex}}(Q, R)$, resulting in a higher exponent. 

