Next theorem considers the partitioning that maximizes the exponent in Lemma~\ref{lem-dual-given}.

\begin{theorem} \label{thm-dual-best-partition}
	Consider a given set of codeword distributions $\mcl{Q}_m = \{ Q_1, Q_2, \ldots, Q_m \}$, as described in Theorem~\ref{thm-primal-best-partition}. 
	Then, there exists a partition of the source sequences into $m$ disjoint sets such that the following exponent is achievable\
	\begin{align} \label{eq-exp-dual}
		&{E}_{J, \mathrm{ex}}^{\mathrm{dual}}(t, \mcl{Q}_m)
		\triangleq \sup _{\lambda\geq 1}\Big\{\overline{E}^{\prime}_{\mathrm{x}}\big(\mcl{Q}_m, \lambda\big)-t{E}_{\mathrm{s}}\big(\lambda, P_V\big)\Big\},
	\end{align}
	where 
	\begin{align}
		\overline{E}^{\prime}_{\mathrm{x}}\big(\mcl{Q}_m, \lambda\big) \triangleq \min_R \sup_{\rho \geq 1} \, E_{\mathrm{x}}^{\prime}(\mcl{Q}_m, \rho) + \big(\lambda  - \rho\big)R,
	\end{align}
	and
	$E_{\mathrm{x}}^{\prime} (\mcl{Q}_m, \rho) \triangleq \max_{Q \in \mcl{Q}_m} {E}_{\mathrm{x}}^{\prime} (Q, \rho)$.
\end{theorem}

