\subsection{Proof of Lemma \ref{lem-dual-given}}
The proof closely follows the approach in~\cite[Sec.~III.C]{8006660}.
We consider the code from Lemma~\ref{lem-expurgation-jscc}, and use the following decoding metric
\begin{align}
	q(\bs{v}, \bs{x}, \bs{y})=W^n(\bs{y} | \bs{x}) \exp\!\big(2 k D(P_i \| P_V)\big)
\end{align}
if $\bs{v} \in \mcl{T}^k(P_i)$.
Then, for any $s > 0$, we can upper bound $p_e\big(\bs{v}, j, \msf{C}\big)$ as
\begin{align}
	\!\!p_e\big(\bs{v}, j, \msf{C}\big)\!
	&= \mathbb{P}\!\left[\bigcup_{\bar{\bs{v}}\in \mcl{T}^k(P_j)} \!\!\! q(\bs{\bar{v}}, \bs{x}_{\bar{\bs{v}}}, \bs{Y})  \geq  q(\bs{v}, \bs{x}_{\bs{v}}, \bs{Y}) \right]\\
	&= \mathbb{P}\!\left[\bigcup_{\bar{\bs{v}}\in \mcl{T}^k(P_j)} \!\!\! q(\bs{\bar{v}}, \bs{x}_{\bar{\bs{v}}}, \bs{Y})^s  \geq  q(\bs{v}, \bs{x}_{\bs{v}}, \bs{Y})^s \right]\\
	& \leq \sum_{\bs{y}} W^n(\bs{y}|\bs{x}_{\bs{v}}) \!\! \sum_{\bar{\bs{v}}\in \mcl{T}^k(P_j)} \left(\frac{q(\bs{\bar{v}}, \bs{x}_{\bar{\bs{v}}}, \bs{y})}{q(\bs{v}, \bs{x}_{\bs{v}}, \bs{y})} \right)^s.
\end{align}
Substituting the decoding metric and setting $s = \frac{1}{2}$, we obtain
\begin{align}
	\begin{split}
		p_e\big(\bs{v}, j, \msf{C}\big)\,
		&\leq \left(\frac{\exp \left(k D\left(P_j \| P_V\right)\right)}{\exp \left(k D\left(P_i \| P_V\right)\right)}\right) \\
		&\times \sum_{\bar{\bs{v}} \in \mcl{T}^k(P_j)} \sum_{\bs{y}} \sqrt{W^n(\bs{y} | \bs{x}_{\bs{v}}) W^n(\bs{y} | \bs{x}_{\bar{\bs{v}}})}.
	\end{split}
\end{align}
If we assume $\rho_{ij} \geq 1$ for all $(i, j)$, we can use Hölder's inequality \cite[Problem~4.15.f]{gallager} to move the summation over $\bs{\bar{v}}$ outside, as follows
\begin{align}
	\begin{split}
		\!\!p_e\big(\bs{v}, j, \msf{C}\big)^{\frac{1}{\rho_{ij}}} \!&\leq 
		\left(\frac{\exp (k D(P_j \| P_V))}{\exp(k D(P_i \| P_V))}\right)^{\frac{1}{\rho_{i j}}}\\
		&\times \!\!\!\!\! \sum_{\bar{\bs{v}} \in \mathcal{T}(P_j)}  \prod_{l=1}^n\!\left[\sum_y\! \sqrt{W(y | x_{\bs{v}}^l) W(y | x_{\bs{\bar{v}}}^l)}\right]^{\frac{1}{\rho_{i j}}}\!\!\!,
	\end{split}
\end{align}
where $x_{\bs{v}}^l$ denotes the $l$-th element of $\bs{x}_{\bs{v}}$.
We now take the expectation of the above expression
\begin{align}
	\begin{split}
		\mathbb{E}\left[p_e\big(\bs{v}, j, \msf{C}\big)^{\frac{1}{\rho_{ij}}}\right] \,&\leq 
		\left(\frac{\exp (k D(P_j \| P_V))}{\exp(k D(P_i \| P_V))}\right)^{\frac{1}{\rho_{i j}}}\\
		&\times \mathbb{E}\left[\sum_{\bar{\bs{v}} \in \mathcal{T}^k(P_j)}  \prod_{l=1}^n \, e^{\frac{-d_B(X_l,  \bar{X}_l)}{\rho_{ij}}}\right],
	\end{split}
\end{align}
where the expectation is taken with respect to $P_{\bs{X}}^{(\hat{i})} \times P_{\bs{X}}^{(\hat{j})}$, where $P_{\bs{X}}^{(c)}$ denotes the uniform distribution over the type class $\mcl{T}^n(Q_c)$.
 Here, $\hat{i}$ denotes the index of the class to which source type $i$ belongs.
We can evaluate this expectation as follows
\begin{align}
	\begin{split}
		&\mathbb{E}\left[\, \prod_{l=1}^n \, e^{\frac{-d_B(X_l,  \bar{X}_l)}{\rho_{ij}}}\right]\\
		&\hspace{1cm}= \sum_{(\bs{x}, \bar{\bs{x}})} P_{\bs{X}}^{(\hat{j})}({\bs{x}}) P_{\bs{X}}^{(\hat{i})}(\bar{\bs{x}})\prod_{k=1}^n \, e^{\frac{-d_B(x_l,  \bar{x}_l)}{\rho_{i j}}}.
	\end{split}
\end{align}
We use Lemma~2.1 of~\cite{poltyrev} to rewrite the first expectation as if the distribution were i.i.d. with $Q_{\hat{i}}$. 
This gives
\begin{align}
	\begin{split}
		&\mathbb{E}\left[\, \prod_{l=1}^n \, e^{\frac{-d_B(X_l,  \bar{X}_l)}{\rho_{ij}}}\right]\\
		&\hspace{0.5cm}\,\dot{\leq}\sum_{\bs{x} \in \mcl{T}^n(Q_{\hat{j}} )} \frac{1}{\big|\mcl{T}^n(Q_{\hat{j}}) \big|} \prod_{l=1}^n \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x_l,  \bar{x})}{\rho_{i j}}}
%		\,\, \sum_{\bs{x}} P_{\bs{X}}^{(\hat{j})}({\bs{x}}) \prod_{k=1}^n \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x_k,  \bar{x})}{\rho_{i j}}}
	\end{split}\\
%	&\hspace{0.5cm}= \sum_{\bs{x} \in \mcl{T}^n(Q_{\hat{j}} )} \frac{1}{\big|\mcl{T}^n(Q_{\hat{j}}) \big|} \prod_{k=1}^n \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x_k,  \bar{x})}{\rho_{i j}}}\\
	&\hspace{0.5cm}\doteq \, \prod_{x \in \mcl{X}} \left[ \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x,  \bar{x})}{\rho_{i j}}}\right]^{nQ_{\hat{j}}(x)}\\
	&\hspace{0.5cm} = \exp\left(n \sum_x Q_{\hat{j}}(x) \log \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x,  \bar{x})}{\rho_{i j}}}  \right). \label{eq-does-not-depend}
\end{align}
Note that the bound in~\eqref{eq-does-not-depend} does not depend on $\bs{\bar{v}}$, and so
\begin{align}
	\begin{split}
		&\,\mathbb{E}\left[\sum_{\bar{\bs{v}} \in \mathcal{T}^k(P_j)}  \prod_{k=1}^n \, e^{\frac{-d_B(X_k,  \bar{X}_k)}{\rho_{ij}}}\right]\\
		&\,\,\dot{\leq} \exp\!\left(-n\! \left[-\sum_x Q_{\hat{j}}(x) \log \sum_{\bar{x}} Q_{\hat{i}}(x) \, e^{\frac{-d_B(x,  \bar{x})}{\rho_{i j}}}\!\!-R_j \right] \right).
	\end{split}
\end{align}
% TODO: changed
Raising both sides to the power $\rho_{ij}$ and taking the worst-case choice of $Q_{\hat{i}}$, we obtain
\begin{align}
	&\mathbb{E}\left[p_e\big(\bs{v}, j, \msf{C}\big)^{\frac{1}{\rho_{ij}}}\right]^{\rho_{ij}}\nonumber \\
%	\begin{split}
