\subsection{Proof of Theorem \ref{thm-dual-best-partition}}
We first set $\rho_{ic} = \rho_c$ and $\lambda_{ic} = \lambda_c$.
To find the optimal partitioning, assume each class is associated with given values of $\rho_c$ and $\lambda_c$, which will be optimized later.
The source type class $\mcl{T}^k(P_i)$ is then assigned to class $c^\star$ if
\begin{align}\label{eq-best-partition}
	\!c^{\star}\!=\!\underset{c \in\{1, \ldots, m\}}{\operatorname{argmax}} E_{\mathrm{x}}^{\prime}(\mathrm{Q}_c, \rho_c)\!+\!(\lambda_c\!-\!\rho_c){R}_i-t {E}_{\mathrm{s}}(\lambda_c, P_V) .
\end{align}
This means that
\begin{align}
	\begin{split}
		&p_e(\mcl{C}) \,\, \dot{\leq}\,\, \sum_{j=1}^{N_k} \exp\bigg(-n\bigg[\max_c\, {E}_{\mathrm{x}}^{\prime}\big({Q}_{c}, \rho_c\big)\\
		&\hspace{2cm}+\big(\lambda_c-\rho_c\big) {R}_j -t \mathrm{E}_{\mathrm{s}}\big(\lambda_c, P_V\big) \bigg]\bigg)
	\end{split}\\
	\begin{split}
		&\hspace{0.85cm}\,\, \dot{\leq}\, \exp\bigg(-n\bigg[\min_R \max_c\, {E}_{\mathrm{x}}^{\prime}\big({Q}_{c}, \rho_c\big)\\
		&\hspace{2cm}+\big(\lambda_c-\rho_c\big) {R}-t \mathrm{E}_{\mathrm{s}}\big(\lambda_c, P_V\big) \bigg]\bigg).
	\end{split}
\end{align}
Optimizing over the parameters yields
\begin{align}
	\begin{split}
		&p_e(\mcl{C}) \, \dot{\leq}\, \exp\bigg(-n\bigg[\min_R \max_{\lambda > 0} \max_{\rho \geq 1} \max_{Q \in \mcl{Q}_m} \, {E}_{\mathrm{x}}^{\prime}\big({Q}, \rho\big)\\
		&\hspace{2cm}+\big(\lambda-\rho\big) {R}-t {E}_{\mathrm{s}}\big(\lambda, P_V\big) \bigg]\bigg).
	\end{split}
\end{align}
%Since $E_s(\lambda, P_V)$ is convex in $\lambda$, we can exchange the order of $\min_R$ and $\max_{\lambda}$ using Sion's minmax theorem \cite{1103040253}, which gives
Since $E_s(\lambda, P_V)$ is convex in $\lambda$, we can apply Sion's minimax theorem~\cite{1103040253} to exchange the order of $\min_R$ and $\max_{\lambda}$, which gives
\begin{align}
	\begin{split}
		&p_e(\mcl{C}) \, \dot{\leq}\, \exp\bigg(-n\bigg[\max_{\lambda > 0} \min_R \max_{\rho \geq 1} \max_{Q \in \mcl{Q}_m} \, {E}_{\mathrm{x}}^{\prime}\big({Q}, \rho\big)\\
		&\hspace{2.5cm}+\big(\lambda-\rho\big) {R}-t {E}_{\mathrm{s}}\big(\lambda, P_V\big) \bigg]\bigg).
	\end{split}
\end{align}
Observe that if $\lambda<1$, then $(\lambda-\rho)R<0$, which implies that ${R} \rightarrow \infty$. Hence, the range of $\lambda$ is restricted to $\lambda \geq 1$. 
