\subsection{Proof of Theorem \ref{theorem-dual-concave-hull}}
% TODO:
Let $g(\lambda) \triangleq E_{\mathrm{x}}^{\prime}(\lambda, \mcl{Q}_m)$. 
Adopting from~\cite{1614076}, the concave conjugate of $g(\cdot)$ over $[1, \infty)$ is given by~\cite{rockafellar1970a}
\begin{align}
	g^{\star}(\lambda) = \inf_{\rho \geq 1} \Big\{ \lambda \rho - E_{\mathrm{x}}^{\prime}(\rho, \mcl{Q}_m)\Big\}.
\end{align}
The concave hull of $g(\cdot)$ is given by its biconjugate $g^{\star\star}(\lambda)$. Hence, we obtain
\begin{align}
	g^{\star\star}(\lambda) 
	&= \inf_{R} \bigg\{\lambda R - \inf_{\rho \geq 1} \Big\{  \rho R - E_{\mathrm{x}}^{\prime}(\rho, \mcl{Q}_m)\Big\}\bigg\}\\
	&= \inf_{R} \sup_{\rho \geq 1} \Big\{E_{\mathrm{x}}^{\prime}(\rho, \mcl{Q}_m) + (\lambda - \rho) R\Big\}.
\end{align}
This argument closely follows the proof of~\cite[Lemma~3]{1614076}.

