\subsection{Gallager's Expurgated Error Exponent}
%The case of no partitioning in JSCC can be attributed to Gallager, as the random-coding exponent he derived in~\cite[Problem~5.16]{gallager} does not consider any partitioning of the source sequences.
We attribute the non-partitioned setting in JSCC to Gallager, as the random-coding exponent he derives in~\cite[Problem~5.16]{gallager} does not involve any partitioning of the source sequences.
The following lemma presents the analogue of Lemma~\ref{lem-primal-given} in the absence of partitioning. 


\begin{lemma} \label{lem-primal-nopart}
	Assume that all codewords are drawn independently and uniformly from the type class $\mcl{T}^n(Q)$, for some given $Q \in \mathcal{P}_n(\mathcal{X})$. 
	Then, there exists a codebook such that for any choice of parameters $\{\lambda_{i}, \rho_{i}\}$ satisfying $\lambda_{i} > 0$ and $\rho_{i} \geq 1$,
	\begin{align}
		\begin{split}
		&p_e \, \dot{\leq} \,
		\sum_{i=1}^{N_k}\,
		\exp\bigg(-n\Big[{E}_{\mathrm{x}}\big({Q}, \rho_{i}\big)   \\
		&\hspace{2.1cm}+\big(\lambda_{i}-\rho_{i}\big) {R}_i-t {E}_{\mathrm{s}}\big(\lambda_{i}, P_V\big)\Big]\bigg),
		\end{split}
	\end{align}
	where
	\begin{align}
		\begin{split}
			&{E}_{\mathrm{x}}(\rho, Q)\\
			&\triangleq \sup_{a(.)} -\rho \sum_x Q(x) \log \sum_{\bar{x}} Q(\bar{x})\! \left(e^{-d_B(x, \bar{x})}\frac{e^{a(\bar{x})}}{e^{{a(x)}}} \right)^{\frac{1}{\rho}}.
		\end{split}
	\end{align} 
\end{lemma}

\begin{proof}
	The proof follows the same steps as in Lemma~\ref{lem-dual-given}, except that all codewords now share the same composition. As a result, ${E}_{\mathrm{x}}(Q, \rho)$ appears in place of ${E}_{\mathrm{x}}^{\prime}(Q, \rho)$.
\end{proof}


\begin{lemma} \label{lem-primal-nopart-opt}
	For a given set of codeword distributions $\mcl{Q}_m = \{ Q_1, Q_2, ..., Q_m \}$, 
	there exists a codebook such that
	\begin{align} 
		p_e \leq \exp\left(-n \left[\sup _{\rho\geq 1}\Big\{{{E}_{\mathrm{x}}}\big(\rho,\mcl{Q}_m\big)-t{E}_{\mathrm{s}}\big(\rho, P_V\big)\Big\} \right] \right),
	\end{align}
	where 
	$E_{\mathrm{x}}(\rho, \mcl{Q}_m) \triangleq \max_{Q \in \mcl{Q}_m} {E}_{\mathrm{x}}(\rho, Q)$.
\end{lemma}


\begin{proof}
	We begin by fixing a codeword distribution $Q \in \mcl{Q}_m$, to be optimized later. 
	By Lemma~\ref{lem-primal-nopart}, we have
	\begin{align}
		\begin{split}
		&p_e \, \dot{\leq} \,
		\sum_{i=1}^{N_k} \inf_{\lambda_{i}\geq 0, \rho_{i}\geq 1}
		\exp\!\bigg(\!\!-n\Big[{E}_{\mathrm{x}}\big({Q}, \rho_{i}\big)  \\
		&\hspace{2.5cm}+\big(\lambda_{i}-\rho_{i}\big) {R}_i-t {E}_{\mathrm{s}}\big(\lambda_{i}, P_V\big)\Big]\bigg),
		\end{split}\\
	&\hspace{0.4cm} \dot{\leq} \, \max_R  \inf_{\lambda \geq 0, \rho \geq 1} \exp\!\bigg(\!\!-n\Big[{E}_{\mathrm{x}}\big({Q}, \rho\big)\\
	&\hspace{2.5cm}+\big(\lambda-\rho\big) {R}-t {E}_{\mathrm{s}}\big(\lambda, P_V\big)\Big]\bigg). \nonumber
	\end{align}
	Hence, the resulting achievable exponent is
	\begin{align}
		\begin{split}
			&{E}_{G, \mathrm{ex}}^{\mathrm{primal}}(t,Q) =  \min_R  \sup_{\lambda \geq 0, \rho \geq 1} {E}_{\mathrm{x}}\big({Q}, \rho\big)\\
			&\hspace{3.0cm}+ \big(\lambda-\rho\big) {R}-t {E}_{\mathrm{s}}\big(\lambda, P_V\big)\Big]\bigg)
		\end{split}\\
		\begin{split}
			&\hspace{2.0cm} = \sup_{\lambda \geq 0, \rho \geq 1} \min_R  {E}_{\mathrm{x}}\big({Q}, \rho\big)\\
			&\hspace{3.0cm}+ \big(\lambda-\rho\big) {R}-t {E}_{\mathrm{s}}\big(\lambda, P_V\big)\Big]\bigg),
		\end{split}
	\end{align}
	where we exchanged the order of $\min$ and $\max$ using Sion's minimax theorem, since $E_{\mathrm{s}}(\lambda, P_V)$ is convex in $\lambda$, and $E_{\mathrm{x}}(Q, \rho)$ is concave in $\rho$ for fixed $Q$.
	If $\lambda \geq \rho$, the expression is minimized by choosing $R = 0$. On the other hand, if $\lambda < \rho$, the maximization over $R$ yields $R \to \infty$, in which case the entire expression tends to $-\infty$. 
	Thus, the optimal $\rho$ must satisfy $\rho \leq \lambda$, implying that $\lambda \geq 1$ and $R = 0$, which leads to
	\begin{align}
		{E}_{G, \mathrm{ex}}^{\mathrm{primal}}(t,Q) 
		&=  \sup_{\lambda \geq 1}   \sup_{\rho \leq \lambda} {E}_{\mathrm{x}}\big({Q}, \rho\big) -t {E}_{\mathrm{s}}\big(\lambda, P_V\big)\\
		&=  \sup_{\lambda \geq 1} \Big\{ {E}_{\mathrm{x}}\big({Q}, \lambda\big) -t {E}_{\mathrm{s}}\big(\lambda, P_V\big)\Big\}.
	\end{align}
	Optimizing further over $Q$ completes the proof.
\end{proof}

Note that the result of Lemma~\ref{lem-primal-nopart-opt} cannot be directly compared with Theorem~\ref{thm-dual-best-partition}, 
since the concave hull of $E_{\mathrm{x}}^{\prime}(\lambda, \mcl{Q}_m)$ can, in general, be larger than $E_{\mathrm{x}}(\lambda, \mcl{Q}_m)$, 
even though $E_{\mathrm{x}}(\lambda, \mcl{Q}_m) \geq E_{\mathrm{x}}^{\prime}(\lambda, \mcl{Q}_m)$ always holds.
Thus, whether partitioning can generally improve the achievable expurgated exponent remains an open question, as pointed out in~\cite{1056585, 8006660}.
This contrasts with the case of the random-coding exponent, where it is known that partitioning can strictly improve the exponent \cite{1614076, 6803047}.
