\subsection{Proof of Lemma \ref{lem-primal-given}}
As in Lemma~\ref{lem-dual-given}, we consider the code from Lemma~\ref{lem-expurgation-jscc}. In contrast, we now use a different decoding metric, given by
\begin{align} \label{eq-dec-primal}
	q(\bs{v}, \bs{x}, \bs{y})= \hat{P}_{\bs{v}}\big(\bs{v}\big)^2 \, W^n(\bs{y} | \bs{x}) ,
\end{align}
where $\hat{P}_{\bs{v}}(\bs{v}) = \prod_{l=1}^k \hat{P}_{\bs{v}}(v_l)$. This decoder is universal with respect to the source and matches the metric used by Csisz\'ar in~\cite{1056585}.
Using the union bound, we upper bound $p_e(\bs{v}, j, \msf{C})$ as
\begin{align}
	p_e\big(\bs{v}, j, \msf{C}\big) 
	&= \mathbb{P}\left[\bigcup_{\bar{\bs{v}}\in \mcl{T}^k(P_j)}\!\!\! q(\bs{\bar{v}}, \bs{x}_{\bs{\bar{v}}}, \bs{Y}) \geq q(\bs{v}, \bs{x}_{\bs{v}}, \bs{Y}) \right]\\
	&\leq \sum_{\bar{\bs{v}}\in \mcl{T}^k(P_j)} \mathbb{P}\Big[ q(\bs{\bar{v}}, \bs{x}_{\bs{\bar{v}}}, \bs{Y}) \geq q(\bs{v}, \bs{x}_{\bs{v}}, \bs{Y}) \Big].
\end{align}
For a fixed pair $(\bs{v}, \bar{\bs{v}})$, we use the method of types~\cite[Ch.~2]{csiszar2011information} to write the probability term as
\begin{align}
	\begin{split}
		&\mathbb{P}\Big[ q(\bs{\bar{v}}, \bs{x}_{\bs{\bar{v}}}, \bs{Y}) \geq q(\bs{v}, \bs{x}_{\bs{v}}, \bs{Y}) \Big]\\
		&\hspace{0.2cm}= \sum_{\bs{y}} W^n(\bs{y} | \bs{x}_{\bs{v}})\, \mathds{1}\Big\{q(\bs{\bar{v}}, \bs{x}_{\bs{\bar{v}}}, \bs{y}) \geq q(\bs{v}, \bs{x}_{\bs{v}}, \bs{y}) \Big\}
	\end{split}\\
	&\hspace{0.2cm}\doteq \!\!\!\!\!\!\!\!\!\!\!\!\!\!\! \sum_{\substack{ P_{X\bar{X}Y}:P_{X\bar{X}}=\hat{P}_{\bs{x}_{\bs{v}}\bs{x}_{\bar{\bs{v}}}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!\!\!\!\!\!\!\!\!\!\!\!
	\exp\left(n\Big[\mathbb{E}_P \log W(Y|X) + H_P(Y|X,\bar{X}) \Big] \right)\\
	&\hspace{0.2cm}\doteq \!\!\!\!\! \max_{\substack{ P_{X\bar{X}Y}:P_{X\bar{X}}=\hat{P}_{\bs{x}_{\bs{v}}\bs{x}_{\bar{\bs{v}}}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!
	\exp\Big(-n D\big( P_{X\bar{X}Y}\|  P_{X\bar{X}}\times W\big) \Big).
\end{align}
Here, $q(i, P_{XY})$ is defined implicitly, as the decoding metric in~\eqref{eq-dec-primal} depends on $(\bs{v}, \bs{x}, \bs{y})$ only through their types, and $D(\cdot\|\cdot)$ denotes the relative entropy.
We again assume that $\rho_{ij} \geq 1$ for all $(i, j)$, allowing us to apply Hölder's inequality to move the summation over $\bs{\bar{v}}$ outside, yielding
\begin{align}
	\begin{split}
		&p_e\big(\bs{v}, j, \msf{C}\big)^{\frac{1}{\rho_{ij}}}\\
		&\,\dot{\leq} \!\!\!\! \sum_{\bar{\bs{v}}\in \mcl{T}^k(P_j)} \!\!\!\!
		\exp\left(-n \!\!\!\!\!\! \min_{\substack{ P:P_{X\bar{X}}=\hat{P}_{\bs{x}_{\bs{v}}\bs{x}_{\bar{\bs{v}}}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} 
		\!\!\!\!\! \frac{D\big( P \|  P_{X\bar{X}}\times W\big)}{\rho_{ij}} \right)
	\end{split}\\
	&\doteq 
		\exp\!\left(\!-n\!\!\left [\min_{\substack{ P:P_{X\bar{X}}=\hat{P}_{\bs{x}_{\bs{v}}\bs{x}_{\bar{\bs{v}}}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!\!\!\!\!\!\!\!\!\!\!
		 \frac{D\big( P \|  P_{X\bar{X}}\times W\big)}{\rho_{ij}}\! -\! R_j \right] \right).
\end{align}
Taking the expectation over $(\bs{x}_{\bs{v}}, \bs{x}_{\bar{\bs{v}}})$, we obtain
\begin{align}
%	\begin{split}
%		&\mathbb{E}\left[ p_e\big(\bs{v}, j, \mcl{C}\big)^{\frac{1}{\rho_{ij}}} \right]^{\rho_{ij}}\\ 
%		&\hspace{0.5cm} \dot{\leq} \max_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}}
%		\exp\Big( -n\bigg[ D\big( P \|  P_{X\bar{X}}\times W\big)\\
%		&\hspace{2cm} + \rho_{ij}\Big(I_P(X;\bar{X}) - R_j \Big) \bigg] \Big).
%	\end{split}
	&\mathbb{E}\left[ p_e\big(\bs{v}, j, \msf{C}\big)^{\frac{1}{\rho_{ij}}} \right]^{\rho_{ij}}\nonumber\\ 
	&\hspace{0.5cm} \dot{\leq} \max_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}}
	\exp\Big( -n\bigg[ D\big( P \|  P_{X\bar{X}}\times W\big)\\
	&\hspace{3cm} + \rho_{ij}\Big(I_P(X;\bar{X}) - R_j \Big) \bigg] \Big). \nonumber
\end{align}
Using Lagrange duality, the optimization over $P$ can be simplified as follows
\begin{align}
%	\begin{split}
%		&\min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!
%		D\big( P \|  P_{X\bar{X}}\times W\big)\! + \!\rho_{ij}\big(I_P(X;\bar{X}) - R_j \big)\\
%		&=\min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}}} \, \sup_{s_{ij} \geq 0} \,\, D\big( P \|  P_{X\bar{X}}\times W\big)\\
%		&\hspace{0.25cm} + \rho_{ij}\Big(I_P(X;\bar{X}) - R_j \Big) + s_{ij}\Big(q(i, P_{{X}Y}) -  q(j, P_{\bar{X}Y})\Big).
%	\end{split}
	&\min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!
	D\big( P \|  P_{X\bar{X}}\times W\big)\! + \!\rho_{ij}\big(I_P(X;\bar{X}) - R_j \big) \nonumber \\
	&=\min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}}} \, \sup_{s_{ij} \geq 0} \,\, D\big( P \|  P_{X\bar{X}}\times W\big)\\
	&\hspace{0.25cm} + \rho_{ij}\Big(I_P(X;\bar{X}) - R_j \Big) + s_{ij}\Big(q(i, P_{{X}Y}) -  q(j, P_{\bar{X}Y})\Big). \nonumber
\end{align}
Substituting the decoding metric and setting $s_{ij} = \frac{\rho_{ij}}{2}$, we obtain
\begin{align}
	\begin{split}
		&\min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}} \!\!\!
		D\big( P \|  P_{X\bar{X}}\times W\big)\! + \!\rho_{ij}\big(I_P(X;\bar{X}) - R_j \big)\\
		&\geq \min_{ \substack{ P: P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}}} D\big( P \|  P_{X\bar{X}}\times W\big) + \rho_{ij}\Bigg(I_P(X;\bar{X}) \\
		&\hspace{1.0cm}  - R_j + \mathbb{E}_P\log \left(\frac{W(Y|X)}{W(Y|\bar{X})}\right)^{\frac{1}{2}} + R_j - R_i \Bigg) .
	\end{split}
\end{align}
Since the zero-error capacity of the channel is assumed to be zero, the optimal $P$ must satisfy $I_P(X;\bar{X}) \leq R_i$, as we aim to choose $\rho_{ij}$ to maximize the exponent. 
As a result, the optimal choice is $\rho_{ij} = 1$ for all $(i, j)$, which implies that
\begin{align}
	&\min_{\substack{ P_{X\bar{X}Y}\\ P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\q(j, P_{\bar{X}Y})\geq q(i, P_{{X}Y})}}
	\!\!\!\!\!\!\!\!\! D\big( P \|  P_{X\bar{X}}\times W\big)\! + \!\rho_{ij}\big(I_P(X;\bar{X}) - R_j \big) \nonumber \\
	&\geq \!\! \min_{\substack{ P_{X\bar{X}}\\ P_X=Q_{\hat{i}}, P_{\bar{X}}=Q_{\hat{j}}\\I_P(X;\bar{X})\leq R_i }}\!\!\! \mathbb{E}_P\big[ d_B(X,\bar{X})\big] + I_P(X;\bar{X})-R_i\\
	&\geq \min_{ \substack{ P_{X\bar{X}}: P_X=Q_{\hat{i}}\\I_P(X;\bar{X})\leq R_i }} \mathbb{E}_P\big[ d_B(X,\bar{X})\big] + I_P(X;\bar{X})-R_i\\
	&= E_{\mathrm{ex}}^{\prime}(Q_{\hat{i}}, R_i). \label{eq-test-test}
\end{align}
Therefore, the error probability of this code is upper bounded as
\begin{align}
	p_e
	&\, \dot{\leq} \, \sum_{i=1}^{N_k} \sum_{\bs{v} \in \mcl{T}^k(P_i)} P^k(\bs{v}) \exp\big(-n E_{\mathrm{ex}}^{\prime}(Q_{\hat{i}}, R_i)\big)\\
	&\, \dot{\leq} \, \sum_{i=1}^{N_k} \exp\left(-n \left[te(\frac{R_i}{t}, P_V) +  E_{\mathrm{ex}}^{\prime}(Q_{\hat{i}}, R_i)\right]\right)\\
	&= \!\sum_{c=1}^{m} \sum_{i \in \Lambda_c} \exp\!\left(\!-n\!\left[t{e}\!\left(\frac{R_i}{t}, P_V\!\right)\! +\! E_{\mathrm{ex}}^{\prime}(Q_c, R_i) \right]\!\right).\\\nonumber
\end{align}



\subsection{Proof of Theorem \ref{thm-primal-best-partition}}
To find the optimal partitioning, the source type class $\mcl{T}^k(P_i)$ is assigned to class $c^\star$ if
\begin{align}
	c^{\star}=\underset{c \in\{1, \ldots, m\}}{\operatorname{argmax}} E_{\mathrm{ex}}^{\prime}(Q_c, R_i).
\end{align}
With this assignment, the error probability of the code is upper bounded as
\begin{align}
	\!\!\!p_e 
	&\, \dot{\leq} \, \sum_{i=1}^{N_k} \exp\!\left(\!-n\!\left[t{e}\!\left(\frac{R_i}{t}, P_V\!\right) \!+\! \max_{Q \in \mcl{Q}_m}\! E_{\mathrm{ex}}^{\prime}(Q, R_i) \right]\right)\\
	&\, \dot{\leq} \exp\!\left(\!-n\!\Bigg[\!\min_R\! \bigg[ t{e}\!\left(\frac{R}{t}, P_V\!\right) \!+\!\! \max_{Q \in \mcl{Q}_m}\!\! E_{\mathrm{ex}}^{\prime}(Q, R) \bigg]\Bigg]\right).
\end{align}











