\section{Appendix to Model and Estimation}
\label{appsec:model}


\subsection{Proof for Minorization-Maximization Estimation}
\label{appssec:mm.algorithm}

\noindent \textbf{Proof of Theorem.} 
We show that $S(\boldsymbol{\theta};\boldsymbol{\theta}^{(k)})$ is a minorization of $\mathcal{L}(\boldsymbol{\theta}^{(k)})$ at $\boldsymbol{\theta}^{(k)}$ for maximization by checking the following requirements.

\begin{itemize}
    \item $\mathcal{S}(\boldsymbol{\theta}; \boldsymbol{\theta}^{(k)})\leq \mathcal{L}(\boldsymbol{\theta}^{(k)})$. For a given consumer $i$ at purchase occasion $t$, we denote the choice probability of consumer $i$ toward brand $j$ during purchase occasion $t$ as $Pr_{ijt}$:
    \begin{equation}
        l(\boldsymbol{\psi}_{it}; \boldsymbol{y}_{it}) = \prod_{j} \left(\frac{\exp(\psi_{ijt})}{1 + \sum_{j=1}^{J} \exp(U_{ijt})}\right)^{y_{ijt}}
    \end{equation}

    \begin{equation}
        h_{j}(\boldsymbol{\psi}_{it};\boldsymbol{y}_{it}) = \frac{\partial \log l(\boldsymbol{\psi}_{it}; \boldsymbol{y}_{it})}{\partial \psi_{ijt}} = y_{ijt} - Pr_{ijt}
    \end{equation}

        \begin{equation}
        h_{jk}(\boldsymbol{\psi}_{it};\boldsymbol{y}_{it}) = \frac{\partial^2 \log l(\boldsymbol{\psi}_{it}; \boldsymbol{y}_{it})}{\partial \psi_{ijt} \partial \psi_{ikt}} = \begin{cases} 
- Pr_{ijt}(1 - Pr_{ikt}), & j = k, \\
Pr_{ijt}Pr_{ikt}, & j \neq k.
\end{cases}
    \end{equation}

The Taylor expansion of $\log l(\boldsymbol{\psi}_{it})$ at $\tilde{\boldsymbol{\psi}}_{it}$ is
\begin{equation}
    \log l(\boldsymbol{\psi}_{it}; \boldsymbol{y}_{it}) =  \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) + (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it})' \nabla \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) \nonumber +  \frac{1}{2} (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it})' \nabla^2 \log l(\boldsymbol{\psi}^{*}_{it}; \boldsymbol{y}_{it}) (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it}).
\end{equation}
Where
\begin{equation}
\begin{aligned}
\nabla^2 \log l(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) &=
\begin{bmatrix}
h_{11}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & h_{12}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & \cdots & h_{1J}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) \\
h_{21}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & h_{22}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & \cdots & h_{2J}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) \\
\vdots & \vdots & \ddots & \vdots \\
h_{J1}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & h_{J2}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) & \cdots & h_{JJ}(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it})
\end{bmatrix} \nonumber \\
&=
\begin{bmatrix}
-{Pr}_{i1t}(1 - {Pr}_{i1t}) & {Pr}_{i1t}{Pr}_{i2t} & \cdots & {Pr}_{i1t}{Pr}_{iJt} \\
{Pr}_{i2t}{Pr}_{i1t} & -{Pr}_{i2t}(1 - {Pr}_{i2t}) & \cdots & {Pr}_{i2t}{Pr}_{iJt} \\
\vdots & \vdots & \ddots & \vdots \\
{Pr}_{iJt}{Pr}_{i1t} & {Pr}_{iJt}{Pr}_{i2t} & \cdots & -{Pr}_{iJt}(1 - {Pr}_{iJt})
\end{bmatrix}
\end{aligned}
\end{equation}

We have $\nabla^2 \log l(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) \geq -I$, i.e., $\nabla^2 \log l(\boldsymbol{\psi}_{it}^{*}; \boldsymbol{y}_{it}) + I$ is semi-positive definite.

Therefore,
\begin{align}
\log l(\boldsymbol{\psi}_{it}; \boldsymbol{y}_{it}) &\geq \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) + (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it})' \nabla \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) \nonumber - \frac{1}{2} (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it})' (\boldsymbol{\psi}_{it} - \tilde{\boldsymbol{\psi}}_{it}) \nonumber \\
&= \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) - (\tilde{\boldsymbol{\psi}}_{it} - \boldsymbol{\psi}_{it})' \nabla \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) - \frac{1}{2} (\tilde{\boldsymbol{\psi}}_{it} - \boldsymbol{\psi}_{it})' (\tilde{\boldsymbol{\psi}}_{it} - \boldsymbol{\psi}_{it}) \nonumber \\
&= \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) - \sum_j h_j(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it})( \tilde{\psi}_{ijt} - \psi_{ijt}) \nonumber - \frac{1}{2} \sum_j (\tilde{\psi}_{ijt} - \psi_{ijt})^2 \nonumber \\
&= \log l(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it}) + \frac{1}{2} \sum_j h_j(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it})^2 - \frac{1}{2} \sum_j (\tilde{\psi}_{ijt} +h_j(\tilde{\boldsymbol{\psi}}_{it}; \boldsymbol{y}_{it})- \psi_{ijt})^2. 
\end{align}

For now, we derive a lower bound for $\log l(\boldsymbol{\psi}_{it};\boldsymbol{y}_{it})$, the log-likelihood for each choice instance (i.e., customer-month purchase occasion). The log-likelihood function is its sum over user $i$ and time $t$. We substitute $\boldsymbol{\psi}_{it}$ and $\tilde{\boldsymbol{\psi}}_{it}$ with the nominal utility $\boldsymbol{x}_{ijt}'\boldsymbol{\alpha} + \delta_{ij}$ and nominal utility evaluated at the current estimates in the $k_{th}$ iteration $\boldsymbol{x}_{ijt}'\boldsymbol{\alpha}^{(k)} + \delta_{ij}^{(k)}$, respectively. Summing over all customers over all periods, the log-likelihood $\mathcal{L}(\boldsymbol{\theta})$ satisfies

\begin{equation}
\begin{aligned}
\mathcal{L}(\boldsymbol{\theta}) & \geq \mathcal{L}(\boldsymbol{\theta}^{(k)}) + \frac{1}{2}\sum_{i,j,t} h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)}; \boldsymbol{y}_{it})^2 - \frac{1}{2}\sum_{i,j,t}(\tilde{\psi}_{ijt}^{(k)} + h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)};\boldsymbol{y}_{it}) - \boldsymbol{x}_{ijt}' \boldsymbol{\alpha} - \delta_{ij})^2 \\
& = \mathcal{L}(\boldsymbol{\theta}^{(k)}) + \frac{1}{2}\sum_{i,j,t} h_{j}(\boldsymbol{x}_{ijt}'\boldsymbol{\alpha}^{(k)} + \delta_{ij}^{(k)}; \boldsymbol{y}_{it})^2 \\
& - \frac{1}{2}\sum_{i,j,t}(\boldsymbol{x}_{ijt}'\boldsymbol{\alpha}^{(k)} + \delta_{ij}^{(k)} + h_{j}(
\boldsymbol{x}_{ijt}'\boldsymbol{\alpha}^{(k)} + \delta_{ij}^{(k)}; \boldsymbol{y}_{it})
- \boldsymbol{x}_{ijt}' \boldsymbol{\alpha} - \delta_{ij})^2 \\
\end{aligned}
\end{equation}
where the RHS of the above inequality is $S(\boldsymbol{\theta}; \boldsymbol{\theta}^{(k)})$.


\item $S(\boldsymbol{\theta}^{(k)}; \boldsymbol{\theta}^{(k)}) = \mathcal{L}(\boldsymbol{\theta}^{(k)})$.

By definition, 
\begin{equation}
\begin{aligned}
    S(\boldsymbol{\theta}^{(k)}; \boldsymbol{\theta}^{(k)}) & = 
    \mathcal{L}(\boldsymbol{\theta}^{(k)}) + \frac{1}{2}\sum_{i,j,t} h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)}; \boldsymbol{y}_{it})^2 - \frac{1}{2}\sum_{i,j,t}(\tilde{\psi}_{ijt}^{(k)} + h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)};\boldsymbol{y}_{it}) - \boldsymbol{x}_{ijt}' \boldsymbol{\alpha}^{(k)} - \delta_{ij}^{(k)})^2 \\
    & =   \mathcal{L}(\boldsymbol{\theta}^{(k)}) + \frac{1}{2}\sum_{i,j,t} h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)}; \boldsymbol{y}_{it})^2  - \frac{1}{2}\sum_{i,j,t} h_{j}(\tilde{\boldsymbol{\psi}}_{it}^{(k)}; \boldsymbol{y}_{it})^2 \\
    & =  \mathcal{L}(\boldsymbol{\theta}^{(k)}) 
\end{aligned}
\end{equation}
\end{itemize}



