\begin{proof}[Proof of \cref{thm:cvxasymptotics}]
Observe that because
\begin{align}
    C^{(n)}(\bm{W}) &= \frac{1}{2} \| \mathcal{X}(\bm{W}) - \bm{\eps} \|_F^2 + \lambda \| \bm{W} + \bm{M} \|_* - \lambda \| \bm{M} \|_*,
