\section{Introduction}\label{sec:1}

\begin{table*}
\begin{center}
  \caption{Summary of CSST instruments and surveys.}
  \label{tab:CSST_sum}
  \includegraphics[scale=1.1]{table1.pdf}
  \end{center}
