As an immediate consequence of the previous results, we get the following characterization of weak $\Rr$-matrices.

\begin{corollary}
\label{cor:weakastwist}
Let $H_1$ and $H_2$ be bialgebras. Then $\Rr\in H_2\otimes H_1$ is a weak $\Rr$-matrix of $(H_2,H_1)$ if and only if $1_{H_1}\otimes\Rr^{-1}\otimes 1_{H_2}$ is a twist on the tensor product bialgebra $H_1\otimes H_2$.
\end{corollary}

\begin{proof}
If $\Rr$ is a weak $\Rr$-matrix, we can take $\Ff_1=1_{H_1}\otimes 1_{H_1}$ and  $\Ff_2=1_{H_2}\otimes 1_{H_2}$ and apply \cref{lem:Drinfeldtwist}. Conversely, if $\Ff\coloneqq 1_{H_1}\otimes\Rr^{-1}\otimes 1_{H_2}$ is a twist, we can use 
\cref{thm:twistot} to get that $\Ff_1=1_{H_1}\otimes1_{H_1}$, $\Ff_2=1_{H_2}\otimes 1_{H_2}$ $\Gg= 1_{H_1}\otimes1_{H_2}$, $\Hh=\Rr^{-1}$ and that $\Gg^\op\Hh^{-1}=\Rr$ is a weak $\Rr$-matrix.
\end{proof}

\subsection{Quasitriangular structures up to cohomology}
Since any quasitriangular structure is a special case of twist, we can apply \cref{thm:twistot} to classify quasitriangular structures on the tensor product bialgebra up to cohomology. 
%\rd{[La coomologia dei twist si restringe ad una coomologia sulle $\Rr$? Per ora non lo sappiamo]\\}
First, we show the following result.
\begin{lemma}
    Let $(H,\Rr)$ be a quasitriangular bialgebra. If $h\in H^{\times}$ is a central element and $\Rr'\coloneq (1\ot 1)^{h}=(h\ot h)\Delta(h^{-1})\in H\ot H$ is a central weak $\Rr$-matrix of $(H,H)$, then $\Rr^{h}=(h\ot h)\Rr\Delta(h^{-1})$ is a quasitriangular structure for $H$.
\end{lemma}
\begin{proof}
Clearly $\Rr^h$ is invertible. Since $h$ is central, we obtain
\[
\Rr^{h}=(h\ot h)\Rr\Delta(h^{-1})=\Rr(h\ot h)\Delta(h^{-1})=\Rr\Rr'
\]
and also
\[
\Rr'\Delta(x)(\Rr')^{-1}
=(h\ot h)\Delta(h^{-1})\Delta(x)\Delta(h)(h^{-1}\ot h^{-1})
=\Delta(h^{-1}xh)=\Delta(x).
\]
Thus, we get
\[
\Rr^{h}\Delta(\cdot)(\Rr^{h})^{-1}=\Rr\Rr'\Delta(\cdot)(\Rr')^{-1}\Rr^{-1}=\Rr\Delta(\cdot)\Rr^{-1}=\Delta^{\mathrm{op}}(\cdot),
\]
hence \eqref{qtr1} is satisfied. 
Moreover, since $\Rr'$ is central  and $\Rr,\Rr'$ satisfy \eqref{qtr2} and\eqref{qtr3}, also $\Rr^{h}$ satisfies \eqref{qtr2} and \eqref{qtr3}.
\end{proof}
\begin{remark}
    Observe that, since $h$ is central, $\Rr'$ is central if and only if $\Delta(h)$ is central. Since $\Rr'\Delta(\cdot)(\Rr')^{-1}=\Delta(\cdot)$, we also observe that $\Rr'$ is a quasitriangular structure for $H$ if and only if $H$ is cocommutative.
\end{remark}

We are now able to state the aforementioned classification result.

\begin{proposition}
\label{pro:Rot}
Let $H_{1}$ and $H_{2}$ be bialgebras. Then, any quasitriangular structure on $H_{1}\ot H_{2}$ is cohomologous to a quasitriangular structure
\begin{equation}\label{eq:quasitriangtensprod}
\Rr_{\ot}:=(1_{H_{1}}\ot\Qq\ot1_{H_{2}})(\mathrm{Id}_{H_{1}}\ot\tau\ot\mathrm{Id}_{H_{2}})(\mathcal{R}_1\ot\mathcal{R}_2),
\end{equation}
where $\mathcal{R}_1\in H_{1}\ot H_{1}$ and $\mathcal{R}_2\in H_{2}\ot H_{2}$ are quasitriangular structures of $H_{1}$ and $H_{2}$, respectively, and $\Qq\in H_{2}\ot H_{1}$ is a central weak $\Rr$-matrix of $(H_{2},H_{1})$.
\end{proposition}

\begin{proof}
    Let $\Ss$ be a quasitriangular structure on $H_{1}\ot H_{2}$, hence a twist on $H_{1}\ot H_{2}$. Then, by \cref{thm:twistot} we know that $\Ss$ is cohomologous to 
\[
\Ss^\Gg=(1_{H_{1}}\ot\Rr^{-1}\ot1_{H_{2}})(\mathrm{Id}_{H_{1}}\ot\tau\ot\mathrm{Id}_{H_{2}})(\mathcal{R}_1\ot\mathcal{R}_2),
\]
where
\[
\mathcal{R}_{1}:=\left( \mathrm{Id}\otimes \varepsilon \otimes \mathrm{Id}%
\otimes \varepsilon \right) \left( \mathcal{\Ss}\right)\in H_{1}\ot H_{1}, \qquad \mathcal{R}_{2}:=\left( \varepsilon \otimes \mathrm{Id}\otimes
\varepsilon \otimes \mathrm{Id}\right) \left( \mathcal{\Ss}\right)\in H_{2}\ot H_{2} 
\]
are twists on $H_{1}$ and $H_{2}$, respectively, and $\Rr=\Gg^{\mathrm{op}}\Hh^{-1}\in H_{2}\ot H_{1}$ is a weak $\Rr$-matrix of $((H_{2})_{\Rr_{2}},(H_{1})_{\Rr_{1}})$ where 
\[
\mathcal{G}:=\left( \mathrm{Id}\otimes \varepsilon \otimes \varepsilon
\otimes \mathrm{Id}\right) \left( \mathcal{\Ss}\right)\in H_{1}\ot H_{2}, \qquad 
\mathcal{H}:=\left( \varepsilon \otimes \mathrm{Id}\otimes \mathrm{Id}%
\otimes \varepsilon \right) \left( \mathcal{\Ss}\right)\in H_{2}\ot H_{1}. 
\]
Since $\mathrm{Id}\ot\varepsilon:H_{1}\ot H_{2}\to H_{1}$ and $\varepsilon\ot\mathrm{Id}:H_{1}\ot H_{2}\to H_{2}$ are bialgebra maps, using Example \ref{exa:weakR} we obtain that $\mathcal{R}_1$ and $\mathcal{R}_2$ are weak $\Rr$-matrices of $(H_{1},H_{1})$ and $(H_{2},H_{2})$, respectively. Moreover, $\Ss$ satisfies \eqref{qtr1}, i.e. for all $x\in H_{1}$ and $a\in H_{2}$ we have
\begin{equation}\label{eqq}
    (x_{2}\ot a_{2}\ot x_{1}\ot a_{1})\Ss=\Ss(x_{1}\ot a_{1}\ot x_{2}\ot a_{2}).
\end{equation}
In particular, we have $(x_{2}\ot1_{H_{2}}\ot x_{1}\ot1_{H_{2}})\Ss=\Ss(x_{1}\ot1_{H_{2}}\ot x_{2}\ot1_{H_{2}})$ for all $x\in H_{1}$ and then, applying $\mathrm{Id}\ot\varepsilon\ot\mathrm{Id}\ot\varepsilon$, we get $\Delta^{\mathrm{op}}(x)\Rr_{1}=\Rr_{1}\Delta(x)$ for all $x\in H_{1}$. Thus, $\Rr_{1}$ is a quasitriangular structure on $H_{1}$. Similarly, we get that $\Rr_{2}$ is a quasitriangular structure on $H_{2}$. Therefore, $(H_{1})_{\Rr_{1}}=H_{1}^{\mathrm{cop}}$ and $(H_{2})_{\Rr_{2}}=H_{2}^{\mathrm{cop}}$. Moreover, applying $\mathrm{Id}\ot\varepsilon\ot\varepsilon\ot\mathrm{Id}$ to \eqref{eqq}, we get $(x\ot a)\Gg=\Gg(x\ot a)$ for all $x\in H_{1}$ and $a\in H_{2}$, hence $\Gg$ is central while, applying $\varepsilon\ot\mathrm{Id}\ot\mathrm{Id}\ot\varepsilon$ to \eqref{eqq}, we get $(a\ot x)\Hh=\Hh(a\ot x)$ for all $x\in H_{1}$ and $a\in H_{2}$, hence also $\Hh$ is central. Thus, $\Rr$ is a central weak $\Rr$-matrix of $(H_{2}^{\mathrm{cop}},H_{1}^{\mathrm{cop}})$ that is equivalent, by \cref{lem:weakop}, to $\Qq\coloneq \Rr^{-1}\in H_{2}\ot H_{1}$ being a central weak $\Rr$-matrix of $(H_{2},H_{1})$.

We also recall that $\Ss$ satisfies \eqref{qtr2} and \eqref{qtr3}, i.e. 
\[
    (\mathrm{Id}_{H_{1}\ot H_{2}}\ot\Delta_{H_{1}\ot H_{2}})(\Ss)=\Ss_{13}\Ss_{12},\qquad (\Delta_{H_{1}\ot H_{2}}\ot\mathrm{Id}_{H_{1}\ot H_{2}})(\Ss)=\Ss_{13}\Ss_{23}.
\]
By applying $\mathrm{Id}\ot\varepsilon\ot\varepsilon\ot\mathrm{Id}\ot\varepsilon\ot\mathrm{Id}$ to the first equality we get $(\mathrm{Id}\ot\Delta)(\Gg)=\Gg_{13}\Gg_{12}$, while applying $\mathrm{Id}\ot\varepsilon\ot\mathrm{Id}\ot\varepsilon\ot\varepsilon\ot\mathrm{Id}$ to the second we obtain $(\Delta\ot\mathrm{Id})(\Gg)=\Gg_{13}\Gg_{23}$. Therefore, $\Gg$ is a central weak $\Rr$-matrix of $(H_{1},H_{2})$. 
Moreover, we have
\[
\begin{split}
\Delta_{H_{1}\ot H_{2}}(\Gg)&=(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Delta_{H_{1}}\ot\Delta_{H_{2}})(\Gg)\\
&\overset{\eqref{eq:DDR}}=(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Gg^{i}\Gg%
^{p}\otimes \Gg^{j}\Gg^{s}\otimes \Gg_{p}\Gg%
_{s}\otimes \Gg_{i}\Gg_{j})\\
&=\Gg^{i}\Gg%
^{p}\otimes  \Gg_{p}\Gg%
_{s}\otimes \Gg^{j}\Gg^{s}\otimes\Gg_{i}\Gg_{j}\\
&=(\Gg^{i}\ot\Gg_{s}\ot\Gg^{s}\ot\Gg_{i})(\Gg\ot\Gg).
\end{split}
\]
Set $\Ss'\coloneqq (\Gg\ot\Gg)
\Delta_{H_{1}\ot H_{2}}(\Gg^{-1})$. Therefore, $(\Ss')^{-1}= 
\Delta_{H_{1}\ot H_{2}}(\Gg)(\Gg^{-1}\ot\Gg^{-1})=\Gg^{i}\ot\Gg_{s}\ot\Gg^{s}\ot\Gg_{i}$.
Thus, $(\Ss')^{-1}$ is central invertible. Moreover, $(\Ss')^{-1}$ also satisfies \eqref{qtr2} and \eqref{qtr3} since $\Gg$ is a central weak $\Rr$-matrix and hence, by Lemma \ref{lem:weakop}, also $\Ss'$ is a central weak $\Rr$-matrix of $(H_{1}\ot H_{2},H_{1}\ot H_{2})$. Therefore, by the previous lemma we know that $\Ss^{\Gg}$ is a quasitriangular structure on $H_{1}\ot H_{2}$.


In order to conclude, we show that, given quasitriangular structures $\Rr_{1}\in H_{1}\ot H_{1}$ and $\Rr_{2}\in H_{2}\ot H_{2}$ of $H_{1}$ and $H_{2}$, respectively, and $\Qq\in H_{2}\ot H_{1}$ a central weak $\Rr$-matrix of $(H_{2},H_{1})$, then \eqref{eq:quasitriangtensprod} is a quasitriangular structure on $H_{1}\ot H_{2}$. Clearly, $\Rr_{\ot}$ is invertible. We compute
\[
\begin{split}
    \Rr_{\ot}\Delta_{H_{1}\ot H_{2}}(x\ot a)&=(1\ot \Qq \ot1)(\Rr_{1}^ix_{1}\ot\Rr_2^ja_{1}\ot\Rr_{1_{i}}x_{2}\ot\Rr_{2_{j}}a_{2})\\&\overset{\eqref{qtr1}}{=}(1\ot \Qq \ot1)(x_{2}\Rr_1^i\ot a_{2}\Rr_2^j\ot x_{1}\Rr_{1_{i}}\ot a_{1}\Rr_{2_{j}})\\&=(x_{2}\ot a_{2}\ot x_{1}\ot a_{1})(1\ot \Qq \ot1)(\Rr_1^i\ot \Rr_2^j\ot\Rr_{1_{i}}\ot\Rr_{2_{j}})\\&=\Delta^{\mathrm{op}}_{H_{1}\ot H_{2}}(x\ot a)\Rr_{\ot}
\end{split}
\]
and also
\[
\begin{split}
    &(\mathrm{Id}_{H_1\ot H_2}\ot\Delta_{H_{1}\ot H_{2}})(\Rr_{\ot})=\\
    &=(1\ot \Qq^i \ot( \Qq_i )_1\ot1\ot( \Qq_i )_2\ot1)(\Rr_1^i\ot\Rr_2^j\ot(\Rr_{1_i})_{1}\ot(\Rr_{2_{j}})_{1}\ot(\Rr_{1_{i}})_2\ot(\Rr_{2_{j}})_{2})\\&\overset{\eqref{qtr2},\eqref{wtr2}}{=}(1\ot \Qq^i\Qq^s \ot \Qq_s \ot1\ot \Qq_i \ot1)(\Rr_1^i\Rr_1^p\ot\Rr_2^j\Rr_2^s\ot\Rr_{1_{p}}\ot\Rr_{2_{s}}\ot\Rr_{1_{i}}\ot\Rr_{2_{j}})\\&=(1\ot \Qq^i \ot1\ot1\ot \Qq_i \ot1)(\Rr_1^i\ot\Rr_2^j\ot1\ot1\ot\Rr_{1_{i}}\ot\Rr_{2_{j}})\\&\ (1\ot \Qq^s \ot \Qq_s\ot1\ot1\ot1)(\Rr_1^p\ot\Rr_2^s\ot\Rr_{1_{p}}\ot\Rr_{2_{s}}\ot1\ot1)=(\Rr_{\ot})_{13}(\Rr_{\ot})_{12},
\end{split}
\]
using that $\Qq$ is central. Similarly, we have $(\Delta_{H_{1}\ot H_{2}}\ot\mathrm{Id}_{H_{1}\ot H_{2}})(\Rr_{\ot})=(\Rr_{\ot})_{13}(\Rr_{\ot})_{23}$ and then $\Rr_{\ot}$ is a quasitriangular structure on $H_{1}\ot H_{2}$. 
%We now conclude by \cref{lem:weakop} which entails that $\mathcal{R}\in H_{2}\ot H_{1}$ is a central weak $\Rr$-matrix of $(H_{2}^{\mathrm{cop}},H_{1}^{\mathrm{cop}})$ if and only if $\Qq\coloneq \Rr^{-1}\in H_{2}\ot H_{1}$ is a central weak $\Rr$-matrix of $(H_{2},H_{1})$.
\end{proof}

\begin{remark}
    Given bialgebras $H$ and $A$, a classification result for the quasitriangular structures on $H\ot A$ is given in \cite[Theorem 2.9]{Chen-quasi} (consider $R=1\ot 1$ so that $H\bowtie^{R}A=H\otimes A$ in loc. cit.). These have the form
\[
\Ff\coloneqq(\id\otimes \tau\otimes\id)(\mathcal{S}\otimes \mathcal{T})(\mathcal{U}^i\otimes \mathcal{V}^\op\otimes \mathcal{U}_i)=(\mathcal{U}^i\otimes \mathcal{V}^\op\otimes \mathcal{U}_i)(\id\otimes \tau\otimes\id)(\mathcal{S}\otimes \mathcal{T})
\]
where $\mathcal{S}\in H\ot H$ and $\mathcal{T}\in A\ot A$ are quasitriangular structures of $H$ and $A$, respectively, while $\mathcal{U},\mathcal{V}\in H\ot A$ are central weak $\Rr$-matrices of $(H,A)$. By using the notations of \cref{pro:Rot} we get
$\Rr_1=\mathcal{S}$,
$\Rr_2=\mathcal{T}$,
$\Gg=\mathcal{U}$,
$\Hh=\mathcal{V}^\op$
and $\Qq=\Rr^{-1}=(\Gg^\op\Hh^{-1})^{-1}
=\Hh(\Gg^{-1})^\op
=(\mathcal{V}\mathcal{U}^{-1})^\op.$  Therefore,
$\Ff$ is cohomologous to 
\[\Ff^\mathcal{U}=(1\ot\Qq\ot1)(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\mathcal{R}_1\ot\mathcal{R}_2)=(1\ot(\mathcal{V}\mathcal{U}^{-1})^\op\ot 1)(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\mathcal{S}\ot\mathcal{T}).\]
Note that, by  \cref{lem:weakop}, since $\mathcal{U}$ and $\mathcal{V}$ are central, we coherently get that $(\mathcal{V}\mathcal{U}^{-1})^\op$ is a central weak $\Rr$-matrix of $(A,H)$.
\end{remark}

