\subsection{The \texorpdfstring{$2$}{2}-category \texorpdfstring{$\TwTrBialg$}{TwTrBialg} of triangular bialgebras and twisted morphisms}
We now want to define another $2$-category, whose 0-cells are triangular bialgebras, endowed with a $2$-functor (see \cite[\S 4.1]{Johnson-Yau-book}) into $\TwBialg$. From now on, the quasitriangular structures considered will be triangular.

\begin{definition}
Let $(H,\Rr)$ and $(H',\Rr')$ be triangular bialgebras. We say that $\left(f,\mathcal{F}\right):(H,\Rr)\to (H',\Rr')$ is a \emph{twisted morphism of triangular bialgebras} if $f:(H,\Rr)\to(H'_{\Ff},\Rr'_{\Ff})$ is a morphism in $\TrBialg$.
\end{definition}

\begin{remark}
Recall that $H_{\mathcal{F}}^{\prime }=\left( H^{\prime
},m^{\prime },u^{\prime },\Delta _{\mathcal{F}}^{\prime },\varepsilon
^{\prime }\right) $, where $\left( H^{\prime },m^{\prime },u^{\prime },\Delta
^{\prime },\varepsilon ^{\prime }\right) $ denotes the starting bialgebra
structure on $H^{\prime }$ while $\Delta _{\mathcal{F}}^{\prime }\left(
\cdot\right) =\mathcal{F}\Delta ^{\prime }\left( \cdot\right) \mathcal{F}^{-1}.$ Therefore, $\left( f,\mathcal{F}\right) :\left( H,\mathcal{R}\right) \rightarrow
\left( H^{\prime },\mathcal{R}^{\prime }\right) $ is a twisted
morphism of triangular bialgebras if $f:H\rightarrow H^{\prime }$ is a counitary algebra
map such that 
\begin{equation}\label{eq:deformedcoproduct}
\mathcal{F}\Delta ^{\prime }f\left( x\right) \mathcal{F}^{-1}=\left(
f\otimes f\right) \Delta \left( x\right) 
\end{equation}%
and verifies%
\begin{equation}\label{eq:deformedR}
\left( f\otimes f\right) \left( \mathcal{R}\right) =\mathcal{F}^{\mathrm{op}}%
\mathcal{R}^{\prime }\mathcal{F}^{-1},
\end{equation}
i.e. if $(f,\Ff):H\to H'$ is a morphism in $\TwBialg$ and \eqref{eq:deformedR} is satisfied.
\end{remark}

