\begin{example}\label{ex:groupalgebra}
    Consider the abelian group $\Gamma=\langle x,y\ |\ xy=yx,\ x^{n}=1,\ y^{n}=1\rangle$, with $n>1$, and let $q\in\Bbbk$ be a primitive $n$-th root of unity. One can define a morphism $(f,\Ff):\Bbbk\Gamma\to\Bbbk\Gamma$ in $\TwBialg$ as in \cite[Example 3.2]{ShilinZhang}, see also \cite{Pansera}. We point out that in \cite{ShilinZhang} the notion of twist (and, accordingly, that of twisted morphism of bialgebras) is dual with respect to Definition \ref{def:twist}. Thus, here we consider the inverse of the twist considered there. We define $f:\Bbbk\Gamma\to\Bbbk\Gamma$ on $x$ and $y$ as $f(x)=y$ and $f(y)=x$ and we extend it into an algebra automorphism of $\Bbbk\Gamma$. Moreover, defining $\Ff:=\frac{1}{n}\sum_{i,j=0}^{n-1}{q^{-ij}x^{i}\ot y^{-j}}$, we obtain a morphism $(f,\Ff):\Bbbk\Gamma\to\Bbbk\Gamma$ in $\TwBialg$. The bialgebra $\Bbbk\Gamma$ is cocommutative, but we can choose triangular structures $\Rr$  different from $1\ot1$, see e.g. \cite[Example 2.1.17]{Majid-book}. If we define $\Rr':=(f\ot f)(\Rr)_{\Ff^{-1}}$ we obtain that $(f,\Ff):(\Bbbk\Gamma,\Rr)\to(\Bbbk\Gamma,\Rr')$ is a (bijective) twisted morphism of triangular bialgebras.  
\end{example}

\begin{example}
\label{exa:Sw1}
Let $\Bbbk$ be a field of characteristic different from 2. The Sweedler's Hopf algebra $H$ is the $\Bbbk$-algebra given by generators $g$ and $x$, and relations
\[
g^{2}=1,\quad x^{2}=0,\quad  xg=-gx. 
\]    
This becomes a Hopf algebra with comultiplication, counit and antipode determined by 
\[
\Delta(g)=g\ot g,\ \Delta(x)=x\ot 1+g\ot x,\ \varepsilon(g)=1,\ \varepsilon(x)=0,\ S(g)=g,\ S(x)=-gx.
\]
There is an exhaustive 1-parameter family of triangular structures on $H$ given by 
\[
\Rr_{\lambda}:=\frac{1}{2}(1\ot1+g\ot1+1\ot g-g\ot g)+\frac{\lambda}{2}(x\ot x-xg\ot x+x\ot xg+xg\ot xg),
\]
see e.g. \cite[Exercise 2.1.7]{Majid-book}. One can define a morphism $(f,\Ff):H\to H$ in $\TwBialg$ as in \cite[Example 3.1]{ShilinZhang}. Again we point out that in \cite{ShilinZhang} the notion of twist (and, accordingly, that of twisted morphism of bialgebras) is dual with respect to Definition \ref{def:twist}. Thus, here we consider the inverse of the twist considered there. We define $f_{s}:H\to H$ on $g$ and $x$ as $f_{s}(g)=g$ and $f_{s}(x)=sx$, for $s\in\Bbbk$ with $s\not=0$, and we extend it into an algebra automorphism of $H$. Moreover, defining $\Ff_{d}:=1\ot1+d(xg\ot x)$, for $d\in\Bbbk$, we obtain a morphism $(f_{s},\Ff_{d}):H\to H$ in $\TwBialg$. We observe that $(\Rr_{\lambda})_{\Ff}=\Rr_{\lambda+2d}$: 
\[
\begin{split}
    (\Rr_{\lambda})_{\Ff}&=(1\ot1+d(x\ot xg))\Rr_{\lambda}(1\ot 1-d(xg\ot x))\\&=\Rr_{\lambda}-\frac{d}{2}(1\ot1+g\ot 1+1\ot g-g\ot g)(xg\ot x)+\frac{d}{2}(x\ot xg)(1\ot 1+g\ot 1+1\ot g-g\ot g)\\&=\Rr_{\lambda}+d(x\ot xg+x\ot x+xg\ot xg-xg\ot x)=\Rr_{\lambda+2d}.
\end{split}
\]
Therefore, $(f_{s},\Ff_{d}):(H,\Rr_{\lambda})\to(H,\Rr_{\gamma})$ is a twisted morphism of triangular bialgebras if and only if 
$\Rr_{\lambda s^{2}}=(f\ot f)(\Rr_{\lambda})=(\Rr_{\gamma})_{\Ff}=\Rr_{\gamma+2d}$,
i.e. if and only if $\lambda s^{2}=\gamma+2d$. 

Hence $(f_{s},\Ff_{d}):(H,\Rr_{\lambda})\to(H,\Rr_{\lambda s^{2}-2d})$ is a (bijective)  twisted morphism of triangular bialgebras. In particular, $(f_{1}=\mathrm{Id},\Ff_{d}):(H,\Rr_{\lambda})\to (H,\Rr_{\lambda-2d})$ is a (bijective) twisted morphism of triangular bialgebras.
\end{example}



\begin{definition}
