\mathcal{F}\right) 1^{\prime }=f^{\prime }\left( 1\right) 1^{\prime
}=1^{\prime }.
\end{eqnarray*}%
Thus $\mathcal{F}^{\prime }$ is a twist. Clearly $f^{\prime
}f:H\rightarrow H^{\prime \prime }$ is a counitary algebra map. Moreover,
we have 
\begin{eqnarray*}
\left( f^{\prime }f\otimes f^{\prime }f\right) \Delta \left( x\right) 
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( f\otimes f\right)
\Delta \left( x\right) =\left( f^{\prime }\otimes f^{\prime }\right) \left( 
\mathcal{F}\Delta ^{\prime }f\left( x\right) \mathcal{F}^{-1}\right)  \\
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( \mathcal{F}\right)
\left( f^{\prime }\otimes f^{\prime }\right) \left( \Delta ^{\prime }f\left(
x\right) \right) \left( f^{\prime }\otimes f^{\prime }\right) \left( 
\mathcal{F}^{-1}\right)  \\
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( \mathcal{F}\right) 
\mathcal{F}^{\prime }\left( \Delta ^{\prime \prime }f^{\prime }f\left(
x\right) \right) \left( \mathcal{F}^{\prime }\right) ^{-1}\left( f^{\prime
}\otimes f^{\prime }\right) \left( \mathcal{F}^{-1}\right) 
\end{eqnarray*}%
so that $\left( f^{\prime }f,\left( f^{\prime }\otimes f^{\prime }\right)
\left( \mathcal{F}\right) \mathcal{F}^{\prime }\right) :\left( H,\mathcal{R}%
\right) \rightarrow \left( H^{\prime \prime },\mathcal{R}^{\prime \prime
}\right) $ is a twisted  morphism of triangular bialgebras once proved the
compatibility with the quasitiangular structure. Indeed we have%
\begin{eqnarray*}
\left( f^{\prime }f\otimes f^{\prime }f\right) \left( \mathcal{R}\right) 
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( f\otimes f\right)
\left( \mathcal{R}\right) =\left( f^{\prime }\otimes f^{\prime }\right)
\left( \mathcal{F}^{\mathrm{op}}\mathcal{R'F}^{-1}\right)  \\
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( \mathcal{F}\right) ^{%
\mathrm{op}}\left( f^{\prime }\otimes f^{\prime }\right) \left( \mathcal{R}%
^{\prime }\right) \left( f^{\prime }\otimes f^{\prime }\right) \left( 
\mathcal{F}\right) ^{-1} \\
&=&\left( f^{\prime }\otimes f^{\prime }\right) \left( \mathcal{F}\right) ^{%
\mathrm{op}}\mathcal{F}^{\prime \mathrm{op}}\mathcal{R}^{\prime \prime }%
\mathcal{F}^{\prime -1}\left( f^{\prime }\otimes f^{\prime }\right) \left( 
\mathcal{F}\right) ^{-1} \\
&=&\mathcal{F}^{\prime \prime \mathrm{op}}\mathcal{R}^{\prime \prime }%
\mathcal{F}^{\prime \prime -1}.
\end{eqnarray*}

$ii)$ Let us check associativity. We compute%
\begin{eqnarray*}
\left( f^{\prime \prime },\mathcal{F}^{\prime \prime }\right) \circ \left(
\left( f^{\prime },\mathcal{F}^{\prime }\right) \circ \left( f,\mathcal{F}%
\right) \right)  &=&\left( f^{\prime \prime },\mathcal{F}^{\prime \prime
}\right) \circ \left( f^{\prime }f,\left( f^{\prime }\otimes f^{\prime
}\right) \left( \mathcal{F}\right) \mathcal{F}^{\prime }\right)  \\
&=&\left( f^{\prime \prime }f^{\prime }f,\left( f^{\prime \prime }\otimes
f^{\prime \prime }\right) \left[ \left( f^{\prime }\otimes f^{\prime
}\right) \left( \mathcal{F}\right) \mathcal{F}^{\prime }\right] \mathcal{F}%
^{\prime \prime }\right)  \\
&=&\left( f^{\prime \prime }f^{\prime }f,\left( f^{\prime \prime }f^{\prime
}\otimes f^{\prime \prime }f^{\prime }\right) \left( \mathcal{F}\right)
\left( f^{\prime \prime }\otimes f^{\prime \prime }\right) \left( \mathcal{F}%
^{\prime }\right) \mathcal{F}^{\prime \prime }\right)  \\
&=&\left( f^{\prime \prime }f^{\prime },\left( f^{\prime \prime }\otimes
f^{\prime \prime }\right) \left( \mathcal{F}^{\prime }\right) \mathcal{F}%
^{\prime \prime }\right) \circ \left( f,\mathcal{F}\right)  \\
&=&\left( \left( f^{\prime \prime },\mathcal{F}^{\prime \prime }\right)
\circ \left( f^{\prime },\mathcal{F}^{\prime }\right) \right) \circ \left( f,%
\mathcal{F}\right) .
\end{eqnarray*}%
The rest of the proof is trivial.
\end{invisible}

