% \end{align*}%
 Moreover, let $(f,\Ff),\left( f^{\prime },\mathcal{F}^{\prime }\right):(H,\Ss) \to (H_1,\Rr_1)\ot (H_2,\Rr_2)$ be any morphisms in $\TwTrBialg$
together with $2$-cells
\begin{align*}
 g_{1} &:\left(
\id\otimes\varepsilon,1\otimes 1\right) \circ \left( f,\mathcal{F}\right)  \Rightarrow \left(
