\section{Applications to twisted tensor product}\label{sec:applications}

Following the recent \cite[Definition 3.1]{Wu-Zhou} we recall the following definition where we drop out the hypothesis of the existence of an antipode. 

\begin{definition}
\label{def:twtensprod}
Let $(H,\Rr)$, $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$ be quasitriangular bialgebras. Then $(H,\Rr)$ is called a \emph{twisted tensor product} of  $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$ if there are a twist $\Ff$ on the tensor product bialgebra $H_{1}\otimes H_2$ and an isomorphism of quasitriangular bialgebras  $f:(H,\Rr)\to (( H_{1}\otimes H_2)_\Ff,\widetilde{\Rr}_\Ff)$ where $\widetilde{\Rr}=(\id\ot\tau\ot\id)(\Rr_1\ot\Rr_2)$.
\end{definition}

\begin{remark}\label{rmk:twistedasinv1cell}
    By Lemma \ref{lem:isoTwTr}, if $(H,\Rr)$, $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$ are triangular bialgebras, then $(H,\Rr)$ is a twisted tensor product of $(H_{1},\Rr_{1})$ and $(H_{2},\Rr_{2})$ if there are a twist $\Ff$ on the tensor product bialgebra $H_{1}\otimes H_2$ and an invertible 1-cell $(f,\Ff):(H,\Rr)\to(H_{1}\ot H_{2},\widetilde{\Rr})$ in $\TwTrBialg$.
\end{remark}


% \rd{In \cite{Wu-Zhou} one considers right twist $\mathcal{J}$ in the sense of \cite[Definition 7.8.1]{Radford-book} that is to say that $\mathcal{J}$ is a  twist in the opposite algebra. By the symmetric version of \cite[Lemma 7.8.2]{Radford-book}, $\mathcal{J}^{-1}$ is twist in our sense. However in \cite{Wu-Zhou} they define $\Delta_{\mathcal{J}}(-)=\mathcal{J}\Delta(-)\mathcal{J}^{-1}$, while the correct one for right twists should be $\Delta_{\mathcal{J}}(-)=\mathcal{J}^{-1}\Delta(-)\mathcal{J}$, see e.g. \href{https://www.sciencedirect.com/science/article/pii/S0021869302000923}{Gelaki}.} 

In \cite[Theorem
4.2]{Wu-Zhou} there is a characterization of quasitriangular Hopf algebras $(H,\Rr) $ that are a twisted tensor product of two quotient Hopf algebras $H_{1}$ and
$H_{2}$ with twist $\mathcal{J}=1\otimes \left(
f_{2}S\otimes f_{1}\right) \left( \mathcal{R}\right) \otimes 1$, where $f_{1}:H\to H_{1}$ and $f_{2}:H\to H_{2}$ denote the projections. In the triangular case, we are able to provide a further characterization in terms of the binary product in $\TwTrBialg$. We prove the result for bialgebras noting that, if $H$ has an antipode $S$, then one has $ 1\otimes \left( f_{2}\otimes
f_{1}\right) \left( \Rr^{-1}\right) \otimes 1 =1\otimes \left(
f_{2}S\otimes f_{1}\right) \left( \mathcal{R}\right) \otimes 1.$ 

\begin{corollary}
\label{cor:twtnsprdweak}
The following are equivalent for a triangular bialgebra $\left( H,\mathcal{R}\right) $.
\begin{enumerate}
    \item There are triangular bialgebras $(H_{1},\Rr_1)$ and $(H_{2},\Rr_2)$ and an
invertible $1$-cell $\left( f,\mathcal{F}\right) :\left( H,\mathcal{R}\right)
\rightarrow \left( H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},%
\mathcal{R}_{2}\right) $ in $\TwTrBialg$, where $\mathcal{F}=1\otimes \Ww^{-1}%
\otimes 1$ for a central weak $\mathcal{R}$-matrix $\Ww\in
H_{2}\otimes H_{1}$.

\item There are triangular bialgebras $(H_{1},\Rr_{1})$ and $(H_{2},\Rr_{2})$ and surjective morphisms $f_i:(H,\Rr)\to (H_i,\Rr_i)$ in $\TrBialg$, for $i=1,2$, such that the diagonal morphism $\langle(f_1,1\otimes 1),(f_2,1\otimes 1)\rangle:(H,\Rr)\to \left( H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},%
\mathcal{R}_{2}\right) $ is an
invertible $1$-cell in $\TwTrBialg$.

\item  There are triangular bialgebras $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$, and an isomorphism $f:(H,\Rr)\to (( H_{1}\otimes H_2)_\Ff,\widetilde{\Rr}_\Ff)$ in $\TrBialg$, where $\widetilde{\Rr}=(\id\ot\tau\ot\id)(\Rr_1\ot\Rr_2)$ and $\mathcal{F}=1\otimes \Ww^{-1}%
\otimes 1$ for a central weak $\mathcal{R}$-matrix $\Ww\in
H_{2}\otimes H_{1}$,
i.e. $(H,\Rr)$ is a twisted tensor product of  $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$ in the sense of \cref{def:twtensprod},  where  $\mathcal{F}=1\otimes \Ww^{-1}%
\otimes 1$.
\item 
There are bialgebras $H_{1}$ and $H_{2}$ and surjective bialgebra maps $f_{i}:H\rightarrow  H_{i} ,i=1,2$, such that $(f_1\ot f_2)\Delta:H\to (H_1\otimes H_2)_\Ff$ is a bialgebra isomorphism, where $\mathcal{F}\coloneqq  1\otimes \left( f_{2}\otimes
f_{1}\right) \left( \Rr^{-1}\right) \otimes 1 .$
\end{enumerate}
\end{corollary}

\begin{proof}
First recall that $\left( H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},%
\mathcal{R}_{2}\right) =\left( H_{1}\otimes H_{2},\widetilde{\mathcal{R}}%
\right)$, where $\widetilde{\mathcal{R}}=\left( \mathrm{Id}\otimes \tau
\otimes \mathrm{Id}\right) \left( \mathcal{R}_{1}\otimes \mathcal{R}%
_{2}\right) .$

\noindent $\left( 1\right) \Rightarrow \left( 2\right) $. Define the following 1-cells in $\TwTrBialg$:
\begin{eqnarray*}
\left( f_{1},\mathcal{F}_{1}\right)  \coloneqq\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \left( f,\mathcal{F}\right)
=\left( \left( \mathrm{Id}\otimes \varepsilon \right) f,\left( \mathrm{Id}%
\otimes \varepsilon \otimes \mathrm{Id}\otimes \varepsilon \right) \left(
1\otimes \Ww^{-1}\otimes 1\right) \right)  =\left( \left( \mathrm{Id}\otimes \varepsilon \right) f,1\otimes 1\right)
\end{eqnarray*}%
and
\begin{eqnarray*}
\left( f_{2},\mathcal{F}_{2}\right)  \coloneqq\left( \varepsilon \otimes \mathrm{%
Id},1\otimes 1\right)\left( f,\mathcal{F}\right)=\left( \left( \varepsilon \otimes \mathrm{Id}\right) f,\left( \varepsilon
\otimes \mathrm{\mathrm{\mathrm{Id}}}\otimes \varepsilon \otimes \mathrm{Id}%
\right) \left( 1\otimes \Ww^{-1}\otimes 1\right) \right)  =\left( \left( \varepsilon \otimes \mathrm{Id}\right) f,1\otimes 1\right) .
\end{eqnarray*}%
In particular, $f_i:(H,\Rr)\to (H_i,\Rr_i)$ is a morphism in $\TrBialg$ for $i=1,2.$
By \cref{lem:isoTwTr}, $\left( f,\mathcal{F}\right) $ is invertible in $\TwTrBialg$ if and only if $%
f:\left( H,\mathcal{R}\right) \rightarrow \left( \left( H_{1}\otimes
H_{2}\right) _{\mathcal{F}},\widetilde{\mathcal{R}}_{\mathcal{F}}\right) $
is an isomorphism in $\TrBialg$. Therefore, $f:H\rightarrow
H_{1}\otimes H_{2}$ is bijective and hence $f_{1}=\left( \mathrm{Id}\otimes
\varepsilon \right) f$ and $f_{2}=\left( \varepsilon \otimes \mathrm{Id}%
\right) f$ are surjective. 

By construction, the diagonal morphism $\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle$ satisfies 
\begin{align*}
\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle &=\left( f_{1},%
\mathcal{F}_{1}\right)\\
\left(\varepsilon \ot \mathrm{Id} ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle &=\left( f_{2},%
\mathcal{F}_{2}\right).
\end{align*}
Hence, we can
take 
\begin{align*}
 g_{1}&=1:\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle
\Rightarrow \left( \mathrm{Id}\otimes \varepsilon ,1\otimes 1\right) \circ
\left( f,\mathcal{F}\right) \\
g_{2}&=1:\left(\varepsilon \ot \mathrm{Id} ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle \Rightarrow \left( \varepsilon \otimes \mathrm{Id},1\otimes
1\right) \circ \left( f,\mathcal{F}\right).
\end{align*} 
By the universal property of
the binary product there is a unique $2$-cell $g:\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle
\Rightarrow \left( f,\mathcal{F}\right) $ such that $\left( \mathrm{Id}%
\otimes \varepsilon ,1\otimes 1\right) g=g_{1}=1$ and $\left(
\varepsilon \otimes \mathrm{Id},1\otimes 1\right) g=g_{2}=1.$ By
construction,
\begin{align*}
g &=\left( \mathrm{Id}\otimes \varepsilon \otimes \varepsilon \otimes
\mathrm{Id}\right) \left( \mathcal{F}^{-1}\right) \left( g_{1}\otimes
g_{2}\right)(\mathrm{Id}\otimes \varepsilon \otimes \varepsilon \otimes
\mathrm{Id})((1\ot(f_{2}\ot f_{1})(\Rr^{-1})\ot1)(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}))\\&= \left( 1\otimes \left(  \varepsilon \otimes \varepsilon \right)(\mathcal{W})\otimes 1\right) \left( 1\otimes
1\right)(1\ot(\varepsilon\ot\varepsilon)(\Rr^{-1})\ot1)(\mathrm{Id}\ot\varepsilon\ot\varepsilon\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}) =1\otimes 1.
\end{align*}%
This means that $\left\langle \left( f_{1},\mathcal{F}_{1}\right) ,\left(
f_{2},\mathcal{F}_{2}\right) \right\rangle =\left( f,\mathcal{F}\right) $. Therefore, $\langle(f_1,1\otimes 1),(f_2,1\otimes 1)\rangle$ is an invertible 1-cell in $\TwTrBialg$. The implication $(2)\Rightarrow(1)$ is obvious once observed the specific form assumed by the diagonal morphism $(f,\Ff)$ in \cref{thm:Tw2cart} when $\Ff_1=1\otimes 1$ and $\Ff_2=1\otimes 1$.

\noindent $\left( 1\right) \Leftrightarrow \left( 3\right) $.  It follows by \cref{lem:isoTwTr}, as mentioned in Remark \ref{rmk:twistedasinv1cell}.


\noindent $\left( 2\right) \Leftrightarrow \left( 4\right) $. If $f_i:(H,\Rr)\to (H_i,\Rr_i)$ is a surjective morphism in $\TrBialg$, for $i=1,2$, then $f_i:H\to H_i$ is a surjective bialgebra map, for $i=1,2$. Conversely, if $f_i:H\to H_{i}$ is a surjective bialgebra map, for $i=1,2$, then $f_i:(H,\Rr)\to (H_i,\Rr_i)$ is a surjective morphism in $\TrBialg$ where $\Rr_i\coloneqq (f_i\otimes f_i)(\Rr)$, for $i=1,2$. 
By \cref{thm:Tw2cart}, the diagonal morphism of $\left(
f_{1},1\otimes 1\right) $ and $\left( f_{2},1\otimes 1\right) $ is given by%
\begin{eqnarray*}
\left\langle \left( f_{1},1\otimes 1\right) ,\left( f_{2},1\otimes 1\right) \right\rangle  &=&\left( \left( f_{1}\otimes f_{2}\right) \Delta
_{H},\left( 1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1\right) \right)  .
\end{eqnarray*}
Thus, by \cref{lem:isoTwTr}, $ \langle(f_1,1\otimes 1),(f_2,1\otimes 1)\rangle$ is invertible in $\TwTrBialg$ if, and only if, $\left( f_{1}\otimes f_{2}\right) \Delta
_{H}:(H,\Rr)\to ((H_1\ot H_2)_\Ff,\widetilde{\Rr}_\Ff)$ is an isomorphism in $\TrBialg$, where $\Ff= 1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1$, i.e. $(f_{1}\ot f_{2})\Delta_{H}:H\to(H_{1}\ot H_{2})_{\Ff}$ is a bialgebra isomorphism and $((f_{1}\ot f_{2})\Delta_{H}\ot (f_{1}\ot f_{2})\Delta_{H})(\Rr)=\widetilde{\Rr}_{\Ff}$. To conclude, we observe that, given $\Rr_{i}:=(f_{i}\ot f_{i})(\Rr)$, for $i=1,2$, the latter equality is satisfied:
\[
\begin{split}
\widetilde{\Rr}_{\Ff}&=(1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1)^{\mathrm{op}}(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1)^{-1}\\&=(f_{1}(\overline{\Rr}_{s})\ot1\ot1\ot f_{2}(\overline{\Rr}^{s}))(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(1\ot f_{2}(\Rr^{l})\ot f_{1}(\Rr_{l})\ot 1)\\&\overset{\eqref{tr}}{=}(f_1(\Rr^{s})\ot1\ot1\ot f_{2}(\Rr_{s}))(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(1\ot f_{2}(\Rr^{l})\ot f_{1}(\Rr_{l})\ot 1)\\&=(f_{1}\ot f_{2}\ot f_{1}\ot f_{2})(\Rr^{s}\Rr^{i}\ot\Rr^{j}\Rr^{l}\ot \Rr_{i}\Rr_{l}\ot\Rr_{s}\Rr_{j})\\&
\overset{\eqref{eq:DDR}}=(f_{1}\ot f_{2}\ot f_{1}\ot f_{2})(\Delta\ot\Delta)(\Rr).
\end{split}
\]
This computation completes the proof.
\end{proof}

