% It is now clear that the horizontal composition of these $2$-cells is $a\hc b=ag(b)=g(b^{-1})g(b)=1$
% \[
% \xymatrix@C=1cm{(H,\Rr)\rtwocell^{(f,\Ff)}_{(f',\Ff')}{b} & (H',\Rr') \rtwocell^{(g,\Gg)}_{(g',\Gg')}{a}& (H,\Rr)}
% \quad = \quad \xymatrix@C=1.5cm{(H,\Rr) \rrtwocell^{(g,\Gg)\circ (f,\Ff)}_{(g',\Gg')\circ (f',\Ff')}{\mathrlap{ag(b)}}&  & (H,\Rr)}.
% \] 
% The fact that this $2$-cell $a\hc b:(g,\Gg)\circ (f,\Ff)\Rightarrow (g',\Gg')\circ (f',\Ff')$ is $1$ just means that $(g,\Gg)\circ (f,\Ff)=(g',\Gg')\circ (f',\Ff')$ and hence $(g',\Gg')\circ (f',\Ff')=\id$.
% Similarly, since $b\hca=bf(a)=bf(g(b^{-1}))=bb^{-1}=1$, we deduce that $(f',\Ff')\circ (g',\Gg')=\id$. We have thus proved that if the $1$-cell $(f,\Ff)$ is invertible, then so is $(f',\Ff').$ For the converse, just consider the $2$-cell $b^{-1}:(f',\Ff')\Rightarrow (f,\Ff)$.
\end{proof}

We are now ready to state the aforementioned characterization.

\begin{corollary}
The following are equivalent for a triangular bialgebra $\left( H,%
\mathcal{R}\right) $.

\begin{enumerate}
\item There are triangular bialgebras $(H_{1},\Rr_{1})$ and $(H_{2},%
\Rr_{2})$, and an invertible $1$-cell $\left( f,\mathcal{F}\right) :\left( H,\mathcal{%
R}\right) \rightarrow \left( H_{1},\mathcal{R}_{1}\right) \otimes \left(
H_{2},\mathcal{R}_{2}\right) $ in $\TwTrBialg$.

\item There are triangular bialgebras $(H_{1},\Rr_{1})$ and $(H_{2},\Rr_{2})$, twists $\Ff_{i}$ of $H_{i}$ and surjective morphisms $f_{i}:(H,\Rr%
)\rightarrow (\left( H_{i}\right) _{\mathcal{F}_{i}},\left( \Rr_{i}\right) _{%
\mathcal{F}_{i}})$ in $\TrBialg$, for $i=1,2$, such that the diagonal morphism $\langle (f_{1},%
\mathcal{F}_{1}),(f_{2},\mathcal{F}_{2})\rangle :(H,\Rr)\rightarrow \left(
H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},\mathcal{R}_{2}\right) $
is an invertible $1$-cell in $\TwTrBialg$.
\item There are triangular bialgebras $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$, a twist $\Ff$ on $H_{1}\ot H_{2}$ and an isomorphism $f:(H,\Rr)\to (( H_{1}\otimes H_2)_\Ff,\widetilde{\Rr}_\Ff)$ in $\TrBialg$ where $\widetilde{\Rr}=(\id\ot\tau\ot\id)(\Rr_1\ot\Rr_2)$,
i.e. $(H,\Rr)$ is a twisted tensor product of $(H_1,\Rr_1)$ and $(H_2,\Rr_2)$ in the sense of \cref{def:twtensprod}.
\item 
There are bialgebras $H_{1}$ and $H_{2}$ and surjective bialgebra maps $f_{i}:H\rightarrow \left( H_{i}\right) _{\mathcal{F}_{i}},i=1,2$, such that $(f_1\ot f_2)\Delta:H\to (H_1\otimes H_2)_\Ff$ is a bialgebra isomorphism, where $\mathcal{F}\coloneqq \left( 1\otimes \left( f_{2}\otimes
f_{1}\right) \left( \Rr^{-1}\right) \otimes 1\right) \left(
\mathrm{Id}\otimes \tau \otimes \mathrm{Id}\right) \left( \mathcal{F}%
_{1}\otimes \mathcal{F}_{2}\right) .$
%\item There are surjective bialgebra maps $f_{i}:H\rightarrow \left( H_{i}\right) _{\mathcal{F}_{i}},i=1,2$, and a bialgebra isomorphism $f:H\to (H_1\otimes H_2)_\Ff$, where $\mathcal{F}\coloneqq \left( 1_{H_{1}}\otimes \left( f_{2}\otimes f_{1}\right) \left( \Rr^{-1}\right) \otimes 1_{H_{2}}\right) \left(\mathrm{Id}\otimes \tau \otimes \mathrm{Id}\right) \left( \mathcal{F}_{1}\otimes \mathcal{F}_{2}\right) .$
\end{enumerate}
\end{corollary}

\begin{proof}
First recall that $\left( H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},%
\mathcal{R}_{2}\right) =\left( H_{1}\otimes H_{2},\widetilde{\mathcal{R}}%
\right),$ where $\widetilde{\mathcal{R}}=\left( \mathrm{Id}\otimes \tau
\otimes \mathrm{Id}\right) \left( \mathcal{R}_{1}\otimes \mathcal{R}%
_{2}\right) .$

\noindent $\left( 1\right) \Rightarrow \left( 2\right) $. Define the following 1-cells in $\TwTrBialg$:
\begin{gather*}
\left( f_{1},\mathcal{F}_{1}\right) \coloneqq\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \circ \left( f,\mathcal{F}\right) =\left(
\left( \mathrm{Id}\otimes \varepsilon \right) f,\left( \mathrm{Id}\otimes
\varepsilon \otimes \mathrm{Id}\otimes \varepsilon \right) \left( \mathcal{F}%
\right) \right) , \\
\left( f_{2},\mathcal{F}_{2}\right) \coloneqq\left( \varepsilon \otimes
\mathrm{Id},1\otimes 1\right) \circ \left( f,\mathcal{F}\right) =\left(
\left( \varepsilon \otimes \mathrm{Id}\right) f,\left( \varepsilon \otimes
\mathrm{\mathrm{\mathrm{Id}}}\otimes \varepsilon \otimes \mathrm{Id}\right)
\left( \mathcal{F}\right) \right) .
\end{gather*}%
In particular, $f_{i}:(H,\Rr)\rightarrow (\left( H_{i}\right) _{\mathcal{F}%
_{i}},\left( \Rr_{i}\right) _{\mathcal{F}_{i}})$ is a morphism in $\TrBialg$  for $%
i=1,2.$ By \cref{lem:isoTwTr}, $\left( f,\mathcal{F}\right) $ is an
isomorphism in $\TwTrBialg$ if and only if $f:\left( H,\mathcal{R}\right)
\rightarrow \left( \left( H_{1}\otimes H_{2}\right) _{\mathcal{F}},%
\widetilde{\mathcal{R}}_{\mathcal{F}}\right) $ is an isomorphism in $\TrBialg
$. Therefore, $f:H\rightarrow H_{1}\otimes H_{2}$ is bijective and hence $%
f_{1}=\left( \mathrm{Id}\otimes \varepsilon \right) f$ and $f_{2}=\left(
\varepsilon \otimes \mathrm{Id}\right) f$ are surjective.
By construction, the diagonal morphism $\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle$ satisfies 
\begin{align*}
\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle &=\left( f_{1},%
\mathcal{F}_{1}\right)\\
\left(\varepsilon \ot \mathrm{Id} ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle &=\left( f_{2},%
\mathcal{F}_{2}\right).
\end{align*}
Hence, we can
take 
\begin{align*}
 g_{1}&=1:\left( \mathrm{Id}\otimes
\varepsilon ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle
\Rightarrow \left( \mathrm{Id}\otimes \varepsilon ,1\otimes 1\right) \circ
\left( f,\mathcal{F}\right) \\
g_{2}&=1:\left(\varepsilon \ot \mathrm{Id} ,1\otimes 1\right) \circ \left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle \Rightarrow \left( \varepsilon \otimes \mathrm{Id},1\otimes
1\right) \circ \left( f,\mathcal{F}\right).
\end{align*} 
By the universal property of
the binary product there is a unique $2$-cell $g:\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle
\Rightarrow \left( f,\mathcal{F}\right) $ such that $\left( \mathrm{Id}%
\otimes \varepsilon ,1\otimes 1\right) g=g_{1}=1$ and $\left(
\varepsilon \otimes \mathrm{Id},1\otimes 1\right) g=g_{2}=1.$ By
construction, setting $\Gg:=(\mathrm{Id}\ot\varepsilon\ot\varepsilon\ot\mathrm{Id})((1\ot(f_{2}\ot f_{1})(\Rr^{-1})\ot1)(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}))=1\ot1$ and $\mathcal{G'}\coloneqq\left( \mathrm{Id}\otimes
\varepsilon \otimes \varepsilon \otimes \mathrm{Id}\right) \left( \mathcal{F}%
\right) ,$ we have
$g=\mathcal{G'}^{-1}\left( g_{1}\otimes g_{2}\right)\Gg =\mathcal{G'}^{-1}$
and hence we have the $2$-cell $\mathcal{G'}^{-1}:\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle
\Rightarrow \left( f,\mathcal{F}\right) ,$ which is invertible as so is the element $\Gg'$. Thus, we can apply  \cref{lem:iso&2cell}, to conclude that, since $(f,\Ff)$ is an invertible $1$-cell, then so is $\left\langle \left( f_{1},%
\mathcal{F}_{1}\right) ,\left( f_{2},\mathcal{F}_{2}\right) \right\rangle.$

\noindent $\left( 2\right) \Rightarrow \left( 1\right). $ It is clear.

\noindent $\left( 1\right) \Leftrightarrow \left( 3\right) $. It follows by \cref{lem:isoTwTr}, as mentioned in Remark \ref{rmk:twistedasinv1cell}.

\noindent $\left( 2\right) \Leftrightarrow \left( 4\right) $. If $f_i:(H,\Rr)\to((H_i)_{\Ff_i},(\Rr_i)_{\Ff_i})$ is a surjective morphism in $\TrBialg$, for $i=1,2$, then $f_i:H\to (H_i)_{\Ff_i}$ is a surjective bialgebra map, for $i=1,2$. Conversely, if $f_i:H\to (H_i)_{\Ff_i}$ is a surjective bialgebra map, for $i=1,2$, then $(H_{i})_{\Ff_i}$ becomes triangular in a unique way such that $f_i$ becomes a morphism in $\TrBialg$, i.e. via $(f_i\otimes f_i)(\Rr)$. If we set $\Rr_i\coloneqq (f_i\otimes f_i)(\Rr)_{\Ff_i^{-1}}$, we then get $(\Rr_i)_{\Ff_i}=(f_i\otimes f_i)(\Rr)$ so that $f_i:(H,\Rr)\to((H_i)_{\Ff_i},(\Rr_i)_{\Ff_i})$ is a surjective morphism in $\TrBialg$, for $i=1,2$. By \cref{thm:Tw2cart}, the diagonal morphism of $\left(
f_{1},\Ff_{1}\right) $ and $\left( f_{2},\Ff_{2}\right) $ is given by%
\begin{eqnarray*}
\left\langle \left( f_{1},\Ff_{1}\right) ,\left( f_{2},\Ff_{2}\right) \right\rangle  &=&\left( \left( f_{1}\otimes f_{2}\right) \Delta
_{H},\left( 1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1\right)(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}) \right)  .
\end{eqnarray*}
By \cref{lem:isoTwTr}, the $1$-cell 
$\langle (f_{1},%
\mathcal{F}_{1}),(f_{2},\mathcal{F}_{2})\rangle :(H,\Rr)\rightarrow \left(
H_{1},\mathcal{R}_{1}\right) \otimes \left( H_{2},\mathcal{R}_{2}\right) $
is invertible in $\TwTrBialg$ if, and only if, 
$\left( f_{1}\otimes f_{2}\right) \Delta
_{H}:(H,\Rr)\to ((H_1\ot H_2)_\Ff,\widetilde{\Rr}_\Ff)$ is an isomorphism in $\TrBialg$, where $\Ff= \left( 1_{H_{1}}\otimes \left( f_{2}\otimes
f_{1}\right) \left( \Rr^{-1}\right) \otimes 1_{H_{2}}\right) \left(
\mathrm{Id}\otimes \tau \otimes \mathrm{Id}\right) \left( \mathcal{F}%
_{1}\otimes \mathcal{F}_{2}\right)$, i.e. $(f_{1}\ot f_{2})\Delta_{H}:H\to(H_{1}\ot H_{2})_{\Ff}$ is a bialgebra isomorphism and $((f_{1}\ot f_{2})\Delta_{H}\ot (f_{1}\ot f_{2})\Delta_{H})(\Rr)=\widetilde{\Rr}_{\Ff}$. To conclude, we observe that, given $\Rr_{i}:=(f_{i}\ot f_{i})(\Rr)_{\Ff_{i}^{-1}}$, for $i=1,2$, we have
\[
\Rr_{1}\ot\Rr_{2}=((\Ff_{1}^{-1})^{\mathrm{op}}\ot(\Ff_{2}^{-1})^{\mathrm{op}})(f_{1}\ot f_{1}\ot f_{2}\ot f_{2})(\Rr\ot\Rr)(\Ff_{1}\ot\Ff_{2})
\]
and then the following equality is satisfied:
\[
\begin{split}
\widetilde{\Rr}_{\Ff}&=(1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1)^{\mathrm{op}}((\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}))^{\mathrm{op}}\\&\hspace{0.5cm}(\mathrm{Id}\ot\tau\ot\mathrm{Id})((\Ff_{1}^{-1})^{\mathrm{op}}\ot(\Ff_{2}^{-1})^{\mathrm{op}})
(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2})\\&\hspace{0.5cm}((\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{1}\ot\Ff_{2}))^{-1}(1\otimes \left( f_{2}\otimes f_{1}\right) \left( \mathcal{R}%
^{-1}\right) \otimes 1)^{-1}\\&=(f_{1}(\overline{\Rr}_{s})\ot1\ot1\ot f_{2}(\overline{\Rr}^{s}))(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(1\ot f_{2}(\Rr^{l})\ot f_{1}(\Rr_{l})\ot 1)\\&\overset{\eqref{tr}}{=}(f_1(\Rr^{s})\ot1\ot1\ot f_{2}(\Rr_{s}))(f_{1}(\Rr^{i})\ot f_{2}(\Rr^{j})\ot f_{1}(\Rr_{i})\ot f_{2}(\Rr_{j}))(1\ot f_{2}(\Rr^{l})\ot f_{1}(\Rr_{l})\ot 1)\\&=(f_{1}\ot f_{2}\ot f_{1}\ot f_{2})((\Rr^{s}\Rr^{i}\ot\Rr^{j}\Rr^{l}\ot \Rr_{i}\Rr_{l}\ot\Rr_{s}\Rr_{j}))\\&\overset{\eqref{eq:DDR}}=(f_{1}\ot f_{2}\ot f_{1}\ot f_{2})(\Delta\ot\Delta)(\Rr).
\end{split}
\]
This computation completes the proof. 
% $\left( 4\right) \Rightarrow \left( 5\right) $ It is clear.
%
% $\left( 5\right) \Rightarrow \left( 2\right) $ If $f_i:H\to H_{\Ff_i}$ is a surjective bialgebra map, then $H_{\Ff_i}$ becomes quasitriangular in a unique way such that $f_i$ becomes a quasitriangular map, i.e. via $(f_i\otimes f_i)(\Rr)$. If we set $\Rr_i\coloneqq (f_i\otimes f_i)(\Rr)_{\Ff_i^{-1}}$, we then get $(\Rr_i)_{\Ff_i}=(f_i\otimes f_i)(\Rr)$ so that $f_i:(H,\Rr)\to((H_i)_{\Ff_i},(\Rr_i)_{\Ff_i})$ is a surjective morphism of quasitriangular bialgebras.
%
% Similarly $f:(H,\Rr)\to ((H_1\ot H_2)_\Ff,\widetilde{\Rr}_\Ff)$ is an isomorphism of quasitriangular bialgebras where $\widetilde{\Rr}=(f\otimes f)(\Rr)_{\Ff^{-1}}$. \rd{[Bisogna vedere che questultimo è $\widetilde{\mathcal{R}}=\left( \mathrm{Id}\otimes \tau
% \otimes \mathrm{Id}\right) \left( \mathcal{R}_{1}\otimes \mathcal{R}%
% _{2}\right) .$]}
\end{proof}


As noticed in \cref{rmk:twistedasinv1cell}, a triangular bialgebra $(H,\Rr)$ is a twisted tensor product of triangular bialgebras $(H_{1},\Rr_{1})$ and $(H_{2},\Rr_{2})$ if and only if there is an invertible 1-cell $(f,\Ff):(H,\Rr)\to(H_{1}\ot H_{2},\widetilde{\Rr})$ in $\TwTrBialg$. Using this, we end this section providing some simple examples of twisted tensor products.

\begin{example}
In view of \cref{rmk:tensorproductmorphism} and \cref{lem:isoTwTr}, we obtain the following examples.

1). Given the Sweedler's Hopf algebra $(H,\Rr_{\lambda})$, we can define invertible 1-cells $(f_{s},\Ff_{d}):(H,\Rr_{\lambda})\to(H,\Rr_{\lambda s^{2}-2d})$ in $\TwTrBialg$, for $0\not=s\in\Bbbk$ and $d\in\Bbbk$, as in Example \ref{exa:Sw1}. Thus
\[ (f_{s},\Ff_{d})\otimes (\id,1\ot 1)\overset{\eqref{eq:tns1cell}}=   (f_{s}\ot\mathrm{Id},(\Ff_{d})^i\ot1\ot(\Ff_{d})_{i}\ot1):(H,\Rr_{\lambda})\ot(K,1\ot1)\to(H,\Rr_{\lambda s^{2}-2d})\ot(K,1\ot1)
\]   
    is an invertible 1-cell in $\TwTrBialg$, for any cocommutative bialgebra $K$. Therefore, $(H,\Rr_{\lambda})\ot(K,1\ot1)$ is a twisted tensor product of $(H,\Rr_{\lambda s^{2}-2d})$ and $(K,1\ot1)$. 

    2). Given the abelian group $\Gamma=\langle x,y\ |\ xy=yx,\ x^{n}=1,\ y^{n}=1\rangle$, for $n>1$, we can define invertible 1-cells $(f,\Ff):(\Bbbk\Gamma,\Rr)\to(\Bbbk\Gamma,\Rr')$ as in \cref{ex:groupalgebra}. Then
\[
(f_s\ot\Ff_d)\ot(f,\Ff)\overset{\eqref{eq:tns1cell}}=(f_{s}\ot f,(\mathrm{Id}\ot\tau\ot\mathrm{Id})(\Ff_{d}\ot\Ff)):(H,\Rr_{\lambda})\ot(\Bbbk\Gamma,\Rr)\to(H,\Rr_{\lambda s^{2}-2d})\ot(\Bbbk\Gamma,\Rr')
\]
is an invertible 1-cell in $\TwTrBialg$. Therefore, $(H,\Rr_{\lambda})\ot(\Bbbk\Gamma,\Rr)$ is a twisted tensor product of $(H,\Rr_{\lambda s^{2}-2d})$ and $(\Bbbk\Gamma,\Rr')$.
\end{example}



